async function supabaseWithRetry(operation, maxRetries = 3) {
  let attempt = 0;
  while (attempt < maxRetries) {
    try {
      const { data, error } = await operation();
      if (error) throw error;
      return { data, error: null };
    } catch (error) {
      attempt++;
      if (attempt >= maxRetries) return { data: null, error };
      await new Promise(resolve => setTimeout(resolve, 800 * attempt));
    }
  }
}

// Optimasi: Tarik data bertahap dan berhenti otomatis jika halaman terakhir sudah tercapai
async function fetchAllJawabanSupabase() {
  const limit = 1000;
  const maxPages = 10;
  let allData = [];

  for (let i = 0; i < maxPages; i++) {
    let from = i * limit;
    let to = from + limit - 1;
    const { data, error } = await supabaseWithRetry(() =>
      supabaseClient.from('jawaban_ujian').select('nama, kelas, mapel, jawaban, nilai, created_at').range(from, to)
    );
    if (error) throw error;
    if (data && data.length > 0) {
      allData = allData.concat(data);
      if (data.length < limit) break; // Berhenti jika data kurang dari limit (sudah habis)
    } else {
      break;
    }
  }
  return allData;
}

