// --- 3. FUNGSI UTILITAS, FORMAT TEKS & KEAMANAN ---
function encryptData(text) {
  let res = '';
  for (let i = 0; i < text.length; i++) {
    res += String.fromCharCode(text.charCodeAt(i) ^ (153 + (i % 10)));
  }
  return btoa(encodeURIComponent(res)).split('').reverse().join('');
}

function decryptData(hash) {
  try {
    let reversed = hash.split('').reverse().join('');
    let res = decodeURIComponent(atob(reversed));
    let orig = '';
    for (let i = 0; i < res.length; i++) {
      orig += String.fromCharCode(res.charCodeAt(i) ^ (153 + (i % 10)));
    }
    return orig;
  } catch (e) {
    return null;
  }
}

