function escapeHtml(unsafe) {
  if (unsafe === null || unsafe === undefined) return "";
  let str = unsafe.toString()
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;");
  str = str
    .replace(/&lt;b&gt;/gi, "<b>").replace(/&lt;\/b&gt;/gi, "</b>")
    .replace(/&lt;i&gt;/gi, "<i>").replace(/&lt;\/i&gt;/gi, "</i>")
    .replace(/&lt;u&gt;/gi, "<u>").replace(/&lt;\/u&gt;/gi, "</u>")
    .replace(/&lt;sup&gt;/gi, "<sup>").replace(/&lt;\/sup&gt;/gi, "</sup>")
    .replace(/&lt;sub&gt;/gi, "<sub>").replace(/&lt;\/sub&gt;/gi, "</sub>")
    .replace(/&lt;br\s*\/?&gt;/gi, "<br>");
  return str;
}

// Fungsi pemformat teks soal (Menangani paragraf, baris baru, dan kata SEBAB)
function formatSoalText(rawText) {
  if (!rawText) return "";
  let safe = escapeHtml(rawText);
  safe = safe.replace(/\r?\n/g, "<br>");
  safe = safe.replace(/\bSEBAB\b/g, '<br><span style="display:inline-block; margin:8px 0; padding:3px 10px; background:#f3e8ff; color:#6b21a8; border-radius:6px; font-weight:800; border:1px solid #d8b4fe;">SEBAB</span><br>');
  return safe;
}

function shuffleArray(array) {
  let arr = [...array];
  for (let i = arr.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [arr[i], arr[j]] = [arr[j], arr[i]];
  }
  return arr;
}

