// Fungsi bantu tangguh untuk menyimpan/update jawaban ke Supabase (mendukung Upsert & Fallback Select/Update/Insert)
async function simpanJawabanKeSupabase(payload) {
  try {
    // Langkah 1: Coba upsert langsung seperti bawaan Kelas 7
    const upsertRes = await supabaseClient
      .from('jawaban_ujian')
      .upsert([payload], { onConflict: 'nama,mapel' });
    if (!upsertRes.error) return upsertRes;

    // Langkah 2 (Fallback): Jika tabel tidak memiliki unique constraint (nama,mapel), gunakan cek manual Select -> Update / Insert
    const { data: existing, error: selectError } = await supabaseClient
      .from('jawaban_ujian')
      .select('nama')
      .eq('nama', payload.nama)
      .eq('mapel', payload.mapel)
      .limit(1);

    if (!selectError && existing && existing.length > 0) {
      const updRes = await supabaseClient
        .from('jawaban_ujian')
        .update({
          kelas: payload.kelas,
          jawaban: payload.jawaban
        })
        .eq('nama', payload.nama)
        .eq('mapel', payload.mapel);
      if (!updRes.error) return updRes;
    }

    // Langkah 3 (Fallback Terakhir): Lakukan INSERT murni
    return await supabaseClient
      .from('jawaban_ujian')
      .insert([payload]);
  } catch (err) {
    return { data: null, error: err };
  }
}

async function silentAutoSync() {
  if (!isExamActive || isSyncingAnswers || Object.keys(userAnswers).length === 0) return;
  isSyncingAnswers = true;
  let answersPayload = { "__security_vCount": violationCount, "__security_vLogs": violationLogs };
  examData.forEach((q, idx) => {
    if (userAnswers[idx] !== undefined && userAnswers[idx] !== "") {
      answersPayload[q.id] = userAnswers[idx];
    }
  });
  try {
    let secureAnswers = encryptData(JSON.stringify(answersPayload));
    await simpanJawabanKeSupabase({
      nama: studentData.name,
      kelas: studentData.kelas,
      mapel: studentData.subject,
      jawaban: secureAnswers
    });
  } catch (e) {
    console.warn("Auto-save senyap ditunda.");
  } finally {
    isSyncingAnswers = false;
  }
}
