function handleSecurityViolation(tipePelanggaran = "Pindah Tab / Keluar Aplikasi") {
  if (!isExamActive) return;
  let now = Date.now();
  if (now - lastViolationTime > 2000) {
    lastViolationTime = now;
    violationCount++;
    let timeStr = new Date().toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit', second: '2-digit' });
    violationLogs.push(`${timeStr} (${tipePelanggaran})`);
    saveState();

    if (violationCount >= 7) {
      isExamActive = false;
      clearInterval(timerInterval);
      if (strictInterval) clearInterval(strictInterval);
      Swal.fire({
        icon: 'error',
        title: 'UJIAN DIBATALKAN!',
        text: 'Anda telah melanggar aturan keamanan sebanyak 7 kali.',
        allowOutsideClick: false,
        allowEscapeKey: false,
        customClass: { popup: 'swal-custom-popup', confirmButton: 'swal-custom-confirm' }
      }).then(() => finishExam(true));
    } else {
      if (tipePelanggaran !== "Keluar Fullscreen") {
        Swal.fire({
          icon: 'warning',
          title: `PELANGGARAN (${violationCount}/7)`,
          html: `Sistem mendeteksi Anda meninggalkan layar ujian atau membuka aplikasi lain.<br><br><b>Waktu Kejadian: ${timeStr}</b><br><br>Aktivitas ini tercatat di Berita Acara Admin!`,
          confirmButtonText: 'Saya Mengerti',
          allowOutsideClick: false,
          customClass: { popup: 'swal-custom-popup', confirmButton: 'swal-custom-confirm' }
        });
      }
    }
  }
}

