function updateLiveClockUI() {
  const now = new Date();
  const d = ['Minggu', 'Senin', 'Selasa', 'Rabu', 'Kamis', 'Jumat', 'Sabtu'];
  const m = ['Jan', 'Feb', 'Mar', 'Apr', 'Mei', 'Jun', 'Jul', 'Agu', 'Sep', 'Okt', 'Nov', 'Des'];
  const elTime = document.getElementById('live-time');
  const elDate = document.getElementById('live-date');
  if (elTime) elTime.innerText = `${now.getHours().toString().padStart(2, '0')}:${now.getMinutes().toString().padStart(2, '0')}:${now.getSeconds().toString().padStart(2, '0')}`;
  if (elDate) elDate.innerText = `${d[now.getDay()]}, ${now.getDate()} ${m[now.getMonth()]} ${now.getFullYear()}`;
}

function initSicibinagaBoot() {
  if (window.__sicibinagaBooted) return;
  window.__sicibinagaBooted = true;

  updateLiveClockUI();
  setInterval(updateLiveClockUI, 1000);

  const defaultLogoUrl = 'https://upload.wikimedia.org/wikipedia/commons/9/9c/Logo_of_Ministry_of_Education_and_Culture_of_Republic_of_Indonesia.svg';
  ['ui-logo', 'cbt-logo-img', 'admin-logo-img', 'print-logo', 'print-logo-analisis'].forEach(id => {
    let el = document.getElementById(id);
    if (el && (!el.getAttribute('src') || el.getAttribute('src') === '')) {
      el.src = defaultLogoUrl;
    }
  });

  const inpQR = document.getElementById('inpLinkQR');
  if (inpQR) inpQR.value = window.location.href.split('?')[0];

  try {
    const urlParams = new URLSearchParams(window.location.search);
    const qrUser = urlParams.get('user');
    if (qrUser && document.getElementById('email')) {
      document.getElementById('email').value = decodeURIComponent(qrUser);
    }
  } catch (e) {}

  if (typeof google !== 'undefined' && google.script && google.script.run) {
    google.script.run.withSuccessHandler(async function (config) {
      if (!config) return;
      globalConfig = config;
      const logoSrc = config.logo || defaultLogoUrl;
      ['ui-logo', 'cbt-logo-img', 'admin-logo-img', 'print-logo', 'print-logo-analisis'].forEach(id => {
        let el = document.getElementById(id);
        if (el) el.src = logoSrc;
      });
      try { base64LogoKartu = await getBase64ImageFromUrl(logoSrc); } catch (e) { base64LogoKartu = logoSrc; }
      if (config.title) {
        if (document.getElementById('app-title-main')) document.getElementById('app-title-main').innerText = config.title;
        if (document.getElementById('univ-app-title')) document.getElementById('univ-app-title').innerText = config.title;
        if (document.getElementById('admin-school-name')) document.getElementById('admin-school-name').innerText = config.title;
        if (document.getElementById('print-school-title')) document.getElementById('print-school-title').innerText = config.title.toUpperCase();
      }
    }).withFailureHandler(err => {
      console.warn('Gagal memuat konfigurasi awal Spreadsheet:', err);
    }).getAppConfig();
  }
}

