async function tarikDataSupabase() {
  Swal.fire({ title: 'Sinkronisasi Data...', text: 'Menarik kunci jawaban terbaru & data peserta...', didOpen: () => Swal.showLoading(), allowOutsideClick: false, customClass: { popup: 'swal-custom-popup' } });
  try {
    await new Promise(resolve => refreshMasterKeysAdmin(resolve));
    const data = await fetchAllJawabanSupabase();
    prosesKoreksiAdmin(data);
    Swal.fire({ icon: 'success', title: 'Berhasil', text: `Sinkronisasi ${data.length} data jawaban selesai.`, timer: 2000, showConfirmButton: false, customClass: { popup: 'swal-custom-popup' } });
  } catch (error) {
    Swal.fire({ title: 'Error Koneksi', text: error.message, icon: 'error', customClass: { popup: 'swal-custom-popup', confirmButton: 'swal-custom-confirm' } });
  }
}

function prosesKoreksiAdmin(rawData) {
  finalGradedData = [];

  rawData.forEach(row => {
    let mapelSiswa = row.mapel ? row.mapel.trim() : "";
    let kelasSiswa = row.kelas ? row.kelas.trim() : "Unknown";
    let configMapel = masterKeys[mapelSiswa];
    if (!configMapel || !configMapel.keys) return;

    let jwb = {};
    let bnr = 0;

    try {
      let rawDataFromSupabase = row.jawaban;
      let decNew = decryptData(rawDataFromSupabase);
      if (decNew && decNew.includes('__security_vCount')) {
        jwb = JSON.parse(decNew);
      } else {
        let legacyDec = (function (hash) {
          try {
            let r = decodeURIComponent(atob(hash));
            let orig = '';
            for (let i = 0; i < r.length; i++) orig += String.fromCharCode(r.charCodeAt(i) ^ 153);
            return orig;
          } catch (e) { return null; }
        })(rawDataFromSupabase);

        if (legacyDec && legacyDec.includes('__security_vCount')) {
          jwb = JSON.parse(legacyDec);
        } else {
          jwb = typeof rawDataFromSupabase === 'string' ? JSON.parse(rawDataFromSupabase) : (rawDataFromSupabase || {});
        }
      }
    } catch (e) {
      jwb = {};
    }

    let secCount = jwb["__security_vCount"] || 0;
    let secLogs = jwb["__security_vLogs"] || [];

    let isFullPG = true;
    for (let key in jwb) {
      if (key !== "__security_vCount" && key !== "__security_vLogs") {
        if (Array.isArray(jwb[key]) || typeof jwb[key] === 'object') {
          isFullPG = false; break;
        }
      }
    }

    for (let no in configMapel.keys) {
      let kunciSistem = String(configMapel.keys[no]).toUpperCase().replace(/\s+/g, '');
      let jwbSiswa = jwb[no];

      if (jwbSiswa === undefined && Array.isArray(jwb)) {
        jwbSiswa = jwb[parseInt(no) - 1];
      }

      let poinSoalIni = 0;
      if (jwbSiswa !== undefined && jwbSiswa !== null && jwbSiswa !== '') {
        if (Array.isArray(jwbSiswa)) {
          let arrKunci = kunciSistem.split(",");
          let jwbSiswaClean = jwbSiswa.map(x => String(x).toUpperCase().replace(/\s+/g, ''));
          if (arrKunci.length === 3 && kunciSistem.length > 3) {
            let benarParsial = 0;
            for (let i = 0; i < 3; i++) {
              if (jwbSiswaClean[i] === arrKunci[i]) benarParsial++;
            }
            poinSoalIni = benarParsial / 3;
          } else {
            let jwbSiswaStr = [...jwbSiswaClean].sort().join(",");
            let kunciSistemSort = [...arrKunci].sort().join(",");
            if (jwbSiswaStr === kunciSistemSort) poinSoalIni = 1;
          }
        } else if (typeof jwbSiswa === 'object' && jwbSiswa !== null) {
          let arrKunci = kunciSistem.split(",");
          if (arrKunci.length === 4) {
            let benarParsial = 0;
            let opsiKeys = ['A', 'B', 'C', 'D'];
            for (let i = 0; i < 4; i++) {
              let k = opsiKeys[i];
              let valSiswa = jwbSiswa[k] ? String(jwbSiswa[k]).toUpperCase().replace(/\s+/g, '') : '';
              if (valSiswa === arrKunci[i]) benarParsial++;
            }
            poinSoalIni = benarParsial / 4;
          } else {
            let jwbBS = [jwbSiswa.A || '', jwbSiswa.B || '', jwbSiswa.C || '', jwbSiswa.D || ''].join(",").toUpperCase().replace(/\s+/g, '');
            if (jwbBS === kunciSistem) poinSoalIni = 1;
          }
        } else {
          let jwbSingleStr = String(jwbSiswa).toUpperCase().replace(/\s+/g, '');
          if (jwbSingleStr === kunciSistem) poinSoalIni = 1;
        }
      }
      bnr += poinSoalIni;
    }

    let totalSoal = configMapel.total > 0 ? configMapel.total : 1;
    
    // 1. Hitung bobot per soal secara adaptif berbasis skala 100
    // Contoh: Jika 25 soal -> 100 / 25 = bobot 4 per soal
    // Contoh: Jika 40 soal -> 100 / 40 = bobot 2.5 per soal
    let bobotPerSoal = 100 / totalSoal; 

    // 2. Kalikan total jawaban yang benar dengan bobot
    let nilaiAkhirRaw = bnr * bobotPerSoal;
    
    // 3. Format hasil agar presisi (bulatkan ke 2 angka desimal jika bukan bilangan bulat)
    let nilaiAkhir = Number.isInteger(nilaiAkhirRaw) ? nilaiAkhirRaw : parseFloat(nilaiAkhirRaw.toFixed(2));
    let benarFinal = Number.isInteger(bnr) ? bnr : parseFloat(bnr.toFixed(2));
    let salahFinal = parseFloat(Math.max(0, totalSoal - bnr).toFixed(2));

    // OVERRIDE WITH ORIGINAL DATABASE SCORE IF AVAILABLE AND VALID (KHAS KELAS 7)
    if (row.nilai !== undefined && row.nilai !== null && !isNaN(row.nilai)) {
      nilaiAkhir = parseFloat(row.nilai);
      benarFinal = Math.round((nilaiAkhir / 100) * totalSoal);
      salahFinal = Math.max(0, totalSoal - benarFinal);
    }

    // TANGKAP NILAI EXCEL ASLI DARI JSON PAYLOAD JIKA ADA (KHAS KELAS 7)
    if (jwb["__target_nilai"] !== undefined) {
      nilaiAkhir = parseFloat(jwb["__target_nilai"]);
      benarFinal = parseInt(jwb["__target_benar"]) || Math.round((nilaiAkhir / 100) * totalSoal);
      salahFinal = parseInt(jwb["__target_salah"]) || Math.max(0, totalSoal - benarFinal);
    }

    finalGradedData.push({
      nama: row.nama || '-',
      kelas: kelasSiswa,
      mapel: mapelSiswa,
      benar: benarFinal,
      salah: salahFinal,
      nilai: nilaiAkhir,
      vCount: secCount,
      vLogs: secLogs,
      rawJawaban: jwb
    });
  });

  populateFilterAdmin();
  renderTableAdmin();
  if (document.getElementById('analisisMapelFilter').value) renderAnalisisSoal();
  if (document.getElementById('admin-tot-selesai')) document.getElementById('admin-tot-selesai').innerText = rawData.length;
  if (typeof renderAllSrnViews === 'function') {
    try { renderAllSrnViews(); } catch (e) {}
  }
}

function populateFilterAdmin() {
  const fMapel = document.getElementById('mapelFilter');
  const fKelas = document.getElementById('kelasFilter');
  const fAnalisis = document.getElementById('analisisMapelFilter');
  const fAnalisisKelas = document.getElementById('analisisKelasFilter');

  let currentMapel = fMapel.value, currentKelas = fKelas.value;
  let currentAnalisis = fAnalisis.value;
  let currentAnalisisKelas = fAnalisisKelas ? fAnalisisKelas.value : "ALL";

  fMapel.innerHTML = '<option value="ALL">Semua Mapel</option>';
  fKelas.innerHTML = '<option value="ALL">Semua Kelas</option>';
  fAnalisis.innerHTML = '<option value="">-- Pilih Mata Pelajaran --</option>';
  if (fAnalisisKelas) fAnalisisKelas.innerHTML = '<option value="ALL">Semua Kelas</option>';

  let mapelSet = new Set(), kelasSet = new Set();
  finalGradedData.forEach(d => { mapelSet.add(d.mapel); kelasSet.add(d.kelas); });

  Array.from(mapelSet).sort().forEach(m => {
    fMapel.innerHTML += `<option value="${escapeHtml(m)}" ${m === currentMapel ? 'selected' : ''}>${escapeHtml(m)}</option>`;
    fAnalisis.innerHTML += `<option value="${escapeHtml(m)}" ${m === currentAnalisis ? 'selected' : ''}>${escapeHtml(m)}</option>`;
  });
  Array.from(kelasSet).sort().forEach(k => {
    fKelas.innerHTML += `<option value="${escapeHtml(k)}" ${k === currentKelas ? 'selected' : ''}>${escapeHtml(k)}</option>`;
    if (fAnalisisKelas) fAnalisisKelas.innerHTML += `<option value="${escapeHtml(k)}" ${k === currentAnalisisKelas ? 'selected' : ''}>${escapeHtml(k)}</option>`;
  });
}

function renderTableAdmin() {
  const vMapel = document.getElementById('mapelFilter').value;
  const vKelas = document.getElementById('kelasFilter').value;
  const tbody = document.getElementById('resultBody');
  const btnPreview = document.getElementById('btnPreview');
  const btnExport = document.getElementById('btnExport');

  let filteredData = finalGradedData.filter(d => (vMapel === "ALL" || d.mapel === vMapel) && (vKelas === "ALL" || d.kelas === vKelas));
  btnPreview.disabled = !(vMapel !== "ALL" && vKelas !== "ALL" && filteredData.length > 0);
  btnExport.disabled = !(filteredData.length > 0);

  if (filteredData.length === 0) {
    tbody.innerHTML = `<tr><td colspan="9" style="text-align:center; padding: 60px; color:var(--text-muted); font-weight:600;"><i class="fa-solid fa-satellite-dish" style="font-size:40px; color:#cbd5e1; margin-bottom:15px; display:block;"></i>Data belum tersedia untuk filter ini.</td></tr>`;
    return;
  }

  let htmlContent = "";
  filteredData.sort((a, b) => {
    let aViolator = a.vCount >= 7 ? 1 : 0;
    let bViolator = b.vCount >= 7 ? 1 : 0;
    if (bViolator !== aViolator) return bViolator - aViolator;
    return a.nama.localeCompare(b.nama);
  }).forEach((s, idx) => {
    let isDisqualified = s.vCount >= 7;
    let secBadge = s.vCount === 0
      ? '<span style="color:var(--success); font-weight:800;"><i class="fa-solid fa-check"></i> Aman</span>'
      : `<div class="violation-badge"><span class="v-count" style="${isDisqualified ? 'background:#e11d48; color:white; border-color:#be123c;' : ''}">${s.vCount}x Melanggar</span><span class="v-log-list">${escapeHtml(s.vLogs.slice(0, 2).join(', '))}${s.vCount > 2 ? '...' : ''}</span></div>`;
    let safeNama = s.nama.replace(/'/g, "\\'");
    let safeMapel = s.mapel.replace(/'/g, "\\'");
    let resetBtn = `<button onclick="resetSiswaRealtime('${safeNama}', '${safeMapel}')" title="Hapus Riwayat Ujian Siswa" style="background:#ef4444; color:white; border:none; padding:8px 12px; border-radius:10px; font-weight:800; cursor:pointer; font-size:12px;"><i class="fa-solid fa-rotate-left"></i> Reset</button>`;
    let rowStyle = isDisqualified ? 'background-color: #fff1f2;' : '';

    htmlContent += `<tr style="${rowStyle}">
      <td>${idx + 1}</td>
      <td><b>${escapeHtml(s.nama)}</b></td>
      <td>${escapeHtml(s.kelas)}</td>
      <td><span style="background:var(--bg-color); padding:4px 8px; border-radius:6px; font-size:12px; font-weight:800; color:var(--teal);">${escapeHtml(s.mapel)}</span></td>
      <td style="color:var(--success); font-weight:800; text-align:center;">${s.benar}</td>
      <td style="color:var(--danger); font-weight:800; text-align:center;">${s.salah}</td>
      <td style="text-align:center;"><span style="background:var(--success); color:white; padding:6px 14px; border-radius:12px; font-weight:800; display:inline-block;">${s.nilai}</span></td>
      <td>${secBadge}</td>
      <td style="text-align:center;">${resetBtn}</td>
    </tr>`;
  });
  tbody.innerHTML = htmlContent;
}

function renderAnalisisSoal() {
  const mapel = document.getElementById('analisisMapelFilter').value;
  const kelas = document.getElementById('analisisKelasFilter').value;
  const tbodyUI = document.getElementById('analisisBody');
  const tbodyPrint = document.getElementById('p-analisis-body');
  const countLabel = document.getElementById('analisisCountLabel');
  const btnCetak = document.getElementById('btnCetakAnalisis');

  if (!mapel) {
    tbodyUI.innerHTML = `<tr><td colspan="7" style="text-align:center; padding: 40px; color:var(--text-muted); font-weight:600;">Pilih mata pelajaran & kelas untuk melihat analisis butir soal.</td></tr>`;
    countLabel.innerText = '0'; btnCetak.disabled = true; return;
  }

  let filteredData = finalGradedData.filter(d => d.mapel === mapel && (kelas === "ALL" || d.kelas === kelas));
  let totalSiswa = filteredData.length;
  countLabel.innerText = totalSiswa;
  if (totalSiswa === 0) {
    tbodyUI.innerHTML = `<tr><td colspan="7" style="text-align:center; padding: 40px; color:var(--text-muted); font-weight:600;">Data ujian belum tersedia.</td></tr>`;
    btnCetak.disabled = true; return;
  }

  let configMapel = masterKeys[mapel];
  if (!configMapel) {
    tbodyUI.innerHTML = `<tr><td colspan="7" style="text-align:center; padding: 40px; color:var(--danger); font-weight:600;">Kunci jawaban mapel ini tidak ditemukan.</td></tr>`;
    btnCetak.disabled = true; return;
  }

  let htmlUI = "", htmlPrint = "";
  let soalNumbers = Object.keys(configMapel.keys).map(Number).sort((a, b) => a - b);
  soalNumbers.forEach(no => {
    let benar = 0, salah = 0, kosong = 0;
    let kunci = String(configMapel.keys[no]).toUpperCase().replace(/\s+/g, '');
    filteredData.forEach(siswa => {
      let jwbSiswa = siswa.rawJawaban[no];
      let isBenar = false;
      if (jwbSiswa === undefined || jwbSiswa === null || jwbSiswa === '') {
        kosong++;
      } else {
        if (Array.isArray(jwbSiswa)) {
          let jwbSiswaStr = jwbSiswa.map(x => String(x).toUpperCase().replace(/\s+/g, '')).sort().join(",");
          let kunciSort = kunci.split(",").sort().join(",");
          if (jwbSiswaStr === kunciSort) isBenar = true;
        } else if (typeof jwbSiswa === 'object' && jwbSiswa !== null) {
          let jwbBS = [jwbSiswa.A || '', jwbSiswa.B || '', jwbSiswa.C || '', jwbSiswa.D || ''].join(",").toUpperCase().replace(/\s+/g, '');
          if (jwbBS === kunci) isBenar = true;
        } else if (String(jwbSiswa).toUpperCase().replace(/\s+/g, '') === kunci) {
          isBenar = true;
        }
        if (isBenar) benar++; else salah++;
      }
    });

    let persentaseBenar = ((benar / totalSiswa) * 100).toFixed(1);
    let persentaseNum = parseFloat(persentaseBenar);
    let badgeUI = "", textPrint = "";
    if (persentaseNum >= 71) {
      badgeUI = `<span style="background:#d1fae5; color:#065f46; padding:6px 12px; border-radius:8px; font-weight:800; font-size:12px;">MUDAH</span>`;
      textPrint = `<b>MUDAH</b>`;
    } else if (persentaseNum >= 31) {
      badgeUI = `<span style="background:#d1fae5; color:#0f766e; padding:6px 12px; border-radius:8px; font-weight:800; font-size:12px;">SEDANG</span>`;
      textPrint = `<b>SEDANG</b>`;
    } else {
      badgeUI = `<span style="background:#fee2e2; color:#991b1b; padding:6px 12px; border-radius:8px; font-weight:800; font-size:12px;">SULIT</span>`;
      textPrint = `<b>SULIT</b>`;
    }
    let colorBar = persentaseNum >= 71 ? '#10b981' : (persentaseNum >= 31 ? '#10b981' : '#ef4444');

    htmlUI += `<tr><td style="text-align:center; font-weight:bold;">${no}</td><td style="text-align:center; font-weight:900; color:var(--primary);">${escapeHtml(kunci)}</td><td style="text-align:center; color:var(--success); font-weight:800;">${benar}</td><td style="text-align:center; color:var(--danger); font-weight:800;">${salah}</td><td style="text-align:center; color:var(--text-muted); font-weight:800;">${kosong}</td><td style="text-align:center; font-weight:bold;"><div style="display:flex; flex-direction:column; align-items:center; gap:6px;"><span>${persentaseBenar}%</span><div style="width:100%; max-width:100px; background:#e2e8f0; height:8px; border-radius:4px; overflow:hidden;"><div style="width:${persentaseBenar}%; background:${colorBar}; height:100%;"></div></div></div></td><td style="text-align:center;">${badgeUI}</td></tr>`;
    htmlPrint += `<tr><td style="text-align:center;">${no}</td><td style="text-align:center;"><b>${escapeHtml(kunci)}</b></td><td style="text-align:center;">${benar}</td><td style="text-align:center;">${salah}</td><td style="text-align:center;">${kosong}</td><td style="text-align:center;">${persentaseBenar}%</td><td style="text-align:center;">${textPrint}</td></tr>`;
  });

  tbodyUI.innerHTML = htmlUI;
  tbodyPrint.innerHTML = htmlPrint;
  document.getElementById('p-analisis-mapel').innerText = mapel;
  document.getElementById('p-analisis-kelas').innerText = kelas === "ALL" ? "Semua Kelas" : kelas;
  document.getElementById('p-analisis-peserta').innerText = totalSiswa;
  document.getElementById('p-analisis-tanggal').innerText = new Intl.DateTimeFormat('id-ID', { day: 'numeric', month: 'long', year: 'numeric' }).format(new Date());
  btnCetak.disabled = false;
}

function executePrintAnalisis() {
  catatRiwayatAksiAdmin('ADMIN', document.getElementById('analisisMapelFilter').value || 'Data', 'CETAK ANALISIS SOAL');
  document.body.classList.add('print-analisis');
  setTimeout(() => { window.print(); document.body.classList.remove('print-analisis'); }, 400);
}

function executePrintBeritaAcara() {
  const vMapel = document.getElementById('mapelFilter').value;
  const vKelas = document.getElementById('kelasFilter').value;
  let targetData = finalGradedData.filter(d => d.mapel === vMapel && d.kelas === vKelas).sort((a, b) => a.nama.localeCompare(b.nama));
  if (targetData.length === 0) return;

  let tNilai = 0;
  let tbodyR = document.getElementById('r-printBody');
  let htmlCetak = '';
  targetData.forEach((s, i) => {
    tNilai += s.nilai;
    htmlCetak += `<tr><td style="text-align:center;">${i + 1}</td><td>${escapeHtml(s.nama)}</td><td style="text-align:center;">${s.benar}</td><td style="text-align:center;">${s.salah}</td><td style="text-align:center;"><b>${s.nilai}</b></td><td style="text-align:center; color:${s.vCount > 0 ? 'red' : 'black'}; font-weight:bold;">${s.vCount > 0 ? s.vCount : '-'}</td><td class="v-log-print">${s.vCount > 0 ? escapeHtml(s.vLogs.join(', ')) : '-'}</td></tr>`;
  });
  tbodyR.innerHTML = htmlCetak;
  document.getElementById('r-mapel').innerText = vMapel;
  document.getElementById('r-kelas').innerText = vKelas;
  document.getElementById('r-peserta').innerText = targetData.length;
  document.getElementById('r-avg').innerText = (tNilai / targetData.length).toFixed(1);
  document.getElementById('r-tanggal').innerText = new Intl.DateTimeFormat('id-ID', { day: 'numeric', month: 'long', year: 'numeric' }).format(new Date());

  catatRiwayatAksiAdmin('ADMIN', vMapel, 'CETAK BERITA ACARA');
  document.body.classList.add('print-berita');
  setTimeout(() => { window.print(); document.body.classList.remove('print-berita'); }, 400);
}

function exportToExcelAdmin() {
  const vMapel = document.getElementById('mapelFilter').value;
  const vKelas = document.getElementById('kelasFilter').value;
  let targetData = finalGradedData.filter(d => (vMapel === "ALL" || d.mapel === vMapel) && (vKelas === "ALL" || d.kelas === vKelas));
  if (targetData.length === 0) {
    Swal.fire({ icon: 'warning', title: 'Kosong', text: 'Tidak ada data untuk diekspor.', customClass: { popup: 'swal-custom-popup' } });
    return;
  }
  targetData.sort((a, b) => a.kelas.localeCompare(b.kelas) || a.nama.localeCompare(b.nama));

  let csvContent = "No,Nama Lengkap,Kelas,Mata Pelajaran,Benar,Salah,Nilai Akhir,Jumlah Pelanggaran,Log Aktivitas\n";
  targetData.forEach((s, idx) => {
    let logs = s.vCount > 0 ? s.vLogs.join(" | ") : "Aman";
    let row = [idx + 1, `"${s.nama.replace(/"/g, '""')}"`, `"${s.kelas}"`, `"${s.mapel}"`, s.benar, s.salah, s.nilai, s.vCount, `"${logs.replace(/"/g, '""')}"`];
    csvContent += row.join(",") + "\n";
  });
  let blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
  let link = document.createElement("a");
  link.href = URL.createObjectURL(blob);
  link.download = `Rekap_Nilai_${vMapel}_${vKelas}.csv`.replace(/\s+/g, '_');
  document.body.appendChild(link); link.click(); document.body.removeChild(link);
  catatRiwayatAksiAdmin('ADMIN', vMapel, 'EKSPOR EXCEL/CSV');
}

