document.addEventListener('DOMContentLoaded', () => {
  document.getElementById('docxInput')?.addEventListener('change', function (e) {
    if (!e.target.files.length) return;
    const file = e.target.files[0];
    document.getElementById('fileNameDocx').innerText = file.name;
    const reader = new FileReader();
    reader.onload = function (event) {
      mammoth.extractRawText({ arrayBuffer: event.target.result }).then(result => {
        parsedSoalData = smartParseText(result.value);
        if (parsedSoalData.length > 0) {
          Swal.fire({ title: 'Terekstrak!', text: `Berhasil memilah ${parsedSoalData.length} Soal.`, icon: 'success', customClass: { popup: 'swal-custom-popup', confirmButton: 'swal-custom-confirm' } });
          document.getElementById('btnSyncSoal').style.display = 'inline-flex';
        } else {
          Swal.fire({ title: 'Gagal', text: 'Pola soal tidak dikenali.', icon: 'error', customClass: { popup: 'swal-custom-popup', confirmButton: 'swal-custom-confirm' } });
        }
      }).catch(() => Swal.fire({ title: 'Error membaca file Word', icon: 'error', customClass: { popup: 'swal-custom-popup' } }));
    };
    reader.readAsArrayBuffer(file);
  });

  document.getElementById('csvSoalInput')?.addEventListener('change', function (e) {
    if (!e.target.files.length) return;
    const file = e.target.files[0];
    document.getElementById('fileNameSoal').innerText = file.name;
    Papa.parse(file, {
      header: true,
      skipEmptyLines: true,
      complete: function (results) {
        if (!results.meta.fields.includes('No') || !results.meta.fields.includes('Soal')) {
          Swal.fire({ title: 'Format Salah', text: 'Gunakan template CSV standar.', icon: 'error', customClass: { popup: 'swal-custom-popup', confirmButton: 'swal-custom-confirm' } });
          return;
        }
        parsedSoalData = results.data.map((row, i) => [
          row['No'] || (i + 1), row['Soal'] || "", row['Opsi A'] || "", row['Opsi B'] || "", row['Opsi C'] || "", row['Opsi D'] || "", row['Kunci'] || "A", "", "", "", "", "", row['Tipe Soal'] || "PG"
        ]);
        document.getElementById('btnSyncSoal').style.display = 'inline-flex';
        Swal.fire({ title: 'Terbaca', text: `${parsedSoalData.length} Soal CSV siap disinkronisasi.`, icon: 'success', customClass: { popup: 'swal-custom-popup', confirmButton: 'swal-custom-confirm' } });
      }
    });
  });
});

