function eksekusiPushSoal(mapelTujuan, isAppend) {
  const btn = document.getElementById('btnSyncSoal');
  btn.innerHTML = '<i class="fa-solid fa-spinner fa-spin"></i> Menyimpan ke Server...';
  btn.disabled = true;
  let namaFungsiServer = isAppend ? 'appendSoalMasalAdmin' : 'saveSoalAdmin';

  google.script.run.withSuccessHandler((res) => {
    btn.innerHTML = '<i class="fa-solid fa-cloud-arrow-up"></i> Tulis ke Spreadsheet Server';
    btn.disabled = false;
    if (res.success) {
      btn.style.display = 'none';
      parsedSoalData = [];
      document.getElementById('docxInput').value = "";
      document.getElementById('csvSoalInput').value = "";
      fetchSoalViewerAdmin();
      refreshMasterKeysAdmin();
      catatRiwayatAksiAdmin('ADMIN', mapelTujuan, isAppend ? 'IMPORT SOAL (TAMBAH)' : 'IMPORT SOAL (TIMPA)');
      Swal.fire({ title: 'Tersimpan!', text: res.message, icon: 'success', timer: 2000, showConfirmButton: false, customClass: { popup: 'swal-custom-popup' } });
    } else {
      Swal.fire({ title: 'Error API', text: res.message, icon: 'error', customClass: { popup: 'swal-custom-popup', confirmButton: 'swal-custom-confirm' } });
    }
  }).withFailureHandler(err => {
    btn.innerHTML = '<i class="fa-solid fa-cloud-arrow-up"></i> Tulis ke Spreadsheet Server';
    btn.disabled = false;
    Swal.fire({ title: 'Koneksi Terputus', text: err.message, icon: 'error', customClass: { popup: 'swal-custom-popup', confirmButton: 'swal-custom-confirm' } });
  })[namaFungsiServer](mapelTujuan, parsedSoalData);
}

function exportTXTAdmin() {
  if (!currentSoalMapel || currentSoalDataArray.length === 0) {
    Swal.fire({ icon: 'warning', title: 'Kosong', text: 'Tidak ada soal untuk diekspor.', customClass: { popup: 'swal-custom-popup', confirmButton: 'swal-custom-confirm' } });
    return;
  }
  let txtContent = `BANK SOAL: ${currentSoalMapel}\r\n=================================\r\n\r\n`;
  currentSoalDataArray.forEach(row => {
    let cleanSoal = (row[1] || "").toString().replace(/<[^>]*>?/gm, '');
    txtContent += `${row[0]}. ${cleanSoal}\r\nA. ${row[2] || ''}\r\nB. ${row[3] || ''}\r\nC. ${row[4] || ''}\r\nD. ${row[5] || ''}\r\nKunci: ${row[6] || 'A'}\r\nTipe: ${row[12] || 'PG'}\r\n\r\n`;
  });
  let blob = new Blob([txtContent], { type: "text/plain;charset=utf-8" });
  let link = document.createElement("a");
  link.href = URL.createObjectURL(blob);
  link.download = `Bank_Soal_${currentSoalMapel}.txt`;
  document.body.appendChild(link); link.click(); document.body.removeChild(link);
}

