function closeEditModal() { document.getElementById("editSoalModal").style.display = "none"; }

function uploadImageToGoogleScript(fileElement) {
  return new Promise((resolve, reject) => {
    if (!fileElement.files || fileElement.files.length === 0) { resolve(null); return; }
    let file = fileElement.files[0];
    let reader = new FileReader();
    reader.onload = function (e) {
      google.script.run.withSuccessHandler(res => {
        if (res.success) resolve(res.url); else reject(res.message);
      }).withFailureHandler(err => reject(err)).uploadImageToDrive(e.target.result, file.name);
    };
    reader.onerror = () => reject("Gagal membaca file gambar.");
    reader.readAsDataURL(file);
  });
}

async function simpanEditSoal() {
  let index = document.getElementById("eRowIndex").value;
  let mapel = currentSoalMapel;
  if (!mapel) return;
  Swal.fire({ title: 'Menyimpan Perubahan...', html: 'Mengunggah gambar (jika ada) dan memperbarui database.', allowOutsideClick: false, didOpen: () => Swal.showLoading(), customClass: { popup: 'swal-custom-popup' } });

  try {
    let [urlSoal, urlA, urlB, urlC, urlD] = await Promise.all([
      uploadImageToGoogleScript(document.getElementById("eSoalFile")),
      uploadImageToGoogleScript(document.getElementById("eOptAFile")),
      uploadImageToGoogleScript(document.getElementById("eOptBFile")),
      uploadImageToGoogleScript(document.getElementById("eOptCFile")),
      uploadImageToGoogleScript(document.getElementById("eOptDFile"))
    ]);

    let updatedRowData = [
      document.getElementById("eNo").value,
      document.getElementById("eSoalText").value,
      document.getElementById("eOptA").value,
      document.getElementById("eOptB").value,
      document.getElementById("eOptC").value,
      document.getElementById("eOptD").value,
      document.getElementById("eKunci").value.trim().toUpperCase(),
      urlSoal || document.getElementById("eSoalOldImg").value,
      urlA || document.getElementById("eOptAOldImg").value,
      urlB || document.getElementById("eOptBOldImg").value,
      urlC || document.getElementById("eOptCOldImg").value,
      urlD || document.getElementById("eOptDOldImg").value,
      document.getElementById("eTipeSoal").value || "PG"
    ];

    if (isEditMode) {
      currentSoalDataArray[index] = updatedRowData;
      google.script.run.withSuccessHandler(res => {
        if (res.success) {
          catatRiwayatAksiAdmin('ADMIN', mapel, 'EDIT SOAL');
          closeEditModal(); fetchSoalViewerAdmin(); refreshMasterKeysAdmin();
          Swal.fire({ icon: 'success', title: 'Tersimpan', text: 'Soal berhasil diperbarui.', timer: 1500, showConfirmButton: false, customClass: { popup: 'swal-custom-popup' } });
        } else {
          Swal.fire({ icon: 'error', title: 'Gagal', text: res.message, customClass: { popup: 'swal-custom-popup', confirmButton: 'swal-custom-confirm' } });
        }
      }).updateSoalAdminRow(mapel, index, updatedRowData);
    } else {
      currentSoalDataArray.push(updatedRowData);
      google.script.run.withSuccessHandler(res => {
        if (res.success) {
          catatRiwayatAksiAdmin('ADMIN', mapel, 'TAMBAH SOAL BARU');
          closeEditModal(); fetchSoalViewerAdmin(); refreshMasterKeysAdmin();
          Swal.fire({ icon: 'success', title: 'Tersimpan', text: 'Soal baru berhasil ditambahkan.', timer: 1500, showConfirmButton: false, customClass: { popup: 'swal-custom-popup' } });
        } else {
          Swal.fire({ icon: 'error', title: 'Gagal', text: res.message, customClass: { popup: 'swal-custom-popup', confirmButton: 'swal-custom-confirm' } });
        }
      }).saveSoalAdmin(mapel, currentSoalDataArray);
    }
  } catch (error) {
    Swal.fire({ icon: 'error', title: 'Gagal Upload', text: error.toString(), customClass: { popup: 'swal-custom-popup', confirmButton: 'swal-custom-confirm' } });
  }
}

// --- FITUR GENERATOR KARTU PESERTA & CETAK SATUAN ---
function getWarnaKelasKartu() { return "#059669"; }

function tarikDataKartuAdmin() {
  const linkQR = document.getElementById("inpLinkQR").value;
  if (!linkQR) {
    Swal.fire({ icon: 'warning', title: 'Tautan Kosong', text: 'Tautan/Link QR Code wajib diisi!', customClass: { popup: 'swal-custom-popup', confirmButton: 'swal-custom-confirm' } });
    return;
  }
  Swal.fire({ title: 'Sinkronisasi Data Peserta...', didOpen: () => Swal.showLoading(), allowOutsideClick: false, customClass: { popup: 'swal-custom-popup' } });

  google.script.run.withSuccessHandler((res) => {
    if (res.success && res.data.length > 0) {
      globalDataKartu = res.data;
      document.getElementById("pencarian-box").style.display = "block";
      filterKartuSiswaRealtime();
    } else {
      Swal.fire({ title: 'Data Kosong', text: res.message || "Sheet Users masih kosong.", icon: 'warning', customClass: { popup: 'swal-custom-popup', confirmButton: 'swal-custom-confirm' } });
    }
  }).getSiswaKartuAdmin();
}

let timerFilterKartu = null;
function filterKartuSiswaRealtime() {
  clearTimeout(timerFilterKartu);
  timerFilterKartu = setTimeout(() => {
    const keyword = (document.getElementById("inpCariNamaKartu").value || "").toLowerCase();
    const filterKelasTarget = document.getElementById("inpFilterKelasKartu").value;
    const linkQR = document.getElementById("inpLinkQR").value;
    const periode = document.getElementById("inpPeriode").value;

    let filteredSiswa = globalDataKartu;
    if (filterKelasTarget !== "ALL") filteredSiswa = filteredSiswa.filter(s => s.kelas.startsWith(filterKelasTarget));
    if (keyword.trim() !== "") filteredSiswa = filteredSiswa.filter(s => s.nama.toLowerCase().includes(keyword) || s.user.toLowerCase().includes(keyword));

    if (filteredSiswa.length === 0) {
      document.getElementById("print-area-internal").innerHTML = `<div style="text-align:center; padding: 30px; font-weight: bold; color: var(--danger);">Siswa tidak ditemukan!</div>`;
      document.getElementById("printKartuArea").innerHTML = "";
      document.getElementById("btnCetakKartuMasal").disabled = true;
      return;
    }
    renderHalamanA4Kartu(filteredSiswa, globalConfig.title, linkQR, periode);
  }, 300);
}

async function renderHalamanA4Kartu(siswaList, namaSekolah, linkQR, periode) {
  const printArea = document.getElementById("print-area-internal");
  const previewBox = document.getElementById("preview-box");
  const printAreaGlobal = document.getElementById("printKartuArea");

  Swal.fire({
    title: 'Menyiapkan Kartu Peserta...',
    html: `Memproses QR Code <b id="qr-progress" style="color:var(--primary);">0</b> dari <b>${siswaList.length}</b> kartu.<br><br><div style="width:100%; background:#e2e8f0; height:8px; border-radius:4px; overflow:hidden;"><div id="qr-bar" style="width:0%; background:var(--primary); height:100%; transition:0.2s;"></div></div>`,
    allowOutsideClick: false, showConfirmButton: false, customClass: { popup: 'swal-custom-popup' }
  });

  let html = "";
  let count = 0;
  const chunkSize = 25;
  let cacheDiv = document.createElement("div");

  for (let i = 0; i < siswaList.length; i += chunkSize) {
    let chunk = siswaList.slice(i, i + chunkSize);
    chunk.forEach((siswa, chunkIdx) => {
      let index = i + chunkIdx;
      const warnaBanner = getWarnaKelasKartu(siswa.kelas);
      const uniqueQRData = `${linkQR}?user=${encodeURIComponent(siswa.user)}`;

      cacheDiv.innerHTML = "";
      new QRCode(cacheDiv, { text: uniqueQRData, width: 58, height: 58, colorDark: "#0F172A", colorLight: "#ffffff", correctLevel: QRCode.CorrectLevel.M });
      const qrCanvas = cacheDiv.querySelector("canvas");
      const qrImg = cacheDiv.querySelector("img");
      const qrImageSrc = qrCanvas ? qrCanvas.toDataURL("image/png") : (qrImg ? qrImg.src : "");

      if (count % 8 === 0) html += `<div class="a4-sheet">`;
      let safeUser = siswa.user.replace(/'/g, "\\'");
      html += `
        <div class="card-compact">
          <div class="card-main-content">
            <div class="card-header-pro"><img src="${base64LogoKartu}" class="card-logo-pro"><div class="header-text-pro"><h4>Kartu Peserta Ujian CBT</h4><h3>${escapeHtml(namaSekolah.toUpperCase())}</h3></div></div>
            <div class="card-body-pro">
              <table class="data-table-pro">
                <tr><td class="lbl-p">Nama</td><td class="sep-p">:</td><td class="val-p val-nama-p">${escapeHtml(siswa.nama)}</td></tr>
                <tr><td class="lbl-p">Kelas</td><td class="sep-p">:</td><td class="val-p">${escapeHtml(siswa.kelas)}</td></tr>
                <tr><td class="lbl-p">No. Absen</td><td class="sep-p">:</td><td class="val-p">${siswa.absen}</td></tr>
                <tr><td class="lbl-p">Username</td><td class="sep-p">:</td><td class="val-user-p">${escapeHtml(siswa.user)}</td></tr>
                <tr><td class="lbl-p">Password</td><td class="sep-p">:</td><td><span class="val-pwd-p">${escapeHtml(siswa.pass)}</span></td></tr>
              </table>
              <div class="qr-box-pro"><img src="${qrImageSrc}" alt="QR"></div>
            </div>
            <div class="card-footer-pro"><span>*Simpan & rahasiakan kartu ini</span><span style="font-weight:700;">${escapeHtml(periode)}</span></div>
          </div>
          <div class="side-banner" style="background-color: ${warnaBanner};">PESERTA CBT</div>
          <div class="btn-cetak-single print-hidden"><button onclick="cetakSatuKartuKhusus('${safeUser}')"><i class="fa-solid fa-print"></i> Cetak</button></div>
        </div>`;
      count++;
      if (count % 8 === 0 || index === siswaList.length - 1) html += `</div>`;
    });

    let processed = Math.min(i + chunkSize, siswaList.length);
    let percent = Math.round((processed / siswaList.length) * 100);
    if (document.getElementById('qr-progress')) document.getElementById('qr-progress').innerText = processed;
    if (document.getElementById('qr-bar')) document.getElementById('qr-bar').style.width = percent + '%';
    await new Promise(resolve => setTimeout(resolve, 15));
  }

  printArea.innerHTML = html;
  printAreaGlobal.innerHTML = html;
  previewBox.style.display = "block";
  document.getElementById("btnCetakKartuMasal").disabled = false;
  Swal.close();
}

function cetakSatuKartuKhusus(usernameTarget) {
  const siswa = globalDataKartu.find(s => s.user === usernameTarget);
  if (!siswa) return;
  const linkQR = document.getElementById("inpLinkQR").value;
  const periode = document.getElementById("inpPeriode").value;
  renderHalamanA4Kartu([siswa], globalConfig.title, linkQR, periode).then(() => {
    executePrintKartuAdmin();
  });
}

function executePrintKartuAdmin() {
  catatRiwayatAksiAdmin('ADMIN', 'Data Kartu Peserta', 'CETAK KARTU PESERTA');
  document.body.classList.add('print-kartu');
  setTimeout(() => { window.print(); document.body.classList.remove('print-kartu'); }, 400);
}

