// --- 9. MONITORING SISWA REALTIME ---
function initLiveUserCounter() {
  if (!supabaseClient) return;
  const sessionKey = 'user_' + Math.random().toString(36).substring(2, 12);
  presenceChannel = supabaseClient.channel('ruang-ujian-aktif', {
    config: { presence: { key: sessionKey }, broadcast: { ack: true } }
  });

  presenceChannel.on('broadcast', { event: 'kick_user' }, (payload) => {
    if (payload.payload.namaSiswa === studentData.name) {
      if (payload.payload.mapel === studentData.subject || payload.payload.mapel === '-') {
        isExamActive = false;
        clearInterval(timerInterval);
        if (strictInterval) clearInterval(strictInterval);
        localStorage.removeItem(getStorageKey());
        exitFullScreenOnly();
        document.getElementById('exam-section').classList.add('hidden');
        document.getElementById('dashboard-section').classList.add('hidden');
        document.getElementById('login-section').classList.remove('hidden');
        document.getElementById('btn-admin-login').classList.remove('hidden');
        studentData = { kelas: '', name: '', email: '', subject: '' };
        lastTrackedState = "";
        Swal.fire({ icon: 'error', title: 'Sesi Dihentikan!', text: 'Pengawas ujian telah mengeluarkan Anda dari sesi ujian.', allowOutsideClick: false, customClass: { popup: 'swal-custom-popup', confirmButton: 'swal-custom-confirm' } });
      }
    }
  });

  presenceChannel.on('presence', { event: 'sync' }, () => {
    const newState = presenceChannel.presenceState();
    daftarSiswaOnline = newState;
    let totalSiswaOnline = 0;
    for (let id in newState) {
      let state = newState[id][0];
      if (state && state.tipe === 'siswa' && state.nama && state.nama !== 'Admin') {
        totalSiswaOnline++;
        if (document.body.classList.contains('admin-mode')) {
          catatRiwayatLoginAdmin(state.nama, state.kelas || '-', state.mapel || '-');
        }
      }
    }

    const countElAdmin = document.getElementById('admin-tot-mengerjakan');
    if (countElAdmin) countElAdmin.innerText = totalSiswaOnline;
    if (!document.getElementById('tab-monitor').classList.contains('hidden')) {
      renderTabelMonitorAdmin();
    }
  });

  presenceChannel.subscribe(async (status) => {
    if (status === 'SUBSCRIBED') {
      setInterval(async () => {
        let isAdmin = document.body.classList.contains('admin-mode');
        if (!isAdmin && (!studentData || !studentData.name)) return;
        let tipeUser = isAdmin ? 'admin' : 'siswa';
        let namaAktif = isAdmin ? 'Admin' : studentData.name;
        let kelasAktif = isAdmin ? '-' : (studentData.kelas || '-');
        let mapelAktif = isAdmin ? '-' : (studentData.subject || '-');
        let currentState = `${tipeUser}_${namaAktif}_${kelasAktif}_${mapelAktif}`;

        if (currentState !== lastTrackedState) {
          await presenceChannel.track({
            online_at: new Date().toISOString(),
            status: 'aktif',
            tipe: tipeUser,
            nama: namaAktif,
            kelas: kelasAktif,
            mapel: mapelAktif
          });
          lastTrackedState = currentState;
        }
      }, 2500);
    }
  });
}

function renderTabelMonitorAdmin() {
  const tbody = document.getElementById('monitorBody');
  if (!tbody) return;
  const filterKelas = document.getElementById('monitorKelasFilter').value;
  const filterMapel = document.getElementById('monitorMapelFilter').value;
  const keyword = (document.getElementById('monitorCariNama').value || "").toLowerCase();

  let onlineMap = {};
  let totalSiswaOnline = 0;
  for (let key in daftarSiswaOnline) {
    let state = daftarSiswaOnline[key][0];
    if (state && state.tipe === 'siswa' && state.nama && state.nama !== 'Admin') {
      onlineMap[state.nama.trim().toLowerCase()] = state;
      totalSiswaOnline++;
    }
  }

  const countLabel = document.getElementById('monitorCountLabel');
  if (countLabel) countLabel.innerText = totalSiswaOnline;

  let targetSiswa = globalDataKartu;
  if (!targetSiswa || targetSiswa.length === 0) {
    tbody.innerHTML = `<tr><td colspan="5" style="text-align: center; padding: 40px; color: var(--text-muted);">Data siswa pada Sheet Users masih kosong atau sedang dimuat...</td></tr>`;
    return;
  }

  let filteredUsers = targetSiswa.filter(u => {
    let matchKelas = (filterKelas === 'ALL' || u.kelas.startsWith(filterKelas));
    let matchNama = u.nama.toLowerCase().includes(keyword);
    return matchKelas && matchNama;
  });

  let html = '';
  let rowNumber = 1;
  let isDataFound = false;

  filteredUsers.sort((a, b) => a.kelas.localeCompare(b.kelas) || a.nama.localeCompare(b.nama)).forEach(siswaDb => {
    let normalizedNamaDb = siswaDb.nama.trim().toLowerCase();
    let onlineState = onlineMap[normalizedNamaDb];
    let isOnline = !!onlineState;
    let currentMapel = isOnline ? onlineState.mapel : null;

    let matchStatus = true;
    if (filterMapel === 'OFFLINE') matchStatus = !isOnline;
    else if (filterMapel === '-') matchStatus = (isOnline && currentMapel === '-');
    else if (filterMapel === 'MENGERJAKAN') matchStatus = (isOnline && currentMapel !== '-');
    if (!matchStatus) return;

    isDataFound = true;
    let aktivitasLabel = "", infoWarning = "", tombolAksi = "";
    if (isOnline) {
      if (currentMapel !== '-') {
        aktivitasLabel = `<span style="background: #d1fae5; color: #065f46; padding: 6px 10px; border-radius: 6px; font-weight: 800; font-size: 11px; border: 1px solid #6ee7b7;"><i class="fa-solid fa-pen-nib"></i> Mengerjakan: ${escapeHtml(currentMapel)}</span>`;
      } else {
        aktivitasLabel = `<span style="background: #d1fae5; color: #059669; padding: 6px 10px; border-radius: 6px; font-weight: 800; font-size: 11px; border: 1px solid #a7f3d0;"><i class="fa-solid fa-house"></i> Di Dashboard (Belum Pilih Mapel)</span>`;
        infoWarning = `<br><span style="font-size:10.5px; color:var(--warning); font-weight:bold; display:inline-block; margin-top:6px;"><i class="fa-solid fa-triangle-exclamation"></i> Menunda masuk ujian.</span>`;
      }
      let safeNama = siswaDb.nama.replace(/'/g, "\\'");
      let safeMapel = currentMapel.replace(/'/g, "\\'");
      tombolAksi = `<button onclick="resetSiswaRealtime('${safeNama}', '${safeMapel}')" style="background:#ef4444; color:white; border:none; padding:8px 12px; border-radius:8px; font-weight:bold; cursor:pointer; font-size:12px;"><i class="fa-solid fa-person-falling-burst"></i> Reset & Kick</button>`;
    } else {
      aktivitasLabel = `<span style="background: #f1f5f9; color: #64748b; padding: 6px 10px; border-radius: 6px; font-weight: 800; font-size: 11px; border: 1px solid #cbd5e1;"><i class="fa-solid fa-power-off"></i> Offline</span>`;
      tombolAksi = `<span style="color:#94a3b8; font-size:11px; font-weight:bold;">-</span>`;
    }

    html += `<tr style="${!isOnline ? 'background-color: #f8fafc;' : ''}">
      <td style="text-align: center; font-weight: bold; color: var(--text-muted);">${rowNumber}</td>
      <td style="font-weight: bold; color: var(--text-main);"><i class="fa-solid fa-circle" style="font-size:9px; color: ${isOnline ? '#10b981' : '#cbd5e1'}; margin-right: 8px;"></i> ${escapeHtml(siswaDb.nama)}</td>
      <td style="text-align:center;"><span style="background: var(--bg-color); color: var(--primary); padding: 4px 8px; border-radius: 6px; font-weight: bold; font-size: 12px;">${escapeHtml(siswaDb.kelas)}</span></td>
      <td>${aktivitasLabel} ${infoWarning}</td>
      <td style="text-align: center;">${tombolAksi}</td>
    </tr>`;
    rowNumber++;
  });

  if (!isDataFound) {
    html = `<tr><td colspan="5" style="text-align: center; padding: 40px; color: var(--text-muted);">Tidak ada siswa yang sesuai dengan filter.</td></tr>`;
  }
  tbody.innerHTML = html;
}

function resetSiswaRealtime(namaSiswa, mapelTarget) {
  let msgText = mapelTarget === '-'
    ? `Keluarkan paksa <b>${escapeHtml(namaSiswa)}</b> dari halaman Dashboard?`
    : `Hapus jawaban & keluarkan <b>${escapeHtml(namaSiswa)}</b> dari ujian <b>${escapeHtml(mapelTarget)}</b>?`;

  Swal.fire({
    title: 'Konfirmasi Reset & Kick',
    html: msgText,
    icon: 'warning',
    showCancelButton: true,
    confirmButtonText: 'Ya, Eksekusi',
    cancelButtonText: 'Batal',
    customClass: { popup: 'swal-custom-popup', confirmButton: 'swal-custom-confirm' }
  }).then(async (result) => {
    if (result.isConfirmed) {
      Swal.fire({ title: 'Memproses...', didOpen: () => Swal.showLoading(), allowOutsideClick: false, customClass: { popup: 'swal-custom-popup' } });
      try {
        if (mapelTarget !== '-') {
          const { error } = await supabaseClient.from('jawaban_ujian').delete().eq('nama', namaSiswa).eq('mapel', mapelTarget);
          if (error) throw error;
        }
        if (presenceChannel) {
          await presenceChannel.send({ type: 'broadcast', event: 'kick_user', payload: { namaSiswa: namaSiswa, mapel: mapelTarget } });
        }
        catatRiwayatAksiAdmin('ADMIN', mapelTarget === '-' ? 'DASHBOARD' : mapelTarget, `RESET & KICK: ${namaSiswa}`);
        Swal.fire({ icon: 'success', title: 'Berhasil', text: `Sesi ${namaSiswa} telah direset.`, timer: 1800, showConfirmButton: false, customClass: { popup: 'swal-custom-popup' } });
        tarikDataSupabaseSilent();
      } catch (err) {
        Swal.fire({ icon: 'error', title: 'Error API', text: err.message, customClass: { popup: 'swal-custom-popup', confirmButton: 'swal-custom-confirm' } });
      }
    }
  });
}

// --- 10. RIWAYAT AKSES LOKAL (ADMIN) ---
function catatRiwayatAksiAdmin(nama, mapel, status) {
  const now = new Date();
  const dateStr = now.toLocaleDateString('id-ID', { day: '2-digit', month: 'short', year: 'numeric' });
  const timeStr = now.toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit', second: '2-digit' });
  let logItem = { waktu: `${dateStr} - ${timeStr}`, nama: nama, mapel: mapel, status: status };
  riwayatLogAkses.unshift(logItem);
  if (riwayatLogAkses.length > 300) riwayatLogAkses.pop();
  localStorage.setItem('admin_riwayat_akses', JSON.stringify(riwayatLogAkses));
  if (!document.getElementById('tab-riwayat').classList.contains('hidden')) {
    renderTabelRiwayatLengkap();
  }
}

function catatRiwayatLoginAdmin(nama, kelas, mapel) {
  let jamStr = new Date().toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit' });
  let statusTarget = mapel !== '-' ? 'MASUK UJIAN' : 'LOGIN DASHBOARD';
  let isDuplicate = riwayatLogAkses.some(log => log.nama === nama && log.mapel === mapel && log.status === statusTarget && log.waktu.includes(jamStr));
  if (!isDuplicate) {
    catatRiwayatAksiAdmin(nama, mapel !== '-' ? mapel : 'Dashboard', statusTarget);
  }
}

function renderTabelRiwayatLengkap() {
  const tbody = document.getElementById('riwayatBody');
  if (!tbody) return;
  if (riwayatLogAkses.length === 0) {
    tbody.innerHTML = `<tr><td colspan="4" style="text-align:center; padding: 60px; color:var(--text-muted);">Belum ada rekaman aktivitas pada sesi ini.</td></tr>`;
    return;
  }

  let htmlRiwayat = '';
  riwayatLogAkses.forEach(log => {
    let colorStatus = 'color: #0284c7; background: #e0f2fe; border: 1px solid #7dd3fc;';
    let iconStatus = '<i class="fa-solid fa-right-to-bracket"></i>';
    let isAdminAction = log.nama === 'ADMIN';

    if (log.status.includes('KICK') || log.status.includes('RESET') || log.status.includes('HAPUS')) {
      colorStatus = 'color: var(--danger); background: #ffe4e6; border: 1px solid #fda4af;';
      iconStatus = '<i class="fa-solid fa-trash-can"></i>';
    } else if (log.status.includes('MASUK UJIAN')) {
      colorStatus = 'color: var(--success); background: #d1fae5; border: 1px solid #6ee7b7;';
      iconStatus = '<i class="fa-solid fa-pen-nib"></i>';
    } else if (log.status.includes('CETAK') || log.status.includes('EKSPOR')) {
      colorStatus = 'color: #334155; background: #e2e8f0; border: 1px solid #cbd5e1;';
      iconStatus = '<i class="fa-solid fa-print"></i>';
    } else if (log.status.includes('SOAL') || log.status.includes('IMPORT') || log.status.includes('AI')) {
      colorStatus = 'color: #6d28d9; background: #ede9fe; border: 1px solid #c4b5fd;';
      iconStatus = '<i class="fa-solid fa-database"></i>';
    }

    let userDisplay = isAdminAction
      ? `<i class="fa-solid fa-user-tie" style="color:var(--primary); margin-right:6px;"></i> <span style="color:var(--primary); font-weight:900;">ADMINISTRATOR</span>`
      : `<i class="fa-solid fa-user" style="color:#94a3b8; margin-right:6px;"></i> ${escapeHtml(log.nama)}`;

    htmlRiwayat += `<tr style="border-bottom: 1px solid #f1f5f9;">
      <td style="color:#64748b; font-weight: 600; font-size: 13px;">${escapeHtml(log.waktu)}</td>
      <td style="font-weight:bold; color:var(--text-main);">${userDisplay}</td>
      <td><span style="background:var(--bg-color); padding:4px 8px; border-radius:6px; font-size:12px; font-weight:800; color:var(--teal);">${escapeHtml(log.mapel)}</span></td>
      <td style="text-align:right;"><span style="padding:6px 12px; border-radius:8px; font-weight:bold; font-size:11px; display:inline-block; ${colorStatus}">${iconStatus} ${escapeHtml(log.status)}</span></td>
    </tr>`;
  });
  tbody.innerHTML = htmlRiwayat;
}

function hapusRiwayatAksesLokal() {
  Swal.fire({
    title: 'Bersihkan Log Aktivitas?',
    text: 'Seluruh rekaman log lokal di perangkat ini akan dihapus.',
    icon: 'warning',
    showCancelButton: true,
    confirmButtonColor: '#e11d48',
    confirmButtonText: 'Bersihkan',
    cancelButtonText: 'Batal',
    customClass: { popup: 'swal-custom-popup', confirmButton: 'swal-custom-confirm' }
  }).then((result) => {
    if (result.isConfirmed) {
      riwayatLogAkses = [];
      localStorage.removeItem('admin_riwayat_akses');
      renderTabelRiwayatLengkap();
    }
  });
}

function lihatRiwayatAkses() {
  let btnTabRiwayat = document.querySelector('.admin-tab-btn[onclick*="riwayat"]');
  if (btnTabRiwayat) switchAdminTab('riwayat', btnTabRiwayat);
}

document.addEventListener("DOMContentLoaded", () => {
  setTimeout(initLiveUserCounter, 800);
});

