// 11. LOGIKA RUANG BELAJAR KONSTRUKTIF (AI TUTOR & QNA SISWA-GURU)
// =====================================================================
let activeLMSSubject = "";
let activeLMSModule = null;
let activeLMSStep = 1; // 1: Pemantik, 2: Eksplorasi Konsep, 3: Kartu Pintar 3D, 4: Studi Kasus & Refleksi, 5: Kuis Formatif
let studentLMSQuizAnswers = {};
let studentLMSReflectionText = "";
let aiTutorChatHistory = {}; // Riwayat chat Asisten Belajar AI per modul

function kembaliKeDashboardSiswa() {
  document.body.classList.remove('lms-zen-mode', 'lms-native-android-mode');
  playStudentSFX('click');
  if ('speechSynthesis' in window) window.speechSynthesis.cancel();
  document.getElementById('lms-learning-section').classList.add('hidden');
  document.getElementById('dashboard-section').classList.remove('hidden');
  window.scrollTo({ top: 0, behavior: 'smooth' });
  loadSubjects();
}

function bersihkanKomponenLMSSebelumUjian() {
  if ('speechSynthesis' in window) {
    try { window.speechSynthesis.cancel(); } catch (e) {}
  }
  const fabAi = document.getElementById('fabAiTutorBtn');
  if (fabAi) fabAi.classList.add('hidden');
  const aiDrawer = document.getElementById('aiTutorDrawer');
  if (aiDrawer) aiDrawer.classList.remove('open');
  const notesDrawer = document.getElementById('studentNotesDrawer');
  if (notesDrawer) notesDrawer.classList.remove('open');
  const dockBtnAi = document.getElementById('dock-btn-ai');
  if (dockBtnAi) dockBtnAi.classList.remove('active');
  const dockBtnNotes = document.getElementById('dock-btn-notes');
  if (dockBtnNotes) dockBtnNotes.classList.remove('active');
  document.body.classList.remove('lms-zen-mode', 'lms-native-android-mode');
  if (typeof closeModuleProgressNotificationHud === 'function') {
    try { closeModuleProgressNotificationHud(); } catch (e) {}
  }
}

function mulaiUjianDariLMS() {
  if (!activeLMSSubject) return;
  bersihkanKomponenLMSSebelumUjian();
  document.getElementById('lms-learning-section').classList.add('hidden');
  document.getElementById('dashboard-section').classList.remove('hidden');
  startExam(activeLMSSubject);
}

