function openStudentLMS(mapelName) {
  activeLMSSubject = mapelName;
  document.getElementById('dashboard-section').classList.add('hidden');
  document.getElementById('lms-learning-section').classList.remove('hidden');
  document.getElementById('lms-active-mapel-badge').innerText = mapelName.toUpperCase();
  const fabAi = document.getElementById('fabAiTutorBtn');
  if (fabAi) fabAi.classList.add('hidden');

  let subObj = (globalLMSDashboard.subjects || []).find(s => s.name === mapelName);
  let modules = (subObj && subObj.modules && subObj.modules.length > 0)
    ? subObj.modules
    : [getDefaultConstructiveModule(mapelName)];

  const selectorBar = document.getElementById('lms-module-selector-bar');
  selectorBar.innerHTML = '';
  modules.forEach((mod, idx) => {
    let isDone = globalLMSDashboard.completedMap && globalLMSDashboard.completedMap[mod.id] !== undefined;
    let rec = isDone ? globalLMSDashboard.completedMap[mod.id] : null;
    selectorBar.innerHTML += `
      <button type="button" id="btn-sel-mod-${idx}" class="lms-module-select-card ${idx === 0 ? 'active-mod-card' : ''}" onclick="selectStudentLMSModule(${idx})">
        <div style="width:44px; height:44px; border-radius:14px; background:${isDone ? '#d1fae5' : '#d1fae5'}; color:${isDone ? '#059669' : '#059669'}; display:flex; align-items:center; justify-content:center; font-size:18px; flex-shrink:0;">
          <i class="fa-solid ${isDone ? 'fa-circle-check' : 'fa-book-open-reader'}"></i>
        </div>
        <div style="flex:1; min-width:0;">
          <div style="font-size:11px; font-weight:800; color:#047857; text-transform:uppercase;">MODUL / BAB ${idx + 1} ${isDone ? '• TUNTAS (' + rec.skor + ')' : ''}</div>
          <div style="font-size:14px; font-weight:800; color:var(--text-main); line-height:1.35; margin-top:2px;">${escapeHtml(mod.judul)}</div>
        </div>
      </button>`;
  });

  window.currentSubjectModulesList = modules;
  selectStudentLMSModule(0);
}

function selectStudentLMSModule(modIdx) {
  const modules = window.currentSubjectModulesList || [];
  if (!modules[modIdx]) return;
  activeLMSModule = modules[modIdx];
  activeLMSStep = 1;
  studentLMSQuizAnswers = {};
  studentLMSReflectionText = "";

  modules.forEach((_, i) => {
    let btn = document.getElementById('btn-sel-mod-' + i);
    if (btn) {
      btn.classList.toggle('active-mod-card', i === modIdx);
    }
  });

  document.getElementById('lms-active-module-title').innerText = activeLMSModule.judul;
  renderConstructiveWorkspace();
  syncAITutorDrawerContent();
}

function switchLMSStep(stepNum) {
  activeLMSStep = stepNum;
  renderConstructiveWorkspace();
  window.scrollTo({ top: 0, behavior: 'smooth' });
}

function renderConstructiveWorkspace() {
  const ws = document.getElementById('lms-constructive-workspace');
  if (!activeLMSModule) return;
  const k = activeLMSModule.konten || {};
  const kuis = Array.isArray(activeLMSModule.kuis) ? activeLMSModule.kuis : [];
  const prevRecord = (globalLMSDashboard.completedMap || {})[activeLMSModule.id];

  const stepsMeta = [
    { num: 1, icon: 'fa-lightbulb', label: '1. Pemantik & Tujuan' },
    { num: 2, icon: 'fa-compass', label: '2. Eksplorasi Konsep' },
    { num: 3, icon: 'fa-clone', label: '3. Kartu Pintar 3D' },
    { num: 4, icon: 'fa-puzzle-piece', label: '4. Studi Kasus & Refleksi' },
    { num: 5, icon: 'fa-trophy', label: '5. Kuis & Klaim XP' }
  ];

  let stepperHtml = `<div class="lms-stepper">`;
  stepsMeta.forEach(st => {
    let cls = (st.num === activeLMSStep) ? 'active' : (st.num < activeLMSStep ? 'done' : '');
    stepperHtml += `
      <div class="lms-step-item ${cls}" onclick="switchLMSStep(${st.num})">
        <i class="fa-solid ${st.num < activeLMSStep ? 'fa-circle-check' : st.icon}" style="font-size:16px;"></i>
        <span>${st.label}</span>
      </div>`;
  });
  stepperHtml += `</div>`;

  let stepBodyHtml = '';

  // Rakit tampilan Media Visual / Gambar Tujuan Pembelajaran yang diunggah manual oleh Guru
  let galeriTujuan = Array.isArray(k.galeri_tujuan) ? k.galeri_tujuan : (k.gambar_tujuan ? [{ url: k.gambar_tujuan, caption: 'Ilustrasi Visual Materi' }] : []);
  let visualTujuanHtml = '';
  if (galeriTujuan.length > 0) {
    let itemsHtml = galeriTujuan.map((g, gIdx) => `
      <div class="student-visual-card">
        <img src="${g.url}" alt="Gambar Materi ${gIdx + 1}" onclick="openLightbox('${g.url}')" title="Klik untuk memperbesar gambar">
        <div style="padding:10px 14px; display:flex; justify-content:space-between; align-items:center; gap:8px;">
          <span style="font-size:12.5px; font-weight:800; color:#065f46; text-align:left;"><i class="fa-solid fa-image" style="color:#059669;"></i> ${escapeHtml(g.caption || ('Media Visual #' + (gIdx + 1)))}</span>
          <button onclick="openLightbox('${g.url}')" style="background:#059669; color:white; border:none; padding:5px 10px; border-radius:8px; font-size:11px; font-weight:800; cursor:pointer; white-space:nowrap;">
            <i class="fa-solid fa-magnifying-glass-plus"></i> Perbesar
          </button>
        </div>
      </div>`).join('');

    visualTujuanHtml = `
      <div class="student-visual-tujuan-box">
        <div style="display:flex; justify-content:space-between; align-items:center; flex-wrap:wrap; gap:8px;">
          <div style="font-size:14.5px; font-weight:800; color:#047857;">
            <i class="fa-solid fa-chalkboard-user"></i> Media Visual & Ilustrasi Materi dari Guru (Klik Gambar untuk Zoom)
          </div>
          <span style="background:#d1fae5; color:#065f46; padding:4px 10px; border-radius:99px; font-size:11px; font-weight:800;">${galeriTujuan.length} Gambar Pendukung</span>
        </div>
        <div class="student-visual-grid">${itemsHtml}</div>
      </div>`;
  }

  if (activeLMSStep === 1) {
    stepBodyHtml = `
      <div style="background:linear-gradient(135deg, #ecfdf5, #d1fae5); border:2px solid #a7f3d0; border-radius:24px; padding:30px; margin-bottom:20px;">
        <div style="display:flex; justify-content:space-between; align-items:center; flex-wrap:wrap; gap:10px; margin-bottom:15px;">
          <span style="background:#059669; color:white; padding:6px 14px; border-radius:20px; font-size:12px; font-weight:800;"><i class="fa-solid fa-bullseye"></i> TUJUAN PEMBELAJARAN TERBIMBING</span>
          <span style="font-size:12.5px; color:#065f46; font-weight:700;"><i class="fa-solid fa-chalkboard-user"></i> Disusun oleh: ${escapeHtml(activeLMSModule.pembuat || 'Guru SMPN 3 Bangil')}</span>
        </div>
        <p style="font-size:16px; font-weight:700; color:#064e3b; line-height:1.6; margin-bottom:20px;">${escapeHtml(activeLMSModule.tujuan)}</p>
        
        ${visualTujuanHtml}
        ${buildStudentVideoAnalysisHubHTML(activeLMSModule)}

        <div style="background:white; border-radius:20px; padding:24px; border-left:6px solid #10b981; box-shadow:0 8px 25px rgba(5, 150, 105,0.08);">
          <h4 style="font-size:16px; font-weight:800; color:#047857; margin-bottom:10px;"><i class="fa-solid fa-wand-magic-sparkles"></i> Pertanyaan Pemantik & Apersepsi Kontekstual</h4>
          <p style="font-size:15.5px; color:var(--text-main); line-height:1.8;">${formatSoalText(k.pemantik || 'Mari amati bagaimana topik ini bekerja dalam kehidupan sehari-hari kita!')}</p>
        </div>
      </div>
      <div style="display:flex; justify-content:flex-end;">
        <button onclick="switchLMSStep(2)" style="background:var(--gradient-main); color:white; border:none; padding:16px 28px; border-radius:16px; font-weight:800; font-size:15px; cursor:pointer; box-shadow:0 10px 20px rgba(5, 150, 105,0.25);">
          Mulai Eksplorasi Konsep <i class="fa-solid fa-arrow-right"></i>
        </button>
      </div>`;
  } else if (activeLMSStep === 2) {
    let subMateriArr = (k.eksplorasi && Array.isArray(k.eksplorasi.sub_materi)) ? k.eksplorasi.sub_materi : [];
    let subHtml = '';
    subMateriArr.forEach((sm, idx) => {
      subHtml += `
        <div style="background:white; border:2px solid #e2e8f0; border-radius:20px; padding:24px; margin-bottom:18px;">
          <h4 style="font-size:17px; font-weight:800; color:#047857; margin-bottom:12px;"><i class="fa-solid fa-layer-group" style="color:#10b981; margin-right:8px;"></i> ${escapeHtml(sm.judul_sub || ('Bagian ' + (idx + 1)))}</h4>
          <div style="font-size:15px; color:var(--text-main); line-height:1.8; margin-bottom:14px;">${formatSoalText(sm.uraian || '')}</div>
          ${sm.contoh_nyata ? `<div style="background:#ecfdf5; border:1px dashed #10b981; padding:14px 18px; border-radius:14px; font-size:13.5px; color:#065f46;"><b><i class="fa-solid fa-magnifying-glass-location"></i> Contoh Konkret di Sekitar Kita:</b><br>${escapeHtml(sm.contoh_nyata)}</div>` : ''}
        </div>`;
    });

    let funFactsArr = Array.isArray(k.fakta_unik) ? k.fakta_unik : [];
    let funHtml = '';
    if (funFactsArr.length > 0) {
      funHtml = `<div style="margin-top:25px;"><h4 style="font-size:16px; font-weight:800; color:#047857; margin-bottom:12px;"><i class="fa-solid fa-wand-magic-sparkles"></i> Tahukah Kamu? (Fakta Sains & Kontekstual)</h4>`;
      funFactsArr.forEach(ff => {
        funHtml += `<div class="funfact-card"><i class="fa-solid fa-lightbulb" style="color:#10b981; margin-right:8px;"></i> ${escapeHtml(ff)}</div>`;
      });
      funHtml += `</div>`;
    }

    stepBodyHtml = `
      <div style="background:#f8fafc; border-radius:24px; padding:28px; border:1px solid #e2e8f0; margin-bottom:20px;">
        <p style="font-size:15.5px; font-weight:600; color:#334155; line-height:1.7; margin-bottom:20px;">${formatSoalText((k.eksplorasi && k.eksplorasi.pengantar) || 'Pelajari konsep-konsep kunci berikut secara bertahap:')}</p>
        ${visualTujuanHtml}
        ${buildStudentVideoAnalysisHubHTML(activeLMSModule)}
        ${subHtml}
        ${funHtml}
      </div>
      <div style="display:flex; justify-content:space-between; gap:15px;">
        <button onclick="switchLMSStep(1)" style="background:white; border:2px solid #cbd5e1; color:#475569; padding:15px 24px; border-radius:16px; font-weight:800; cursor:pointer;"><i class="fa-solid fa-arrow-left"></i> Sebelumnya</button>
        <button onclick="switchLMSStep(3)" style="background:var(--gradient-main); color:white; border:none; padding:15px 28px; border-radius:16px; font-weight:800; cursor:pointer; box-shadow:0 10px 20px rgba(5, 150, 105,0.25);">Lanjut Kartu Pintar 3D <i class="fa-solid fa-arrow-right"></i></button>
      </div>`;
  } else if (activeLMSStep === 3) {
    let cards = Array.isArray(k.kartu_pintar) ? k.kartu_pintar : [];
    let cardsHtml = cards.map(c => `
      <div class="flashcard-box" onclick="this.classList.toggle('flipped')">
        <div class="flashcard-inner">
          <div class="flashcard-front">
            <span style="font-size:10px; font-weight:800; text-transform:uppercase; background:#a7f3d0; padding:4px 10px; border-radius:10px; margin-bottom:10px;"><i class="fa-solid fa-rotate"></i> Klik Untuk Balik Kartu</span>
            <h4 style="font-size:17px; font-weight:800;">${escapeHtml(c.istilah || 'Konsep Penting')}</h4>
          </div>
          <div class="flashcard-back">
            <span style="font-size:10px; font-weight:800; color:#fbbf24; text-transform:uppercase; margin-bottom:8px;">Penjelasan Kunci</span>
            <p style="font-size:13.5px; line-height:1.5; font-weight:600;">${escapeHtml(c.definisi || '')}</p>
          </div>
        </div>
      </div>`).join('');

    let rangkumanArr = Array.isArray(k.rangkuman) ? k.rangkuman : [];
    let rangkumanHtml = rangkumanArr.map(r => `<li style="margin-bottom:8px;">${escapeHtml(r)}</li>`).join('');

    stepBodyHtml = `
      <div style="background:white; border:2px solid #e2e8f0; border-radius:24px; padding:28px; margin-bottom:20px;">
        <h4 style="font-size:18px; font-weight:800; color:var(--text-main); margin-bottom:6px;"><i class="fa-solid fa-clone" style="color:var(--primary);"></i> Kartu Pintar Interaktif (3D Active Recall)</h4>
        <p style="font-size:14px; color:var(--text-muted); margin-bottom:18px;">Uji ingatanmu! Tebak makna istilah di bawah ini, lalu <b>klik kartu</b> untuk membalik dan melihat jawabannya.</p>
        <div class="flashcard-grid">${cardsHtml}</div>
        ${rangkumanHtml ? `<div style="background:#f8fafc; border-radius:18px; padding:20px 24px; border:1px solid #e2e8f0; margin-top:25px;"><h5 style="font-size:15px; font-weight:800; color:#0f172a; margin-bottom:10px;"><i class="fa-solid fa-bookmark" style="color:var(--primary);"></i> Intisari Materi (Rangkuman Cepat)</h5><ul style="padding-left:20px; font-size:14px; color:#334155; line-height:1.6;">${rangkumanHtml}</ul></div>` : ''}
      </div>
      <div style="display:flex; justify-content:space-between; gap:15px;">
        <button onclick="switchLMSStep(2)" style="background:white; border:2px solid #cbd5e1; color:#475569; padding:15px 24px; border-radius:16px; font-weight:800; cursor:pointer;"><i class="fa-solid fa-arrow-left"></i> Sebelumnya</button>
        <button onclick="switchLMSStep(4)" style="background:var(--gradient-main); color:white; border:none; padding:15px 28px; border-radius:16px; font-weight:800; cursor:pointer; box-shadow:0 10px 20px rgba(5, 150, 105,0.25);">Lanjut Studi Kasus & Refleksi <i class="fa-solid fa-arrow-right"></i></button>
      </div>`;
  } else if (activeLMSStep === 4) {
    let sk = k.studi_kasus || {};
    let savedRefl = studentLMSReflectionText || (prevRecord ? prevRecord.refleksi : '');
    stepBodyHtml = `
      <div style="background:white; border:2px solid #e2e8f0; border-radius:24px; padding:28px; margin-bottom:20px;">
        <div style="background:linear-gradient(135deg, #eff6ff, #dbeafe); border:1.5px solid #93c5fd; border-radius:20px; padding:24px; margin-bottom:24px;">
          <span style="background:#2563eb; color:white; padding:5px 12px; border-radius:12px; font-size:11px; font-weight:800;"><i class="fa-solid fa-users-gear"></i> PROBLEM-BASED LEARNING (STUDI KASUS NYATA)</span>
          <h4 style="font-size:18px; font-weight:800; color:#1e3a8a; margin:12px 0 8px 0;">${escapeHtml(sk.judul_kasus || 'Tantangan Pemecahan Masalah')}</h4>
          <p style="font-size:14.5px; color:#1e40af; line-height:1.7; margin-bottom:14px;">${formatSoalText(sk.cerita_kasus || '')}</p>
          <div style="background:white; padding:14px 18px; border-radius:14px; border-left:4px solid #2563eb; font-size:14px; color:#0f172a; font-weight:700;">
            <i class="fa-solid fa-circle-question" style="color:#2563eb;"></i> Tantangan Diskusi: ${escapeHtml(sk.pertanyaan_diskusi || '')}
          </div>
          <button onclick="document.getElementById('box-panduan-solusi').classList.toggle('hidden')" style="margin-top:12px; background:#1d4ed8; color:white; border:none; padding:9px 16px; border-radius:10px; font-size:12.5px; font-weight:800; cursor:pointer;">
            <i class="fa-solid fa-key"></i> Lihat Panduan Berpikir / Solusi Terbimbing
          </button>
          <div id="box-panduan-solusi" class="hidden" style="margin-top:12px; background:#f8fafc; padding:14px; border-radius:12px; font-size:13.5px; color:#334155; border:1px dashed #60a5fa;">
            <b>Alur Solusi Terbimbing:</b><br>${escapeHtml(sk.panduan_solusi || '')}
          </div>
        </div>

        <h4 style="font-size:16px; font-weight:800; color:var(--text-main); margin-bottom:8px;"><i class="fa-solid fa-pen-fancy" style="color:var(--primary);"></i> Jurnal Refleksi Konstruktif Siswa</h4>
        <p style="font-size:13.5px; color:var(--text-muted); margin-bottom:12px;">Tuliskan dengan bahasamu sendiri: Apa kesimpulan terpenting yang kamu pahami dari bab ini, atau bagaimana solusi menurut pendapatmu?</p>
        <textarea id="inp-lms-refleksi" oninput="studentLMSReflectionText = this.value" rows="3" placeholder="Ketik kesimpulan / refleksi singkatmu di sini (akan tercatat di Dashboard Guru)..." style="width:100%; padding:16px; border-radius:14px; border:2px solid #cbd5e1; font-size:14px; font-weight:600; outline:none; background:#f8fafc;">${escapeHtml(savedRefl)}</textarea>
      </div>
      <div style="display:flex; justify-content:space-between; gap:15px;">
        <button onclick="switchLMSStep(3)" style="background:white; border:2px solid #cbd5e1; color:#475569; padding:15px 24px; border-radius:16px; font-weight:800; cursor:pointer;"><i class="fa-solid fa-arrow-left"></i> Sebelumnya</button>
        <button onclick="switchLMSStep(5)" style="background:var(--gradient-main); color:white; border:none; padding:15px 28px; border-radius:16px; font-weight:800; cursor:pointer; box-shadow:0 10px 20px rgba(5, 150, 105,0.25);">Lanjut Kuis Interaktif & Klaim XP <i class="fa-solid fa-trophy"></i></button>
      </div>`;
  } else if (activeLMSStep === 5) {
    let kuisHtml = '';
    kuis.forEach((q, idx) => {
      let chosen = studentLMSQuizAnswers[idx] || '';
      let optsHtml = ['a', 'b', 'c', 'd'].map(letter => {
        let up = letter.toUpperCase();
        let textOpt = q[letter] || q[up] || '';
        if (!textOpt) return '';
        let isSelected = (chosen === up);
        return `
          <div onclick="pilihJawabanKuisLMS(${idx}, '${up}')" style="padding:14px 18px; border-radius:14px; border:2px solid ${isSelected ? '#059669' : '#e2e8f0'}; background:${isSelected ? '#ecfdf5' : '#f8fafc'}; color:${isSelected ? '#065f46' : '#334155'}; font-weight:700; font-size:14px; cursor:pointer; margin-bottom:10px; display:flex; align-items:center; gap:12px;">
            <span style="width:28px; height:28px; border-radius:50%; background:${isSelected ? '#059669' : 'white'}; color:${isSelected ? 'white' : '#64748b'}; border:2px solid ${isSelected ? '#059669' : '#cbd5e1'}; display:inline-flex; align-items:center; justify-content:center; font-weight:800; font-size:12px; flex-shrink:0;">${up}</span>
            <span>${escapeHtml(textOpt)}</span>
          </div>`;
      }).join('');

      kuisHtml += `
        <div style="background:white; border:2px solid #e2e8f0; border-radius:20px; padding:24px; margin-bottom:18px;">
          <div style="font-size:12px; font-weight:800; color:#047857; margin-bottom:8px;">PERTANYAAN FORMATIF #${idx + 1}</div>
          <div style="font-size:15.5px; font-weight:700; color:var(--text-main); line-height:1.7; margin-bottom:16px;">${formatSoalText(q.soal || '')}</div>
          <div>${optsHtml}</div>
          <div id="lms-quiz-feedback-${idx}" class="hidden" style="margin-top:12px; padding:14px 18px; border-radius:12px; font-size:13.5px; line-height:1.6;"></div>
        </div>`;
    });

    stepBodyHtml = `
      <div style="background:#f8fafc; border:1px solid #e2e8f0; border-radius:24px; padding:28px; margin-bottom:20px;">
        <div style="display:flex; justify-content:space-between; align-items:center; flex-wrap:wrap; gap:10px; margin-bottom:20px;">
          <div>
            <h4 style="font-size:19px; font-weight:800; color:var(--text-main);"><i class="fa-solid fa-bolt" style="color:#10b981;"></i> Kuis Evaluasi Terbimbing & Umpan Balik Instan</h4>
            <p style="font-size:13.5px; color:var(--text-muted);">Jawab seluruh pertanyaan di bawah ini untuk melihat pembahasan lengkap dan mengklaim poin XP belajarmu!</p>
          </div>
          ${prevRecord ? `<span style="background:#d1fae5; color:#065f46; padding:8px 16px; border-radius:12px; font-weight:800; font-size:13px;"><i class="fa-solid fa-medal"></i> Skor Terbaikmu: ${prevRecord.skor} (${prevRecord.xp} XP)</span>` : ''}
        </div>
        ${kuisHtml}
        <button id="btn-submit-lms-quiz" onclick="periksaKuisDanKlaimXP()" style="width:100%; padding:18px; background:linear-gradient(135deg, #10b981, #059669); color:white; border:none; border-radius:18px; font-weight:800; font-size:16px; cursor:pointer; box-shadow:0 12px 25px rgba(16, 185, 129,0.3);">
          <i class="fa-solid fa-check-double"></i> Periksa Jawaban, Lihat Pembahasan & Klaim XP!
        </button>
      </div>
      <div style="display:flex; justify-content:space-between;">
        <button onclick="switchLMSStep(4)" style="background:white; border:2px solid #cbd5e1; color:#475569; padding:14px 22px; border-radius:14px; font-weight:800; cursor:pointer;"><i class="fa-solid fa-arrow-left"></i> Kembali ke Studi Kasus</button>
      </div>`;
  }

  let interactiveHubHtml = buildStudentInteractiveHubHTML();
  ws.innerHTML = stepperHtml + stepBodyHtml + interactiveHubHtml;
}

function syncAITutorDrawerContent() {
  if (!activeLMSModule) return;
  const modId = activeLMSModule.id;
  if (!aiTutorChatHistory[modId]) {
    aiTutorChatHistory[modId] = [
      {
        role: 'bot',
        text: `Halo <b>${escapeHtml(studentData.name || 'Sobat Pembelajar')}</b>! 👋 Aku <b>Asisten Belajar AI SICIBINAGA</b>. Ada bagian dari modul <b>"${escapeHtml(activeLMSModule.judul)}"</b> yang ingin kamu tanyakan atau minta dijelaskan dengan contoh sederhana?`
      }
    ];
  }
  const subEl = document.getElementById('ai-drawer-subtitle');
  if (subEl) subEl.innerText = `Modul: ${activeLMSModule.judul}`;

  const chatBox = document.getElementById('ai-tutor-chat-box');
  if (chatBox) {
    chatBox.innerHTML = aiTutorChatHistory[modId].map(msg => {
      if (msg.role === 'user') {
        return `<div class="ai-bubble-user">${escapeHtml(msg.text)}</div>`;
      } else {
        return `<div class="ai-bubble-bot"><div style="font-size:11px; font-weight:800; color:#6d28d9; margin-bottom:4px;"><i class="fa-solid fa-robot"></i> Asisten Belajar AI</div>${msg.text}</div>`;
      }
    }).join('');
    chatBox.scrollTop = chatBox.scrollHeight;
  }
}

function toggleAITutorDrawer() {
  if (isExamActive || !document.getElementById('exam-section')?.classList.contains('hidden')) {
    const d = document.getElementById('aiTutorDrawer');
    if (d) d.classList.remove('open');
    return;
  }
  playStudentSFX('click');
  const drawer = document.getElementById('aiTutorDrawer');
  if (!drawer) return;
  const isOpen = drawer.classList.toggle('open');
  if (isOpen) {
    syncAITutorDrawerContent();
    setTimeout(() => {
      const inp = document.getElementById('inp-ai-tutor-question') || document.getElementById('isi');
      if (inp) inp.focus();
    }, 200);
  }
}

function showStudentToast(message, type = 'info') {
  const container = document.getElementById('studentToastContainer');
  if (!container) return;
  const icons = {
    success: 'fa-circle-check',
    warning: 'fa-triangle-exclamation',
    error: 'fa-circle-xmark',
    info: 'fa-circle-info'
  };
  const colors = {
    success: '#10b981',
    warning: '#10b981',
    error: '#f43f5e',
    info: '#38bdf8'
  };
  const toast = document.createElement('div');
  toast.className = `student-toast-item toast-${type}`;
  toast.innerHTML = `
    <i class="fa-solid ${icons[type] || icons.info}" style="font-size:18px; color:${colors[type] || colors.info}; flex-shrink:0;"></i>
    <div style="flex:1;">${message}</div>`;
  container.appendChild(toast);
  setTimeout(() => {
    toast.style.opacity = '0';
    toast.style.transform = 'translateY(-10px)';
    setTimeout(() => toast.remove(), 260);
  }, 3200);
}

function buildStudentInteractiveHubHTML() {
  if (!activeLMSModule) return '';
  syncAITutorDrawerContent();

  let qnaArr = Array.isArray(activeLMSModule.qnaList) ? activeLMSModule.qnaList : [];
  let qnaItemsHtml = '';
  if (qnaArr.length === 0) {
    qnaItemsHtml = `<div style="text-align:center; padding:35px 15px; color:var(--text-muted); font-size:13.5px;"><i class="fa-regular fa-comments" style="font-size:32px; color:#cbd5e1; display:block; margin-bottom:8px;"></i>Belum ada diskusi di modul ini. Jadilah yang pertama bertanya kepada Bapak/Ibu Guru!</div>`;
  } else {
    qnaItemsHtml = qnaArr.slice().reverse().map(item => `
      <div class="qna-item-box">
        <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:6px; flex-wrap:wrap; gap:6px;">
          <span style="font-weight:800; color:var(--text-main); font-size:13px;"><i class="fa-solid fa-user-graduate" style="color:#059669;"></i> ${escapeHtml(item.namaSiswa)} <span style="background:#d1fae5; color:#047857; padding:2px 8px; border-radius:6px; font-size:11px;">${escapeHtml(item.kelas)}</span></span>
          <span style="font-size:11px; color:#94a3b8;">${escapeHtml(item.waktu)}</span>
        </div>
        <div style="color:var(--text-main); line-height:1.6;">${escapeHtml(item.pertanyaan)}</div>
        ${item.balasanGuru
          ? `<div class="qna-teacher-reply"><div style="font-weight:800; font-size:11.5px; color:#047857; margin-bottom:3px;"><i class="fa-solid fa-chalkboard-user"></i> Dijawab oleh ${escapeHtml(item.namaGuru || 'Guru Pengampu')} (${escapeHtml(item.waktuBalas)}):</div>${escapeHtml(item.balasanGuru)}</div>`
          : `<div style="margin-top:8px; font-size:11.5px; color:#059669; font-weight:700;"><i class="fa-regular fa-clock"></i> Menunggu tanggapan Bapak/Ibu Guru...</div>`}
      </div>`).join('');
  }

  return `
    <div style="margin-top:28px; padding-top:24px; border-top:2px dashed #a7f3d0; display:flex; flex-direction:column; gap:18px;">
      <!-- KARTU PINTAS AI TUTOR DRAWER (TIDAK MENUTUPI TEKS MATERI) -->
      <div style="background:linear-gradient(135deg, #2e1065 0%, #4c1d95 60%, #6d28d9 100%); color:white; border-radius:22px; padding:20px 24px; display:flex; justify-content:space-between; align-items:center; flex-wrap:wrap; gap:16px; box-shadow:0 12px 28px rgba(109, 40, 217, 0.2);">
        <div style="display:flex; align-items:center; gap:14px;">
          <div style="width:48px; height:48px; border-radius:16px; background:rgba(255,255,255,0.18); display:flex; align-items:center; justify-content:center; font-size:22px; flex-shrink:0;">
            <i class="fa-solid fa-robot"></i>
          </div>
          <div>
            <div style="font-size:11px; font-weight:800; color:#ddd6fe; text-transform:uppercase;">ASISTEN BELAJAR AI (DRAWER SAMPING)</div>
            <div style="font-size:16px; font-weight:800; margin-top:2px;">Butuh penjelasan lebih sederhana atau contoh soal tambahan?</div>
          </div>
        </div>
        <button type="button" onclick="toggleAITutorDrawer()" style="background:#fbbf24; color:#0f172a; border:none; min-height:48px; padding:0 22px; border-radius:14px; font-weight:900; font-size:13.5px; cursor:pointer; display:inline-flex; align-items:center; gap:8px; box-shadow:0 8px 18px rgba(0,0,0,0.2);">
          <i class="fa-solid fa-comments"></i> Buka Chat AI Tutor
        </button>
      </div>

      <!-- KARTU DISKUSI & QNA INTERAKTIF SISWA DAN GURU -->
      <div class="qna-forum-card">
        <div class="qna-forum-header">
          <div style="display:flex; align-items:center; gap:10px;">
            <i class="fa-solid fa-comments" style="font-size:22px;"></i>
            <div>
              <div style="font-size:15px; font-weight:800;">Ruang Tanya Jawab (QnA) Siswa & Guru</div>
              <div style="font-size:11px; opacity:0.9;">Tanyakan langsung ke Bapak/Ibu Guru Pengampu</div>
            </div>
          </div>
          <span style="background:rgba(255,255,255,0.2); padding:4px 10px; border-radius:12px; font-size:10.5px; font-weight:800;">${qnaArr.length} Diskusi</span>
        </div>

        <div class="qna-thread-list" id="student-qna-thread-box">${qnaItemsHtml}</div>

        <div style="padding:14px; background:var(--bg-slate-card); border-top:1px solid var(--border-slate-subtle); display:flex; gap:10px; flex-wrap:wrap;">
          <input type="text" id="inp-student-qna-text" placeholder="Tulis pertanyaanmu untuk Bapak/Ibu Guru..." onkeydown="if(event.key==='Enter') kirimPertanyaanQnAGuru()" style="flex:1; min-width:200px; min-height:48px; padding:12px 15px; border-radius:12px; border:2px solid #cbd5e1; font-size:13.5px; font-weight:600; outline:none;">
          <button type="button" id="btn-send-qna-guru" onclick="kirimPertanyaanQnAGuru()" style="background:linear-gradient(135deg, #059669, #047857); color:white; border:none; min-height:48px; padding:0 20px; border-radius:12px; font-weight:800; cursor:pointer; font-size:13.5px;">
            <i class="fa-solid fa-paper-plane"></i> Kirim ke Guru
          </button>
        </div>
      </div>
    </div>`;
}

function kirimPertanyaanCepatAI(teks) {
  const inp = document.getElementById('inp-ai-tutor-question') || document.getElementById('isi');
  if (inp) {
    inp.value = teks;
    kirimPesanKeAITutor();
  }
}

function kirimPesanKeAITutor() {
  if (!activeLMSModule) return;
  const inp = document.getElementById('inp-ai-tutor-question') || document.getElementById('isi');
  const btn = document.getElementById('btn-send-ai-tutor');
  if (!inp || !inp.value.trim()) return;

  let questionText = inp.value.trim();
  inp.value = '';
  const modId = activeLMSModule.id;
  if (!aiTutorChatHistory[modId]) aiTutorChatHistory[modId] = [];
  aiTutorChatHistory[modId].push({ role: 'user', text: questionText });

  const chatBox = document.getElementById('ai-tutor-chat-box');
  if (chatBox) {
    chatBox.innerHTML += `<div class="ai-bubble-user">${escapeHtml(questionText)}</div>`;
    chatBox.innerHTML += `<div id="ai-typing-indicator" class="ai-bubble-bot"><i class="fa-solid fa-spinner fa-spin" style="color:#7c3aed;"></i> Asisten AI sedang menyusun penjelasan...</div>`;
    chatBox.scrollTop = chatBox.scrollHeight;
  }
  if (btn) btn.disabled = true;

  let k = activeLMSModule.konten || {};
  let subRingkas = (k.eksplorasi && Array.isArray(k.eksplorasi.sub_materi))
    ? k.eksplorasi.sub_materi.map(s => `${s.judul_sub}: ${s.uraian}`).join(' | ')
    : '';
  let ringkasanKonten = `Tujuan: ${activeLMSModule.tujuan}. Pemantik: ${k.pemantik || ''}. Materi Inti: ${subRingkas}`;

  google.script.run.withSuccessHandler(res => {
    if (btn) btn.disabled = false;
    let indicator = document.getElementById('ai-typing-indicator');
    if (indicator) indicator.remove();

    let rawAnswer = (res && res.success) ? res.answer : (res ? res.message : 'Maaf, terjadi gangguan koneksi.');
    let formattedAnswer = formatSoalText(rawAnswer);
    aiTutorChatHistory[modId].push({ role: 'bot', text: formattedAnswer });

    if (chatBox) {
      chatBox.innerHTML += `<div class="ai-bubble-bot"><div style="font-size:11px; font-weight:800; color:#6d28d9; margin-bottom:4px;"><i class="fa-solid fa-robot"></i> Asisten Belajar AI</div>${formattedAnswer}</div>`;
      chatBox.scrollTop = chatBox.scrollHeight;
    }
  }).withFailureHandler(err => {
    if (btn) btn.disabled = false;
    let indicator = document.getElementById('ai-typing-indicator');
    if (indicator) indicator.remove();
  }).askAITutorLMS({
    mapel: activeLMSSubject,
    judulModul: activeLMSModule.judul,
    ringkasanKonten: ringkasanKonten,
    namaSiswa: studentData.name || 'Siswa',
    pertanyaan: questionText
  });
}

function kirimPertanyaanQnAGuru() {
  if (!activeLMSModule) return;
  const inp = document.getElementById('inp-student-qna-text');
  const btn = document.getElementById('btn-send-qna-guru');
  if (!inp || !inp.value.trim()) return;

  let pertanyaan = inp.value.trim();
  btn.innerHTML = '<i class="fa-solid fa-spinner fa-spin"></i>';
  btn.disabled = true;

  google.script.run.withSuccessHandler(res => {
    btn.innerHTML = '<i class="fa-solid fa-paper-plane"></i> Kirim ke Guru';
    btn.disabled = false;
    if (res && res.success) {
      inp.value = '';
      if (!Array.isArray(activeLMSModule.qnaList)) activeLMSModule.qnaList = [];
      activeLMSModule.qnaList.push(res.item);
      renderConstructiveWorkspace();
      Swal.fire({ icon: 'success', title: 'Pertanyaan Terkirim!', text: res.message, timer: 1600, showConfirmButton: false, customClass: { popup: 'swal-custom-popup' } });
    } else {
      Swal.fire({ icon: 'error', title: 'Gagal Mengirim', text: res ? res.message : 'Terjadi kesalahan.', customClass: { popup: 'swal-custom-popup' } });
    }
  }).submitStudentLMSQuestion({
    idModul: activeLMSModule.id,
    mapel: activeLMSSubject,
    judulModul: activeLMSModule.judul,
    namaSiswa: studentData.name || 'Siswa',
    kelas: studentData.kelas || '7',
    pertanyaan: pertanyaan
  });
}

function pilihJawabanKuisLMS(qIdx, optLetter) {
  studentLMSQuizAnswers[qIdx] = optLetter;
  renderConstructiveWorkspace();
}

function periksaKuisDanKlaimXP() {
  if (!activeLMSModule) return;
  const kuis = Array.isArray(activeLMSModule.kuis) ? activeLMSModule.kuis : [];
  if (kuis.length === 0) return;

  if (Object.keys(studentLMSQuizAnswers).length < kuis.length) {
    Swal.fire({
      icon: 'warning',
      title: 'Masih Ada Soal Kosong',
      text: 'Jawab semua soal kuis formatif terlebih dahulu agar kamu mendapatkan umpan balik pembahasan yang utuh!',
      customClass: { popup: 'swal-custom-popup', confirmButton: 'swal-custom-confirm' }
    });
    return;
  }

  let benar = 0;
  kuis.forEach((q, idx) => {
    let kunci = (q.kunci || 'A').toString().trim().toUpperCase();
    let jwb = (studentLMSQuizAnswers[idx] || '').toString().trim().toUpperCase();
    let isCorrect = (jwb === kunci);
    if (isCorrect) benar++;

    let fbBox = document.getElementById('lms-quiz-feedback-' + idx);
    if (fbBox) {
      fbBox.classList.remove('hidden');
      fbBox.style.background = isCorrect ? '#ecfdf5' : '#fff1f2';
      fbBox.style.border = isCorrect ? '1.5px solid #6ee7b7' : '1.5px solid #fecdd3';
      fbBox.style.color = isCorrect ? '#065f46' : '#9f1239';
      fbBox.innerHTML = `
        <div style="font-weight:800; margin-bottom:4px;">
          <i class="fa-solid ${isCorrect ? 'fa-circle-check' : 'fa-circle-xmark'}"></i>
          ${isCorrect ? 'Tepat Sekali!' : 'Kurang Tepat — Jawaban Benar: ' + kunci}
        </div>
        <div><b>Pembahasan Terbimbing:</b> ${escapeHtml(q.pembahasan || 'Perhatikan kembali konsep inti pada tahap eksplorasi.')}</div>`;
    }
  });

  let skor = Math.round((benar / kuis.length) * 100);
  const btn = document.getElementById('btn-submit-lms-quiz');
  if (btn) {
    btn.innerHTML = '<i class="fa-solid fa-spinner fa-spin"></i> Menyimpan Progres & Menghitung XP...';
    btn.disabled = true;
  }

  google.script.run.withSuccessHandler(res => {
    if (btn) {
      btn.innerHTML = `<i class="fa-solid fa-rotate"></i> Ulangi Kuis (Skor Terakhir: ${skor})`;
      btn.disabled = false;
    }
    let xp = res && res.xpEarned ? res.xpEarned : Math.round(100 + skor * 1.5);
    if (globalLMSDashboard.completedMap) {
      globalLMSDashboard.completedMap[activeLMSModule.id] = {
        skor: skor,
        xp: xp,
        refleksi: studentLMSReflectionText || 'Telah menyelesaikan modul secara konstruktif'
      };
    }
    Swal.fire({
      icon: 'success',
      title: `Luar Biasa! Skor Kamu: ${skor}/100`,
      html: `Kamu berhasil menjawab benar <b>${benar} dari ${kuis.length}</b> soal dan memperoleh <b>+${xp} XP</b>!<br><br>Silakan baca kotak <b>Pembahasan Terbimbing</b> di bawah setiap soal untuk memperkuat pemahamanmu sebelum ujian PTS/PAS.`,
      confirmButtonText: 'Mantap, Mengerti!',
      customClass: { popup: 'swal-custom-popup', confirmButton: 'swal-custom-confirm' }
    });
  }).saveStudentLMSProgress({
    email: studentData.email,
    nama: studentData.name,
    kelas: studentData.kelas,
    mapel: activeLMSSubject,
    idModul: activeLMSModule.id,
    judulModul: activeLMSModule.judul,
    skor: skor,
    refleksi: studentLMSReflectionText || 'Selesai eksplorasi & kuis formatif'
  });
}

