function exportLMSProgressCSV() {
  if (!adminLMSProgressList || adminLMSProgressList.length === 0) {
    Swal.fire({ icon: 'warning', title: 'Data Kosong', text: 'Belum ada progres belajar LMS untuk diekspor.', customClass: { popup: 'swal-custom-popup' } });
    return;
  }
  let csv = "No,Waktu,Nama Siswa,Kelas,Mata Pelajaran,Judul Modul,Skor Kuis Formatif,XP,Refleksi Siswa\n";
  adminLMSProgressList.forEach((p, i) => {
    csv += `${i + 1},"${p.waktu}","${(p.nama || '').replace(/"/g, '""')}","${p.kelas}","${p.mapel}","${(p.judulModul || '').replace(/"/g, '""')}",${p.skor},${p.xp},"${(p.refleksi || '').replace(/"/g, '""')}"\n`;
  });
  let blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
  let a = document.createElement('a');
  a.href = URL.createObjectURL(blob);
  a.download = 'Rekap_Progres_LMS_SICIBINAGA_Kelas7.csv';
  document.body.appendChild(a); a.click(); document.body.removeChild(a);
}

