  const dupBody = document.getElementById('srnDuplicatesBody');
  if (dupBody) dupBody.innerHTML = dupHtml || `<tr><td colspan="6" style="text-align:center; padding:25px; color:#059669; font-weight:700;">Tidak ditemukan data ganda / lintas kelas.</td></tr>`;
