function unduhCatatanPintarTxt() {
  const val = document.getElementById('student-smart-notes-area')?.value || '';
  if (!val.trim()) {
    Swal.fire({ icon: 'info', title: 'Catatan Masih Kosong', text: 'Tuliskan rangkuman atau poin penting terlebih dahulu sebelum mengunduh.' });
    return;
  }
  const modTitle = activeLMSModule ? activeLMSModule.judul : 'Materi_LMS';
  const header = "CATATAN PINTAR SISWA - SICIBINAGA KELAS 7\r\n" +
                 "Nama: " + (studentData.name || 'Siswa') + " (" + (studentData.kelas || '7') + ")\r\n" +
                 "Mata Pelajaran: " + activeLMSSubject + "\r\n" +
                 "Judul Modul: " + modTitle + "\r\n" +
                 "================================================\r\n\r\n";
  const blob = new Blob([header + val], { type: 'text/plain;charset=utf-8' });
  const a = document.createElement('a');
  a.href = URL.createObjectURL(blob);
  a.download = `Catatan_${modTitle.replace(/\s+/g, '_')}.txt`;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
}

