// Micro-Interactions: Tandai Sub-Materi Paham & Mastery Flashcard 3D
function toggleSubConceptCheck(subIdx) {
  if (!activeLMSModule) return;
  const key = `${activeLMSModule.id}_sub_${subIdx}`;
  lmsSubConceptChecked[key] = !lmsSubConceptChecked[key];
  playStudentSFX('click');
  const btn = document.getElementById(`btn-subcheck-${subIdx}`);
  if (btn) {
    btn.classList.toggle('understood', !!lmsSubConceptChecked[key]);
    btn.innerHTML = lmsSubConceptChecked[key]
      ? '<i class="fa-solid fa-circle-check"></i> Konsep Ini Sudah Aku Pahami!'
      : '<i class="fa-regular fa-circle-check"></i> Tandai Sudah Paham Konsep Ini';
  }
}

function setFlashcardMasteryStatus(cardIdx, status) {
  showStudentToast(status === 'mastered' ? 'Kartu ditandai Sudah Hafal! Mantap!' : 'Kartu ditandai untuk diulang kembali.', status === 'mastered' ? 'success' : 'warning');
  if (!activeLMSModule) return;
  const key = `${activeLMSModule.id}_card_${cardIdx}`;
  lmsFlashcardMastery[key] = status;
  playStudentSFX(status === 'mastered' ? 'success' : 'click');
  updateFlashcardMasteryUI();
}

function updateFlashcardMasteryUI() {
  if (!activeLMSModule) return;
  const k = activeLMSModule.konten || {};
  const cards = Array.isArray(k.kartu_pintar) ? k.kartu_pintar : [];
  let masteredCount = 0;

  cards.forEach((_, idx) => {
    const st = lmsFlashcardMastery[`${activeLMSModule.id}_card_${idx}`];
    if (st === 'mastered') masteredCount++;
    const btnM = document.getElementById(`btn-fc-master-${idx}`);
    const btnR = document.getElementById(`btn-fc-review-${idx}`);
    if (btnM) btnM.classList.toggle('mastered', st === 'mastered');
    if (btnR) btnR.classList.toggle('review', st === 'review');
  });

  const counterEl = document.getElementById('fc-mastery-counter-badge');
  if (counterEl && cards.length > 0) {
    const pct = Math.round((masteredCount / cards.length) * 100);
    counterEl.innerHTML = `<i class="fa-solid fa-award"></i> Penguasaan Istilah: <b>${masteredCount}/${cards.length} Kartu (${pct}%)</b>`;
  }
}

function setStudentConfidenceLevel(level) {
  const confLabels = { ragu: 'Status: Masih perlu baca ulang materi.', cukup: 'Status: Cukup paham konsep inti!', siap: 'Status: Sangat siap menghadapi Kuis!' };
  showStudentToast(confLabels[level] || 'Kesiapan tercatat', 'success');
  if (!activeLMSModule) return;
  lmsConfidenceLevel[activeLMSModule.id] = level;
  playStudentSFX('click');
  ['ragu', 'cukup', 'siap'].forEach(l => {
    const b = document.getElementById('btn-conf-' + l);
    if (b) b.classList.toggle('active', l === level);
  });
}

// Hook Fluid Enhancements into existing LMS functions
const _baseLoadSubjects = loadSubjects;
loadSubjects = async function() {
  await _baseLoadSubjects();
  renderStudentEngagementWidgets();
  renderQuickResumeBanner();
};

const _v5RenderConstructiveWorkspace = renderConstructiveWorkspace;
renderConstructiveWorkspace = function() {
  _v5RenderConstructiveWorkspace();

  // 1. Trigger Fluid Stage Animation
  const ws = document.getElementById('lms-constructive-workspace');
  if (ws) {
    ws.classList.remove('fluid-stage-animate');
    void ws.offsetWidth; // Reflow for smooth animation restart
    ws.classList.add('fluid-stage-animate');
  }

  // 2. Sync Floating Bottom Navigation Dock Active State & Top Progress Bar
  for (let s = 1; s <= 5; s++) {
    const pill = document.getElementById('dock-step-' + s);
    if (pill) pill.classList.toggle('active', s === activeLMSStep);
  }
  const topBar = document.getElementById('fluid-top-progress-bar');
  if (topBar) topBar.style.width = (activeLMSStep * 20) + '%';

  // 3. Save Last Visited Module & Step for Quick-Resume
  if (activeLMSSubject && activeLMSModule) {
    let modIdx = (window.currentSubjectModulesList || []).findIndex(m => m.id === activeLMSModule.id);
    saveLastVisitedLMSModule(activeLMSSubject, Math.max(0, modIdx), activeLMSStep);
  }

  // 4. Refresh Concept Map if open
  const mapSlot = document.getElementById('lms-concept-map-slot');
  if (mapSlot && !mapSlot.classList.contains('hidden')) {
    renderInteractiveConceptMap();
  }

  // 5. Enhance Step 2 (Sub-Materi Micro-Check) & Step 3 (Flashcard Mastery Controls) & Step 4 (Confidence Self-Check)
  if (activeLMSStep === 3 && activeLMSModule) {
    const k = activeLMSModule.konten || {};
    const cards = Array.isArray(k.kartu_pintar) ? k.kartu_pintar : [];
    const grid = ws ? ws.querySelector('.flashcard-grid') : null;
    if (grid && cards.length > 0) {
      grid.insertAdjacentHTML('beforebegin', `<div id="fc-mastery-counter-badge" style="display:inline-block; background:#d1fae5; color:#065f46; padding:6px 14px; border-radius:99px; font-size:12.5px; font-weight:800; margin-bottom:10px;"></div>`);
      const boxes = grid.querySelectorAll('.flashcard-box');
      boxes.forEach((box, idx) => {
        box.addEventListener('click', () => playStudentSFX('flip'));
        const wrapper = document.createElement('div');
        wrapper.className = 'flashcard-wrap-item';
        box.parentNode.insertBefore(wrapper, box);
        wrapper.appendChild(box);
        wrapper.insertAdjacentHTML('beforeend', `
          <div class="flashcard-mastery-bar">
            <button type="button" id="btn-fc-master-${idx}" class="btn-card-mastery" onclick="setFlashcardMasteryStatus(${idx}, 'mastered')"><i class="fa-solid fa-check"></i> Sudah Hafal</button>
            <button type="button" id="btn-fc-review-${idx}" class="btn-card-mastery" onclick="setFlashcardMasteryStatus(${idx}, 'review')"><i class="fa-solid fa-rotate"></i> Perlu Diulang</button>
          </div>`);
      });
      updateFlashcardMasteryUI();
    }
  } else if (activeLMSStep === 4 && activeLMSModule && ws) {
    const curConf = lmsConfidenceLevel[activeLMSModule.id] || '';
    const confHtml = `
      <div class="confidence-meter-box">
        <div>
          <div style="font-size:14px; font-weight:800; color:#065f46;"><i class="fa-solid fa-heart-pulse"></i> Cek Kesiapan Mandiri Sebelum Kuis Formatif</div>
          <div style="font-size:12px; color:#047857;">Seberapa yakin kamu sudah menguasai konsep pada bab ini?</div>
        </div>
        <div style="display:flex; gap:8px; flex-wrap:wrap;">
          <button type="button" id="btn-conf-ragu" class="confidence-btn ${curConf === 'ragu' ? 'active' : ''}" onclick="setStudentConfidenceLevel('ragu')">🤔 Masih Perlu Baca Lagi</button>
          <button type="button" id="btn-conf-cukup" class="confidence-btn ${curConf === 'cukup' ? 'active' : ''}" onclick="setStudentConfidenceLevel('cukup')">😊 Cukup Paham</button>
          <button type="button" id="btn-conf-siap" class="confidence-btn ${curConf === 'siap' ? 'active' : ''}" onclick="setStudentConfidenceLevel('siap')">🤩 Sangat Siap Kuis!</button>
        </div>
      </div>`;
    const textareaEl = document.getElementById('inp-lms-refleksi');
    if (textareaEl) textareaEl.insertAdjacentHTML('afterend', confHtml);
  }
};


