function openStudentGuideCenter(defaultTab) {
  playStudentSFX('click');
  const modal = document.getElementById('studentGuideCenterModal');
  if (!modal) return;

  // Deteksi otomatis tab yang paling relevan jika defaultTab tidak ditentukan
  if (!defaultTab) {
    const lmsSec = document.getElementById('lms-learning-section');
    const examSec = document.getElementById('exam-section');
    const dashSec = document.getElementById('dashboard-section');
    if (examSec && !examSec.classList.contains('hidden')) defaultTab = 'ujian';
    else if (lmsSec && !lmsSec.classList.contains('hidden')) defaultTab = 'tahap';
    else if (dashSec && !dashSec.classList.contains('hidden')) defaultTab = 'beranda';
    else defaultTab = 'login';
  }

  modal.classList.add('active');
  switchStudentGuideTab(defaultTab);
}

function closeStudentGuideCenter() {
  playStudentSFX('click');
  const modal = document.getElementById('studentGuideCenterModal');
  if (modal) modal.classList.remove('active');
}

function switchStudentGuideTab(tabKey) {
  playStudentSFX('click');
  const data = STUDENT_GUIDE_TABS_DATA[tabKey] || STUDENT_GUIDE_TABS_DATA.login;

  ['login', 'beranda', 'tahap', 'alat', 'aiqna', 'ujian'].forEach(k => {
    const btn = document.getElementById('gtab-btn-' + k);
    if (btn) btn.classList.toggle('active', k === tabKey);
  });

  const bodyEl = document.getElementById('studentGuideModalBody');
  if (!bodyEl) return;

  const cardsHtml = data.cards.map(c => `
    <div class="guide-feature-card">
      <div class="guide-icon-badge"><i class="${c.icon}"></i></div>
      <h5 style="font-size:15px; font-weight:800; color:var(--text-main); margin-bottom:6px;">${c.title}</h5>
      <div style="font-size:13px; color:var(--text-muted); line-height:1.6;">${c.desc}</div>
    </div>`).join('');

  bodyEl.innerHTML = `
    <div class="fluid-stage-animate">
      <div style="background:linear-gradient(135deg, #ecfdf5, #d1fae5); border:1.5px solid #a7f3d0; border-radius:18px; padding:18px 22px; margin-bottom:16px;">
        <span style="background:#059669; color:white; padding:3px 10px; border-radius:99px; font-size:10.5px; font-weight:900;">${data.badge}</span>
        <h4 style="font-size:18px; font-weight:800; color:#064e3b; margin-top:6px;">${data.title}</h4>
        <p style="font-size:13.5px; color:#065f46; margin-top:3px;">${data.subtitle}</p>
      </div>
      <div class="guide-feature-grid">${cardsHtml}</div>
    </div>`;
}

function toggleContextualGuide(bodyId, iconId) {
  playStudentSFX('click');
  const bodyEl = document.getElementById(bodyId);
  const iconEl = document.getElementById(iconId);
  if (!bodyEl) return;
  const isHidden = bodyEl.classList.toggle('hidden');
  if (iconEl) {
    iconEl.className = isHidden ? 'fa-solid fa-chevron-down' : 'fa-solid fa-chevron-up';
  }
}

// Arahkan fungsi showGuide() lama ke Pusat Panduan Interaktif yang baru
showGuide = function() {
  openStudentGuideCenter('login');
};

