const _v11RenderConstructiveWorkspace = renderConstructiveWorkspace;
renderConstructiveWorkspace = function() {
  _v11RenderConstructiveWorkspace();
  if (typeof syncComposeNativeAndroidTopBar === 'function') syncComposeNativeAndroidTopBar();
  for (let s = 1; s <= 5; s++) {
    const pill = document.getElementById('dock-step-' + s);
    if (pill) {
      pill.classList.toggle('active', s === activeLMSStep);
      pill.classList.toggle('done-step', s < activeLMSStep);
    }
  }
};

