function tryGuideJumpStep(stepNum) {
  closeStudentGuideCenter();
  const lmsSec = document.getElementById('lms-learning-section');
  if (lmsSec && !lmsSec.classList.contains('hidden')) {
    switchLMSStep(stepNum);
  } else {
    showStudentToast('Pilih salah satu Mata Pelajaran lalu klik "Ruang Belajar" untuk membuka Tahap ' + stepNum + '!', 'info');
  }
}

function previewSimulatedBottomIcon(idx) {
  playStudentSFX('click');
  const item = BOTTOM_BAR_SIMULATOR_ITEMS[idx] || BOTTOM_BAR_SIMULATOR_ITEMS[0];
  document.querySelectorAll('.guide-sim-icon-btn').forEach((b, i) => b.classList.toggle('active', i === idx));
  const box = document.getElementById('guideSimExplainText');
  if (box) {
    box.innerHTML = `<b style="color:#6ee7b7;">${item.name}:</b> ${item.desc}`;
  }
}

// Override switchStudentGuideTab untuk merender tampilan proporsional + tombol aksi interaktif + simulator
switchStudentGuideTab = function(tabKey) {
  playStudentSFX('click');
  currentActiveGuideTabKey = GUIDE_TAB_KEYS_ORDER.includes(tabKey) ? tabKey : 'login';
  const data = STUDENT_GUIDE_TABS_DATA[currentActiveGuideTabKey] || STUDENT_GUIDE_TABS_DATA.login;
  const tabIndex = GUIDE_TAB_KEYS_ORDER.indexOf(currentActiveGuideTabKey);

  // Bersihkan input pencarian saat ganti tab
  const sInp = document.getElementById('guideQuickSearchInput');
  if (sInp) sInp.value = '';

  // Update label langkah & tombol Prev/Next
  const progLbl = document.getElementById('guideStepProgressLabel');
  if (progLbl) progLbl.textContent = `Bagian ${tabIndex + 1} dari ${GUIDE_TAB_KEYS_ORDER.length}`;

  const prevBtn = document.getElementById('btnGuidePrevTab');
  const nextBtn = document.getElementById('btnGuideNextTab');
  if (prevBtn) prevBtn.style.display = tabIndex === 0 ? 'none' : 'inline-flex';
  if (nextBtn) nextBtn.style.display = tabIndex === GUIDE_TAB_KEYS_ORDER.length - 1 ? 'none' : 'inline-flex';

  GUIDE_TAB_KEYS_ORDER.forEach(k => {
    const btn = document.getElementById('gtab-btn-' + k);
    if (btn) {
      const isAct = (k === currentActiveGuideTabKey);
      btn.classList.toggle('active', isAct);
      if (isAct && btn.scrollIntoView) {
        try { btn.scrollIntoView({ behavior: 'smooth', inline: 'center', block: 'nearest' }); } catch (e) {}
      }
    }
  });

  const bodyEl = document.getElementById('studentGuideModalBody');
  if (!bodyEl) return;

  // Jika di Tab 4 (Alat & Bottom Bar), tampilkan Simulator Interaktif 8 Ikon Solid Bottom Bar
  let simulatorHtml = '';
  if (currentActiveGuideTabKey === 'alat') {
    const simButtons = BOTTOM_BAR_SIMULATOR_ITEMS.map((it, idx) => `
      <button type="button" class="guide-sim-icon-btn ${idx === 0 ? 'active' : ''}" onclick="previewSimulatedBottomIcon(${idx})" title="${it.name}">
        <i class="${it.icon}"></i>
      </button>`).join('');
    simulatorHtml = `
      <div class="guide-interactive-sim-box">
        <div style="display:flex; justify-content:space-between; align-items:center; flex-wrap:wrap; gap:6px;">
          <span style="font-size:11px; font-weight:900; color:#6ee7b7; text-transform:uppercase; letter-spacing:0.5px;">
            <i class="fa-solid fa-mobile-screen-button"></i> Simulasi Interaktif 8 Ikon Bottom Bar Solid (Klik Ikon untuk Cek Fungsinya!)
          </span>
        </div>
        <div class="guide-sim-icons-row">${simButtons}</div>
        <div id="guideSimExplainText" style="margin-top:10px; font-size:12.5px; color:#f8fafc; line-height:1.5; background:rgba(0,0,0,0.25); padding:9px 12px; border-radius:10px;">
          <b style="color:#6ee7b7;">${BOTTOM_BAR_SIMULATOR_ITEMS[0].name}:</b> ${BOTTOM_BAR_SIMULATOR_ITEMS[0].desc}
        </div>
      </div>`;
  }

  const actionsArr = GUIDE_CARD_INTERACTIVE_ACTIONS[currentActiveGuideTabKey] || [];
  const cardsHtml = data.cards.map((c, idx) => {
    const actObj = actionsArr[idx];
    const btnTryHtml = actObj
      ? `<button type="button" class="guide-try-btn" onclick="${actObj.action}">
           <i class="fa-solid fa-bolt"></i> ${actObj.label}
         </button>`
      : '';
    return `
      <div class="guide-feature-card">
        <div>
          <div class="guide-card-head">
            <div class="guide-icon-badge"><i class="${c.icon}"></i></div>
            <div>
              <h5 style="font-size:14.5px; font-weight:800; color:var(--text-main); line-height:1.35; margin-bottom:4px;">${c.title}</h5>
            </div>
          </div>
          <div style="font-size:12.8px; color:var(--text-muted); line-height:1.6; margin-top:8px;">${c.desc}</div>
        </div>
        ${btnTryHtml}
      </div>`;
  }).join('');

  bodyEl.innerHTML = `
    <div class="fluid-stage-animate">
      <div class="guide-banner-summary">
        <div>
          <span style="background:#059669; color:white; padding:3px 10px; border-radius:99px; font-size:10px; font-weight:900;">${data.badge}</span>
          <h4 style="font-size:16.5px; font-weight:800; color:#064e3b; margin-top:5px;">${data.title}</h4>
          <p style="font-size:12.8px; color:#065f46; margin-top:2px;">${data.subtitle}</p>
        </div>
      </div>
      ${simulatorHtml}
      <div class="guide-feature-grid">${cardsHtml}</div>
    </div>`;
  bodyEl.scrollTop = 0;
};

function navigateStudentGuideStep(delta) {
  const curIdx = GUIDE_TAB_KEYS_ORDER.indexOf(currentActiveGuideTabKey);
  const nextIdx = Math.min(GUIDE_TAB_KEYS_ORDER.length - 1, Math.max(0, curIdx + delta));
  switchStudentGuideTab(GUIDE_TAB_KEYS_ORDER[nextIdx]);
}

function filterStudentGuideContent(keyword) {
  const kw = (keyword || '').toLowerCase().trim();
  if (!kw) {
    switchStudentGuideTab(currentActiveGuideTabKey);
    return;
  }

  const bodyEl = document.getElementById('studentGuideModalBody');
  if (!bodyEl) return;

  let matchedCards = [];
  GUIDE_TAB_KEYS_ORDER.forEach(tabKey => {
    const group = STUDENT_GUIDE_TABS_DATA[tabKey];
    const actionsArr = GUIDE_CARD_INTERACTIVE_ACTIONS[tabKey] || [];
    (group.cards || []).forEach((c, idx) => {
      if (c.title.toLowerCase().includes(kw) || c.desc.toLowerCase().includes(kw) || group.title.toLowerCase().includes(kw)) {
        matchedCards.push({
          badge: group.badge,
          card: c,
          actObj: actionsArr[idx]
        });
      }
    });
  });

  if (matchedCards.length === 0) {
    bodyEl.innerHTML = `
      <div style="text-align:center; padding:40px 20px; color:var(--text-muted);">
        <i class="fa-solid fa-magnifying-glass" style="font-size:34px; color:#10b981; margin-bottom:10px; display:block;"></i>
        <div style="font-weight:800; font-size:15px; color:var(--text-main);">Tidak ditemukan panduan untuk "${escapeHtml(keyword)}"</div>
        <div style="font-size:12.5px; margin-top:4px;">Coba kata kunci lain seperti: <b>XP, Kartu 3D, AI Tutor, Catatan, Token, Fullscreen</b>.</div>
      </div>`;
    return;
  }

  const cardsHtml = matchedCards.map(item => `
    <div class="guide-feature-card">
      <div>
        <span style="display:inline-block; font-size:9.5px; font-weight:900; background:#d1fae5; color:#047857; padding:2px 8px; border-radius:99px; margin-bottom:6px;">${item.badge}</span>
        <div class="guide-card-head">
          <div class="guide-icon-badge"><i class="${item.card.icon}"></i></div>
          <div>
            <h5 style="font-size:14.5px; font-weight:800; color:var(--text-main); line-height:1.35;">${item.card.title}</h5>
          </div>
        </div>
        <div style="font-size:12.8px; color:var(--text-muted); line-height:1.6; margin-top:8px;">${item.card.desc}</div>
      </div>
      ${item.actObj ? `<button type="button" class="guide-try-btn" onclick="${item.actObj.action}"><i class="fa-solid fa-bolt"></i> ${item.actObj.label}</button>` : ''}
    </div>`).join('');

  bodyEl.innerHTML = `
    <div class="fluid-stage-animate">
      <div style="font-size:13px; font-weight:800; color:#047857; margin-bottom:10px;">
        <i class="fa-solid fa-check-circle"></i> Ditemukan ${matchedCards.length} panduan terkait "${escapeHtml(keyword)}":
      </div>
      <div class="guide-feature-grid">${cardsHtml}</div>
    </div>`;
}


