// C. PELACAK AKTIVITAS BELAJAR NYATA SISWA (ANTI-INSTAN / ANTI-SKIP XP TRACKER)
function getStudentActivityStoreKey() {
  return `lms_v15_act_${(studentData && studentData.email) ? studentData.email : 'guest'}`;
}

function getStudentVerifiedTracker() {
  try {
    const raw = localStorage.getItem(getStudentActivityStoreKey());
    const parsed = raw ? JSON.parse(raw) : {};
    return {
      readTimers: parsed.readTimers || {},       // modId -> detik membaca aktif
      subChecked: parsed.subChecked || {},       // modId_subIdx -> true
      cardsFlipped: parsed.cardsFlipped || {},   // modId_cardIdx -> true
      cardsMastered: parsed.cardsMastered || {}, // modId_cardIdx -> 'mastered'
      aiEvaluated: parsed.aiEvaluated || {},     // modId -> { score, feedback, passed }
      aiChatCount: parsed.aiChatCount || 0,      // jumlah diskusi dengan AI Tutor
      socraticHintsUsed: parsed.socraticHintsUsed || 0,
      conceptMapOpened: parsed.conceptMapOpened || false,
      ttsUsed: parsed.ttsUsed || false,
      pomodoroCompleted: parsed.pomodoroCompleted || 0,
      firstTryQuiz90: parsed.firstTryQuiz90 || {} // modId -> true
    };
  } catch (e) {
    return {
      readTimers: {}, subChecked: {}, cardsFlipped: {}, cardsMastered: {},
      aiEvaluated: {}, aiChatCount: 0, socraticHintsUsed: 0,
      conceptMapOpened: false, ttsUsed: false, pomodoroCompleted: 0, firstTryQuiz90: {}
    };
  }
}

function saveStudentVerifiedTracker(trackerObj) {
  try {
    localStorage.setItem(getStudentActivityStoreKey(), JSON.stringify(trackerObj));
  } catch (e) {}
}

// Hitung bonus XP dari ketuntasan misi eksplorasi & penggunaan fitur pintar
function getStudentBonusActivityXP() {
  const tr = getStudentVerifiedTracker();
  let bonus = 0;
  bonus += Math.min(5, Object.keys(tr.aiEvaluated).filter(k => tr.aiEvaluated[k] && tr.aiEvaluated[k].passed).length) * 40;
  bonus += Math.min(10, Object.keys(tr.cardsMastered).filter(k => tr.cardsMastered[k] === 'mastered').length) * 10;
  bonus += Math.min(5, tr.aiChatCount || 0) * 10;
  bonus += (tr.pomodoroCompleted || 0) * 25;
  return bonus;
}

// Timer Baca Aktif per Modul (Berjalan otomatis saat siswa berada di Ruang Belajar LMS)
let activeReadingIntervalV15 = null;
function startActiveReadingTimerV15() {
  if (activeReadingIntervalV15) clearInterval(activeReadingIntervalV15);
  activeReadingIntervalV15 = setInterval(() => {
    const lmsSec = document.getElementById('lms-learning-section');
    if (!lmsSec || lmsSec.classList.contains('hidden') || !activeLMSModule || document.hidden) return;
    const tr = getStudentVerifiedTracker();
    const modId = activeLMSModule.id;
    tr.readTimers[modId] = (tr.readTimers[modId] || 0) + 2;
    saveStudentVerifiedTracker(tr);

    // Update badge waktu baca jika sedang di Tahap 1, 2, atau 5
    const timerBadge = document.getElementById('v15-read-time-indicator');
    if (timerBadge) {
      const sec = tr.readTimers[modId] || 0;
      const isEnough = sec >= 45;
      timerBadge.innerHTML = `<i class="fa-solid ${isEnough ? 'fa-circle-check' : 'fa-hourglass-half'}"></i> Waktu Eksplorasi Aktif: <b>${sec} dtk</b> ${isEnough ? '(Terverifikasi ✓)' : '(Min. 45 dtk)'}`;
      timerBadge.style.background = isEnough ? '#d1fae5' : '#d1fae5';
      timerBadge.style.color = isEnough ? '#065f46' : '#065f46';
    }
  }, 2000);
}
startActiveReadingTimerV15();

// Cek Status Ketuntasan 5 Syarat Modul Aktif (Anti-Skip Gate sebelum Klaim XP Penuh)
function getModuleVerificationStatusV15(mod) {
  if (!mod) return { allReady: false, items: [], verifiedXPBonus: 0 };
  const tr = getStudentVerifiedTracker();
  const modId = mod.id;
  const k = mod.konten || {};
  const subArr = (k.eksplorasi && Array.isArray(k.eksplorasi.sub_materi)) ? k.eksplorasi.sub_materi : [];
  const cardsArr = Array.isArray(k.kartu_pintar) ? k.kartu_pintar : [];

  // 1. Waktu baca aktif minimal 45 detik
  const readSec = tr.readTimers[modId] || 0;
  const readOk = readSec >= 45;

  // 2. Ceklis pemahaman sub-materi di Tahap 2
  let checkedSubCount = 0;
  subArr.forEach((_, idx) => {
    if (lmsSubConceptChecked[`${modId}_sub_${idx}`] || tr.subChecked[`${modId}_sub_${idx}`]) checkedSubCount++;
  });
  const subOk = subArr.length === 0 ? true : (checkedSubCount >= subArr.length);

  // 3. Membalik & menandai minimal seluruh Kartu Pintar 3D di Tahap 3
  let masteredCardCount = 0;
  cardsArr.forEach((_, idx) => {
    const st = lmsFlashcardMastery[`${modId}_card_${idx}`] || tr.cardsMastered[`${modId}_card_${idx}`];
    if (st === 'mastered' || st === 'review') masteredCardCount++;
  });
  const cardsOk = cardsArr.length === 0 ? true : (masteredCardCount >= cardsArr.length);

  // 4. Jurnal Refleksi minimal 12 kata & telah dievaluasi AI Groq (skor >= 65)
  const reflText = (studentLMSReflectionText || '').trim();
  const wordCount = reflText ? reflText.split(/\s+/).filter(Boolean).length : 0;
  const aiEval = tr.aiEvaluated[modId];
  const reflOk = (wordCount >= 10) && (aiEval && aiEval.passed);

  // 5. Catatan Pintar terisi minimal 15 karakter untuk modul ini
  const savedNote = (localStorage.getItem(getStudentNoteKey()) || '').trim();
  const noteOk = savedNote.length >= 15;

  const items = [
    { key: 'read', label: `Baca Materi Aktif (${Math.min(45, readSec)}/45 dtk)`, done: readOk, xp: 25, step: 2 },
    { key: 'sub', label: `Ceklis Sub-Konsep (${checkedSubCount}/${subArr.length} Pilar)`, done: subOk, xp: 25, step: 2 },
    { key: 'cards', label: `Uji Kartu 3D (${masteredCardCount}/${cardsArr.length} Kartu)`, done: cardsOk, xp: 30, step: 3 },
    { key: 'refl', label: `Refleksi Terverifikasi AI Groq`, done: reflOk, xp: 45, step: 4 },
    { key: 'note', label: `Tulis Catatan Pintar Bab Ini`, done: noteOk, xp: 20, step: 2 }
  ];

  const verifiedXPBonus = items.reduce((acc, it) => acc + (it.done ? it.xp : 0), 0);
  // Wajib minimal 3 aktivitas inti (Baca/Sub-konsep, Kartu 3D, dan Refleksi AI) selesai untuk membuka Klaim XP Kuis
  const coreReady = (readOk || subOk) && cardsOk && reflOk;
  return { allReady: coreReady, items, verifiedXPBonus, readOk, subOk, cardsOk, reflOk, noteOk };
}

// D. INTEGRASI AI GROQ SOCRATIC MENTOR PADA TAHAP 4 (STUDI KASUS & REFLEKSI) & TAHAP 5 (KUIS)
function mintaPanduanBerpikirAIGroq() {
  if (!activeLMSModule) return;
  const k = activeLMSModule.konten || {};
  const sk = k.studi_kasus || {};
  const box = document.getElementById('ai-socratic-case-guide-box');
  const btn = document.getElementById('btn-ai-socratic-guide');
  if (!box) return;

  playStudentSFX('click');
  box.classList.remove('hidden');
  box.innerHTML = `<i class="fa-solid fa-spinner fa-spin" style="color:#7c3aed;"></i> <b>Mentor Sokratik AI Groq</b> sedang merumuskan petunjuk berpikir bertahap untukmu...`;
  if (btn) btn.disabled = true;

  const tr = getStudentVerifiedTracker();
  tr.socraticHintsUsed = (tr.socraticHintsUsed || 0) + 1;
  saveStudentVerifiedTracker(tr);

  google.script.run.withSuccessHandler(res => {
    if (btn) btn.disabled = false;
    if (res && res.success && res.data) {
      const d = res.data;
      const stepsLi = (Array.isArray(d.langkah_pancingan) ? d.langkah_pancingan : []).map(s => `<li style="margin-bottom:6px;">${escapeHtml(s)}</li>`).join('');
      const kwBadges = (Array.isArray(d.kata_kunci_bantuan) ? d.kata_kunci_bantuan : []).map(w => `<span style="background:white; color:#6d28d9; border:1px solid #c4b5fd; padding:2px 9px; border-radius:99px; font-size:11px; font-weight:800;">#${escapeHtml(w)}</span>`).join(' ');
      box.innerHTML = `
        <div style="font-weight:900; color:#5b21b6; margin-bottom:6px;"><i class="fa-solid fa-wand-magic-sparkles"></i> Petunjuk Berpikir Sokratik AI Groq (Temukan Solusimu Sendiri!):</div>
        <ol style="padding-left:18px; margin-bottom:10px;">${stepsLi}</ol>
        ${kwBadges ? `<div style="margin-bottom:8px;"><b>Kata Kunci Konsep:</b> ${kwBadges}</div>` : ''}
        <div style="font-size:12px; color:#4c1d95; font-style:italic;"><i class="fa-solid fa-lightbulb" style="color:#10b981;"></i> ${escapeHtml(d.kalimat_motivasi || 'Gunakan petunjuk di atas untuk merangkai kesimpulan dengan bahasamu sendiri!')}</div>`;
    } else {
      box.innerHTML = `<b>Panduan Berpikir:</b><br>${escapeHtml(sk.panduan_solusi || '1) Amati masalah utama pada cerita kasus. 2) Hubungkan dengan konsep inti yang telah dipelajari di Tahap 2. 3) Tuliskan solusi logis menurut pendapatmu.')}`;
    }
  }).withFailureHandler(() => {
    if (btn) btn.disabled = false;
    box.innerHTML = `<b>Panduan Berpikir:</b><br>${escapeHtml(sk.panduan_solusi || 'Hubungkan permasalahan kasus dengan konsep inti bab ini.')}`;
  }).evaluateStudentReflectionGroq({
    mapel: activeLMSSubject,
    judulModul: activeLMSModule.judul,
    tujuan: activeLMSModule.tujuan,
    ceritaKasus: sk.cerita_kasus || '',
    pertanyaanDiskusi: sk.pertanyaan_diskusi || '',
    mode: 'PANDUAN'
  });
}

function verifikasiJurnalRefleksiAIGroq() {
  if (!activeLMSModule) return;
  const reflInput = document.getElementById('inp-lms-refleksi');
  const reflText = (reflInput ? reflInput.value : studentLMSReflectionText || '').trim();
  studentLMSReflectionText = reflText;

  const words = reflText.split(/\s+/).filter(Boolean);
  if (words.length < 10) {
    Swal.fire({
      icon: 'warning',
      title: 'Refleksi Masih Terlalu Singkat',
      html: `Tuliskan kesimpulan pemahamanmu minimal <b>10 kata</b> (saat ini baru <b>${words.length} kata</b>).<br><br>Jelaskan <i>mengapa</i> dan <i>bagaimana</i> konsep bab ini menyelesaikan tantangan pada studi kasus!`,
      customClass: { popup: 'swal-custom-popup', confirmButton: 'swal-custom-confirm' }
    });
    return;
  }

  const k = activeLMSModule.konten || {};
  const sk = k.studi_kasus || {};
  const box = document.getElementById('ai-reflection-eval-result');
  const btn = document.getElementById('btn-verify-reflection-ai');
  if (box) {
    box.classList.remove('hidden');
    box.innerHTML = `<i class="fa-solid fa-spinner fa-spin" style="color:#7c3aed;"></i> <b>AI Groq</b> sedang membaca & mengevaluasi kedalaman jurnal refleksimu...`;
  }
  if (btn) btn.disabled = true;

  google.script.run.withSuccessHandler(res => {
    if (btn) btn.disabled = false;
    if (res && res.success && res.data) {
      const d = res.data;
      const skor = Number(d.skor_kualitas) || 75;
      const isPassed = (d.status_lulus !== false) && (skor >= 65);

      const tr = getStudentVerifiedTracker();
      tr.aiEvaluated[activeLMSModule.id] = {
        score: skor,
        passed: isPassed,
        feedback: d.koreksi_dan_arahan || ''
      };
      saveStudentVerifiedTracker(tr);

      if (isPassed) playStudentSFX('success');
      else playStudentSFX('click');

      if (box) {
        box.style.background = isPassed ? '#ecfdf5' : '#ecfdf5';
        box.style.borderColor = isPassed ? '#10b981' : '#10b981';
        box.style.color = isPassed ? '#065f46' : '#065f46';
        box.innerHTML = `
          <div style="display:flex; justify-content:space-between; align-items:center; flex-wrap:wrap; gap:8px; margin-bottom:6px;">
            <span style="font-weight:900; font-size:14px;">
              <i class="fa-solid ${isPassed ? 'fa-circle-check' : 'fa-circle-exclamation'}"></i>
              ${isPassed ? 'Refleksi Terverifikasi AI Groq! (+45 XP Aktif)' : 'Refleksi Perlu Dipertajam Sedikit Lagi'}
            </span>
            <span style="background:${isPassed ? '#059669' : '#059669'}; color:white; padding:3px 10px; border-radius:99px; font-size:11.5px; font-weight:900;">Skor Kedalaman: ${skor}/100</span>
          </div>
          <div style="margin-bottom:6px;"><b><i class="fa-solid fa-thumbs-up"></i> Apresiasi AI:</b> ${escapeHtml(d.apresiasi || 'Usaha refleksi yang bagus!')}</div>
          <div style="margin-bottom:6px;"><b><i class="fa-solid fa-compass-drafting"></i> Panduan & Koreksi Konstruktif:</b> ${escapeHtml(d.koreksi_dan_arahan || '')}</div>
          ${d.pertanyaan_lanjutan ? `<div style="background:rgba(255,255,255,0.7); padding:8px 12px; border-radius:10px; font-size:12.5px; margin-top:6px;"><b>🤔 Tantangan Berpikir Lanjutan:</b> ${escapeHtml(d.pertanyaan_lanjutan)}</div>` : ''}`;
      }
      renderStudentEngagementWidgets();
      updateStudentHeroLevelBannerV15();
    } else {
      // Fallback jika API sibuk tetapi siswa sudah menulis >= 10 kata
      const tr = getStudentVerifiedTracker();
      tr.aiEvaluated[activeLMSModule.id] = { score: 80, passed: true, feedback: 'Refleksi terverifikasi.' };
      saveStudentVerifiedTracker(tr);
      if (box) {
        box.innerHTML = `<b style="color:#059669;"><i class="fa-solid fa-circle-check"></i> Jurnal Refleksi Terverifikasi! (+45 XP Aktif)</b>`;
      }
    }
  }).withFailureHandler(() => {
    if (btn) btn.disabled = false;
  }).evaluateStudentReflectionGroq({
    mapel: activeLMSSubject,
    judulModul: activeLMSModule.judul,
    tujuan: activeLMSModule.tujuan,
    ceritaKasus: sk.cerita_kasus || '',
    pertanyaanDiskusi: sk.pertanyaan_diskusi || '',
    jawabanRefleksi: reflText,
    mode: 'EVALUASI'
  });
}

// Coach Sokratik AI Groq per Soal Kuis di Tahap 5 (Tanpa Membocorkan Kunci Jawaban!)
function mintaPetunjukSokratikSoalKuis(qIdx, mode) {
  if (!activeLMSModule) return;
  const kuis = Array.isArray(activeLMSModule.kuis) ? activeLMSModule.kuis : [];
  const q = kuis[qIdx];
  if (!q) return;

  const coachBox = document.getElementById(`lms-quiz-socratic-${qIdx}`);
  if (!coachBox) return;
  playStudentSFX('click');

  coachBox.classList.remove('hidden');
  coachBox.innerHTML = `<i class="fa-solid fa-spinner fa-spin" style="color:#7c3aed;"></i> <b>Coach AI Groq</b> sedang menyusun petunjuk penalaran untuk soal #${qIdx + 1}...`;

  const tr = getStudentVerifiedTracker();
  tr.socraticHintsUsed = (tr.socraticHintsUsed || 0) + 1;
  saveStudentVerifiedTracker(tr);

  const chosen = studentLMSQuizAnswers[qIdx] || '';
  const opsiStr = `A. ${q.a || ''} | B. ${q.b || ''} | C. ${q.c || ''} | D. ${q.d || ''}`;

  google.script.run.withSuccessHandler(res => {
    if (res && res.success && res.coaching) {
      coachBox.innerHTML = `
        <div style="font-weight:800; color:#5b21b6; margin-bottom:4px;">
          <i class="fa-solid fa-robot"></i> ${mode === 'COACH' ? `Bimbingan Perbaikan AI Groq (Mengapa Opsi ${chosen} Kurang Tepat?):` : 'Petunjuk Penalaran Sokratik AI Groq:'}
        </div>
        <div>${formatSoalText(res.coaching)}</div>`;
    } else {
      coachBox.innerHTML = `<b>Petunjuk Berpikir:</b> Perhatikan kembali kata kunci pada soal dan cocokkan dengan konsep utama yang telah kamu pelajari pada Tahap 2.`;
    }
  }).withFailureHandler(() => {
    coachBox.innerHTML = `<b>Petunjuk Berpikir:</b> Eliminasi opsi yang bertentangan dengan konsep dasar bab ini, lalu uji sisa opsi terhadap konteks soal.`;
  }).getGroqQuizSocraticCoaching({
    mapel: activeLMSSubject,
    judulModul: activeLMSModule.judul,
    soal: q.soal || '',
    opsiText: opsiStr,
    jawabanSiswa: chosen ? `${chosen} (${q[chosen.toLowerCase()] || ''})` : '',
    mode: mode || 'HINT'
  });
}

// E. OVERRIDE PERIKSA KUIS & KLAIM XP (TERapkan VERIFIKASI ANTI-INSTAN & BIMBINGAN SOKRATIK)
periksaKuisDanKlaimXP = function() {
  if (!activeLMSModule) return;
  const kuis = Array.isArray(activeLMSModule.kuis) ? activeLMSModule.kuis : [];
  if (kuis.length === 0) return;

  // 1. Cek apakah seluruh soal kuis sudah dijawab
  if (Object.keys(studentLMSQuizAnswers).length < kuis.length) {
    Swal.fire({
      icon: 'warning',
      title: 'Masih Ada Soal Kuis Kosong',
      text: 'Jawab seluruh soal latihan HOTS terlebih dahulu sebelum memeriksa jawaban dan mengklaim XP!',
      customClass: { popup: 'swal-custom-popup', confirmButton: 'swal-custom-confirm' }
    });
    return;
  }

  // 2. Cek apakah syarat eksplorasi modul sudah terpenuhi (Anti-Instan XP Gate)
  const verStatus = getModuleVerificationStatusV15(activeLMSModule);
  if (!verStatus.allReady) {
    const missingHtml = verStatus.items.filter(i => !i.done).map(i => `<li style="margin-bottom:6px;"><b>${i.label}</b> (Buka Tahap ${i.step})</li>`).join('');
    Swal.fire({
      icon: 'info',
      title: 'Tuntaskan Eksplorasi Materi Dulu Yuk!',
      html: `Agar XP dan Lencana yang kamu peroleh benar-benar mencerminkan pemahaman utuh, selesaikan aktivitas berikut sebelum mengklaim XP Kuis:<br><ul style="text-align:left; margin-top:10px; color:#047857;">${missingHtml}</ul>`,
      confirmButtonText: 'Siap, Aku Lengkapi Dulu!',
      customClass: { popup: 'swal-custom-popup', confirmButton: 'swal-custom-confirm' }
    });
    return;
  }

  // 3. Evaluasi jawaban kuis: untuk jawaban yang salah, JANGAN langsung bocorkan kunci mentah jika siswa belum mencoba memperbaiki, berikan tombol Coach Sokratik AI Groq!
  let benar = 0;
  let wrongIndices = [];
  kuis.forEach((q, idx) => {
    let kunci = (q.kunci || 'A').toString().trim().toUpperCase();
    let jwb = (studentLMSQuizAnswers[idx] || '').toString().trim().toUpperCase();
    let isCorrect = (jwb === kunci);
    if (isCorrect) benar++;
    else wrongIndices.push(idx);

    let fbBox = document.getElementById('lms-quiz-feedback-' + idx);
    if (fbBox) {
      fbBox.classList.remove('hidden');
      fbBox.style.background = isCorrect ? '#ecfdf5' : '#fff1f2';
      fbBox.style.border = isCorrect ? '1.5px solid #6ee7b7' : '1.5px solid #fecdd3';
      fbBox.style.color = isCorrect ? '#065f46' : '#9f1239';
      if (isCorrect) {
        fbBox.innerHTML = `
          <div style="font-weight:800; margin-bottom:4px;">
            <i class="fa-solid fa-circle-check"></i> Tepat Sekali! (Opsi ${jwb} Benar)
          </div>
          <div><b>Penguatan Konsep:</b> ${escapeHtml(q.pembahasan || 'Pemahamanmu terhadap konsep ini sudah sangat tepat!')}</div>`;
      } else {
        fbBox.innerHTML = `
          <div style="display:flex; justify-content:space-between; align-items:center; flex-wrap:wrap; gap:8px; margin-bottom:6px;">
            <span style="font-weight:800;">
              <i class="fa-solid fa-triangle-exclamation"></i> Opsi ${jwb} Masih Kurang Tepat — Ayo Temukan Jawaban Benarnya!
            </span>
            <button type="button" onclick="mintaPetunjukSokratikSoalKuis(${idx}, 'COACH')" style="background:#7c3aed; color:white; border:none; padding:5px 12px; border-radius:8px; font-size:11.5px; font-weight:800; cursor:pointer;">
              <i class="fa-solid fa-wand-magic-sparkles"></i> Minta Bimbingan AI Groq
            </button>
          </div>
          <div style="font-size:12.5px;">Klik <b>"Minta Bimbingan AI Groq"</b> di atas agar AI memandumu menemukan letak kekeliruan dan memilih jawaban yang benar secara mandiri!</div>`;
      }
    }
  });

  let skor = Math.round((benar / kuis.length) * 100);
  const tr = getStudentVerifiedTracker();
  if (skor >= 90 && !globalLMSDashboard.completedMap[activeLMSModule.id]) {
    tr.firstTryQuiz90[activeLMSModule.id] = true;
    saveStudentVerifiedTracker(tr);
  }

  // Hitung Total XP Terverifikasi (Dari aktivitas baca + kartu 3D + refleksi AI + catatan + akurasi kuis)
  const quizXP = Math.round(skor * 1.3);
  const totalVerifiedXP = verStatus.verifiedXPBonus + quizXP;

  const btn = document.getElementById('btn-submit-lms-quiz');
  if (btn) {
    btn.innerHTML = '<i class="fa-solid fa-spinner fa-spin"></i> Menyimpan Progres & XP Terverifikasi...';
    btn.disabled = true;
  }

  playStudentSFX('success');
  if (skor >= 75) launchConfettiCelebration();

  google.script.run.withSuccessHandler(res => {
    if (btn) {
      btn.innerHTML = `<i class="fa-solid fa-rotate"></i> Periksa Ulang Jawaban untuk Skor 100 (Skor Saat Ini: ${skor})`;
      btn.disabled = false;
    }
    let xpEarned = (res && res.xpEarned) ? res.xpEarned : totalVerifiedXP;
    if (globalLMSDashboard.completedMap) {
      const oldRec = globalLMSDashboard.completedMap[activeLMSModule.id];
      if (!oldRec || skor >= oldRec.skor) {
        if (oldRec) globalLMSDashboard.totalXP = Math.max(0, (globalLMSDashboard.totalXP || 0) - (oldRec.xp || 0));
        globalLMSDashboard.completedMap[activeLMSModule.id] = {
          skor: skor,
          xp: xpEarned,
          refleksi: studentLMSReflectionText
        };
        globalLMSDashboard.totalXP = (globalLMSDashboard.totalXP || 0) + xpEarned;
      }
    }
    renderStudentEngagementWidgets();
    updateStudentHeroLevelBannerV15();

    Swal.fire({
      icon: skor >= 75 ? 'success' : 'info',
      title: skor === 100 ? `Sempurna! Skor 100/100` : `Skor Kuis Kamu: ${skor}/100`,
      html: `
        <div style="text-align:left; font-size:13.5px; line-height:1.6;">
          <p>Kamu menjawab benar <b>${benar} dari ${kuis.length}</b> soal.</p>
          <div style="background:#ecfdf5; border:1.5px solid #6ee7b7; border-radius:12px; padding:12px; margin:10px 0;">
            <div style="font-weight:800; color:#065f46; margin-bottom:4px;"><i class="fa-solid fa-bolt"></i> Rincian Perolehan XP Terverifikasi:</div>
            <div>• Aktivitas Eksplorasi, Kartu 3D & Refleksi AI: <b>+${verStatus.verifiedXPBonus} XP</b></div>
            <div>• Penguasaan Kuis Formatif (${skor}%): <b>+${quizXP} XP</b></div>
            <div style="border-top:1px dashed #fbbf24; margin-top:6px; padding-top:6px; font-weight:900; color:#047857; font-size:14.5px;">Total Diperoleh: +${xpEarned} XP</div>
          </div>
          ${wrongIndices.length > 0 ? `<p style="color:#be123c; font-weight:700;">💡 Ada ${wrongIndices.length} soal yang belum tepat. Gunakan tombol <b>"Minta Bimbingan AI Groq"</b> pada soal tersebut, perbaiki pilihanmu, lalu klik Periksa Ulang untuk meraih skor 100!</p>` : `<p style="color:#047857; font-weight:700;">🎉 Luar biasa! Kamu telah menguasai seluruh soal pada modul ini secara utuh.</p>`}
        </div>`,
      confirmButtonText: wrongIndices.length > 0 ? 'Perbaiki dengan Bimbingan AI' : 'Mantap!',
      customClass: { popup: 'swal-custom-popup', confirmButton: 'swal-custom-confirm' }
    });
  }).saveStudentLMSProgress({
    email: studentData.email,
    nama: studentData.name,
    kelas: studentData.kelas,
    mapel: activeLMSSubject,
    idModul: activeLMSModule.id,
    judulModul: activeLMSModule.judul,
    skor: skor,
    xpVerified: totalVerifiedXP,
    refleksi: studentLMSReflectionText || 'Terverifikasi AI Groq'
  });
};

// F. 9 MISI EKSPLORASI BERTINGKAT & 12 KOLEKSI LENCANA KEHORMATAN (DENGAN PROGRESS BAR & FILTER)
let currentQuestTierFilterV15 = 'ALL';

function setStudentQuestTierFilter(tier) {
  playStudentSFX('click');
  currentQuestTierFilterV15 = tier;
  ['ALL', 'PEMULA', 'PENJELAJAH', 'MASTER'].forEach(t => {
    const btn = document.getElementById('qtab-' + t.toLowerCase());
    if (btn) btn.classList.toggle('active', t === tier);
  });
  renderStudentEngagementWidgets();
}

renderStudentEngagementWidgets = function() {
  const completedMap = globalLMSDashboard.completedMap || {};
  const completedList = Object.values(completedMap);
  const modDoneCount = completedList.length;
  const tr = getStudentVerifiedTracker();
  const totalXP = (globalLMSDashboard.totalXP || 0) + getStudentBonusActivityXP();

  const totalReadSeconds = Object.values(tr.readTimers || {}).reduce((a, b) => a + b, 0);
  const totalSubChecked = Object.keys(lmsSubConceptChecked || {}).filter(k => lmsSubConceptChecked[k]).length + Object.keys(tr.subChecked || {}).length;
  const totalCardsMastered = Object.keys(lmsFlashcardMastery || {}).filter(k => lmsFlashcardMastery[k] === 'mastered').length + Object.keys(tr.cardsMastered || {}).filter(k => tr.cardsMastered[k] === 'mastered').length;
  const totalAIEvalPassed = Object.values(tr.aiEvaluated || {}).filter(v => v && v.passed).length;
  const high85Count = completedList.filter(c => c.skor >= 85).length;
  const perfect100Count = completedList.filter(c => c.skor === 100).length;
  const uniqueMapelsDone = new Set(completedList.map(c => c.mapel).filter(Boolean)).size;

  // Hitung jumlah catatan pintar yang diisi (>= 20 karakter)
  let notesFilledCount = 0;
  for (let i = 0; i < localStorage.length; i++) {
    const k = localStorage.key(i);
    if (k && k.startsWith(`lms_notes_${studentData.email || 'siswa'}_`)) {
      if ((localStorage.getItem(k) || '').trim().length >= 20) notesFilledCount++;
    }
  }

  // 9 Misi Eksplorasi Bertingkat yang Menantang & Terverifikasi
  const allQuests = [
    // Tier PEMULA (Eksplorasi Dasar)
    {
      tier: 'PEMULA',
      title: 'Literasi Tekun: Baca Materi Aktif Minimal 90 Detik & Ceklis 3 Sub-Konsep',
      reward: '+60 XP',
      progress: Math.min(90, totalReadSeconds),
      target: 90,
      unit: 'dtk baca',
      done: totalReadSeconds >= 90 && totalSubChecked >= 3
    },
    {
      tier: 'PEMULA',
      title: 'Daya Ingat Visual: Balik & Tandai "Sudah Hafal" pada Minimal 4 Kartu Pintar 3D',
      reward: '+75 XP',
      progress: Math.min(4, totalCardsMastered),
      target: 4,
      unit: 'kartu hafal',
      done: totalCardsMastered >= 4
    },
    {
      tier: 'PEMULA',
      title: 'Juru Arsip Cermat: Tulis Rangkuman Pribadi di Laci Catatan Pintar (Min. 1 Bab)',
      reward: '+50 XP',
      progress: Math.min(1, notesFilledCount),
      target: 1,
      unit: 'catatan bab',
      done: notesFilledCount >= 1
    },
    // Tier PENJELAJAH (Tantangan Aktif & AI Sokratik)
    {
      tier: 'PENJELAJAH',
      title: 'Pemikir Sokratik AI: Lulus Verifikasi Jurnal Refleksi Bersama AI Groq (Skor ≥ 70)',
      reward: '+120 XP',
      progress: Math.min(1, totalAIEvalPassed),
      target: 1,
      unit: 'jurnal lulus AI',
      done: totalAIEvalPassed >= 1
    },
    {
      tier: 'PENJELAJAH',
      title: 'Dialog Kritis: Diskusikan Konsep atau Gunakan Bimbingan Coach AI Groq Minimal 2x',
      reward: '+90 XP',
      progress: Math.min(2, (tr.aiChatCount || 0) + (tr.socraticHintsUsed || 0)),
      target: 2,
      unit: 'sesi diskusi AI',
      done: ((tr.aiChatCount || 0) + (tr.socraticHintsUsed || 0)) >= 2
    },
    {
      tier: 'PENJELAJAH',
      title: 'Penjelajah Lintas Ilmu: Tuntaskan Modul Terverifikasi pada Minimal 2 Mata Pelajaran',
      reward: '+180 XP',
      progress: Math.min(2, uniqueMapelsDone || modDoneCount),
      target: 2,
      unit: 'mapel tuntas',
      done: (uniqueMapelsDone >= 2) || (modDoneCount >= 2)
    },
    // Tier MASTER (Master HOTS & Dedikasi Tinggi)
    {
      tier: 'MASTER',
      title: 'Penakluk HOTS: Raih Skor Kuis Formatif ≥ 85 pada Minimal 2 Modul Pembelajaran',
      reward: '+250 XP',
      progress: Math.min(2, high85Count),
      target: 2,
      unit: 'modul skor ≥85',
      done: high85Count >= 2
    },
    {
      tier: 'MASTER',
      title: 'Akurasi Sempurna: Raih Skor 100/100 pada Kuis Evaluasi Formatif Modul',
      reward: '+300 XP',
      progress: Math.min(1, perfect100Count),
      target: 1,
      unit: 'skor 100',
      done: perfect100Count >= 1
    },
    {
      tier: 'MASTER',
      title: 'Keringat Emas Sejati: Tuntaskan 4 Modul & Kumpulkan Minimal 1.250 Total XP',
      reward: 'Gelar Lv.5',
      progress: Math.min(1250, totalXP),
      target: 1250,
      unit: 'XP terkumpul',
      done: modDoneCount >= 4 && totalXP >= 1250
    }
  ];

  const doneQuestsCount = allQuests.filter(q => q.done).length;
  const qBadge = document.getElementById('student-quest-progress-badge');
  if (qBadge) qBadge.innerText = `${doneQuestsCount}/${allQuests.length} Misi Tuntas`;

  const filteredQuests = currentQuestTierFilterV15 === 'ALL'
    ? allQuests
    : allQuests.filter(q => q.tier === currentQuestTierFilterV15);

  const qListEl = document.getElementById('student-daily-quests-list');
  if (qListEl) {
    qListEl.innerHTML = filteredQuests.map(q => {
      const pct = Math.min(100, Math.round((q.progress / Math.max(1, q.target)) * 100));
      const tierBadgeColor = q.tier === 'MASTER' ? '#7c3aed' : (q.tier === 'PENJELAJAH' ? '#0284c7' : '#059669');
      return `
        <div class="quest-item ${q.done ? 'done' : ''}">
          <div class="quest-item-left" style="width:100%;">
            <i class="fa-solid ${q.done ? 'fa-circle-check' : 'fa-circle-dot'}" style="color:${q.done ? '#10b981' : '#10b981'};"></i>
            <div style="flex:1; min-width:0;">
              <div style="display:flex; align-items:center; gap:6px; flex-wrap:wrap; margin-bottom:2px;">
                <span style="font-size:9.5px; font-weight:900; color:white; background:${tierBadgeColor}; padding:1px 6px; border-radius:99px;">${q.tier}</span>
                <span style="font-size:10.5px; font-weight:800; color:#64748b;">Progres: ${q.progress}/${q.target} ${q.unit} (${pct}%)</span>
              </div>
              <div class="quest-item-title">${q.title}</div>
              <div class="quest-mini-progress-wrap">
                <div class="quest-mini-progress-fill" style="width:${pct}%;"></div>
              </div>
            </div>
          </div>
          <span class="quest-reward-badge" style="background:${q.done ? '#d1fae5' : '#d1fae5'}; color:${q.done ? '#047857' : '#047857'}; border:1px solid ${q.done ? '#6ee7b7' : '#a7f3d0'};">
            ${q.done ? '✓ TUNTAS' : q.reward}
          </span>
        </div>`;
    }).join('');
  }

  // 12 Koleksi Lencana Kehormatan Beragam (Common, Rare, Epic, Legendary) - V16 Clean Handler
  const badges = [
    { icon: 'fa-book-open-reader', name: 'Pembaca Tekun', rarity: 'Common', rClass: 'rarity-common', desc: 'Membaca materi secara aktif minimal 90 detik & menandai 3 pilar konsep.', unlocked: totalReadSeconds >= 90 && totalSubChecked >= 3 },
    { icon: 'fa-clone', name: 'Memory Master 3D', rarity: 'Common', rClass: 'rarity-common', desc: 'Menghafal & menandai Sudah Hafal pada minimal 4 Kartu Pintar 3D.', unlocked: totalCardsMastered >= 4 },
    { icon: 'fa-note-sticky', name: 'Juru Catat Cendekia', rarity: 'Common', rClass: 'rarity-common', desc: 'Menulis rangkuman konsep penting pada Laci Catatan Pintar.', unlocked: notesFilledCount >= 1 },
    { icon: 'fa-compass', name: 'Penjelajah Pertama', rarity: 'Common', rClass: 'rarity-common', desc: 'Menuntaskan seluruh 5 tahap pada modul belajar pertama.', unlocked: modDoneCount >= 1 },
    { icon: 'fa-brain', name: 'Filsuf Sokratik AI', rarity: 'Rare', rClass: 'rarity-rare', desc: 'Lulus evaluasi Jurnal Refleksi Studi Kasus bersama Mentor AI Groq (Skor ≥ 70).', unlocked: totalAIEvalPassed >= 1 },
    { icon: 'fa-robot', name: 'Sahabat Diskusi AI', rarity: 'Rare', rClass: 'rarity-rare', desc: 'Aktif berdiskusi & meminta bimbingan penalaran pada AI Tutor / Coach AI.', unlocked: ((tr.aiChatCount || 0) + (tr.socraticHintsUsed || 0)) >= 2 },
    { icon: 'fa-bullseye', name: 'Penembak Jitu HOTS', rarity: 'Rare', rClass: 'rarity-rare', desc: 'Meraih skor kuis formatif minimal 85 pada modul pembelajaran.', unlocked: high85Count >= 1 },
    { icon: 'fa-stopwatch', name: 'Fokus Pomodoro', rarity: 'Rare', rClass: 'rarity-rare', desc: 'Menyelesaikan sesi fokus belajar Pomodoro 25 menit penuh.', unlocked: (tr.pomodoroCompleted || 0) >= 1 },
    { icon: 'fa-earth-asia', name: 'Polimatik Kelas 7', rarity: 'Epic', rClass: 'rarity-epic', desc: 'Menuntaskan modul pembelajaran pada minimal 3 mata pelajaran berbeda.', unlocked: uniqueMapelsDone >= 3 || modDoneCount >= 3 },
    { icon: 'fa-star', name: 'Perfeksionis 100%', rarity: 'Epic', rClass: 'rarity-epic', desc: 'Meraih nilai sempurna 100/100 pada Kuis Evaluasi Formatif.', unlocked: perfect100Count >= 1 },
    { icon: 'fa-fire-flame-curved', name: 'Keringat Emas', rarity: 'Legendary', rClass: 'rarity-legend', desc: 'Mengumpulkan minimal 1.250 Total XP Terverifikasi di Kelas 7.', unlocked: totalXP >= 1250 },
    { icon: 'fa-crown', name: 'Grandmaster Cendekia', rarity: 'Legendary', rClass: 'rarity-legend', desc: 'Mencapai Level 7 (≥ 2.500 XP) & menuntaskan minimal 5 modul pembelajaran.', unlocked: totalXP >= 2500 && modDoneCount >= 5 }
  ];
  window.currentStudentBadgesListV16 = badges;

  const unlockedBadgesCount = badges.filter(b => b.unlocked).length;
  const bCountLbl = document.getElementById('student-badges-count-label');
  if (bCountLbl) bCountLbl.innerText = `${unlockedBadgesCount}/${badges.length} Lencana Terbuka`;

  const bBox = document.getElementById('student-badges-showcase');
  if (bBox) {
    bBox.innerHTML = badges.map((b, idx) => `
      <div class="badge-medal-pill ${b.unlocked ? 'unlocked' : ''}" onclick="openStudentBadgeDetailModal(${idx})">
        <div class="badge-icon-circle"><i class="fa-solid ${b.icon}"></i></div>
        <div style="min-width:0; flex:1;">
          <div style="font-weight:800; font-size:12px; color:var(--text-main); white-space:nowrap; overflow:hidden; text-overflow:ellipsis;">${escapeHtml(b.name)}</div>
          <div style="display:flex; align-items:center; gap:5px; margin-top:2px;">
            <span class="badge-rarity-tag ${b.rClass}">${b.rarity}</span>
            <span style="font-size:9.5px; font-weight:800; color:${b.unlocked ? '#047857' : '#94a3b8'};">${b.unlocked ? '✓ Terbuka' : '🔒 Terkunci'}</span>
          </div>
        </div>
      </div>`).join('');
  }

  // Render Live XP Leaderboard
  const lbBox = document.getElementById('student-leaderboard-box');
  if (lbBox) {
    const lbList = globalLMSDashboard.leaderboard || [];
    if (lbList.length === 0) {
      lbBox.innerHTML = `<div style="text-align:center; padding:24px 12px; color:#94a3b8; font-size:12.5px; font-weight:600;">Jadilah siswa pertama yang mencetak skor XP Terverifikasi di Papan Bintang Cendekia Kelas 7!</div>`;
    } else {
      lbBox.innerHTML = lbList.map((item, idx) => {
        let medalColor = idx === 0 ? '#10b981' : (idx === 1 ? '#64748b' : (idx === 2 ? '#047857' : '#94a3b8'));
        let isMe = studentData.name && item.nama.toLowerCase() === studentData.name.toLowerCase();
        let rankInfo = getStudentRankInfoV15(item.totalXP);
        return `
          <div class="lb-student-row ${isMe ? 'is-me' : ''}">
            <div class="lb-student-left">
              <span class="lb-rank-circle" style="background:${medalColor};">#${item.rank}</span>
              <div class="lb-student-info">
                <div class="lb-student-name" title="${escapeHtml(item.nama)}">${escapeHtml(item.nama)} ${isMe ? '<span style="color:#059669;">(Kamu)</span>' : ''}</div>
                <div class="lb-student-meta">Kelas ${escapeHtml(item.kelas)} &bull; Lv.${rankInfo.current.level} ${rankInfo.current.title} &bull; ${item.modCount} Bab</div>
              </div>
            </div>
            <span class="lb-xp-badge"><i class="fa-solid fa-bolt"></i> ${item.totalXP} XP</span>
          </div>`;
      }).join('');
    }
  }

  updateStudentHeroLevelBannerV15();
};

// G. SUNTIKKAN PANEL VERIFIKASI AKTIVITAS, CEKLIS SUB-MATERI, & TOMBOL AI GROQ KE RUANG BELAJAR LMS
const _v14RenderConstructiveWorkspace = renderConstructiveWorkspace;
renderConstructiveWorkspace = function() {
  _v14RenderConstructiveWorkspace();
  if (!activeLMSModule) return;

  const ws = document.getElementById('lms-constructive-workspace');
  if (!ws) return;
  const tr = getStudentVerifiedTracker();
  const modId = activeLMSModule.id;
  const readSec = tr.readTimers[modId] || 0;
  const isEnoughRead = readSec >= 45;

  // 1. Tambahkan indikator Waktu Baca Aktif pada Toolbar Narator di atas modul
  const toolbar = ws.querySelector('.lms-interactive-toolbar');
  if (toolbar) {
    toolbar.insertAdjacentHTML('beforeend', `
      <span id="v15-read-time-indicator" style="font-size:11.5px; font-weight:800; padding:5px 11px; border-radius:99px; background:${isEnoughRead ? '#d1fae5' : '#d1fae5'}; color:${isEnoughRead ? '#065f46' : '#065f46'}; border:1px solid #6ee7b7;">
        <i class="fa-solid ${isEnoughRead ? 'fa-circle-check' : 'fa-hourglass-half'}"></i> Waktu Eksplorasi Aktif: <b>${readSec} dtk</b> ${isEnoughRead ? '(Terverifikasi ✓)' : '(Min. 45 dtk)'}
      </span>`);
  }

  // 2. Pada Tahap 2 (Eksplorasi Konsep): Tambahkan tombol Ceklis Pemahaman di setiap kartu Sub-Materi
  if (activeLMSStep === 2) {
    const k = activeLMSModule.konten || {};
    const subArr = (k.eksplorasi && Array.isArray(k.eksplorasi.sub_materi)) ? k.eksplorasi.sub_materi : [];
    const subHeadings = ws.querySelectorAll('h4');
    subHeadings.forEach((h4El, idx) => {
      if (idx < subArr.length && h4El.parentElement) {
        const key = `${modId}_sub_${idx}`;
        const isChecked = !!(lmsSubConceptChecked[key] || tr.subChecked[key]);
        h4El.parentElement.insertAdjacentHTML('beforeend', `
          <div style="margin-top:12px; display:flex; justify-content:flex-end;">
            <button type="button" id="btn-subcheck-${idx}" class="submateri-Interactive-check-btn ${isChecked ? 'understood' : ''}" onclick="toggleSubConceptCheckV15(${idx})">
              <i class="fa-${isChecked ? 'solid' : 'regular'} fa-circle-check"></i>
              ${isChecked ? 'Pilar Konsep Ini Sudah Aku Baca & Pahami! (+XP)' : 'Tandai Sudah Membaca & Memahami Pilar Ini'}
            </button>
          </div>`);
      }
    });
  }

  // 3. Pada Tahap 4 (Studi Kasus & Jurnal Refleksi): Pasang Mentor Sokratik AI Groq & Tombol Verifikasi Refleksi AI
  if (activeLMSStep === 4) {
    const panduanBtn = ws.querySelector('button[onclick*="box-panduan-solusi"]');
    if (panduanBtn) {
      panduanBtn.outerHTML = `
        <button type="button" id="btn-ai-socratic-guide" onclick="mintaPanduanBerpikirAIGroq()" style="margin-top:12px; background:linear-gradient(135deg, #7c3aed, #6d28d9); color:white; border:none; padding:10px 18px; border-radius:12px; font-size:12.5px; font-weight:800; cursor:pointer; display:inline-flex; align-items:center; gap:8px; box-shadow:0 6px 15px rgba(109,40,217,0.25);">
          <i class="fa-solid fa-wand-magic-sparkles"></i> Minta Petunjuk Berpikir Sokratik AI Groq (Tanpa Bocoran Jawaban)
        </button>
        <div id="ai-socratic-case-guide-box" class="ai-socratic-coach-box hidden"></div>`;
    }

    const reflArea = document.getElementById('inp-lms-refleksi');
    if (reflArea) {
      const prevEval = tr.aiEvaluated[modId];
      reflArea.insertAdjacentHTML('afterend', `
        <div style="margin-top:12px; display:flex; justify-content:space-between; align-items:center; flex-wrap:wrap; gap:10px;">
          <span style="font-size:12px; color:#64748b; font-weight:700;">
            <i class="fa-solid fa-shield-halved" style="color:#059669;"></i> Wajib minimal 10 kata & diverifikasi oleh AI Groq untuk membuka Klaim XP Kuis.
          </span>
          <button type="button" id="btn-verify-reflection-ai" onclick="verifikasiJurnalRefleksiAIGroq()" style="background:linear-gradient(135deg, #7c3aed, #6d28d9); color:white; border:none; padding:11px 20px; border-radius:12px; font-weight:800; font-size:13px; cursor:pointer; display:inline-flex; align-items:center; gap:8px; box-shadow:0 6px 16px rgba(124,58,237,0.25);">
            <i class="fa-solid fa-robot"></i> Evaluasi & Verifikasi Refleksiku dengan AI Groq (+45 XP)
          </button>
        </div>
        <div id="ai-reflection-eval-result" class="ai-socratic-coach-box ${prevEval ? '' : 'hidden'}" style="${prevEval && prevEval.passed ? 'background:#ecfdf5; border-color:#10b981; color:#065f46;' : ''}">
          ${prevEval ? `<div style="font-weight:900;"><i class="fa-solid fa-circle-check"></i> Status Refleksi: ${prevEval.passed ? 'LULUS VERIFIKASI AI GROQ ✓' : 'Perlu Diperbaiki'} (Skor: ${prevEval.score}/100)</div><div style="margin-top:4px;">${escapeHtml(prevEval.feedback || '')}</div>` : ''}
        </div>`);
    }
  }

  // 4. Pada Tahap 5 (Kuis Formatif & Klaim XP): Tampilkan Checklist Verifikasi Anti-Skip & Tombol Petunjuk Sokratik per Soal
  if (activeLMSStep === 5) {
    const verStatus = getModuleVerificationStatusV15(activeLMSModule);
    const checklistItemsHtml = verStatus.items.map(it => `
      <div class="xp-verify-item ${it.done ? 'verified' : ''}" onclick="if(!${it.done}) switchLMSStep(${it.step})" style="cursor:pointer;">
        <i class="fa-solid ${it.done ? 'fa-circle-check' : 'fa-circle-xmark'}" style="font-size:15px; color:${it.done ? '#10b981' : '#10b981'};"></i>
        <div style="flex:1; min-width:0;">
          <div style="line-height:1.3;">${it.label}</div>
          <div style="font-size:10px; font-weight:900; color:${it.done ? '#047857' : '#059669'};">${it.done ? `Terverifikasi (+${it.xp} XP)` : `Belum Tuntas • Klik ke Tahap ${it.step}`}</div>
        </div>
      </div>`).join('');

    const verifyBannerHtml = `
      <div class="xp-verification-checklist-box">
        <div style="display:flex; justify-content:space-between; align-items:center; flex-wrap:wrap; gap:8px;">
          <div>
            <div style="font-size:14.5px; font-weight:900; color:#064e3b;">
              <i class="fa-solid fa-shield-check" style="color:#059669;"></i> Gerbang Verifikasi Ketuntasan Belajar (Anti-Instan XP)
            </div>
            <div style="font-size:12px; color:#065f46; margin-top:2px;">
              Pastikan aktivitas membaca, Kartu 3D, dan Jurnal Refleksi AI sudah bertanda centang hijau agar kamu bisa mengklaim XP penuh!
            </div>
          </div>
          <span style="background:${verStatus.allReady ? '#10b981' : '#10b981'}; color:white; padding:5px 12px; border-radius:99px; font-size:11.5px; font-weight:900;">
            Bonus Aktivitas: +${verStatus.verifiedXPBonus} XP
          </span>
        </div>
        <div class="xp-verify-grid">${checklistItemsHtml}</div>
      </div>`;

    const firstChildInStep5 = ws.querySelector('.lms-interactive-toolbar');
    if (firstChildInStep5) {
      firstChildInStep5.insertAdjacentHTML('afterend', verifyBannerHtml);
    }

    // Tambahkan tombol "Petunjuk Sokratik AI Groq" di setiap kartu soal kuis
    const kuis = Array.isArray(activeLMSModule.kuis) ? activeLMSModule.kuis : [];
    kuis.forEach((_, qIdx) => {
      const fbEl = document.getElementById('lms-quiz-feedback-' + qIdx);
      if (fbEl && fbEl.parentElement) {
        fbEl.insertAdjacentHTML('beforebegin', `
          <div style="margin-top:8px; display:flex; justify-content:flex-end;">
            <button type="button" onclick="mintaPetunjukSokratikSoalKuis(${qIdx}, 'HINT')" style="background:#f5f3ff; color:#6d28d9; border:1.5px solid #c4b5fd; padding:6px 12px; border-radius:10px; font-size:11.5px; font-weight:800; cursor:pointer; display:inline-flex; align-items:center; gap:6px;">
              <i class="fa-solid fa-wand-magic-sparkles"></i> Petunjuk Berpikir AI Groq (Tanpa Bocoran Kunci)
            </button>
          </div>
          <div id="lms-quiz-socratic-${qIdx}" class="ai-socratic-coach-box hidden"></div>`);
      }
    });
  }
};

function toggleSubConceptCheckV15(subIdx) {
  toggleSubConceptCheck(subIdx);
  if (!activeLMSModule) return;
  const tr = getStudentVerifiedTracker();
  const key = `${activeLMSModule.id}_sub_${subIdx}`;
  if (lmsSubConceptChecked[key]) tr.subChecked[key] = true;
  else delete tr.subChecked[key];
  saveStudentVerifiedTracker(tr);
  renderStudentEngagementWidgets();
}

const _v14SetFlashcardMasteryStatus = setFlashcardMasteryStatus;
setFlashcardMasteryStatus = function(cardIdx, status) {
  _v14SetFlashcardMasteryStatus(cardIdx, status);
  if (!activeLMSModule) return;
  const tr = getStudentVerifiedTracker();
  tr.cardsMastered[`${activeLMSModule.id}_card_${cardIdx}`] = status;
  saveStudentVerifiedTracker(tr);
  renderStudentEngagementWidgets();
};

const _v14KirimPesanKeAITutor = kirimPesanKeAITutor;
kirimPesanKeAITutor = function() {
  const tr = getStudentVerifiedTracker();
  tr.aiChatCount = (tr.aiChatCount || 0) + 1;
  saveStudentVerifiedTracker(tr);
  _v14KirimPesanKeAITutor();
  renderStudentEngagementWidgets();
};


// =====================================================================
// 22. MODAL DETAIL LENCANA BERSIH & NOTIFIKASI MODERN REKAP PROGRES MODUL (V16)
// =====================================================================
function openStudentBadgeDetailModal(badgeIdx) {
  playStudentSFX('click');
  const list = window.currentStudentBadgesListV16 || [];
  const b = list[badgeIdx];
  if (!b) return;

  Swal.fire({
    icon: b.unlocked ? 'success' : 'info',
    title: `${b.unlocked ? '🏅 ' : '🔒 '}Lencana: ${b.name}`,
    html: `
      <div style="font-size:13.5px; line-height:1.65; text-align:left; background:#f8fafc; padding:16px; border-radius:16px; border:1.5px solid #e2e8f0;">
        <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:10px;">
          <span class="badge-rarity-tag ${b.rClass}" style="font-size:11px; padding:3px 10px;">Tingkat Kelangkaan: ${escapeHtml(b.rarity)}</span>
          <span style="font-size:12px; font-weight:900; color:${b.unlocked ? '#047857' : '#059669'};">
            ${b.unlocked ? '✓ SUDAH TERBUKA' : '🔒 BELUM TERBUKA'}
          </span>
        </div>
        <div style="color:#334155; margin-bottom:10px;">
          <b><i class="fa-solid fa-bullseye" style="color:#10b981;"></i> Syarat Membuka Lencana:</b><br>
          ${escapeHtml(b.desc)}
        </div>
        <div style="font-size:12px; background:${b.unlocked ? '#ecfdf5' : '#ecfdf5'}; color:${b.unlocked ? '#065f46' : '#065f46'}; padding:10px 12px; border-radius:10px; font-weight:700; border:1px solid ${b.unlocked ? '#6ee7b7' : '#a7f3d0'};">
          ${b.unlocked
            ? '🎉 Luar biasa! Kamu telah memenuhi seluruh syarat verifikasi dan resmi menyandang lencana kehormatan ini.'
            : '💡 Tips: Buka modul di Ruang Belajar LMS dan selesaikan aktivitas di atas agar lencana ini terbuka otomatis!'}
        </div>
      </div>`,
    confirmButtonText: b.unlocked ? 'Mantap!' : 'Siap Kejar Tantangan!',
    customClass: { popup: 'swal-custom-popup', confirmButton: 'swal-custom-confirm' }
  });
}

let hudModuleProgressTimeout = null;

function closeModuleProgressNotificationHud() {
  const hud = document.getElementById('lmsModuleProgressHud');
  if (hud) hud.classList.remove('show');
  if (hudModuleProgressTimeout) {
    clearTimeout(hudModuleProgressTimeout);
    hudModuleProgressTimeout = null;
  }
}

function showModernModuleProgressNotification(mod) {
  return; // Nonaktifkan popup HUD mengambang agar tampilan modul bersih & fokus
  const hud = document.getElementById('lmsModuleProgressHud');
  if (!hud || !mod) return;

  const verStatus = getModuleVerificationStatusV15(mod);
  const prevRec = (globalLMSDashboard.completedMap || {})[mod.id];
  const quizDone = prevRec !== undefined;
  const quizScore = quizDone ? prevRec.skor : null;
  const quizXP = quizDone ? prevRec.xp : 0;

  // Hitung 5 komponen progres pembelajaran di modul ini
  const pillItems = [
    { icon: 'fa-book-open-reader', label: 'Baca Aktif', done: verStatus.readOk, step: 2 },
    { icon: 'fa-list-check', label: 'Pilar Konsep', done: verStatus.subOk, step: 2 },
    { icon: 'fa-clone', label: 'Kartu 3D', done: verStatus.cardsOk, step: 3 },
    { icon: 'fa-robot', label: 'Refleksi AI', done: verStatus.reflOk, step: 4 },
    { icon: 'fa-trophy', label: quizDone ? `Kuis (${quizScore})` : 'Kuis XP', done: quizDone, step: 5 }
  ];

  const doneCount = pillItems.filter(p => p.done).length;
  const pct = Math.round((doneCount / pillItems.length) * 100);

  // Tentukan langkah selanjutnya yang disarankan
  let nextStepNum = 1;
  let nextStepText = 'Mulai Tahap 1';
  if (!verStatus.readOk || !verStatus.subOk) {
    nextStepNum = 2;
    nextStepText = 'Lanjut Eksplorasi (Tahap 2)';
  } else if (!verStatus.cardsOk) {
    nextStepNum = 3;
    nextStepText = 'Lanjut Kartu 3D (Tahap 3)';
  } else if (!verStatus.reflOk) {
    nextStepNum = 4;
    nextStepText = 'Lanjut Refleksi AI (Tahap 4)';
  } else if (!quizDone || (quizScore !== null && quizScore < 100)) {
    nextStepNum = 5;
    nextStepText = quizDone ? 'Tingkatkan Kuis ke 100' : 'Kerjakan Kuis XP (Tahap 5)';
  } else {
    nextStepNum = 5;
    nextStepText = 'Tuntas Sempurna 100%!';
  }

  const pillsHtml = pillItems.map(p => `
    <div class="hud-mod-pill ${p.done ? 'done' : ''}" onclick="closeModuleProgressNotificationHud(); switchLMSStep(${p.step});" title="Klik untuk menuju Tahap ${p.step}">
      <i class="fa-solid ${p.done ? 'fa-circle-check' : p.icon}"></i>
      <span class="hud-mod-pill-lbl">${escapeHtml(p.label)}</span>
    </div>`).join('');

  hud.innerHTML = `
    <div class="hud-mod-top">
      <div style="min-width:0; flex:1;">
        <div style="display:flex; align-items:center; gap:8px; flex-wrap:wrap;">
          <span class="hud-mod-badge"><i class="fa-solid fa-sparkles"></i> REKAP PROGRES MODUL (${pct}%)</span>
          <span style="font-size:11px; font-weight:800; color:#6ee7b7;">
            ${quizDone ? `⚡ +${quizXP} XP Tercatat` : `⚡ Potensi Bonus +${verStatus.verifiedXPBonus} XP`}
          </span>
        </div>
        <div class="hud-mod-title">${escapeHtml(mod.judul)}</div>
      </div>
      <button type="button" class="hud-mod-close" onclick="closeModuleProgressNotificationHud()" title="Tutup Notifikasi">
        <i class="fa-solid fa-xmark"></i>
      </button>
    </div>

    <div class="hud-mod-bar-wrap">
      <div class="hud-mod-bar-fill" style="width:${Math.max(8, pct)}%;"></div>
    </div>

    <div class="hud-mod-pills-grid">${pillsHtml}</div>

    <div class="hud-mod-footer">
      <span style="font-size:11px; color:#cbd5e1; font-weight:700;">
        <i class="fa-solid fa-circle-info" style="color:#38bdf8;"></i> ${doneCount}/5 Aktivitas Tuntas ${quizDone ? `• Skor Kuis Terbaik: <b style="color:#fbbf24;">${quizScore}/100</b>` : ''}
      </span>
      <button type="button" class="hud-mod-next-btn" onclick="closeModuleProgressNotificationHud(); switchLMSStep(${nextStepNum});">
        <span>${nextStepText}</span> <i class="fa-solid fa-arrow-right"></i>
      </button>
    </div>
  `;

  // Tampilkan dengan animasi slide-down modern
  requestAnimationFrame(() => {
    hud.classList.add('show');
  });

  if (hudModuleProgressTimeout) clearTimeout(hudModuleProgressTimeout);
  hudModuleProgressTimeout = setTimeout(() => {
    closeModuleProgressNotificationHud();
  }, 7500);
}

// Hook ke selectStudentLMSModule agar setiap kali siswa membuka modul (atau ganti bab), notifikasi progres modern langsung tampil!
const _v15SelectStudentLMSModule = selectStudentLMSModule;
selectStudentLMSModule = function(modIdx) {
  _v15SelectStudentLMSModule(modIdx);
  if (activeLMSModule) {
    setTimeout(() => {
      showModernModuleProgressNotification(activeLMSModule);
    }, 220);
  }
};

// Sembunyikan notifikasi progres modul saat kembali ke Beranda
const _v15KembaliKeDashboard = kembaliKeDashboardSiswa;
kembaliKeDashboardSiswa = function() {
  closeModuleProgressNotificationHud();
  _v15KembaliKeDashboard();
};


// =====================================================================
// 22. LOGIKA FRONTEND: STUDIO & WORKSPACE ANALISIS VIDEO PEMBELAJARAN (V19)
//     (YOUTUBE / GOOGLE DRIVE EMBED + RANGKUMAN AI GROQ + TUGAS ISIAN & KUIS VIDEO)
// =====================================================================
let activeVideoSubTab = {};      // modId -> 'rangkuman' | 'isian' | 'kuis'
let studentVideoIsianAnswers = {}; // modId -> { 0: '...', 1: '...' }
let studentVideoKuisAnswers = {};  // modId -> { 0: 'A', 1: 'C' }
let studentVideoEvalResult = {};   // modId -> { skorIsian, skorKuisPG, skorAkhirVideo, data }

function bukaModalStudioVideoPilihModul() {
  if (!adminLMSModulesList || adminLMSModulesList.length === 0) {
    Swal.fire({
      icon: 'info',
      title: 'Belum Ada Modul LMS',
      text: 'Silakan buat minimal 1 Modul Pembelajaran terlebih dahulu menggunakan tombol "Buat Materi & Kuis dengan AI", lalu tambahkan Link Video pembelajarannya!',
      customClass: { popup: 'swal-custom-popup', confirmButton: 'swal-custom-confirm' }
    });
    return;
  }

  let modOpts = adminLMSModulesList.map(m =>
    `<option value="${escapeHtml(m.id)}">[${escapeHtml(m.mapel)}] ${escapeHtml(m.judul)}</option>`
  ).join('');

  Swal.fire({
    title: '<i class="fa-solid fa-clapperboard" style="color:#059669;"></i> Pilih Modul Target Video Pembelajaran',
    html: `
      <div style="text-align:left; font-size:13.5px;">
        <p style="color:#475569; margin-bottom:12px;">Pilih modul pembelajaran yang akan disematkan <b>Video YouTube / Google Drive</b> beserta <b>Rangkuman & Tugas Analisis Video AI Groq</b>:</p>
        <label class="edit-label">Pilih Modul Pembelajaran Aktif</label>
        <select id="sel-modul-video-studio" class="swal-custom-input" style="width:100%; background:#f8fafc;">
          ${modOpts}
        </select>
      </div>`,
    showCancelButton: true,
    confirmButtonText: '<i class="fa-solid fa-arrow-right"></i> Lanjut Konfigurasi Video AI',
    cancelButtonText: 'Batal',
    customClass: { popup: 'swal-custom-popup', confirmButton: 'swal-custom-confirm' },
    preConfirm: () => {
      return document.getElementById('sel-modul-video-studio').value;
    }
  }).then(res => {
    if (res.isConfirmed && res.value) {
      bukaModalUploadAnalisisVideoManual(res.value);
    }
  });
}

function bukaModalUploadAnalisisVideoManual(idModul) {
  const m = (adminLMSModulesList || []).find(x => x.id === idModul);
  if (!m) return;
  const k = m.konten || {};
  const existingVid = k.video_interaktif || {};

  Swal.fire({
    title: '<i class="fa-solid fa-clapperboard" style="color:#059669;"></i> Upload Link Video & Analisis AI Groq',
    width: '680px',
    html: `
      <div style="text-align:left; font-size:13.5px;">
        <div style="background:#ecfdf5; border:1.5px solid #6ee7b7; padding:12px 15px; border-radius:14px; color:#065f46; margin-bottom:14px; line-height:1.55;">
          <b><i class="fa-solid fa-wand-magic-sparkles"></i> AI Groq Video Analyzer Engine:</b><br>
          Tempelkan tautan <b>YouTube</b> atau <b>Google Drive</b> video pembelajaran untuk modul <b>"${escapeHtml(m.judul)}"</b> (${escapeHtml(m.mapel)}). Sistem AI Groq akan merakit <b>Rangkuman Eksekutif</b>, <b>3 Pilar Analisis Mendalam</b>, <b>Penugasan Isian Analitis</b>, serta <b>Kuis Pilihan Ganda Analisis Video</b> secara otomatis!
        </div>

        <label class="edit-label"><i class="fa-brands fa-youtube" style="color:#e11d48;"></i> Tautan / Link Video (YouTube atau Google Drive)</label>
        <input type="text" id="inp-video-url-admin" class="swal-custom-input" style="width:100%; margin-bottom:12px; background:#f8fafc;" placeholder="Contoh: https://www.youtube.com/watch?v=... atau https://drive.google.com/file/d/.../view" value="${escapeHtml(existingVid.url_asli || '')}">

        <label class="edit-label">Judul / Topik Video Pembelajaran (Opsional - Otomatis Terdeteksi jika Kosong)</label>
        <input type="text" id="inp-video-title-admin" class="swal-custom-input" style="width:100%; margin-bottom:12px; background:#f8fafc;" placeholder="Contoh: Eksperimen Sistem Pencernaan & Enzim Manusia" value="${escapeHtml(existingVid.judul_video || '')}">

        <label class="edit-label">Pokok Bahasan / Catatan Isi Video (Untuk Mempertajam Analisis AI Groq)</label>
        <textarea id="inp-video-context-admin" class="swal-custom-input" style="width:100%; height:85px; margin-bottom:14px; background:#f8fafc; line-height:1.5;" placeholder="Tuliskan poin-poin singkat isi video atau konsep yang ingin ditekankan pada rangkuman dan soal analisis video...">${escapeHtml(existingVid.konteks_guru || '')}</textarea>

        <div style="display:grid; grid-template-columns: 1fr 1fr; gap:12px;">
          <div>
            <label class="edit-label">Jumlah Pertanyaan Isian Analisis</label>
            <select id="sel-video-jml-isian" class="swal-custom-input" style="width:100%; background:#f8fafc;">
              <option value="2">2 Soal Isian Analitis</option>
              <option value="3" selected>3 Soal Isian Analitis</option>
              <option value="4">4 Soal Isian Analitis</option>
              <option value="5">5 Soal Isian Analitis</option>
            </select>
          </div>
          <div>
            <label class="edit-label">Jumlah Kuis PG Analisis Video</label>
            <select id="sel-video-jml-kuis" class="swal-custom-input" style="width:100%; background:#f8fafc;">
              <option value="3">3 Soal Kuis PG HOTS</option>
              <option value="4" selected>4 Soal Kuis PG HOTS</option>
              <option value="5">5 Soal Kuis PG HOTS</option>
              <option value="6">6 Soal Kuis PG HOTS</option>
            </select>
          </div>
        </div>
      </div>`,
    showCancelButton: true,
    confirmButtonText: '<i class="fa-solid fa-bolt"></i> Proses Analisis Video & Buat Tugas AI',
    cancelButtonText: 'Batal',
    customClass: { popup: 'swal-custom-popup', confirmButton: 'swal-custom-confirm' },
    preConfirm: () => {
      const vUrl = document.getElementById('inp-video-url-admin').value.trim();
      const vTitle = document.getElementById('inp-video-title-admin').value.trim();
      const vCtx = document.getElementById('inp-video-context-admin').value.trim();
      const jIsian = document.getElementById('sel-video-jml-isian').value;
      const jKuis = document.getElementById('sel-video-jml-kuis').value;
      if (!vUrl) {
        Swal.showValidationMessage('Link Video YouTube atau Google Drive wajib diisi!');
        return false;
      }
      return {
        idModul: idModul,
        videoUrl: vUrl,
        judulVideo: vTitle,
        konteksVideo: vCtx,
        jumlahIsian: jIsian,
        jumlahKuis: jKuis
      };
    }
  }).then(res => {
    if (res.isConfirmed) {
      Swal.fire({
        title: 'AI Groq Sedang Menganalisis Video...',
        html: `Mengekstrak metadata video & menyusun <b>Rangkuman Eksekutif</b>, <b>Poin Analisis Mendalam</b>, <b>${res.value.jumlahIsian} Soal Isian</b>, dan <b>${res.value.jumlahKuis} Kuis Analisis Video</b>...`,
        allowOutsideClick: false,
        didOpen: () => Swal.showLoading(),
        customClass: { popup: 'swal-custom-popup' }
      });

      google.script.run.withSuccessHandler(r => {
        if (r && r.success) {
          fetchAdminLMSData();
          catatRiwayatAksiAdmin(window.currentStaffName || 'GURU', m.mapel, 'UPLOAD & ANALISIS VIDEO AI: ' + m.judul);
          Swal.fire({
            icon: 'success',
            title: 'Analisis Video AI Berhasil Disimpan!',
            text: r.message,
            customClass: { popup: 'swal-custom-popup', confirmButton: 'swal-custom-confirm' }
          });
        } else {
          Swal.fire({ icon: 'error', title: 'Gagal Memproses Video', text: r ? r.message : 'Terjadi kesalahan server.', customClass: { popup: 'swal-custom-popup' } });
        }
      }).withFailureHandler(err => {
        Swal.fire({ icon: 'error', title: 'Error Koneksi', text: err.toString(), customClass: { popup: 'swal-custom-popup' } });
      }).generateAndSaveVideoAnalysisLMSAdmin(res.value);
    }
  });
}

function hapusVideoPembelajaranManual(idModul) {
  Swal.fire({
    title: 'Hapus Video & Tugas Analisis?',
    text: 'Video pembelajaran beserta rangkuman dan tugas analisisnya akan dihapus dari modul ini.',
    icon: 'warning',
    showCancelButton: true,
    confirmButtonColor: '#e11d48',
    confirmButtonText: 'Ya, Hapus Video',
    cancelButtonText: 'Batal',
    customClass: { popup: 'swal-custom-popup', confirmButton: 'swal-custom-confirm' }
  }).then(res => {
    if (res.isConfirmed) {
      Swal.fire({ title: 'Menghapus Video...', didOpen: () => Swal.showLoading(), allowOutsideClick: false, customClass: { popup: 'swal-custom-popup' } });
      google.script.run.withSuccessHandler(r => {
        fetchAdminLMSData();
        Swal.fire({ icon: 'success', title: 'Terhapus', text: r.message, timer: 1500, showConfirmButton: false, customClass: { popup: 'swal-custom-popup' } });
      }).removeVideoAnalysisLMSAdmin(idModul);
    }
  });
}

// Render Hub Analisis Video Interaktif di Ruang Belajar Siswa
function buildStudentVideoAnalysisHubHTML(mod) {
  if (!mod || !mod.konten || !mod.konten.video_interaktif || !mod.konten.video_interaktif.url_asli) {
    return '';
  }
  const vid = mod.konten.video_interaktif;
  const modId = mod.id;
  const curTab = activeVideoSubTab[modId] || 'rangkuman';
  const isianArr = Array.isArray(vid.tugas_isian) ? vid.tugas_isian : [];
  const kuisArr = Array.isArray(vid.kuis_video) ? vid.kuis_video : [];
  const savedIsian = studentVideoIsianAnswers[modId] || {};
  const savedKuis = studentVideoKuisAnswers[modId] || {};
  const evalDone = studentVideoEvalResult[modId] || null;

  let platformBadge = vid.platform === 'YOUTUBE'
    ? `<span style="background:#ffe4e6; color:#e11d48; padding:4px 10px; border-radius:99px; font-size:11px; font-weight:900;"><i class="fa-brands fa-youtube"></i> YOUTUBE INTERAKTIF</span>`
    : (vid.platform === 'GDRIVE'
      ? `<span style="background:#dbeafe; color:#1d4ed8; padding:4px 10px; border-radius:99px; font-size:11px; font-weight:900;"><i class="fa-brands fa-google-drive"></i> GOOGLE DRIVE VIDEO</span>`
      : `<span style="background:#d1fae5; color:#047857; padding:4px 10px; border-radius:99px; font-size:11px; font-weight:900;"><i class="fa-solid fa-video"></i> VIDEO MATERI</span>`);

  // Konten Sub-Tab 1: Rangkuman Eksekutif & 3 Pilar Analisis Mendalam Video AI Groq
  let tabRangkumanHtml = '';
  if (curTab === 'rangkuman') {
    let aspekHtml = (Array.isArray(vid.poin_analisis_mendalam) ? vid.poin_analisis_mendalam : []).map(p => `
      <div class="video-analysis-aspect-card">
        <div style="font-size:14.5px; font-weight:800; color:#047857; margin-bottom:6px;">
          <i class="fa-solid fa-magnifying-glass-chart" style="color:#10b981; margin-right:6px;"></i> ${escapeHtml(p.aspek || 'Aspek Analisis')}
        </div>
        <div style="font-size:14px; color:var(--text-main); line-height:1.7;">${formatSoalText(p.uraian || '')}</div>
      </div>`).join('');

    let kesimpulanLi = (Array.isArray(vid.kesimpulan_kunci) ? vid.kesimpulan_kunci : []).map(kItem =>
      `<li style="margin-bottom:6px;">${escapeHtml(kItem)}</li>`
    ).join('');

    tabRangkumanHtml = `
      <div class="fluid-stage-animate">
        <div style="background:#ecfdf5; border:1.5px solid #6ee7b7; border-radius:18px; padding:18px 20px; margin-bottom:16px;">
          <div style="font-size:12px; font-weight:900; color:#047857; text-transform:uppercase; margin-bottom:6px;">
            <i class="fa-solid fa-robot"></i> Rangkuman Eksekutif Video (AI Groq Analyzer)
          </div>
          <p style="font-size:14.5px; color:#064e3b; line-height:1.75; font-weight:600;">${formatSoalText(vid.rangkuman_eksekutif || '')}</p>
        </div>

        <h5 style="font-size:15px; font-weight:800; color:var(--text-main); margin-bottom:10px;">
          <i class="fa-solid fa-layer-group" style="color:#059669;"></i> Bedah & Analisis Mendalam Isi Video:
        </h5>
        ${aspekHtml}

        ${kesimpulanLi ? `
          <div style="background:#fffbeb; border:1.5px dashed #10b981; border-radius:16px; padding:16px 20px; margin-top:14px;">
            <div style="font-size:13.5px; font-weight:800; color:#065f46; margin-bottom:8px;"><i class="fa-solid fa-key"></i> Poin Kesimpulan Kunci Video:</div>
            <ul style="padding-left:20px; font-size:13.5px; color:#064e3b; line-height:1.6; font-weight:600;">${kesimpulanLi}</ul>
          </div>` : ''}

        <div style="display:flex; justify-content:flex-end; margin-top:16px;">
          <button type="button" onclick="switchStudentVideoSubTab('${modId}', 'isian')" style="background:linear-gradient(135deg, #10b981, #059669); color:white; border:none; padding:12px 20px; border-radius:12px; font-weight:800; font-size:13px; cursor:pointer; display:inline-flex; align-items:center; gap:8px; box-shadow:0 6px 16px rgba(5, 150, 105,0.25);">
            Lanjut Kerjakan Tugas Isian Video (${isianArr.length} Soal) <i class="fa-solid fa-arrow-right"></i>
          </button>
        </div>
      </div>`;
  }

  // Konten Sub-Tab 2: Penugasan Pertanyaan Isian Analisis Video
  let tabIsianHtml = '';
  if (curTab === 'isian') {
    let isianCardsHtml = isianArr.map((item, idx) => {
      let ansVal = savedIsian[idx] || '';
      let perNoEval = (evalDone && evalDone.data && Array.isArray(evalDone.data.evaluasi_per_nomor))
        ? evalDone.data.evaluasi_per_nomor.find(e => Number(e.no) === (idx + 1)) || evalDone.data.evaluasi_per_nomor[idx]
        : null;

      return `
        <div class="video-isian-card">
          <div style="display:flex; justify-content:space-between; align-items:center; gap:8px; flex-wrap:wrap; margin-bottom:8px;">
            <span style="background:#d1fae5; color:#065f46; padding:3px 10px; border-radius:99px; font-size:11px; font-weight:900;">TUGAS ISIAN ANALISIS VIDEO #${idx + 1}</span>
            ${perNoEval ? `<span style="background:#10b981; color:white; padding:3px 10px; border-radius:99px; font-size:11px; font-weight:900;">Skor AI: ${perNoEval.skor}/100</span>` : ''}
          </div>
          <div style="font-size:15px; font-weight:800; color:var(--text-main); line-height:1.6; margin-bottom:8px;">${formatSoalText(item.pertanyaan || '')}</div>
          ${item.petunjuk_jawab ? `<div style="font-size:12px; color:#047857; background:#ecfdf5; padding:8px 12px; border-radius:10px; margin-bottom:10px; font-weight:600;"><i class="fa-solid fa-lightbulb" style="color:#10b981;"></i> <b>Petunjuk Amatan Video:</b> ${escapeHtml(item.petunjuk_jawab)}</div>` : ''}
          <textarea rows="3" placeholder="Tuliskan hasil pengamatan dan analisismu berdasarkan video di atas..." oninput="simpanJawabanIsianVideoSiswa('${modId}', ${idx}, this.value)" style="width:100%; padding:14px; border-radius:12px; border:2px solid #a7f3d0; font-size:13.5px; font-weight:600; outline:none; background:#f8fafc;">${escapeHtml(ansVal)}</textarea>
          ${perNoEval ? `<div style="margin-top:10px; background:#ecfdf5; border-left:4px solid #10b981; padding:10px 14px; border-radius:10px; font-size:12.5px; color:#064e3b;"><b><i class="fa-solid fa-robot"></i> Evaluasi AI Groq:</b> ${escapeHtml(perNoEval.umpan_balik || '')}</div>` : ''}
        </div>`;
    }).join('');

    tabIsianHtml = `
      <div class="fluid-stage-animate">
        <div style="margin-bottom:14px; font-size:13.5px; color:var(--text-muted); font-weight:600;">
          Jawablah ${isianArr.length} pertanyaan isian di bawah ini berdasarkan hasil pengamatanmu terhadap video pembelajaran, lalu lanjutkan ke tab <b>Kuis Analisis Video</b>!
        </div>
        ${isianCardsHtml}
        <div style="display:flex; justify-content:space-between; gap:10px; flex-wrap:wrap; margin-top:14px;">
          <button type="button" onclick="switchStudentVideoSubTab('${modId}', 'rangkuman')" style="background:white; border:1.5px solid #cbd5e1; color:#475569; padding:11px 18px; border-radius:12px; font-weight:800; font-size:12.5px; cursor:pointer;">
            <i class="fa-solid fa-arrow-left"></i> Lihat Rangkuman Video
          </button>
          <button type="button" onclick="switchStudentVideoSubTab('${modId}', 'kuis')" style="background:linear-gradient(135deg, #10b981, #059669); color:white; border:none; padding:12px 20px; border-radius:12px; font-weight:800; font-size:13px; cursor:pointer; display:inline-flex; align-items:center; gap:8px; box-shadow:0 6px 16px rgba(5, 150, 105,0.25);">
            Lanjut Kuis Analisis Video (${kuisArr.length} Soal) & Evaluasi AI <i class="fa-solid fa-arrow-right"></i>
          </button>
        </div>
      </div>`;
  }

  // Konten Sub-Tab 3: Kuis Pilihan Ganda Analisis Video + Tombol Evaluasi Komprehensif AI Groq
  let tabKuisHtml = '';
  if (curTab === 'kuis') {
    let kuisCardsHtml = kuisArr.map((q, qIdx) => {
      let chosen = savedKuis[qIdx] || '';
      let kunci = (q.kunci || 'A').toString().trim().toUpperCase();
      let optsHtml = ['a', 'b', 'c', 'd'].map(letter => {
        let up = letter.toUpperCase();
        let textOpt = q[letter] || q[up] || '';
        if (!textOpt) return '';
        let isSel = (chosen === up);
        return `
          <div onclick="pilihJawabanKuisVideoSiswa('${modId}', ${qIdx}, '${up}')" style="padding:12px 16px; border-radius:12px; border:2px solid ${isSel ? '#059669' : '#e2e8f0'}; background:${isSel ? '#ecfdf5' : '#f8fafc'}; color:${isSel ? '#065f46' : '#334155'}; font-weight:700; font-size:13.5px; cursor:pointer; margin-bottom:8px; display:flex; align-items:center; gap:10px;">
            <span style="width:26px; height:26px; border-radius:50%; background:${isSel ? '#059669' : 'white'}; color:${isSel ? 'white' : '#64748b'}; border:2px solid ${isSel ? '#059669' : '#cbd5e1'}; display:inline-flex; align-items:center; justify-content:center; font-weight:800; font-size:11.5px; flex-shrink:0;">${up}</span>
            <span>${escapeHtml(textOpt)}</span>
          </div>`;
      }).join('');

      let feedbackHtml = '';
      if (evalDone) {
        let isCorrect = (chosen === kunci);
        feedbackHtml = `
          <div style="margin-top:10px; padding:12px 15px; border-radius:12px; background:${isCorrect ? '#ecfdf5' : '#fff1f2'}; border:1.5px solid ${isCorrect ? '#6ee7b7' : '#fecdd3'}; color:${isCorrect ? '#065f46' : '#9f1239'}; font-size:13px;">
            <div style="font-weight:800; margin-bottom:3px;">
              <i class="fa-solid ${isCorrect ? 'fa-circle-check' : 'fa-circle-xmark'}"></i>
              ${isCorrect ? 'Jawaban Tepat!' : `Kurang Tepat (Jawaban Benar: ${kunci})`}
            </div>
            <div><b>Pembahasan Video:</b> ${escapeHtml(q.pembahasan || '')}</div>
          </div>`;
      }

      return `
        <div class="video-isian-card">
          <div style="font-size:11px; font-weight:900; color:#047857; margin-bottom:6px;">KUIS ANALISIS VIDEO #${qIdx + 1}</div>
          <div style="font-size:15px; font-weight:800; color:var(--text-main); line-height:1.65; margin-bottom:12px;">${formatSoalText(q.soal || '')}</div>
          <div>${optsHtml}</div>
          ${feedbackHtml}
        </div>`;
    }).join('');

    let summaryEvalBanner = '';
    if (evalDone) {
      summaryEvalBanner = `
        <div style="background:linear-gradient(135deg, #ecfdf5 0%, #d1fae5 100%); border:2px solid #10b981; border-radius:18px; padding:18px 20px; margin-bottom:16px;">
          <div style="display:flex; justify-content:space-between; align-items:center; flex-wrap:wrap; gap:10px; margin-bottom:8px;">
            <div style="font-size:15px; font-weight:900; color:#064e3b;">
              <i class="fa-solid fa-award" style="color:#059669;"></i> Hasil Evaluasi Komprehensif Analisis Video AI Groq
            </div>
            <div style="display:flex; gap:8px; flex-wrap:wrap;">
              <span style="background:white; color:#047857; border:1px solid #6ee7b7; padding:4px 10px; border-radius:99px; font-size:11.5px; font-weight:800;">Skor Isian: ${evalDone.skorIsian}/100</span>
              <span style="background:white; color:#047857; border:1px solid #6ee7b7; padding:4px 10px; border-radius:99px; font-size:11.5px; font-weight:800;">Skor Kuis PG: ${evalDone.skorKuisPG}/100</span>
              <span style="background:#059669; color:white; padding:4px 12px; border-radius:99px; font-size:12px; font-weight:900;">Nilai Akhir Video: ${evalDone.skorAkhirVideo}/100 (+60 XP)</span>
            </div>
          </div>
          <div style="font-size:13.5px; color:#065f46; line-height:1.65;">
            <b>Umpan Balik AI Groq:</b> ${escapeHtml((evalDone.data && evalDone.data.ringkasan_umpan_balik) || 'Kerja bagus! Kamu telah menyelesaikan analisis video secara komprehensif.')}
          </div>
        </div>`;
    }

    tabKuisHtml = `
      <div class="fluid-stage-animate">
        ${summaryEvalBanner}
        ${kuisCardsHtml}
        <button type="button" id="btn-submit-video-analysis-${modId}" onclick="kumpulkanTugasDanKuisVideoAI('${modId}')" style="width:100%; padding:16px; background:linear-gradient(135deg, #10b981 0%, #059669 100%); color:white; border:none; border-radius:16px; font-weight:800; font-size:15px; cursor:pointer; box-shadow:0 10px 24px rgba(5, 150, 105,0.28); display:flex; align-items:center; justify-content:center; gap:10px;">
          <i class="fa-solid fa-wand-magic-sparkles"></i> ${evalDone ? 'Evaluasi Ulang Tugas Isian & Kuis Video bersama AI Groq' : 'Periksa Penugasan Isian & Kuis Analisis Video (Klaim +60 XP)'}
        </button>
      </div>`;
  }

  return `
    <div class="student-video-analysis-hub" id="student-video-hub-${modId}">
      <div style="display:flex; justify-content:space-between; align-items:flex-start; flex-wrap:wrap; gap:12px; margin-bottom:14px;">
        <div>
          <div style="display:flex; align-items:center; gap:8px; flex-wrap:wrap; margin-bottom:4px;">
            ${platformBadge}
            <span style="background:#d1fae5; color:#065f46; padding:4px 10px; border-radius:99px; font-size:11px; font-weight:800;">
              <i class="fa-solid fa-bolt"></i> Dilengkapi Rangkuman AI, ${isianArr.length} Tugas Isian & ${kuisArr.length} Kuis
            </span>
          </div>
          <h4 style="font-size:18px; font-weight:800; color:var(--text-main); line-height:1.35;">
            <i class="fa-solid fa-clapperboard" style="color:#059669; margin-right:6px;"></i> ${escapeHtml(vid.judul_video || 'Video Pembelajaran Interaktif')}
          </h4>
        </div>
        <a href="${escapeHtml(vid.url_asli)}" target="_blank" rel="noopener noreferrer" style="background:#ecfdf5; color:#047857; border:1.5px solid #6ee7b7; padding:7px 13px; border-radius:10px; font-size:12px; font-weight:800; text-decoration:none; display:inline-flex; align-items:center; gap:6px;">
          <i class="fa-solid fa-up-right-from-square"></i> Buka Tautan Asli
        </a>
      </div>

      <!-- Pemutar Video Responsif (YouTube / Google Drive Preview) -->
      <div class="video-responsive-frame-wrap">
        <iframe src="${escapeHtml(vid.embed_url)}" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; fullscreen" allowfullscreen loading="lazy"></iframe>
      </div>

      <!-- Navigasi 3 Sub-Fitur Analisis Video AI -->
      <div class="video-ai-tabs-bar">
        <button type="button" class="video-ai-tab-btn ${curTab === 'rangkuman' ? 'active' : ''}" onclick="switchStudentVideoSubTab('${modId}', 'rangkuman')">
          <i class="fa-solid fa-file-waveform"></i> <span>1. Rangkuman & Analisis AI</span>
        </button>
        <button type="button" class="video-ai-tab-btn ${curTab === 'isian' ? 'active' : ''}" onclick="switchStudentVideoSubTab('${modId}', 'isian')">
          <i class="fa-solid fa-pen-to-square"></i> <span>2. Tugas Isian Video (${isianArr.length})</span>
        </button>
        <button type="button" class="video-ai-tab-btn ${curTab === 'kuis' ? 'active' : ''}" onclick="switchStudentVideoSubTab('${modId}', 'kuis')">
          <i class="fa-solid fa-list-check"></i> <span>3. Kuis Analisis Video (${kuisArr.length})</span>
        </button>
      </div>

      <!-- Konten Sub-Tab Aktif -->
      <div id="student-video-subtab-body-${modId}">
        ${tabRangkumanHtml}${tabIsianHtml}${tabKuisHtml}
      </div>
    </div>`;
}

function switchStudentVideoSubTab(modId, tabName) {
  playStudentSFX('click');
  activeVideoSubTab[modId] = tabName;
  renderConstructiveWorkspace();
  const hub = document.getElementById('student-video-hub-' + modId);
  if (hub) hub.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
}

function simpanJawabanIsianVideoSiswa(modId, idx, val) {
  if (!studentVideoIsianAnswers[modId]) studentVideoIsianAnswers[modId] = {};
  studentVideoIsianAnswers[modId][idx] = val;
}

function pilihJawabanKuisVideoSiswa(modId, qIdx, optLetter) {
  playStudentSFX('click');
  if (!studentVideoKuisAnswers[modId]) studentVideoKuisAnswers[modId] = {};
  studentVideoKuisAnswers[modId][qIdx] = optLetter;
  renderConstructiveWorkspace();
}

function kumpulkanTugasDanKuisVideoAI(modId) {
  if (!activeLMSModule || activeLMSModule.id !== modId) return;
  const vid = (activeLMSModule.konten && activeLMSModule.konten.video_interaktif) ? activeLMSModule.konten.video_interaktif : null;
  if (!vid) return;

  const isianArr = Array.isArray(vid.tugas_isian) ? vid.tugas_isian : [];
  const kuisArr = Array.isArray(vid.kuis_video) ? vid.kuis_video : [];
  const ansIsian = studentVideoIsianAnswers[modId] || {};
  const ansKuis = studentVideoKuisAnswers[modId] || {};

  // Validasi semua pertanyaan isian sudah diisi
  for (let i = 0; i < isianArr.length; i++) {
    if (!ansIsian[i] || ansIsian[i].trim().length < 5) {
      Swal.fire({
        icon: 'warning',
        title: `Tugas Isian #${i + 1} Belum Lengkap`,
        text: 'Silakan lengkapi seluruh jawaban pada tab "2. Tugas Isian Video" terlebih dahulu sebelum mengevaluasi bersama AI!',
        customClass: { popup: 'swal-custom-popup', confirmButton: 'swal-custom-confirm' }
      }).then(() => switchStudentVideoSubTab(modId, 'isian'));
      return;
    }
  }

  // Validasi semua soal kuis PG video sudah dipilih
  if (Object.keys(ansKuis).length < kuisArr.length) {
    Swal.fire({
      icon: 'warning',
      title: 'Kuis Analisis Video Belum Lengkap',
      text: 'Pilih jawaban untuk seluruh soal kuis analisis video terlebih dahulu!',
      customClass: { popup: 'swal-custom-popup', confirmButton: 'swal-custom-confirm' }
    });
    return;
  }

  // Hitung skor Kuis PG Video
  let benarPG = 0;
  kuisArr.forEach((q, idx) => {
    let kunci = (q.kunci || 'A').toString().trim().toUpperCase();
    let jwb = (ansKuis[idx] || '').toString().trim().toUpperCase();
    if (jwb === kunci) benarPG++;
  });
  let skorKuisPG = kuisArr.length > 0 ? Math.round((benarPG / kuisArr.length) * 100) : 100;

  let payloadIsian = isianArr.map((item, idx) => ({
    no: idx + 1,
    pertanyaan: item.pertanyaan || '',
    kunci_konsep: item.kunci_konsep || '',
    jawaban_siswa: (ansIsian[idx] || '').trim()
  }));

  const btn = document.getElementById('btn-submit-video-analysis-' + modId);
  if (btn) {
    btn.innerHTML = '<i class="fa-solid fa-spinner fa-spin"></i> AI Groq Sedang Mengevaluasi Tugas Isian & Kuis Video...';
    btn.disabled = true;
  }

  google.script.run.withSuccessHandler(res => {
    if (btn) btn.disabled = false;
    if (res && res.success) {
      studentVideoEvalResult[modId] = res;
      playStudentSFX('success');
      if (res.skorAkhirVideo >= 75) launchConfettiCelebration();

      // Berikan bonus XP +60 atas ketuntasan analisis video
      const tr = getStudentVerifiedTracker();
      if (!tr.videoAnalyzed) tr.videoAnalyzed = {};
      if (!tr.videoAnalyzed[modId]) {
        tr.videoAnalyzed[modId] = res.skorAkhirVideo;
        globalLMSDashboard.totalXP = (globalLMSDashboard.totalXP || 0) + 60;
        saveStudentVerifiedTracker(tr);
        updateStudentHeroLevelBannerV15();
      }

      renderConstructiveWorkspace();
      Swal.fire({
        icon: 'success',
        title: `Analisis Video Tuntas! Skor: ${res.skorAkhirVideo}/100`,
        html: `
          <div style="text-align:left; font-size:13.5px; line-height:1.6;">
            <div style="background:#ecfdf5; border:1.5px solid #6ee7b7; border-radius:12px; padding:12px; margin-bottom:10px;">
              <div>• Skor Tugas Isian (AI Groq): <b>${res.skorIsian}/100</b></div>
              <div>• Skor Kuis Pilihan Ganda Video: <b>${res.skorKuisPG}/100</b> (${benarPG}/${kuisArr.length} Benar)</div>
              <div style="margin-top:4px; font-weight:900; color:#047857;">• Bonus Ketuntasan Analisis Video: <b>+60 XP</b></div>
            </div>
            <div><b>Evaluasi AI Groq:</b> ${escapeHtml((res.data && res.data.ringkasan_umpan_balik) || 'Analisis video yang sangat baik!')}</div>
          </div>`,
        confirmButtonText: 'Lihat Detail Pembahasan',
        customClass: { popup: 'swal-custom-popup', confirmButton: 'swal-custom-confirm' }
      });
    } else {
      studentVideoEvalResult[modId] = {
        skorIsian: 85,
        skorKuisPG: skorKuisPG,
        skorAkhirVideo: Math.round((85 + skorKuisPG) / 2),
        data: { ringkasan_umpan_balik: 'Tugas analisis video telah tercatat.' }
      };
      renderConstructiveWorkspace();
    }
  }).withFailureHandler(() => {
    if (btn) btn.disabled = false;
  }).evaluateStudentVideoAssignmentGroq({
    mapel: activeLMSSubject,
    judulModul: activeLMSModule.judul,
    judulVideo: vid.judul_video || activeLMSModule.judul,
    rangkumanVideo: vid.rangkuman_eksekutif || '',
    jawabanIsian: payloadIsian,
    skorKuisPG: skorKuisPG
  });
}


// =========================================================================
// 23. EDUVANCE UI/UX CONTROLLER (INTEGRASI GAMBAR 1 & GAMBAR 2 - V22)
// =========================================================================
let eduvanceAssignPage = 1;
const eduvanceAssignPageSize = 5;
let eduvanceActiveNav = 'dashboard';

function getStudentAttendanceState() {
  const key = `eduvance_att_${studentData.email || 'guest'}`;
  const todayStr = new Date().toISOString().slice(0, 10);
  let saved = {};
  try { saved = JSON.parse(localStorage.getItem(key) || '{}'); } catch (e) { saved = {}; }
  if (!Array.isArray(saved.days)) saved.days = [];
  const isCheckedToday = saved.days.includes(todayStr);
  return { key, todayStr, days: saved.days, isCheckedToday };
}

function markStudentDailyAttendance() {
  playStudentSFX('success');
  const st = getStudentAttendanceState();
  if (!st.isCheckedToday) {
    st.days.push(st.todayStr);
    localStorage.setItem(st.key, JSON.stringify({ days: st.days }));
    globalLMSDashboard.totalXP = (globalLMSDashboard.totalXP || 0) + 15;
    if (typeof showStudentToast === 'function') {
      showStudentToast('Presensi belajar hari ini tercatat! Kamu mendapat +15 XP & Streak bertambah!', 'success');
    }
    if (typeof launchConfettiCelebration === 'function') launchConfettiCelebration();
  } else {
    if (typeof showStudentToast === 'function') {
      showStudentToast('Kamu sudah melakukan presensi kehadiran belajar hari ini. Tetap semangat!', 'info');
    }
  }
  renderEduvanceDashboardAll();
}

function openEduvanceMobileSidebar() {
  playStudentSFX('click');
  document.getElementById('eduvance-sidebar')?.classList.add('open');
  document.getElementById('eduvance-sidebar-backdrop')?.classList.add('open');
}

function closeEduvanceMobileSidebar() {
  document.getElementById('eduvance-sidebar')?.classList.remove('open');
  document.getElementById('eduvance-sidebar-backdrop')?.classList.remove('open');
}

function toggleStudentQuickToolsPopover() {
  playStudentSFX('click');
  const pop = document.getElementById('eduvance-comfort-popover');
  if (pop) pop.classList.toggle('hidden');
}

function openEduvanceAIChatQuick() {
  playStudentSFX('click');
  if (!activeLMSModule) {
    const firstSub = (globalLMSDashboard.subjects || [])[0];
    if (firstSub) {
      activeLMSSubject = firstSub.name;
      activeLMSModule = (firstSub.modules && firstSub.modules[0]) ? firstSub.modules[0] : getDefaultConstructiveModule(firstSub.name);
    }
  }
  toggleAITutorDrawer();
}

function triggerStartStudyingQuick() {
  playStudentSFX('click');
  const saved = (studentData && studentData.email)
    ? JSON.parse(localStorage.getItem(`lms_last_${studentData.email}`) || 'null')
    : null;
  if (saved && saved.mapel) {
    resumeLastLMSModule(saved.mapel, saved.modIdx || 0, saved.step || 1);
    return;
  }
  const firstSub = (globalLMSDashboard.subjects || [])[0];
  if (firstSub) openStudentLMS(firstSub.name);
}

function scrollToEduvanceSection(secId) {
  playStudentSFX('click');
  closeEduvanceMobileSidebar();
  const lmsSec = document.getElementById('lms-learning-section');
  if (lmsSec && !lmsSec.classList.contains('hidden')) {
    kembaliKeDashboardSiswa();
  }
  setTimeout(() => {
    const el = document.getElementById(secId);
    if (el) el.scrollIntoView({ behavior: 'smooth', block: 'start' });
  }, 80);
}

function switchEduvanceNav(navKey) {
  playStudentSFX('click');
  closeEduvanceMobileSidebar();

  if (navKey === 'notes') {
    navKey = 'dashboard';
  }

  eduvanceActiveNav = navKey;

  // Jika siswa sedang berada di dalam Ruang Belajar modul, kembalikan ke kontainer Dashboard utama
  const lmsSec = document.getElementById('lms-learning-section');
  const dashSec = document.getElementById('dashboard-section');
  if (lmsSec && !lmsSec.classList.contains('hidden')) {
    document.body.classList.remove('lms-zen-mode', 'lms-native-android-mode');
    if ('speechSynthesis' in window) window.speechSynthesis.cancel();
    lmsSec.classList.add('hidden');
    if (dashSec) dashSec.classList.remove('hidden');
  }

  // Aktifkan tombol menu di Sidebar Kiri & Mobile Bottom Nav
  ['dashboard', 'courses', 'assignments', 'grades'].forEach(k => {
    document.getElementById('edunav-' + k)?.classList.toggle('active', k === navKey);
    document.getElementById('edumob-' + k)?.classList.toggle('active', k === navKey);
  });

  // Tampilkan HANYA view pane yang dipilih agar halaman tidak ramai
  const viewKeys = ['dashboard', 'courses', 'assignments', 'grades'];
  viewKeys.forEach(vKey => {
    const pane = document.getElementById('eduview-' + vKey);
    if (pane) {
      if (vKey === navKey) {
        pane.classList.remove('hidden');
        pane.classList.add('active');
      } else {
        pane.classList.add('hidden');
        pane.classList.remove('active');
      }
    }
  });

  // Perbarui judul Topbar sesuai menu yang sedang dibuka
  const titleMap = {
    dashboard: 'Beranda Saya',
    courses: 'Ruang Belajar Konstruktif (LMS)',
    assignments: 'Portal Ujian Akhir (CBT)',
    schedule: 'Jadwal & Statistik Keaktifan',
    grades: 'Prestasi, Lencana & Peringkat'
  };
  const topTitleEl = document.getElementById('eduvance-topbar-title');
  if (topTitleEl && titleMap[navKey]) {
    topTitleEl.innerText = titleMap[navKey];
  }

  window.scrollTo({ top: 0, behavior: 'smooth' });
}

function handleEduvanceGlobalSearch(val) {
  const clearBtn = document.getElementById('eduvance-search-clear');
  if (clearBtn) clearBtn.classList.toggle('hidden', !val || !val.trim());
  renderStudentSubjectCards();
  renderEduvanceCourseDonuts();
  renderEduvanceAssignmentsTable(1);
}

function clearEduvanceGlobalSearch() {
  const inp = document.getElementById('studentSearchMapel');
  if (inp) inp.value = '';
  handleEduvanceGlobalSearch('');
}

function renderEduvanceSidebarAndHeader() {
  const name = (studentData && studentData.name) ? studentData.name : 'Siswa Kelas 7';
  const kelas = (studentData && studentData.kelas) ? studentData.kelas : '7A';
  const initial = name.trim().charAt(0).toUpperCase() || 'S';

  ['eduvance-sidebar-avatar', 'eduvance-footer-avatar', 'eduvance-topbar-avatar'].forEach(id => {
    const el = document.getElementById(id);
    if (el) el.innerText = initial;
  });
  if (document.getElementById('eduvance-sidebar-name')) document.getElementById('eduvance-sidebar-name').innerText = name;
  if (document.getElementById('eduvance-footer-name')) document.getElementById('eduvance-footer-name').innerText = name;
  if (document.getElementById('eduvance-sidebar-kelas')) {
    document.getElementById('eduvance-sidebar-kelas').innerText = `Kelas ${kelas} • Semester Aktif`;
  }

  const now = new Date();
  const hr = now.getHours();
  const greetWord = hr < 11 ? 'Good morning' : (hr < 15 ? 'Good afternoon' : (hr < 19 ? 'Good evening' : 'Good night'));
  const firstName = name.split(' ')[0];
  const dateFormatted = now.toLocaleDateString('id-ID', { weekday: 'long', day: 'numeric', month: 'short', year: 'numeric' });

  if (document.getElementById('eduvance-topbar-subtitle')) {
    document.getElementById('eduvance-topbar-subtitle').innerText = `SICIBINAGA • Kelas ${kelas} • ${dateFormatted}`;
  }
  if (document.getElementById('eduvance-greeting-title')) {
    document.getElementById('eduvance-greeting-title').innerText = `${greetWord}, ${firstName} ✨`;
  }

  const att = getStudentAttendanceState();
  const completedCount = Object.keys(globalLMSDashboard.completedMap || {}).length;
  const streakDays = Math.max(1, att.days.length + completedCount);
  const xp = (globalLMSDashboard.totalXP || 0) + (typeof getStudentBonusActivityXP === 'function' ? getStudentBonusActivityXP() : 0);
  const rankInfo = typeof getStudentRankInfoV15 === 'function' ? getStudentRankInfoV15(xp) : { current: { level: 1 }, next: { minXP: 200 }, pctToNext: 15 };

  if (document.getElementById('eduvance-sidebar-streak-num')) document.getElementById('eduvance-sidebar-streak-num').innerText = streakDays;
  if (document.getElementById('eduvance-sidebar-level-num')) document.getElementById('eduvance-sidebar-level-num').innerText = rankInfo.current.level;
  if (document.getElementById('eduvance-greeting-streak-pill')) {
    document.getElementById('eduvance-greeting-streak-pill').innerText = `🔥 DAY ${streakDays} STUDY STREAK!`;
  }

  const attBtn = document.getElementById('btn-eduvance-attendance');
  const attLbl = document.getElementById('lbl-eduvance-attendance');
  if (attBtn && attLbl) {
    attBtn.classList.toggle('checked-in', att.isCheckedToday);
    attLbl.innerText = att.isCheckedToday ? 'Attendance Checked ✓' : 'Mark Attendance';
  }

  const subjs = globalLMSDashboard.subjects || [];
  if (document.getElementById('edunav-badge-courses')) {
    document.getElementById('edunav-badge-courses').innerText = subjs.length;
  }

  const enrolledBox = document.getElementById('eduvance-sidebar-enrolled');
  if (enrolledBox) {
    const barColors = ['#fbbf24', '#38bdf8', '#f472b6', '#fbbf24', '#a78bfa', '#fb923c'];
    const icons = ['fa-laptop-code', 'fa-calculator', 'fa-flask', 'fa-book-open', 'fa-earth-asia', 'fa-language'];
    enrolledBox.innerHTML = subjs.map((s, idx) => {
      const tot = Math.max(1, s.totalModules || 1);
      const done = s.completedModules || 0;
      const pct = s.totalModules > 0 ? Math.round((done / tot) * 100) : (globalLMSDashboard.examHistoryMap && globalLMSDashboard.examHistoryMap[s.name] ? 100 : 15);
      const col = barColors[idx % barColors.length];
      const ic = icons[idx % icons.length];
      const safeName = s.name.replace(/'/g, "\\'");
      return `
        <div class="eduvance-enrolled-item" onclick="openStudentLMS('${safeName}')">
          <div class="eduvance-enrolled-left">
            <div class="eduvance-enrolled-icon" style="color:${col};"><i class="fa-solid ${ic}"></i></div>
            <div style="min-width:0; flex:1;">
              <div class="eduvance-enrolled-name">${escapeHtml(s.name)}</div>
              <div class="eduvance-enrolled-pct">${pct}% complete</div>
            </div>
          </div>
          <div class="eduvance-enrolled-mini-bar">
            <div class="eduvance-enrolled-mini-fill" style="width:${pct}%; background:${col};"></div>
          </div>
        </div>`;
    }).join('');
  }
}

function renderEduvanceKPICards() {
  const subjs = globalLMSDashboard.subjects || [];
  const completedMap = globalLMSDashboard.completedMap || {};
  const completedList = Object.values(completedMap);
  const examHistory = globalLMSDashboard.examHistoryMap || {};
  const tr = typeof getStudentVerifiedTracker === 'function' ? getStudentVerifiedTracker() : { readTimers: {} };

  const avg100 = completedList.length > 0
    ? (completedList.reduce((a, c) => a + (Number(c.skor) || 0), 0) / completedList.length)
    : 88.5;
  const gpa4 = Math.min(4.0, Math.max(2.5, (avg100 / 25))).toFixed(2);
  if (document.getElementById('edukpi-gpa-val')) document.getElementById('edukpi-gpa-val').innerText = gpa4;
  if (document.getElementById('edukpi-gpa-sub')) {
    document.getElementById('edukpi-gpa-sub').innerText = `▲ Rata-rata Kuis: ${Math.round(avg100)}/100`;
  }

  const att = getStudentAttendanceState();
  const streakDays = Math.max(1, att.days.length + completedList.length);
  if (document.getElementById('edukpi-streak-val')) document.getElementById('edukpi-streak-val').innerText = streakDays;

  const totalSec = Object.values(tr.readTimers || {}).reduce((a, b) => a + b, 0);
  const studyHours = Math.max(0.5, ((totalSec / 3600) + (completedList.length * 1.2))).toFixed(1);
  const xp = (globalLMSDashboard.totalXP || 0) + (typeof getStudentBonusActivityXP === 'function' ? getStudentBonusActivityXP() : 0);
  if (document.getElementById('edukpi-hours-val')) document.getElementById('edukpi-hours-val').innerText = studyHours;
  if (document.getElementById('edukpi-hours-sub')) document.getElementById('edukpi-hours-sub').innerText = `${xp.toLocaleString('id-ID')} XP Terverifikasi`;

  const totalDoneTasks = completedList.length + Object.keys(examHistory).length;
  const totalAvailableTasks = subjs.reduce((a, s) => a + Math.max(1, s.totalModules || 1), 0) + subjs.length;
  const pctDone = totalAvailableTasks > 0 ? Math.round((totalDoneTasks / totalAvailableTasks) * 100) : 100;
  if (document.getElementById('edukpi-completed-val')) document.getElementById('edukpi-completed-val').innerText = totalDoneTasks;
  if (document.getElementById('edukpi-completed-sub')) document.getElementById('edukpi-completed-sub').innerText = `${pctDone}% on-time completion`;

  const attPct = att.isCheckedToday ? 100 : 94;
  if (document.getElementById('edukpi-attendance-val')) document.getElementById('edukpi-attendance-val').innerText = attPct;
  if (document.getElementById('edukpi-attendance-sub')) {
    document.getElementById('edukpi-attendance-sub').innerText = att.isCheckedToday
      ? `✓ Hadir hari ini • ${subjs.length} kelas aktif`
      : `↑ Klik untuk klaim kehadiran (+15 XP)`;
  }

  const activeExamsCount = subjs.filter(s => s.examStatus === 'AKTIF' && !examHistory[s.name]).length;
  const pendingModsCount = Math.max(0, subjs.reduce((a, s) => a + Math.max(0, (s.totalModules || 1) - (s.completedModules || 0)), 0));
  if (document.getElementById('eduvance-greeting-sub')) {
    document.getElementById('eduvance-greeting-sub').innerText =
      `Kamu memiliki ${subjs.length} mata pelajaran, ${pendingModsCount} modul eksplorasi, dan ${activeExamsCount} ujian aktif — Keep the streak going!`;
  }
  if (document.getElementById('edunav-badge-due')) {
    document.getElementById('edunav-badge-due').innerText = `${pendingModsCount + activeExamsCount} due`;
  }
}

function renderEduvanceCourseDonuts() {
  const grid = document.getElementById('eduvance-course-donut-grid');
  if (!grid) return;
  const kw = (document.getElementById('studentSearchMapel')?.value || '').toLowerCase().trim();
  const subjs = (globalLMSDashboard.subjects || []).filter(s => !kw || s.name.toLowerCase().includes(kw));

  if (document.getElementById('eduvance-course-progress-sub')) {
    document.getElementById('eduvance-course-progress-sub').innerText = `Semester Aktif • ${subjs.length} enrolled courses`;
  }

  if (subjs.length === 0) {
    grid.innerHTML = `<div style="grid-column:1/-1; text-align:center; padding:30px; color:#64748b;">Tidak ada mata pelajaran yang cocok dengan pencarian.</div>`;
    return;
  }

  const ringColors = ['#064e3b', '#0284c7', '#ec4899', '#14b8a6', '#10b981', '#10b981'];
  const icons = ['fa-laptop-code', 'fa-calculator', 'fa-palette', 'fa-flask-vial', 'fa-globe', 'fa-book-open-reader'];
  const radius = 38;
  const circum = 2 * Math.PI * radius;

  grid.innerHTML = subjs.slice(0, 6).map((s, idx) => {
    const tot = Math.max(1, s.totalModules || 1);
    const done = s.completedModules || 0;
    const isExamDone = globalLMSDashboard.examHistoryMap && globalLMSDashboard.examHistoryMap[s.name] !== undefined;
    const pct = s.totalModules > 0 ? Math.round((done / tot) * 100) : (isExamDone ? 100 : 25);
    const offset = circum - (pct / 100) * circum;
    const color = ringColors[idx % ringColors.length];
    const icon = icons[idx % icons.length];
    const lvl = Math.min(5, Math.max(1, Math.ceil((pct + 1) / 20)));
    const safeName = s.name.replace(/'/g, "\\'");

    return `
      <div class="eduvance-donut-item" onclick="openStudentLMS('${safeName}')" title="Klik untuk membuka Ruang Belajar ${escapeHtml(s.name)}">
        <div class="eduvance-donut-svg-wrap">
          <svg viewBox="0 0 96 96">
            <circle cx="48" cy="48" r="${radius}" fill="none" stroke="#fef3c7" stroke-width="10"></circle>
            <circle cx="48" cy="48" r="${radius}" fill="none" stroke="${color}" stroke-width="10"
              stroke-dasharray="${circum.toFixed(1)}" stroke-dashoffset="${offset.toFixed(1)}" stroke-linecap="round"></circle>
          </svg>
          <div class="eduvance-donut-center">
            <i class="fa-solid ${icon}" style="color:${color};"></i>
            <span class="eduvance-donut-pct">${pct}%</span>
          </div>
        </div>
        <div class="eduvance-donut-name">${escapeHtml(s.name)}</div>
        <div class="eduvance-donut-meta">Lv ${lvl} • ${done}/${tot} modules</div>
      </div>`;
  }).join('');
}

function renderEduvanceTodayTimeline() {
  const box = document.getElementById('eduvance-today-timeline');
  if (!box) return;
  const subjs = globalLMSDashboard.subjects || [];
  const completedMap = globalLMSDashboard.completedMap || {};
  const examHistory = globalLMSDashboard.examHistoryMap || {};

  const now = new Date();
  if (document.getElementById('eduvance-today-date-label')) {
    document.getElementById('eduvance-today-date-label').innerText =
      `TODAY • ${now.toLocaleDateString('id-ID', { day: '2-digit', month: 'short' }).toUpperCase()}`;
  }

  let sessions = [];
  const slots = ['07:30', '08:30', '10:00', '13:00', '15:00', '19:00'];
  subjs.forEach((s, idx) => {
    const safeName = s.name.replace(/'/g, "\\'");
    const mods = (s.modules && s.modules.length > 0) ? s.modules : [getDefaultConstructiveModule(s.name)];
    const firstMod = mods[0];
    const isModDone = completedMap[firstMod.id] !== undefined;

    sessions.push({
      time: slots[sessions.length % slots.length],
      title: `Eksplorasi Modul — ${firstMod.judul}`,
      sub: `Self-paced LMS • ${s.name}`,
      status: isModDone ? 'Done' : (idx === 0 ? 'Live!' : 'Soon'),
      pillClass: isModDone ? 'pill-done' : (idx === 0 ? 'pill-live' : 'pill-soon'),
      icon: isModDone ? 'fa-square-check' : (idx === 0 ? 'fa-circle-play' : 'fa-book-open'),
      iconBg: isModDone ? '#d1fae5' : (idx === 0 ? '#ffe4e6' : '#fef3c7'),
      iconColor: isModDone ? '#10b981' : (idx === 0 ? '#e11d48' : '#059669'),
      action: `openStudentLMS('${safeName}')`
    });

    if (s.examStatus === 'AKTIF' || examHistory[s.name]) {
      const exDone = examHistory[s.name] !== undefined;
      sessions.push({
        time: slots[sessions.length % slots.length],
        title: `Asesmen PTS/PAS — ${s.name}`,
        sub: `${s.totalSoalUjian || 25} Butir Soal HOTS • CBT Aman`,
        status: exDone ? 'Done' : 'Live!',
        pillClass: exDone ? 'pill-done' : 'pill-live',
        icon: 'fa-file-signature',
        iconBg: exDone ? '#d1fae5' : '#ffe4e6',
        iconColor: exDone ? '#10b981' : '#e11d48',
        action: `startExam('${safeName}')`
      });
    }
  });

  if (document.getElementById('eduvance-today-count-label')) {
    document.getElementById('eduvance-today-count-label').innerText =
      `${now.toLocaleDateString('id-ID', { weekday: 'long' })} • ${Math.min(6, sessions.length)} sessions`;
  }

  const renderRows = (arr) => arr.map(it => `
    <div class="eduvance-session-row" onclick="${it.action}">
      <div class="eduvance-session-left">
        <span class="eduvance-session-time">${it.time}</span>
        <div class="eduvance-session-icon" style="background:${it.iconBg}; color:${it.iconColor};">
          <i class="fa-solid ${it.icon}"></i>
        </div>
        <div style="min-width:0; flex:1;">
          <div class="eduvance-session-title">${escapeHtml(it.title)}</div>
          <div class="eduvance-session-sub">${escapeHtml(it.sub)}</div>
        </div>
      </div>
      <span class="eduvance-session-pill ${it.pillClass}">${it.status}</span>
    </div>`).join('');

  box.innerHTML = renderRows(sessions.slice(0, 5));
  const fullBox = document.getElementById('eduvance-schedule-full-list');
  if (fullBox) fullBox.innerHTML = renderRows(sessions);
}

function buildEduvanceAssignmentsDataset() {
  const subjs = globalLMSDashboard.subjects || [];
  const completedMap = globalLMSDashboard.completedMap || {};
  const examHistory = globalLMSDashboard.examHistoryMap || {};
  const kw = (document.getElementById('studentSearchMapel')?.value || '').toLowerCase().trim();
  const modeFilter = document.getElementById('eduvance-assign-filter')?.value || 'ALL';

  let items = [];
  subjs.forEach(s => {
    const safeName = s.name.replace(/'/g, "\\'");
    const mods = (s.modules && s.modules.length > 0) ? s.modules : [getDefaultConstructiveModule(s.name)];

    mods.forEach((m, mIdx) => {
      const rec = completedMap[m.id];
      const isDone = rec !== undefined;
      const kuisCount = Array.isArray(m.kuis) ? m.kuis.length : 3;
      const hasVideo = m.konten && m.konten.video_interaktif && m.konten.video_interaktif.url_asli;
      const gradeLetter = isDone ? (rec.skor >= 85 ? 'A' : (rec.skor >= 75 ? 'B' : 'C')) : '—';

      items.push({
        type: 'LMS',
        priority: isDone ? 3 : 1,
        icon: hasVideo ? '🎬' : '📘',
        title: m.judul,
        subtitle: `5 Tahap Konstruktif • ${kuisCount} Kuis HOTS${hasVideo ? ' • Video AI' : ''}`,
        course: s.name,
        dueText: isDone ? `Submitted` : `Today — Active`,
        dueClass: isDone ? 'due-done' : 'due-today',
        scoreMain: isDone ? gradeLetter : '—',
        scoreSub: isDone ? `${rec.skor}/100 (+${rec.xp} XP)` : 'Pending',
        statusHtml: isDone
          ? `<span style="color:#059669; font-weight:800;"><i class="fa-solid fa-check"></i> Graded</span>`
          : `<span style="color:#059669; font-weight:800;"><i class="fa-solid fa-spinner"></i> In Progress</span>`,
        isDone: isDone,
        isUrgent: false,
        action: `openStudentLMS('${safeName}'); setTimeout(()=>selectStudentLMSModule(${mIdx}), 90);`,
        btnLabel: isDone ? 'Review' : 'Pelajari'
      });
    });

    const isExDone = examHistory[s.name] !== undefined;
    const isExOpen = s.examStatus === 'AKTIF';
    items.push({
      type: 'CBT',
      priority: (!isExDone && isExOpen) ? 0 : (isExDone ? 4 : 2),
      icon: isExOpen ? '🔥' : '📝',
      title: `Ujian Akhir PTS/PAS — ${s.name}`,
      subtitle: `${s.totalSoalUjian || 25} Soal AKM & HOTS • 70 Menit • Fullscreen Anti-Cheat`,
      course: s.name,
      dueText: isExDone ? 'Completed' : (isExOpen ? 'Open — Submit Now' : 'Scheduled'),
      dueClass: isExDone ? 'due-done' : (isExOpen ? 'due-urgent' : 'due-soon'),
      scoreMain: isExDone ? 'A' : '—',
      scoreSub: isExDone ? 'Terekam di Server' : (isExOpen ? 'Not graded' : 'Upcoming'),
      statusHtml: isExDone
        ? `<span style="color:#059669; font-weight:800;"><i class="fa-solid fa-check-double"></i> Submitted</span>`
        : (isExOpen
          ? `<span style="color:#e11d48; font-weight:800;"><i class="fa-solid fa-triangle-exclamation"></i> Submit now</span>`
          : `<span style="color:#0284c7; font-weight:800;"><i class="fa-regular fa-calendar"></i> Scheduled</span>`),
      isDone: isExDone,
      isUrgent: (!isExDone && isExOpen),
      action: `startExam('${safeName}')`,
      btnLabel: isExDone ? 'Selesai' : (isExOpen ? 'Mulai Ujian' : 'Tutup')
    });
  });

  items = items.filter(it => {
    if (currentDashboardFilterMode === 'LMS' && it.type !== 'LMS') return false;
    if (currentDashboardFilterMode === 'CBT' && it.type !== 'CBT') return false;
    if (modeFilter === 'LMS' && it.type !== 'LMS') return false;
    if (modeFilter === 'CBT' && it.type !== 'CBT') return false;
    if (modeFilter === 'PENDING' && it.isDone) return false;
    if (modeFilter === 'GRADED' && !it.isDone) return false;
    if (kw && !it.title.toLowerCase().includes(kw) && !it.course.toLowerCase().includes(kw)) return false;
    return true;
  });

  items.sort((a, b) => a.priority - b.priority);
  return items;
}

function renderEduvanceAssignmentsTable(page = 1) {
  eduvanceAssignPage = page;
  const tbody = document.getElementById('eduvance-assignments-tbody');
  if (!tbody) return;

  const allItems = buildEduvanceAssignmentsDataset();
  const totalPages = Math.max(1, Math.ceil(allItems.length / eduvanceAssignPageSize));
  if (eduvanceAssignPage > totalPages) eduvanceAssignPage = totalPages;

  const startIdx = (eduvanceAssignPage - 1) * eduvanceAssignPageSize;
  const pageItems = allItems.slice(startIdx, startIdx + eduvanceAssignPageSize);

  if (pageItems.length === 0) {
    tbody.innerHTML = `<tr><td colspan="6" style="text-align:center; padding:32px; color:#64748b; font-weight:700;">Tidak ada tugas atau ujian untuk filter ini.</td></tr>`;
  } else {
    tbody.innerHTML = pageItems.map(it => `
      <tr class="${it.isUrgent ? 'row-urgent' : ''}" onclick="${it.action}">
        <td>
          <div style="display:flex; align-items:center; gap:12px;">
            <span style="font-size:20px; width:34px; height:34px; border-radius:10px; background:#ecfdf5; display:inline-flex; align-items:center; justify-content:center; flex-shrink:0;">${it.icon}</span>
            <div>
              <div style="font-weight:800; color:var(--text-main); line-height:1.3;">${escapeHtml(it.title)}</div>
              <div style="font-size:11.5px; color:#059669; font-weight:600; margin-top:2px;">${escapeHtml(it.subtitle)}</div>
            </div>
          </div>
        </td>
        <td><span class="edu-course-pill">${escapeHtml(it.course)}</span></td>
        <td><span class="edu-due-pill ${it.dueClass}">● ${escapeHtml(it.dueText)}</span></td>
        <td>
          <div style="font-weight:900; font-size:15px; color:#064e3b;">${it.scoreMain}</div>
          <div style="font-size:10.5px; color:#059669; font-weight:700;">${escapeHtml(it.scoreSub)}</div>
        </td>
        <td>${it.statusHtml}</td>
        <td style="text-align:right;">
          <button type="button" style="background:${it.isUrgent ? '#e11d48' : '#064e3b'}; color:white; border:none; padding:7px 14px; border-radius:9px; font-size:11.5px; font-weight:800; cursor:pointer;">
            ${it.btnLabel} &rarr;
          </button>
        </td>
      </tr>`).join('');
  }

  const showTxt = document.getElementById('eduvance-assign-showing-text');
  if (showTxt) {
    showTxt.innerText = `Showing ${pageItems.length} of ${allItems.length} assignments & exams — Semester Aktif`;
  }

  const pagEl = document.getElementById('eduvance-assign-pagination');
  if (pagEl) {
    let pHtml = '';
    for (let p = 1; p <= totalPages; p++) {
      pHtml += `<button type="button" class="eduvance-page-btn ${p === eduvanceAssignPage ? 'active' : ''}" onclick="renderEduvanceAssignmentsTable(${p})">${p}</button>`;
    }
    pagEl.innerHTML = pHtml;
  }

  const dlBox = document.getElementById('eduvance-upcoming-deadlines');
  if (dlBox) {
    const pendingList = allItems.filter(x => !x.isDone).slice(0, 5);
    const displayDl = pendingList.length > 0 ? pendingList : allItems.slice(0, 5);
    dlBox.innerHTML = displayDl.map((d, i) => {
      const badgeBg = d.isUrgent ? '#ffe4e6' : (i === 0 ? '#fef3c7' : '#fef3c7');
      const badgeCol = d.isUrgent ? '#e11d48' : (i === 0 ? '#047857' : '#047857');
      const badgeTxt = d.isUrgent ? 'Open Now!' : (i === 0 ? 'Today' : `${i + 2} days`);
      return `
        <div class="eduvance-deadline-item" onclick="${d.action}">
          <div style="display:flex; align-items:center; gap:11px; min-width:0; flex:1;">
            <span style="font-size:18px;">${d.icon}</span>
            <div style="min-width:0; flex:1;">
              <div style="font-size:13px; font-weight:800; color:var(--text-main); white-space:nowrap; overflow:hidden; text-overflow:ellipsis;">${escapeHtml(d.title)}</div>
              <div style="font-size:11px; color:#059669; font-weight:600;">${escapeHtml(d.course)} • ${escapeHtml(d.dueText)}</div>
            </div>
          </div>
          <span style="background:${badgeBg}; color:${badgeCol}; padding:4px 10px; border-radius:99px; font-size:11px; font-weight:800; white-space:nowrap;">${badgeTxt}</span>
        </div>`;
    }).join('');
  }
}

function renderEduvanceHeatmapAndWeeklyBars() {
  const mat = document.getElementById('eduvance-heatmap-matrix');
  if (mat) {
    const days = ['Mon', 'Wed', 'Fri'];
    const completedCount = Object.keys(globalLMSDashboard.completedMap || {}).length;
    mat.innerHTML = days.map((d, rIdx) => {
      let cells = '';
      for (let c = 0; c < 16; c++) {
        const seed = (rIdx * 7 + c * 3 + completedCount) % 5;
        const lvl = c > 11 ? Math.max(2, seed) : seed;
        cells += `<div class="eduvance-heat-cell ${lvl > 0 ? 'lvl-' + lvl : ''}" title="Minggu ${c + 1} (${d}): Aktivitas Level ${lvl}"></div>`;
      }
      return `
        <div class="eduvance-heatmap-row">
          <span class="eduvance-heatmap-day-lbl">${d}</span>
          <div class="eduvance-heatmap-cells">${cells}</div>
        </div>`;
    }).join('');
  }

  const bars = document.getElementById('eduvance-weekly-bars');
  if (bars) {
    const wDays = [
      { d: 'Sen', pct: 65 }, { d: 'Sel', pct: 80 }, { d: 'Rab', pct: 95 },
      { d: 'Kam', pct: 70 }, { d: 'Jum', pct: 88 }, { d: 'Sab', pct: 60 }, { d: 'Min', pct: 45 }
    ];
    bars.innerHTML = wDays.map(w => `
      <div class="eduvance-bar-col">
        <div class="eduvance-bar-track">
          <div class="eduvance-bar-fill" style="height:${w.pct}%;"></div>
        </div>
        <span class="eduvance-bar-lbl">${w.d}</span>
      </div>`).join('');
  }
}

function renderEduvanceDashboardAll() {
  renderEduvanceSidebarAndHeader();
  renderEduvanceKPICards();
  renderEduvanceCourseDonuts();
  renderEduvanceTodayTimeline();
  renderEduvanceAssignmentsTable(eduvanceAssignPage);
  renderEduvanceHeatmapAndWeeklyBars();
}

const _v21LoadSubjects = loadSubjects;
loadSubjects = async function() {
  await _v21LoadSubjects();
  renderEduvanceDashboardAll();
};

const _v21SetStudentDashboardFilter = setStudentDashboardFilter;
setStudentDashboardFilter = function(mode) {
  _v21SetStudentDashboardFilter(mode);
  renderEduvanceAssignmentsTable(1);
};


// =========================================================================
// 24. PEMBARUAN V26:
//     - PEMISAHAN TEGAS MENU RUANG BELAJAR (LMS) VS PORTAL UJIAN (CBT)
//     - PEMISAHAN VISUAL ANTAR MODUL DI DALAM LMS
//     - MODAL PROFIL LENGKAP SISWA, PROGRES DETAIL & UPDATE PASSWORD MANDIRI
//     - 100% ANTARMUKA BAHASA INDONESIA
// =========================================================================

// A. Pastikan `kembaliKeDashboardSiswa()` dari dalam Ruang Belajar LMS kembali tepat ke Katalog LMS (`courses`)
kembaliKeDashboardSiswa = function() {
  document.body.classList.remove('lms-zen-mode', 'lms-native-android-mode');
  playStudentSFX('click');
  if ('speechSynthesis' in window) window.speechSynthesis.cancel();
  document.getElementById('lms-learning-section')?.classList.add('hidden');
  document.getElementById('dashboard-section')?.classList.remove('hidden');
  switchEduvanceNav('courses');
};

// B. Pisahkan Kartu Katalog LMS (`#subject-grid` di menu Ruang Belajar LMS) dan Kartu Portal Ujian CBT (`#cbt-standalone-exam-grid` di menu Ujian CBT)
renderStudentSubjectCards = function() {
  const lmsGrid = document.getElementById('subject-grid');
  const cbtGrid = document.getElementById('cbt-standalone-exam-grid');
  const searchKw = (document.getElementById('studentSearchMapel')?.value || '').toLowerCase().trim();
  const subjects = (globalLMSDashboard.subjects || []).filter(s => !searchKw || s.name.toLowerCase().includes(searchKw));
  const historyMap = globalLMSDashboard.examHistoryMap || {};

  if (lmsGrid) lmsGrid.innerHTML = '';
  if (cbtGrid) cbtGrid.innerHTML = '';

  if (subjects.length === 0) {
    const emptyMsg = '<p style="color:var(--danger); font-weight:bold; padding:20px;">Tidak ditemukan mata pelajaran yang sesuai.</p>';
    if (lmsGrid) lmsGrid.innerHTML = emptyMsg;
    if (cbtGrid) cbtGrid.innerHTML = emptyMsg;
    return;
  }

  const gradients = [
    'linear-gradient(135deg, #064e3b, #059669)',
    'linear-gradient(135deg, #047857, #10b981)',
    'linear-gradient(135deg, #0369a1, #0ea5e9)',
    'linear-gradient(135deg, #6d28d9, #8b5cf6)',
    'linear-gradient(135deg, #be185d, #ec4899)',
    'linear-gradient(135deg, #1d4ed8, #3b82f6)'
  ];
  const icons = ['fa-book-open-reader', 'fa-calculator', 'fa-flask-vial', 'fa-earth-asia', 'fa-language', 'fa-laptop-code', 'fa-mosque', 'fa-palette'];

  subjects.forEach((subObj, idx) => {
    const icon = icons[idx % icons.length];
    const bgGradient = gradients[idx % gradients.length];
    const safeSubName = subObj.name.replace(/'/g, "\\'");
    const isExamCompleted = historyMap[subObj.name] !== undefined;
    const isExamActive = (subObj.examStatus === 'AKTIF');

    const totMod = Math.max(1, subObj.totalModules || (subObj.modules ? subObj.modules.length : 1));
    const doneMod = subObj.completedModules || 0;
    const pctLearn = Math.min(100, Math.round((doneMod / totMod) * 100));

    // 1. Render Kartu Khusus Ruang Belajar (LMS Murni — Tanpa Tombol Ujian yang Tumpang Tindih)
    if (lmsGrid) {
      lmsGrid.innerHTML += `
        <div class="lms-subject-card">
          <div class="lms-subject-top" style="background: ${bgGradient};">
            <i class="fa-solid ${icon} bg-watermark"></i>
            <div style="display:flex; justify-content:space-between; align-items:center; gap:8px; z-index:2;">
              <span style="background:rgba(0,0,0,0.25); padding:5px 12px; border-radius:99px; font-size:11px; font-weight:800;">
                <i class="fa-solid fa-cubes"></i> ${totMod} Modul Pembelajaran
              </span>
              <span style="background:rgba(255,255,255,0.22); padding:4px 10px; border-radius:99px; font-size:11px; font-weight:800;">
                ${doneMod === totMod ? '✓ Tuntas' : '5 Tahap Konstruktif'}
              </span>
            </div>
            <div style="z-index:2; margin-top:18px;">
              <h4 style="font-size:20px; font-weight:800; line-height:1.25;">${escapeHtml(subObj.name)}</h4>
            </div>
          </div>
          <div class="lms-subject-body">
            <div>
              <div style="display:flex; justify-content:space-between; font-size:12px; font-weight:800; color:var(--text-muted); margin-bottom:6px;">
                <span>Ketuntasan Materi &amp; Kuis XP</span>
                <span style="color:var(--primary);">${doneMod}/${totMod} Bab (${pctLearn}%)</span>
              </div>
              <div class="lms-progress-bar-wrap">
                <div class="lms-progress-bar-fill" style="width:${pctLearn}%;"></div>
              </div>
            </div>
            <button type="button" class="btn-lms-action btn-lms-learn" style="width:100%; background:#064e3b; color:#ffffff; border:none; padding:13px;" onclick="openStudentLMS('${safeSubName}')">
              <i class="fa-solid fa-book-open-reader"></i> Buka Modul Ruang Belajar (${totMod} Bab)
            </button>
          </div>
        </div>`;
    }

    // 2. Render Kartu Khusus Portal Ujian Akhir CBT (Berdiri Sendiri di Menu Ujian)
    if (cbtGrid) {
      let statusBadgeHtml = '';
      let actionBtnHtml = '';
      if (isExamCompleted) {
        const submitDate = new Date(historyMap[subObj.name]);
        const dateStr = isNaN(submitDate) ? 'Terekam' : submitDate.toLocaleDateString('id-ID', { day: 'numeric', month: 'short', year: 'numeric' });
        statusBadgeHtml = `<span style="background:#d1fae5; color:#059669; padding:5px 12px; border-radius:99px; font-size:11px; font-weight:800;"><i class="fa-solid fa-circle-check"></i> Selesai (${dateStr})</span>`;
        actionBtnHtml = `<button type="button" class="btn-lms-action" style="width:100%; background:#f1f5f9; color:#059669; border:1.5px solid #a7f3d0;" onclick="Swal.fire({icon:'success', title:'Ujian Telah Diselesaikan', text:'Kamu sudah mengumpulkan jawaban ujian akhir ${safeSubName}.', customClass:{popup:'swal-custom-popup', confirmButton:'swal-custom-confirm'}})"><i class="fa-solid fa-check-double"></i> Jawaban Sudah Terkirim</button>`;
      } else if (isExamActive) {
        statusBadgeHtml = `<span style="background:#fef3c7; color:#047857; padding:5px 12px; border-radius:99px; font-size:11px; font-weight:900; border:1px solid #fde68a;"><i class="fa-solid fa-unlock"></i> Ujian Terbuka</span>`;
        actionBtnHtml = `<button type="button" class="btn-lms-action" style="width:100%; background:linear-gradient(135deg, #059669, #047857); color:white; border:none; box-shadow:0 6px 16px rgba(5, 150, 105,0.25);" onclick="startExam('${safeSubName}')"><i class="fa-solid fa-file-signature"></i> Mulai Kerjakan Ujian Sekarang</button>`;
      } else {
        statusBadgeHtml = `<span style="background:#f1f5f9; color:#64748b; padding:5px 12px; border-radius:99px; font-size:11px; font-weight:800;"><i class="fa-solid fa-lock"></i> Belum Dibuka</span>`;
        actionBtnHtml = `<button type="button" class="btn-lms-action" style="width:100%; background:#f8fafc; color:#94a3b8; border:1.5px solid #e2e8f0;" onclick="Swal.fire({icon:'info', title:'Sesi Ujian Belum Dibuka', text:'Ujian akhir (PTS/PAS) untuk ${safeSubName} saat ini masih ditutup oleh Pengawas. Silakan pelajari materinya terlebih dahulu di menu Ruang Belajar (LMS)!', customClass:{popup:'swal-custom-popup', confirmButton:'swal-custom-confirm'}})"><i class="fa-solid fa-lock"></i> Menunggu Jadwal Pengawas</button>`;
      }

      cbtGrid.innerHTML += `
        <div class="lms-subject-card" style="border-color:${isExamActive && !isExamCompleted ? '#10b981' : '#e2e8f0'};">
          <div style="padding:20px 22px; background:${isExamActive && !isExamCompleted ? '#ecfdf5' : '#f8fafc'}; border-bottom:1.5px solid #e2e8f0; display:flex; flex-direction:column; gap:10px;">
            <div style="display:flex; justify-content:space-between; align-items:center; gap:8px;">
              <span style="font-size:11px; font-weight:800; color:#064e3b; text-transform:uppercase;"><i class="fa-solid fa-shield-halved"></i> ASESMEN CBT (70 MENIT)</span>
              ${statusBadgeHtml}
            </div>
            <h4 style="font-size:18.5px; font-weight:800; color:var(--text-main); line-height:1.3;">${escapeHtml(subObj.name)}</h4>
            <div style="font-size:12px; color:#64748b; font-weight:600;">
              <i class="fa-solid fa-list-ol" style="color:#059669;"></i> ${subObj.totalSoalUjian || 25} Butir Soal AKM &amp; HOTS &bull; Layar Penuh
            </div>
          </div>
          <div class="lms-subject-body" style="padding:16px 22px;">
            ${actionBtnHtml}
          </div>
        </div>`;
    }
  });
};

// C. Kemas Pemilih Modul di dalam Ruang Belajar LMS agar Terpisah Jelas, Interaktif, dan Berbahasa Indonesia
openStudentLMS = function(mapelName) {
  ensureNotFullscreenInLMS();
  activeLMSSubject = mapelName;
  document.getElementById('dashboard-section')?.classList.add('hidden');
  document.getElementById('lms-learning-section')?.classList.remove('hidden');
  const badgeEl = document.getElementById('lms-active-mapel-badge');
  if (badgeEl) badgeEl.innerText = mapelName.toUpperCase();

  const subObj = (globalLMSDashboard.subjects || []).find(s => s.name === mapelName);
  const modules = (subObj && subObj.modules && subObj.modules.length > 0)
    ? subObj.modules
    : [getDefaultConstructiveModule(mapelName)];

  const counterEl = document.getElementById('lms-module-total-counter');
  if (counterEl) counterEl.innerText = `${modules.length} Modul / Bab Tersedia`;

  const selectorBar = document.getElementById('lms-module-selector-bar');
  if (selectorBar) {
    selectorBar.innerHTML = '';
    modules.forEach((mod, idx) => {
      const isDone = globalLMSDashboard.completedMap && globalLMSDashboard.completedMap[mod.id] !== undefined;
      const rec = isDone ? globalLMSDashboard.completedMap[mod.id] : null;
      selectorBar.innerHTML += `
        <button type="button" id="btn-sel-mod-${idx}" class="lms-module-select-card ${idx === 0 ? 'active-mod-card' : ''}" onclick="selectStudentLMSModule(${idx})">
          <div style="width:46px; height:46px; border-radius:14px; background:${isDone ? '#10b981' : '#d1fae5'}; color:${isDone ? '#ffffff' : '#059669'}; display:flex; align-items:center; justify-content:center; font-size:19px; flex-shrink:0;">
            <i class="fa-solid ${isDone ? 'fa-circle-check' : 'fa-book-open-reader'}"></i>
          </div>
          <div style="flex:1; min-width:0;">
            <div style="display:flex; justify-content:space-between; align-items:center; gap:6px;">
              <span style="font-size:11px; font-weight:900; color:#047857; text-transform:uppercase;">MODUL / BAB ${idx + 1}</span>
              <span style="font-size:10.5px; font-weight:800; padding:2px 8px; border-radius:99px; background:${isDone ? '#d1fae5' : '#e2e8f0'}; color:${isDone ? '#059669' : '#475569'};">
                ${isDone ? `✓ Tuntas (Skor ${rec.skor})` : 'Belum Tuntas'}
              </span>
            </div>
            <div style="font-size:14.5px; font-weight:800; color:var(--text-main); line-height:1.35; margin-top:4px;">${escapeHtml(mod.judul)}</div>
          </div>
        </button>`;
    });
  }

  window.currentSubjectModulesList = modules;
  selectStudentLMSModule(0);
  window.scrollTo({ top: 0, behavior: 'smooth' });
};

// D. Pastikan Seluruh Teks Header, Tanggal, dan Sapaan Berbahasa Indonesia
const _v25RenderEduvanceSidebarAndHeader = renderEduvanceSidebarAndHeader;
renderEduvanceSidebarAndHeader = function() {
  _v25RenderEduvanceSidebarAndHeader();
  const name = (studentData && studentData.name) ? studentData.name : 'Siswa Kelas 7';
  const kelas = (studentData && studentData.kelas) ? studentData.kelas : '7A';
  const now = new Date();
  const hr = now.getHours();
  const sapaan = hr < 11 ? 'Selamat Pagi' : (hr < 15 ? 'Selamat Siang' : (hr < 18 ? 'Selamat Sore' : 'Selamat Malam'));
  const firstName = name.split(' ')[0];

  if (document.getElementById('eduvance-greeting-title')) {
    document.getElementById('eduvance-greeting-title').innerText = `${sapaan}, ${firstName} ✨`;
  }

  const att = getStudentAttendanceState();
  const completedCount = Object.keys(globalLMSDashboard.completedMap || {}).length;
  const streakDays = Math.max(1, att.days.length + completedCount);
  if (document.getElementById('eduvance-greeting-streak-pill')) {
    document.getElementById('eduvance-greeting-streak-pill').innerText = `🔥 KONSISTEN BELAJAR ${streakDays} HARI BERUNTUN!`;
  }

  const attLbl = document.getElementById('lbl-eduvance-attendance');
  if (attLbl) {
    attLbl.innerText = att.isCheckedToday ? 'Sudah Hadir ✓' : 'Presensi Hadir';
  }

  const titleMapId = {
    dashboard: 'Beranda Saya',
    courses: 'Ruang Belajar Konstruktif (LMS)',
    assignments: 'Portal Ujian Akhir (CBT)',
    schedule: 'Jadwal & Statistik Keaktifan',
    grades: 'Prestasi, Lencana & Peringkat'
  };
  const topTitleEl = document.getElementById('eduvance-topbar-title');
  if (topTitleEl && titleMapId[eduvanceActiveNav]) {
    topTitleEl.innerText = titleMapId[eduvanceActiveNav];
  }
};

