function closeStudentProfileAndProgressModal() {
  const modal = document.getElementById('studentProfileCenterModal');
  if (modal) modal.classList.remove('active');
}

function toggleProfilePasswordVisibility() {
  isProfilePasswordVisible = !isProfilePasswordVisible;
  openStudentProfileAndProgressModal();
}

function simpanPasswordBaruSiswa() {
  const newPassEl = document.getElementById('inp-new-student-pass');
  const confPassEl = document.getElementById('inp-confirm-student-pass');
  const btn = document.getElementById('btn-save-student-pass');
  if (!newPassEl || !confPassEl) return;

  const newPass = newPassEl.value.trim();
  const confPass = confPassEl.value.trim();

  if (!newPass || newPass.length < 4) {
    Swal.fire({
      icon: 'warning',
      title: 'Kata Sandi Terlalu Pendek',
      text: 'Kata sandi baru minimal harus terdiri dari 4 karakter!',
      customClass: { popup: 'swal-custom-popup', confirmButton: 'swal-custom-confirm' }
    });
    return;
  }

  if (newPass !== confPass) {
    Swal.fire({
      icon: 'error',
      title: 'Konfirmasi Tidak Cocok',
      text: 'Ketikan kata sandi baru dan konfirmasinya harus sama persis!',
      customClass: { popup: 'swal-custom-popup', confirmButton: 'swal-custom-confirm' }
    });
    return;
  }

  if (btn) {
    btn.innerHTML = '<i class="fa-solid fa-spinner fa-spin"></i> Menyimpan...';
    btn.disabled = true;
  }

  google.script.run.withSuccessHandler(res => {
    if (btn) {
      btn.innerHTML = '<i class="fa-solid fa-floppy-disk"></i> Simpan Kata Sandi Baru';
      btn.disabled = false;
    }
    if (res && res.success) {
      studentData.password = newPass;
      isProfilePasswordVisible = true;
      openStudentProfileAndProgressModal();
      Swal.fire({
        icon: 'success',
        title: 'Kata Sandi Berhasil Diperbarui!',
        text: res.message,
        customClass: { popup: 'swal-custom-popup', confirmButton: 'swal-custom-confirm' }
      });
    } else {
      Swal.fire({
        icon: 'error',
        title: 'Gagal Memperbarui Kata Sandi',
        text: res ? res.message : 'Terjadi gangguan koneksi ke server.',
        customClass: { popup: 'swal-custom-popup', confirmButton: 'swal-custom-confirm' }
      });
    }
  }).withFailureHandler(err => {
    if (btn) {
      btn.innerHTML = '<i class="fa-solid fa-floppy-disk"></i> Simpan Kata Sandi Baru';
      btn.disabled = false;
    }
    Swal.fire({
      icon: 'error',
      title: 'Gagal Menghubungi Server',
      text: err.toString(),
      customClass: { popup: 'swal-custom-popup', confirmButton: 'swal-custom-confirm' }
    });
  }).updateStudentPasswordClient({
    email: studentData.email,
    oldPass: studentData.password || '',
    newPass: newPass
  });
}


// =========================================================================
// 25. PEMBARUAN V27:
//     - FITUR KUNCI MANUAL MENU LMS OLEH ADMIN (GLOBAL & PER MATA PELAJARAN)
//     - PROPORSI SEMPURNA SELURUH HEADER DI SMARTPHONE & DESKTOP
//     - RENDER INSTAN HEADER SAAT LOGIN (TANPA DELAY "MEMUAT TANGGAL...")
// =========================================================================

let currentGlobalLMSStatusAdmin = 'AKTIF';

// 1. Fungsi Cek Status Kunci LMS (Global maupun Per Mata Pelajaran)
function isGlobalLMSLockedForStudent() {
  if (globalLMSDashboard.globalLMSStatus === 'NONAKTIF') return true;
  const subjs = globalLMSDashboard.subjects || [];
  if (subjs.length > 0 && subjs.every(s => s.lmsStatus === 'NONAKTIF')) return true;
  return false;
}

function isSubjectLMSLockedForStudent(mapelName) {
  if (isGlobalLMSLockedForStudent()) return true;
  const subObj = (globalLMSDashboard.subjects || []).find(s => s.name === mapelName);
  if (subObj && subObj.lmsStatus === 'NONAKTIF') return true;
  return false;
}

function showLockedLMSAlertModal(mapelName) {
  playStudentSFX('click');
  const isGlobal = isGlobalLMSLockedForStudent() || !mapelName;
  Swal.fire({
    icon: 'warning',
    title: isGlobal ? '🔒 Menu Ruang Belajar (LMS) Dikunci' : `🔒 LMS ${mapelName} Dikunci Admin`,
    html: isGlobal
      ? `Akses menuju <b>Menu Ruang Belajar (LMS)</b> saat ini sedang <b>dikunci secara manual oleh Admin / Pengawas</b> (misalnya selama pelaksanaan Ujian PTS/PAS berlangsung).<br><br>Silakan menuju ke menu <b>Ujian Akhir (CBT)</b> untuk mengerjakan asesmen yang sedang dibuka!`
      : `Akses materi <b>Ruang Belajar (LMS)</b> untuk mata pelajaran <b>${escapeHtml(mapelName)}</b> saat ini sedang dikunci oleh Admin/Guru Pengampu.<br><br>Silakan pelajari mata pelajaran lain yang berstatus terbuka atau cek menu <b>Ujian Akhir (CBT)</b>.`,
    showCancelButton: true,
    confirmButtonText: '<i class="fa-solid fa-file-signature"></i> Buka Menu Ujian (CBT)',
    cancelButtonText: 'Tutup',
    customClass: { popup: 'swal-custom-popup', confirmButton: 'swal-custom-confirm' }
  }).then(res => {
    if (res.isConfirmed) {
      switchEduvanceNav('assignments');
    }
  });
}

// 2. Pengaturan Admin: Tabel 5 Kolom (Akses LMS + Akses Ujian CBT + Token Mulai + Token Selesai) & Master Switch LMS
function syncGlobalLMSAdminBannerUI() {
  const isUnlocked = currentGlobalLMSStatusAdmin !== 'NONAKTIF';
  const chk = document.getElementById('toggle_global_lms');
  if (chk) chk.checked = isUnlocked;

  const banner = document.getElementById('admin-global-lms-banner');
  if (banner) banner.classList.toggle('lms-global-locked', !isUnlocked);

  const iconBox = document.getElementById('admin-global-lms-icon');
  if (iconBox) {
    iconBox.style.background = isUnlocked ? '#10b981' : '#e11d48';
    iconBox.innerHTML = `<i class="fa-solid ${isUnlocked ? 'fa-book-open-reader' : 'fa-lock'}"></i>`;
  }

  const badge = document.getElementById('badge-global-lms-status');
  if (badge) {
    badge.style.background = isUnlocked ? '#d1fae5' : '#ffe4e6';
    badge.style.color = isUnlocked ? '#059669' : '#be123c';
    badge.innerHTML = isUnlocked ? '<i class="fa-solid fa-unlock"></i> TERBUKA UNTUK SISWA' : '<i class="fa-solid fa-lock"></i> DIKUNCI OLEH ADMIN';
  }
}

function toggleGlobalLMSMasterState(isChecked) {
  currentGlobalLMSStatusAdmin = isChecked ? 'AKTIF' : 'NONAKTIF';
  syncGlobalLMSAdminBannerUI();
}

function setBulkSettingsStatus(fieldKey, targetVal) {
  if (!Array.isArray(currentSettingsData) || currentSettingsData.length === 0) return;
  if (fieldKey === 'statusLMS') {
    currentGlobalLMSStatusAdmin = targetVal;
    syncGlobalLMSAdminBannerUI();
  }
  currentSettingsData.forEach((item, idx) => {
    item[fieldKey] = targetVal;
    if (fieldKey === 'statusLMS') {
      const chk = document.getElementById(`toggle_lms_${idx}`);
      if (chk) chk.checked = (targetVal === 'AKTIF');
      const lbl = document.getElementById(`lbl_toggle_lms_${idx}`);
      if (lbl) {
        lbl.innerHTML = targetVal === 'AKTIF' ? '<i class="fa-solid fa-unlock"></i> LMS TERBUKA' : '<i class="fa-solid fa-lock"></i> LMS DIKUNCI';
        lbl.style.color = targetVal === 'AKTIF' ? 'var(--success)' : 'var(--danger)';
      }
    } else if (fieldKey === 'status') {
      const chk = document.getElementById(`toggle_${idx}`);
      if (chk) chk.checked = (targetVal === 'AKTIF');
      const lbl = document.getElementById(`lbl_toggle_${idx}`);
      if (lbl) {
        lbl.innerHTML = targetVal === 'AKTIF' ? '<i class="fa-solid fa-unlock"></i> UJIAN TERBUKA' : '<i class="fa-solid fa-lock"></i> UJIAN DITUTUP';
        lbl.style.color = targetVal === 'AKTIF' ? 'var(--success)' : 'var(--danger)';
      }
    }
  });
}

fetchExamSettingsAdmin = function() {
  const tbody = document.getElementById('settingsBody');
  if (!tbody) return;
  tbody.innerHTML = `<tr><td colspan="5" style="text-align:center; padding: 40px;"><i class="fa-solid fa-spinner fa-spin" style="font-size:30px; color:var(--primary);"></i></td></tr>`;
  google.script.run.withSuccessHandler(res => {
    tbody.innerHTML = '';
    if (res && res.success && res.data.length > 0) {
      currentSettingsData = res.data.map(item => ({
        mapel: item.mapel,
        status: item.status || 'NONAKTIF',
        tokenMulai: item.tokenMulai || 'MULAI123',
        tokenSelesai: item.tokenSelesai || 'SELESAI123',
        statusLMS: item.statusLMS || 'AKTIF'
      }));
      currentGlobalLMSStatusAdmin = res.globalLMSStatus || 'AKTIF';
      syncGlobalLMSAdminBannerUI();

      currentSettingsData.forEach((item, idx) => {
        const isCbtChecked = item.status === 'AKTIF' ? 'checked' : '';
        const isLmsChecked = item.statusLMS !== 'NONAKTIF' ? 'checked' : '';
        tbody.innerHTML += `<tr>
          <td style="vertical-align: middle;"><b style="color:var(--text-main); font-size:15px;">${escapeHtml(item.mapel)}</b></td>
          <td style="text-align:center; vertical-align: middle; background:#f0fdfa;">
            <label class="switch" title="Kunci / Buka Ruang Belajar LMS ${escapeHtml(item.mapel)}">
              <input type="checkbox" id="toggle_lms_${idx}" ${isLmsChecked} onchange="updateSettingsState(${idx}, 'statusLMS', this.checked ? 'AKTIF' : 'NONAKTIF')">
              <span class="slider"></span>
            </label>
            <div style="font-size:11px; margin-top:5px; font-weight:800; color:${item.statusLMS !== 'NONAKTIF' ? 'var(--success)' : 'var(--danger)'};" id="lbl_toggle_lms_${idx}">
              ${item.statusLMS !== 'NONAKTIF' ? '<i class="fa-solid fa-unlock"></i> LMS TERBUKA' : '<i class="fa-solid fa-lock"></i> LMS DIKUNCI'}
            </div>
          </td>
          <td style="text-align:center; vertical-align: middle;">
            <label class="switch" title="Kunci / Buka Ujian Akhir CBT ${escapeHtml(item.mapel)}">
              <input type="checkbox" id="toggle_${idx}" ${isCbtChecked} onchange="updateSettingsState(${idx}, 'status', this.checked ? 'AKTIF' : 'NONAKTIF')">
              <span class="slider"></span>
            </label>
            <div style="font-size:11px; margin-top:5px; font-weight:800; color:${item.status === 'AKTIF' ? 'var(--success)' : 'var(--danger)'};" id="lbl_toggle_${idx}">
              ${item.status === 'AKTIF' ? '<i class="fa-solid fa-unlock"></i> UJIAN TERBUKA' : '<i class="fa-solid fa-lock"></i> UJIAN DITUTUP'}
            </div>
          </td>
          <td style="vertical-align: middle;"><input type="text" value="${escapeHtml(item.tokenMulai)}" onchange="updateSettingsState(${idx}, 'tokenMulai', this.value)" style="padding:12px; border:2px solid #e2e8f0; border-radius:12px; outline:none; font-weight:800; width:100%; color:var(--primary);"></td>
          <td style="vertical-align: middle;"><input type="text" value="${escapeHtml(item.tokenSelesai)}" onchange="updateSettingsState(${idx}, 'tokenSelesai', this.value)" style="padding:12px; border:2px solid #e2e8f0; border-radius:12px; outline:none; font-weight:800; width:100%; color:var(--danger);"></td>
        </tr>`;
      });
    } else {
      tbody.innerHTML = `<tr><td colspan="5" style="text-align:center; padding: 40px; color:var(--text-muted); font-weight:600;">Data mata pelajaran belum tersedia. Silakan buat Mapel baru di tab Bank Soal.</td></tr>`;
    }
  }).getExamSettingsAdmin();
};

updateSettingsState = function(idx, key, value) {
  if (!currentSettingsData[idx]) return;
  currentSettingsData[idx][key] = value;
  if (key === 'status') {
    const lbl = document.getElementById(`lbl_toggle_${idx}`);
    if (lbl) {
      lbl.innerHTML = value === 'AKTIF' ? '<i class="fa-solid fa-unlock"></i> UJIAN TERBUKA' : '<i class="fa-solid fa-lock"></i> UJIAN DITUTUP';
      lbl.style.color = value === 'AKTIF' ? 'var(--success)' : 'var(--danger)';
    }
  } else if (key === 'statusLMS') {
    const lbl = document.getElementById(`lbl_toggle_lms_${idx}`);
    if (lbl) {
      lbl.innerHTML = value === 'AKTIF' ? '<i class="fa-solid fa-unlock"></i> LMS TERBUKA' : '<i class="fa-solid fa-lock"></i> LMS DIKUNCI';
      lbl.style.color = value === 'AKTIF' ? 'var(--success)' : 'var(--danger)';
    }
  }
};

saveExamSettingsFrontend = function() {
  Swal.fire({ title: 'Menyimpan Pengaturan Akses...', didOpen: () => Swal.showLoading(), allowOutsideClick: false, customClass: { popup: 'swal-custom-popup' } });
  google.script.run.withSuccessHandler(res => {
    if (res && res.success) {
      catatRiwayatAksiAdmin('ADMIN', 'Semua Mapel', `SIMPAN AKSES LMS (${currentGlobalLMSStatusAdmin}) & TOKEN CBT`);
      Swal.fire({ icon: 'success', title: 'Tersimpan!', text: res.message, timer: 1600, showConfirmButton: false, customClass: { popup: 'swal-custom-popup' } });
    } else {
      Swal.fire({ icon: 'error', title: 'Gagal', text: res ? res.message : 'Gagal menyimpan pengaturan', customClass: { popup: 'swal-custom-popup' } });
    }
  }).saveExamSettingsAdmin(currentSettingsData, currentGlobalLMSStatusAdmin);
};

