const _v26TriggerStartStudyingQuick = triggerStartStudyingQuick;
triggerStartStudyingQuick = function() {
  if (isGlobalLMSLockedForStudent()) {
    showLockedLMSAlertModal();
    return;
  }
  const unlockedSub = (globalLMSDashboard.subjects || []).find(s => s.lmsStatus !== 'NONAKTIF');
  if (!unlockedSub) {
    showLockedLMSAlertModal();
    return;
  }
  const saved = (studentData && studentData.email)
    ? JSON.parse(localStorage.getItem(`lms_last_${studentData.email}`) || 'null')
    : null;
  if (saved && saved.mapel && !isSubjectLMSLockedForStudent(saved.mapel)) {
    resumeLastLMSModule(saved.mapel, saved.modIdx || 0, saved.step || 1);
    return;
  }
  openStudentLMS(unlockedSub.name);
};

