// =========================================================================
// 26. PEMBARUAN V28:
//     - 4 WIDGET INFORMASI REKAP PEMBELAJARAN SISWA REAL-TIME (MURNI DATA NYATA TANPA ANGKA GIMIK)
//     - MODAL REKAP DETAIL SAAT WIDGET DIKLIK (NILAI, KEAKTIFAN, XP & EKSPLORASI, KETUNTASAN)
//     - SIDEBAR SOLID & KONSISTEN DI SMARTPHONE MAUPUN DESKTOP (PERSENTASE REAL 0% - 100%)
// =========================================================================

function computeRealStudentLearningMetrics() {
  const subjs = globalLMSDashboard.subjects || [];
  const completedMap = globalLMSDashboard.completedMap || {};
  const completedList = Object.values(completedMap);
  const historyLogs = Array.isArray(globalLMSDashboard.history) ? globalLMSDashboard.history : completedList;
  const examHistory = globalLMSDashboard.examHistoryMap || {};
  const examScores = globalLMSDashboard.examScoresMap || {};
  const qnaByModul = globalLMSDashboard.qnaByModul || {};
  const tr = typeof getStudentVerifiedTracker === 'function' ? getStudentVerifiedTracker() : { readTimers: {}, subChecked: {}, cardsMastered: {}, aiEvaluated: {} };
  const att = typeof getStudentAttendanceState === 'function' ? getStudentAttendanceState() : { days: [], isCheckedToday: false };

  // 1. Hitung Rata-Rata Nilai Real (Gabungan Skor Kuis Formatif LMS & Nilai Ujian CBT yang sudah dikerjakan)
  const quizScores = completedList.map(c => Number(c.skor)).filter(n => !isNaN(n));
  const cbtScoresList = Object.values(examScores).map(n => Number(n)).filter(n => !isNaN(n));
  const allRealScores = [...quizScores, ...cbtScoresList];

  const avgScore100 = allRealScores.length > 0
    ? (allRealScores.reduce((a, b) => a + b, 0) / allRealScores.length)
    : 0;
  const avgQuizOnly = quizScores.length > 0
    ? Math.round(quizScores.reduce((a, b) => a + b, 0) / quizScores.length)
    : 0;
  const gpaScale4 = allRealScores.length > 0 ? (avgScore100 / 25).toFixed(2) : '0.00';

  // 2. Hitung Hari Belajar Aktif Real (Berdasarkan tanggal unik di LMS_Progress + tanggal ujian Supabase + presensi nyata)
  const activeDatesSet = new Set();
  (att.days || []).forEach(d => { if (d) activeDatesSet.add(d.toString().substring(0, 10)); });
  historyLogs.forEach(h => {
    if (h && h.waktu) {
      const datePart = h.waktu.toString().split(' ')[0].split(',')[0].trim();
      if (datePart) activeDatesSet.add(datePart);
    }
  });
  Object.values(examHistory).forEach(ts => {
    if (ts) {
      const dt = new Date(ts);
      if (!isNaN(dt)) activeDatesSet.add(dt.toISOString().slice(0, 10));
    }
  });

  // Hitung jumlah Jurnal Refleksi nyata & pertanyaan QnA siswa ini
  const realReflections = completedList.filter(c => c.refleksi && c.refleksi.trim().length > 3);
  const myNameClean = (studentData && studentData.name) ? studentData.name.trim().toLowerCase() : '';
  let myQnaCount = 0;
  let myQnaItems = [];
  Object.values(qnaByModul).forEach(arr => {
    (arr || []).forEach(q => {
      if (myNameClean && (q.namaSiswa || '').trim().toLowerCase() === myNameClean) {
        myQnaCount++;
        myQnaItems.push(q);
      }
    });
  });

  const activeDaysCount = activeDatesSet.size;

  // 3. Hitung Poin XP Real, Level, Durasi Eksplorasi Nyata, & Kartu Pintar 3D yang dikuasai
  const baseXP = Number(globalLMSDashboard.totalXP) || 0;
  const bonusXP = typeof getStudentBonusActivityXP === 'function' ? getStudentBonusActivityXP() : 0;
  const totalRealXP = baseXP + bonusXP;
  const rankInfo = typeof getStudentRankInfoV15 === 'function'
    ? getStudentRankInfoV15(totalRealXP)
    : { current: { level: 1, title: 'Tunas Pembelajar' }, next: { minXP: 200 }, pctToNext: 0 };

  const totalReadSeconds = Object.values(tr.readTimers || {}).reduce((a, b) => a + (Number(b) || 0), 0);
  const totalReadMinutes = Math.round(totalReadSeconds / 60);
  const totalCardsMastered = Object.keys(lmsFlashcardMastery || {}).filter(k => lmsFlashcardMastery[k] === 'mastered').length +
    Object.keys(tr.cardsMastered || {}).filter(k => tr.cardsMastered[k] === 'mastered').length;

  // 4. Hitung Ketuntasan Modul LMS & Ujian CBT Real
  const totalModulesAvailable = subjs.reduce((acc, s) => acc + Math.max(0, Number(s.totalModules) || (s.modules ? s.modules.length : 0)), 0);
  const totalModulesDone = completedList.length;
  const totalExamsAvailable = subjs.length;
  const totalExamsDone = Object.keys(examHistory).length;
  const totalOpenExamsNow = subjs.filter(s => s.examStatus === 'AKTIF' && !examHistory[s.name]).length;

  const totalTargetItems = totalModulesAvailable + totalExamsAvailable;
  const totalFinishedItems = totalModulesDone + totalExamsDone;
  const overallCompletionPct = totalTargetItems > 0 ? Math.min(100, Math.round((totalFinishedItems / totalTargetItems) * 100)) : 0;
  const modCompletionPct = totalModulesAvailable > 0 ? Math.min(100, Math.round((totalModulesDone / totalModulesAvailable) * 100)) : 0;

  return {
    subjs,
    completedMap,
    completedList,
    historyLogs,
    examHistory,
    examScores,
    allRealScores,
    quizScores,
    cbtScoresList,
    avgScore100,
    avgQuizOnly,
    gpaScale4,
    activeDaysCount,
    activeDatesList: Array.from(activeDatesSet),
    realReflections,
    myQnaCount,
    myQnaItems,
    baseXP,
    bonusXP,
    totalRealXP,
    rankInfo,
    totalReadSeconds,
    totalReadMinutes,
    totalCardsMastered,
    totalModulesAvailable,
    totalModulesDone,
    totalExamsAvailable,
    totalExamsDone,
    totalOpenExamsNow,
    totalTargetItems,
    totalFinishedItems,
    overallCompletionPct,
    modCompletionPct
  };
}

// Override `renderEduvanceKPICards` agar 4 Widget Informasi 100% menampilkan Data Real Siswa
renderEduvanceKPICards = function() {
  const m = computeRealStudentLearningMetrics();

  // WIDGET 1: RATA-RATA SKOR & INDEKS PRESTASI REAL
  const gpaValEl = document.getElementById('edukpi-gpa-val');
  const gpaScaleEl = document.getElementById('edukpi-gpa-scale');
  const gpaBadgeEl = document.getElementById('edukpi-gpa-badge');
  const gpaBarEl = document.getElementById('edukpi-gpa-bar');
  const gpaSubEl = document.getElementById('edukpi-gpa-sub');

  if (gpaValEl) gpaValEl.innerText = m.allRealScores.length > 0 ? m.avgScore100.toFixed(1) : '0.0';
  if (gpaScaleEl) gpaScaleEl.innerText = `/ 100 (IP ${m.gpaScale4})`;
  if (gpaBadgeEl) {
    gpaBadgeEl.innerText = m.allRealScores.length > 0
      ? (m.avgScore100 >= 85 ? 'PREDIKAT A' : (m.avgScore100 >= 75 ? 'TUNTAS KKM' : 'PERLU REMEDIAL'))
      : 'BELUM ADA NILAI';
  }
  if (gpaBarEl) gpaBarEl.style.width = `${Math.min(100, Math.round(m.avgScore100))}%`;
  if (gpaSubEl) {
    gpaSubEl.innerText = m.allRealScores.length > 0
      ? `Dari ${m.quizScores.length} Kuis LMS & ${m.cbtScoresList.length} Ujian CBT`
      : `Kerjakan kuis modul / ujian untuk melihat nilai`;
  }

  // WIDGET 2: KEAKTIFAN HARI BELAJAR & JURNAL REFLEKSI REAL
  const streakValEl = document.getElementById('edukpi-streak-val');
  const streakBadgeEl = document.getElementById('edukpi-streak-badge');
  const streakBarEl = document.getElementById('edukpi-streak-bar');
  const streakSubEl = document.getElementById('edukpi-streak-sub');

  if (streakValEl) streakValEl.innerText = m.activeDaysCount;
  if (streakBadgeEl) {
    streakBadgeEl.innerText = m.activeDaysCount > 0 ? `${m.historyLogs.length} AKTIVITAS` : 'MULAI HARI INI';
  }
  if (streakBarEl) {
    const targetDaysPct = Math.min(100, Math.round((m.activeDaysCount / 14) * 100));
    streakBarEl.style.width = `${targetDaysPct}%`;
  }
  if (streakSubEl) {
    streakSubEl.innerText = `${m.realReflections.length} Jurnal Refleksi • ${m.myQnaCount} Diskusi QnA`;
  }

  // WIDGET 3: AKUMULASI POIN XP, LEVEL & WAKTU EKSPLORASI REAL
  const hoursValEl = document.getElementById('edukpi-hours-val');
  const hoursBadgeEl = document.getElementById('edukpi-hours-badge');
  const hoursBarEl = document.getElementById('edukpi-hours-bar');
  const hoursSubEl = document.getElementById('edukpi-hours-sub');

  if (hoursValEl) hoursValEl.innerText = m.totalRealXP.toLocaleString('id-ID');
  if (hoursBadgeEl) hoursBadgeEl.innerText = `LV.${m.rankInfo.current.level} ${m.rankInfo.current.title.toUpperCase()}`;
  if (hoursBarEl) hoursBarEl.style.width = `${m.rankInfo.pctToNext || 0}%`;
  if (hoursSubEl) {
    const readText = m.totalReadMinutes > 0 ? `${m.totalReadMinutes} mnt baca` : `${m.totalReadSeconds} dtk baca`;
    hoursSubEl.innerText = `${readText} • ${m.totalCardsMastered} Kartu 3D hafal`;
  }

  // WIDGET 4: KETUNTASAN MODUL LMS & UJIAN CBT REAL
  const compValEl = document.getElementById('edukpi-completed-val');
  const compBadgeEl = document.getElementById('edukpi-completed-badge');
  const compBarEl = document.getElementById('edukpi-completed-bar');
  const compSubEl = document.getElementById('edukpi-completed-sub');

  if (compValEl) compValEl.innerText = `${m.totalFinishedItems}/${m.totalTargetItems}`;
  if (compBadgeEl) compBadgeEl.innerText = `${m.overallCompletionPct}% TUNTAS`;
  if (compBarEl) compBarEl.style.width = `${m.overallCompletionPct}%`;
  if (compSubEl) {
    compSubEl.innerText = `${m.totalModulesDone}/${m.totalModulesAvailable} Modul LMS • ${m.totalExamsDone}/${m.totalExamsAvailable} CBT`;
  }

  // Sinkronkan sub-teks banner sapaan & lencana menu Ujian Akhir (CBT) dengan data real
  const pendingModsCount = Math.max(0, m.totalModulesAvailable - m.totalModulesDone);
  if (document.getElementById('eduvance-greeting-sub')) {
    document.getElementById('eduvance-greeting-sub').innerHTML =
      `Rekap Real-Time: <b>${m.totalModulesDone}/${m.totalModulesAvailable} modul LMS</b> telah diselesaikan (${pendingModsCount} modul tersisa) dan <b>${m.totalOpenExamsNow} ujian CBT</b> sedang dibuka. Klik salah satu dari 4 kartu di bawah untuk melihat rincian rekapmu!`;
  }
  if (document.getElementById('edunav-badge-due')) {
    document.getElementById('edunav-badge-due').innerText = m.totalOpenExamsNow > 0 ? `${m.totalOpenExamsNow} terbuka` : `${m.totalExamsDone}/${m.totalExamsAvailable} selesai`;
  }
};

// Override `renderEduvanceSidebarAndHeader` & `renderEduvanceCourseDonuts` agar persentase per mata pelajaran 100% REAL (tidak ada angka palsu 15% atau 25%)
const _v27RenderEduvanceSidebarAndHeader = renderEduvanceSidebarAndHeader;
renderEduvanceSidebarAndHeader = function() {
  _v27RenderEduvanceSidebarAndHeader();
  const m = computeRealStudentLearningMetrics();

  if (document.getElementById('eduvance-sidebar-streak-num')) {
    document.getElementById('eduvance-sidebar-streak-num').innerText = m.activeDaysCount;
  }
  if (document.getElementById('eduvance-sidebar-level-num')) {
    document.getElementById('eduvance-sidebar-level-num').innerText = m.rankInfo.current.level;
  }
  if (document.getElementById('eduvance-greeting-streak-pill')) {
    document.getElementById('eduvance-greeting-streak-pill').innerText =
      m.activeDaysCount > 0
        ? `🔥 TERCATAT AKTIF BELAJAR ${m.activeDaysCount} HARI (${m.totalRealXP} XP)`
        : `🌱 MULAI EKSPLORASI MODUL PERTAMAMU HARI INI!`;
  }

  const enrolledBox = document.getElementById('eduvance-sidebar-enrolled');
  if (enrolledBox) {
    const barColors = ['#fbbf24', '#38bdf8', '#fbbf24', '#f472b6', '#a78bfa', '#fb923c'];
    const icons = ['fa-calculator', 'fa-flask', 'fa-book-open', 'fa-earth-asia', 'fa-language', 'fa-laptop-code'];
    enrolledBox.innerHTML = m.subjs.map((s, idx) => {
      const totMod = Number(s.totalModules) || (s.modules ? s.modules.length : 0);
      const doneMod = Number(s.completedModules) || 0;
      const isExamDone = m.examHistory[s.name] !== undefined;
      // Persentase Murni Real: Jika ada modul LMS, hitung doneMod/totMod; jika belum ada modul di sheet, cek apakah ujian CBT sudah selesai (100% atau 0%)
      const realPct = totMod > 0 ? Math.min(100, Math.round((doneMod / totMod) * 100)) : (isExamDone ? 100 : 0);
      const col = barColors[idx % barColors.length];
      const ic = icons[idx % icons.length];
      const safeName = s.name.replace(/'/g, "\\'");
      const statusSubText = totMod > 0 ? `${doneMod}/${totMod} modul (${realPct}%)` : (isExamDone ? 'Ujian Selesai (100%)' : '0% selesai');
      return `
        <div class="eduvance-enrolled-item" onclick="openStudentLMS('${safeName}')" title="${escapeHtml(s.name)}: ${statusSubText}">
          <div class="eduvance-enrolled-left">
            <div class="eduvance-enrolled-icon" style="color:${col};"><i class="fa-solid ${ic}"></i></div>
            <div style="min-width:0; flex:1;">
              <div class="eduvance-enrolled-name">${escapeHtml(s.name)}</div>
              <div class="eduvance-enrolled-pct">${statusSubText}</div>
            </div>
          </div>
          <div class="eduvance-enrolled-mini-bar">
            <div class="eduvance-enrolled-mini-fill" style="width:${realPct}%; background:${col};"></div>
          </div>
        </div>`;
    }).join('');
  }
};

renderEduvanceCourseDonuts = function() {
  const grid = document.getElementById('eduvance-course-donut-grid');
  if (!grid) return;
  const kw = (document.getElementById('studentSearchMapel')?.value || '').toLowerCase().trim();
  const subjs = (globalLMSDashboard.subjects || []).filter(s => !kw || s.name.toLowerCase().includes(kw));

  if (document.getElementById('eduvance-course-progress-sub')) {
    document.getElementById('eduvance-course-progress-sub').innerText = `Semester Aktif • ${subjs.length} Mata Pelajaran Terdaftar`;
  }

  if (subjs.length === 0) {
    grid.innerHTML = `<div style="grid-column:1/-1; text-align:center; padding:30px; color:#64748b;">Tidak ada mata pelajaran yang cocok dengan pencarian.</div>`;
    return;
  }

  const ringColors = ['#064e3b', '#0284c7', '#059669', '#059669', '#7c3aed', '#e11d48'];
  const icons = ['fa-calculator', 'fa-flask-vial', 'fa-book-open-reader', 'fa-earth-asia', 'fa-laptop-code', 'fa-language'];
  const radius = 38;
  const circum = 2 * Math.PI * radius;

  grid.innerHTML = subjs.slice(0, 6).map((s, idx) => {
    const tot = Number(s.totalModules) || (s.modules ? s.modules.length : 0);
    const done = Number(s.completedModules) || 0;
    const isExamDone = globalLMSDashboard.examHistoryMap && globalLMSDashboard.examHistoryMap[s.name] !== undefined;
    const pct = tot > 0 ? Math.min(100, Math.round((done / tot) * 100)) : (isExamDone ? 100 : 0);
    const offset = circum - (pct / 100) * circum;
    const color = ringColors[idx % ringColors.length];
    const icon = icons[idx % icons.length];
    const safeName = s.name.replace(/'/g, "\\'");

    return `
      <div class="eduvance-donut-item" onclick="openStudentLMS('${safeName}')" title="Klik untuk membuka Ruang Belajar ${escapeHtml(s.name)}">
        <div class="eduvance-donut-svg-wrap">
          <svg viewBox="0 0 96 96">
            <circle cx="48" cy="48" r="${radius}" fill="none" stroke="#fef3c7" stroke-width="10"></circle>
            <circle cx="48" cy="48" r="${radius}" fill="none" stroke="${color}" stroke-width="10"
              stroke-dasharray="${circum.toFixed(1)}" stroke-dashoffset="${offset.toFixed(1)}" stroke-linecap="round"></circle>
          </svg>
          <div class="eduvance-donut-center">
            <i class="fa-solid ${icon}" style="color:${color};"></i>
            <span class="eduvance-donut-pct">${pct}%</span>
          </div>
        </div>
        <div class="eduvance-donut-name">${escapeHtml(s.name)}</div>
        <div class="eduvance-donut-meta">${done}/${tot} Modul • ${isExamDone ? 'CBT ✓' : 'CBT Belum'}</div>
      </div>`;
  }).join('');
};

// Modal Rincian Real-Time saat salah satu dari 4 Widget Informasi diklik oleh Siswa
function openRealWidgetRekapModal(widgetType) {
  playStudentSFX('click');
  const m = computeRealStudentLearningMetrics();

  let titleHtml = '';
  let bodyHtml = '';

  if (widgetType === 'nilai') {
    titleHtml = '<i class="fa-solid fa-graduation-cap" style="color:#059669;"></i> Rekap Real-Time Nilai Kuis LMS & Ujian CBT';
    const quizRows = m.completedList.map((c, i) => `
      <tr>
        <td style="padding:8px 10px; border-bottom:1px solid #e2e8f0; font-weight:700;">${i + 1}. ${escapeHtml(c.mapel || '-')}</td>
        <td style="padding:8px 10px; border-bottom:1px solid #e2e8f0;">${escapeHtml(c.judulModul || c.idModul || '-')}</td>
        <td style="padding:8px 10px; border-bottom:1px solid #e2e8f0; text-align:center;"><span style="background:#d1fae5; color:#059669; padding:3px 9px; border-radius:99px; font-weight:900;">${c.skor}/100</span></td>
      </tr>`).join('');

    const cbtRows = Object.keys(m.examHistory).map((mp, i) => {
      const sc = m.examScores[mp] !== undefined ? `${m.examScores[mp]}/100` : 'Terekam di Server';
      const dt = new Date(m.examHistory[mp]);
      const dtStr = isNaN(dt) ? '-' : dt.toLocaleDateString('id-ID', { day: '2-digit', month: 'short', year: 'numeric' });
      return `
        <tr>
          <td style="padding:8px 10px; border-bottom:1px solid #e2e8f0; font-weight:700;">${i + 1}. ${escapeHtml(mp)}</td>
          <td style="padding:8px 10px; border-bottom:1px solid #e2e8f0;">Ujian Akhir CBT (${dtStr})</td>
          <td style="padding:8px 10px; border-bottom:1px solid #e2e8f0; text-align:center;"><span style="background:#dbeafe; color:#1d4ed8; padding:3px 9px; border-radius:99px; font-weight:900;">${sc}</span></td>
        </tr>`;
    }).join('');

    bodyHtml = `
      <div style="text-align:left; font-size:13px; line-height:1.55;">
        <div style="display:grid; grid-template-columns:repeat(3, 1fr); gap:10px; margin-bottom:14px;">
          <div style="background:#ecfdf5; border:1px solid #a7f3d0; padding:10px; border-radius:12px; text-align:center;">
            <div style="font-size:10px; font-weight:800; color:#047857;">RATA-RATA GABUNGAN</div>
            <div style="font-size:20px; font-weight:900; color:#064e3b;">${m.avgScore100.toFixed(1)}</div>
          </div>
          <div style="background:#fffbeb; border:1px solid #a7f3d0; padding:10px; border-radius:12px; text-align:center;">
            <div style="font-size:10px; font-weight:800; color:#059669;">INDEKS PRESTASI (4.00)</div>
            <div style="font-size:20px; font-weight:900; color:#059669;">${m.gpaScale4}</div>
          </div>
          <div style="background:#eff6ff; border:1px solid #bfdbfe; padding:10px; border-radius:12px; text-align:center;">
            <div style="font-size:10px; font-weight:800; color:#1d4ed8;">TOTAL EVALUASI</div>
            <div style="font-size:20px; font-weight:900; color:#1e3a8a;">${m.allRealScores.length} Sesi</div>
          </div>
        </div>
        <div style="max-height:280px; overflow-y:auto; border:1px solid #e2e8f0; border-radius:12px;">
          <table style="width:100%; border-collapse:collapse; font-size:12.5px;">
            <thead>
              <tr style="background:#064e3b; color:white;">
                <th style="padding:9px 10px; text-align:left;">Mata Pelajaran</th>
                <th style="padding:9px 10px; text-align:left;">Modul LMS / Ujian CBT</th>
                <th style="padding:9px 10px; text-align:center;">Skor Real</th>
              </tr>
            </thead>
            <tbody>
              ${quizRows || ''}
              ${cbtRows || ''}
              ${(!quizRows && !cbtRows) ? `<tr><td colspan="3" style="padding:24px; text-align:center; color:#64748b;">Belum ada nilai kuis modul LMS maupun ujian CBT yang tercatat untuk akunmu.</td></tr>` : ''}
            </tbody>
          </table>
        </div>
      </div>`;
  } else if (widgetType === 'keaktifan') {
    titleHtml = '<i class="fa-solid fa-fire-flame-curved" style="color:#059669;"></i> Rekap Real-Time Keaktifan Belajar & Jurnal Refleksi';
    const reflItems = m.realReflections.map((r, i) => `
      <div style="background:#f8fafc; border:1px solid #e2e8f0; border-left:4px solid #10b981; border-radius:10px; padding:10px 12px; margin-bottom:8px;">
        <div style="font-size:11px; font-weight:800; color:#047857;">${i + 1}. ${escapeHtml(r.mapel)} — ${escapeHtml(r.judulModul)} (${escapeHtml(r.waktu || '-')})</div>
        <div style="font-size:12.5px; color:#334155; font-style:italic; margin-top:3px;">"${escapeHtml(r.refleksi)}"</div>
      </div>`).join('') || '<div style="padding:16px; text-align:center; color:#64748b; background:#f8fafc; border-radius:10px;">Belum ada jurnal refleksi yang kamu tulis pada Tahap 4 modul LMS.</div>';

    bodyHtml = `
      <div style="text-align:left; font-size:13px; line-height:1.55;">
        <div style="display:grid; grid-template-columns:repeat(3, 1fr); gap:10px; margin-bottom:14px;">
          <div style="background:#fef3c7; border:1px solid #fde68a; padding:10px; border-radius:12px; text-align:center;">
            <div style="font-size:10px; font-weight:800; color:#047857;">HARI AKTIF TERCATAT</div>
            <div style="font-size:20px; font-weight:900; color:#065f46;">${m.activeDaysCount} Hari</div>
          </div>
          <div style="background:#ecfdf5; border:1px solid #a7f3d0; padding:10px; border-radius:12px; text-align:center;">
            <div style="font-size:10px; font-weight:800; color:#047857;">JURNAL REFLEKSI</div>
            <div style="font-size:20px; font-weight:900; color:#065f46;">${m.realReflections.length} Bab</div>
          </div>
          <div style="background:#f3e8ff; border:1px solid #ddd6fe; padding:10px; border-radius:12px; text-align:center;">
            <div style="font-size:10px; font-weight:800; color:#6d28d9;">DISKUSI QnA GURU</div>
            <div style="font-size:20px; font-weight:900; color:#5b21b6;">${m.myQnaCount} Tanya</div>
          </div>
        </div>
        <div style="font-size:12px; font-weight:800; color:#064e3b; margin-bottom:6px;">Daftar Jurnal Refleksi Pemahamanmu:</div>
        <div style="max-height:240px; overflow-y:auto; padding-right:4px;">${reflItems}</div>
      </div>`;
  } else if (widgetType === 'xp') {
    titleHtml = '<i class="fa-solid fa-bolt" style="color:#0284c7;"></i> Rincian Poin XP, Level & Eksplorasi Materi Real';
    bodyHtml = `
      <div style="text-align:left; font-size:13px; line-height:1.6;">
        <div style="background:linear-gradient(135deg, #064e3b, #059669); color:white; padding:16px 18px; border-radius:16px; margin-bottom:14px;">
          <div style="font-size:11px; font-weight:800; color:#6ee7b7; text-transform:uppercase;">GELAR LEVEL SAAT INI</div>
          <div style="font-size:21px; font-weight:900; margin-top:2px;">Level ${m.rankInfo.current.level}: ${m.rankInfo.current.title} (${m.totalRealXP} XP)</div>
          <div style="font-size:12px; color:#d1fae5; margin-top:4px;">${m.rankInfo.xpNeededText || ''}</div>
        </div>
        <div style="display:grid; grid-template-columns:1fr 1fr; gap:10px;">
          <div style="background:#f8fafc; border:1px solid #e2e8f0; padding:12px; border-radius:12px;">
            <div style="font-size:11px; font-weight:800; color:#64748b;">XP PENYELESAIAN MODUL (SERVER)</div>
            <div style="font-size:18px; font-weight:900; color:#064e3b; margin-top:2px;">+${m.baseXP} XP</div>
          </div>
          <div style="background:#f8fafc; border:1px solid #e2e8f0; padding:12px; border-radius:12px;">
            <div style="font-size:11px; font-weight:800; color:#64748b;">XP AKTIVITAS &amp; VERIFIKASI AI</div>
            <div style="font-size:18px; font-weight:900; color:#0284c7; margin-top:2px;">+${m.bonusXP} XP</div>
          </div>
          <div style="background:#f8fafc; border:1px solid #e2e8f0; padding:12px; border-radius:12px;">
            <div style="font-size:11px; font-weight:800; color:#64748b;">DURASI BACA MATERI AKTIF</div>
            <div style="font-size:18px; font-weight:900; color:#059669; margin-top:2px;">${m.totalReadMinutes} Menit (${m.totalReadSeconds} dtk)</div>
          </div>
          <div style="background:#f8fafc; border:1px solid #e2e8f0; padding:12px; border-radius:12px;">
            <div style="font-size:11px; font-weight:800; color:#64748b;">KARTU PINTAR 3D DIKUASAI</div>
            <div style="font-size:18px; font-weight:900; color:#7c3aed; margin-top:2px;">${m.totalCardsMastered} Kartu Hafal</div>
          </div>
        </div>
      </div>`;
  } else {
    titleHtml = '<i class="fa-solid fa-list-check" style="color:#059669;"></i> Rekap Ketuntasan Modul LMS & Ujian CBT per Mapel';
    const subjRows = m.subjs.map((s, idx) => {
      const tot = Number(s.totalModules) || (s.modules ? s.modules.length : 0);
      const done = Number(s.completedModules) || 0;
      const isExDone = m.examHistory[s.name] !== undefined;
      return `
        <tr>
          <td style="padding:8px 10px; border-bottom:1px solid #e2e8f0; font-weight:700;">${idx + 1}. ${escapeHtml(s.name)}</td>
          <td style="padding:8px 10px; border-bottom:1px solid #e2e8f0; text-align:center; font-weight:800; color:${done >= tot && tot > 0 ? '#059669' : '#064e3b'};">${done} / ${tot} Bab</td>
          <td style="padding:8px 10px; border-bottom:1px solid #e2e8f0; text-align:center;">
            <span style="padding:3px 9px; border-radius:99px; font-size:11px; font-weight:800; background:${isExDone ? '#d1fae5' : (s.examStatus === 'AKTIF' ? '#fef3c7' : '#f1f5f9')}; color:${isExDone ? '#059669' : (s.examStatus === 'AKTIF' ? '#047857' : '#64748b')};">
              ${isExDone ? '✓ Selesai' : (s.examStatus === 'AKTIF' ? 'Terbuka' : 'Tutup')}
            </span>
          </td>
        </tr>`;
    }).join('');

    bodyHtml = `
      <div style="text-align:left; font-size:13px;">
        <div style="margin-bottom:12px; font-weight:700; color:#475569;">
          Total Ketuntasan Keseluruhan: <b style="color:#059669;">${m.totalFinishedItems} dari ${m.totalTargetItems} item (${m.overallCompletionPct}%)</b>
        </div>
        <div style="max-height:300px; overflow-y:auto; border:1px solid #e2e8f0; border-radius:12px;">
          <table style="width:100%; border-collapse:collapse; font-size:12.5px;">
            <thead>
              <tr style="background:#064e3b; color:white;">
                <th style="padding:9px 10px; text-align:left;">Mata Pelajaran</th>
                <th style="padding:9px 10px; text-align:center;">Modul LMS</th>
                <th style="padding:9px 10px; text-align:center;">Ujian CBT</th>
              </tr>
            </thead>
            <tbody>${subjRows}</tbody>
          </table>
        </div>
      </div>`;
  }

  Swal.fire({
    title: titleHtml,
    width: '650px',
    html: bodyHtml,
    confirmButtonText: 'Tutup Rekap',
    customClass: { popup: 'swal-custom-popup', confirmButton: 'swal-custom-confirm' }
  });
}


