// =========================================================================
// 28. PEMBARUAN V31:
//     - SINKRONISASI EKSPLISIT SOLID BOTTOM MENU BAR LMS (`#lms-fluid-dock`)
//       DI SMARTPHONE ANDROID, IPHONE, TABLET & DESKTOP AGAR MUNCUL OTOMATIS
//       BEGITU MEMBUKA MODUL LMS DAN TERTUTUP SAAT KEMBALI KE DASHBOARD/UJIAN
// =========================================================================

function syncLMSBottomDockVisibilityV31() {
  const lmsSec = document.getElementById('lms-learning-section');
  const examSec = document.getElementById('exam-section');
  const lmsDock = document.getElementById('lms-fluid-dock');
  const mobDashNav = document.getElementById('eduvance-mobile-bottom-nav');

  const isLmsActive = lmsSec && !lmsSec.classList.contains('hidden');
  const isExamOpen = examSec && !examSec.classList.contains('hidden');

  if (lmsDock) {
    if (isLmsActive && !isExamOpen) {
      lmsDock.classList.remove('hidden');
      lmsDock.style.display = 'flex';
    } else {
      lmsDock.classList.add('hidden');
      lmsDock.style.display = 'none';
    }
  }

  if (mobDashNav) {
    if (isLmsActive || isExamOpen) {
      mobDashNav.style.display = 'none';
    } else {
      mobDashNav.style.display = '';
    }
  }
}

const _v30OpenStudentLMS = openStudentLMS;
openStudentLMS = function(mapelName) {
  _v30OpenStudentLMS(mapelName);
  syncLMSBottomDockVisibilityV31();
};

const _v30KembaliKeDashboardSiswa = kembaliKeDashboardSiswa;
kembaliKeDashboardSiswa = function() {
  _v30KembaliKeDashboardSiswa();
  syncLMSBottomDockVisibilityV31();
};

const _v30SwitchEduvanceNav = switchEduvanceNav;
switchEduvanceNav = function(navKey) {
  _v30SwitchEduvanceNav(navKey);
  syncLMSBottomDockVisibilityV31();
};

const _v30BersihkanKomponenLMSSebelumUjian = bersihkanKomponenLMSSebelumUjian;
bersihkanKomponenLMSSebelumUjian = function() {
  _v30BersihkanKomponenLMSSebelumUjian();
  const lmsDock = document.getElementById('lms-fluid-dock');
  if (lmsDock) {
    lmsDock.classList.add('hidden');
    lmsDock.style.display = 'none';
  }
};


// =========================================================================
// 29. PEMBARUAN V32:
//     - ISOLASI PENUH ENVIRONMENT UJIAN CBT (PTS/PAS/PAT) DARI SELURUH FITUR & FUNGSI LMS
//     - PENGHAPUSAN DOM DINAMIS MENU BOTTOM BAR 8-ICON LMS (`#lms-fluid-dock`)
//       BESERTA TOMBOL AKSES LMS SAAT MEMASUKI PORTAL UJIAN MAUPUN SESI UJIAN CBT AKTIF
//       AGAR SISWA TIDAK SALAH PENCET DAN 100% FOKUS PADA PELAKSANAAN UJIAN CBT
// =========================================================================

// Simpan referensi template HTML #lms-fluid-dock agar dapat dihapus total dari DOM saat di environment CBT
// dan dipulihkan kembali hanya saat siswa benar-benar membuka modul di Ruang Belajar LMS
let __savedLMSFluidDockNodeV32 = null;

function detachLMSFluidDockFromDOMV32() {
  const dock = document.getElementById('lms-fluid-dock');
  if (dock) {
    __savedLMSFluidDockNodeV32 = dock.cloneNode(true);
    dock.remove(); // Hapus fisik elemen 8-icon bottom bar LMS dari DOM!
  }
}

function restoreLMSFluidDockToDOMV32() {
  if (isExamActive || document.body.classList.contains('cbt-exam-lockdown') || document.body.classList.contains('cbt-portal-environment')) {
    return null;
  }
  let dock = document.getElementById('lms-fluid-dock');
  if (!dock && __savedLMSFluidDockNodeV32) {
    const appWrap = document.getElementById('app-wrapper');
    if (appWrap) {
      dock = __savedLMSFluidDockNodeV32.cloneNode(true);
      appWrap.appendChild(dock);
    }
  }
  return dock;
}

function purgeAllLMSFeaturesAndUIForCBTEnvironmentV32(isFullExamLockdown) {
  // 1. Hentikan narator suara (TTS), timer baca LMS, & tutup seluruh laci/modal LMS
  if ('speechSynthesis' in window) {
    try { window.speechSynthesis.cancel(); } catch (e) {}
  }
  if (typeof isPomodoroRunning !== 'undefined' && isPomodoroRunning && typeof pomodoroInterval !== 'undefined') {
    try {
      clearInterval(pomodoroInterval);
      isPomodoroRunning = false;
    } catch (e) {}
  }

  // 2. Hapus fisik 8-Icon Bottom Bar LMS (#lms-fluid-dock) dari DOM agar mustahil muncul atau terpencet
  detachLMSFluidDockFromDOMV32();

  // 3. Tutup & sembunyikan paksa seluruh laci dan komponen LMS
  ['aiTutorDrawer', 'studentNotesDrawer', 'studentGuideCenterModal', 'studentProfileCenterModal', 'lmsModuleProgressHud', 'eduvance-comfort-popover'].forEach(id => {
    const el = document.getElementById(id);
    if (el) {
      el.classList.remove('open', 'active', 'show');
      if (id === 'eduvance-comfort-popover') el.classList.add('hidden');
    }
  });

  const lmsSec = document.getElementById('lms-learning-section');
  if (lmsSec) {
    lmsSec.classList.add('hidden');
    const ws = document.getElementById('lms-constructive-workspace');
    if (ws && isFullExamLockdown) ws.innerHTML = '';
  }

  document.body.classList.remove('lms-zen-mode', 'lms-native-android-mode');

  if (isFullExamLockdown) {
    document.body.classList.add('cbt-exam-lockdown');
    document.body.classList.remove('cbt-portal-environment');
  }
}

// 1. Override `syncLMSBottomDockVisibilityV31` agar mematuhi sterilisasi penuh Environment Ujian CBT
syncLMSBottomDockVisibilityV31 = function() {
  const lmsSec = document.getElementById('lms-learning-section');
  const examSec = document.getElementById('exam-section');
  const resSec = document.getElementById('result-section');
  const assignView = document.getElementById('eduview-assignments');
  const mobDashNav = document.getElementById('eduvance-mobile-bottom-nav');

  const isLmsActive = lmsSec && !lmsSec.classList.contains('hidden');
  const isExamOpen = (examSec && !examSec.classList.contains('hidden')) || (resSec && !resSec.classList.contains('hidden')) || isExamActive;
  const isCbtPortalOpen = !isLmsActive && !isExamOpen && assignView && !assignView.classList.contains('hidden');

  if (isExamOpen) {
    purgeAllLMSFeaturesAndUIForCBTEnvironmentV32(true);
    if (mobDashNav) mobDashNav.style.display = 'none';
    return;
  }

  document.body.classList.remove('cbt-exam-lockdown');

  if (isCbtPortalOpen) {
    document.body.classList.add('cbt-portal-environment');
    purgeAllLMSFeaturesAndUIForCBTEnvironmentV32(false);
    if (mobDashNav) mobDashNav.style.display = '';
    return;
  }

  document.body.classList.remove('cbt-portal-environment');

  if (isLmsActive) {
    const dock = restoreLMSFluidDockToDOMV32();
    if (dock) {
      dock.classList.remove('hidden');
      dock.style.display = 'flex';
      for (let s = 1; s <= 5; s++) {
        const pill = document.getElementById('dock-step-' + s);
        if (pill) {
          pill.classList.toggle('active', s === activeLMSStep);
          pill.classList.toggle('done-step', s < activeLMSStep);
        }
      }
    }
    if (mobDashNav) mobDashNav.style.display = 'none';
  } else {
    detachLMSFluidDockFromDOMV32();
    if (mobDashNav) mobDashNav.style.display = '';
  }
};

// 2. Blokir Seluruh Fungsi LMS (openStudentLMS, AI Tutor, Catatan Pintar, Peta Konsep, Narator) selama Environment Ujian CBT Aktif
