// 4. Pastikan di Portal Ujian CBT (`#eduview-assignments`):
//    - Tabel & Daftar Jadwal HANYA menampilkan Sesi Ujian CBT (100% Tanpa Item Modul LMS & Tanpa Tombol "Pelajari" LMS!)
//    - Kartu Ujian yang belum dibuka tidak mengarahkan siswa ke LMS
buildEduvanceAssignmentsDataset = function() {
  const subjs = globalLMSDashboard.subjects || [];
  const examHistory = globalLMSDashboard.examHistoryMap || {};
  const examScores = globalLMSDashboard.examScoresMap || {};
  const kw = (document.getElementById('studentSearchMapel')?.value || '').toLowerCase().trim();
  const modeFilter = document.getElementById('eduvance-assign-filter')?.value || 'CBT';

  let items = [];
  subjs.forEach(s => {
    const safeName = s.name.replace(/'/g, "\\'");
    const isExDone = examHistory[s.name] !== undefined;
    const isExOpen = s.examStatus === 'AKTIF';
    const scoreVal = examScores[s.name];
    const hasNumScore = scoreVal !== undefined && scoreVal !== null && !isNaN(Number(scoreVal));

    items.push({
      type: 'CBT',
      priority: (!isExDone && isExOpen) ? 0 : (isExDone ? 2 : 1),
      icon: isExDone ? '✅' : (isExOpen ? '🔥' : '🔒'),
      title: `Ujian Resmi CBT (PTS/PAS/PAT) — ${s.name}`,
      subtitle: `${s.totalSoalUjian || 25} Butir Soal AKM & HOTS • 70 Menit • Fullscreen Anti-Cheat`,
      course: s.name,
      dueText: isExDone ? 'Sudah Dikumpulkan' : (isExOpen ? 'Ujian Terbuka — Kerjakan Sekarang' : 'Menunggu Jadwal Pengawas'),
      dueClass: isExDone ? 'due-done' : (isExOpen ? 'due-urgent' : 'due-soon'),
      scoreMain: isExDone ? (hasNumScore ? `${scoreVal}` : 'Terekam') : '—',
      scoreSub: isExDone ? 'Tersimpan di Server' : (isExOpen ? 'Siap Dikerjakan' : 'Belum Dibuka'),
      statusHtml: isExDone
        ? `<span style="color:#059669; font-weight:800;"><i class="fa-solid fa-check-double"></i> Terverifikasi</span>`
        : (isExOpen
          ? `<span style="color:#e11d48; font-weight:800;"><i class="fa-solid fa-unlock"></i> Sesi Terbuka</span>`
          : `<span style="color:#64748b; font-weight:800;"><i class="fa-solid fa-lock"></i> Ditutup</span>`),
      isDone: isExDone,
      isUrgent: (!isExDone && isExOpen),
      action: isExDone
        ? `Swal.fire({icon:'success', title:'Ujian Telah Diselesaikan', text:'Jawaban ujian ${safeName} Anda sudah tercatat dengan aman di database server.', customClass:{popup:'swal-custom-popup', confirmButton:'swal-custom-confirm'}})`
        : (isExOpen
          ? `startExam('${safeName}')`
          : `Swal.fire({icon:'info', title:'Sesi Ujian Belum Dibuka', text:'Sesi ujian CBT untuk mata pelajaran ${safeName} saat ini belum dibuka oleh Pengawas Ruangan.', customClass:{popup:'swal-custom-popup', confirmButton:'swal-custom-confirm'}})`),
      btnLabel: isExDone ? 'Selesai ✓' : (isExOpen ? 'Mulai Ujian' : 'Terkunci')
    });
  });

  items = items.filter(it => {
    if (modeFilter === 'PENDING' && it.isDone) return false;
    if (modeFilter === 'GRADED' && !it.isDone) return false;
    if (kw && !it.title.toLowerCase().includes(kw) && !it.course.toLowerCase().includes(kw)) return false;
    return true;
  });

  items.sort((a, b) => a.priority - b.priority);
  return items;
};

// Pastikan Kartu Ujian CBT Mandiri di `#cbt-standalone-exam-grid` juga steril dari ajakan membuka LMS
const _v31RenderStudentSubjectCards = renderStudentSubjectCards;
renderStudentSubjectCards = function() {
  _v31RenderStudentSubjectCards();
  const cbtGrid = document.getElementById('cbt-standalone-exam-grid');
  if (!cbtGrid) return;

  const searchKw = (document.getElementById('studentSearchMapel')?.value || '').toLowerCase().trim();
  const subjects = (globalLMSDashboard.subjects || []).filter(s => !searchKw || s.name.toLowerCase().includes(searchKw));
  const historyMap = globalLMSDashboard.examHistoryMap || {};
  if (subjects.length === 0) return;

  cbtGrid.innerHTML = subjects.map(subObj => {
    const safeSubName = subObj.name.replace(/'/g, "\\'");
    const isExamCompleted = historyMap[subObj.name] !== undefined;
    const isExamOpen = (subObj.examStatus === 'AKTIF');

    let statusBadgeHtml = '';
    let actionBtnHtml = '';
    if (isExamCompleted) {
      const submitDate = new Date(historyMap[subObj.name]);
      const dateStr = isNaN(submitDate) ? 'Terekam' : submitDate.toLocaleDateString('id-ID', { day: 'numeric', month: 'short', year: 'numeric' });
      statusBadgeHtml = `<span style="background:#d1fae5; color:#059669; padding:5px 12px; border-radius:99px; font-size:11px; font-weight:800;"><i class="fa-solid fa-circle-check"></i> Selesai (${dateStr})</span>`;
      actionBtnHtml = `<button type="button" class="btn-lms-action" style="width:100%; background:#f1f5f9; color:#059669; border:1.5px solid #a7f3d0;" onclick="Swal.fire({icon:'success', title:'Ujian Telah Diselesaikan', text:'Jawaban ujian akhir ${safeSubName} sudah tersimpan di server.', customClass:{popup:'swal-custom-popup', confirmButton:'swal-custom-confirm'}})"><i class="fa-solid fa-check-double"></i> Jawaban Sudah Terkirim</button>`;
    } else if (isExamOpen) {
      statusBadgeHtml = `<span style="background:#fef3c7; color:#047857; padding:5px 12px; border-radius:99px; font-size:11px; font-weight:900; border:1px solid #fde68a;"><i class="fa-solid fa-unlock"></i> Ujian Terbuka</span>`;
      actionBtnHtml = `<button type="button" class="btn-lms-action" style="width:100%; background:linear-gradient(135deg, #059669, #047857); color:white; border:none; box-shadow:0 6px 16px rgba(5, 150, 105,0.25);" onclick="startExam('${safeSubName}')"><i class="fa-solid fa-file-signature"></i> Mulai Kerjakan Ujian CBT</button>`;
    } else {
      statusBadgeHtml = `<span style="background:#f1f5f9; color:#64748b; padding:5px 12px; border-radius:99px; font-size:11px; font-weight:800;"><i class="fa-solid fa-lock"></i> Belum Dibuka</span>`;
      actionBtnHtml = `<button type="button" class="btn-lms-action" style="width:100%; background:#f8fafc; color:#94a3b8; border:1.5px solid #e2e8f0;" onclick="Swal.fire({icon:'info', title:'Sesi Ujian Belum Dibuka', text:'Sesi ujian CBT (PTS/PAS/PAT) untuk mata pelajaran ${safeSubName} saat ini masih dikunci oleh Pengawas Ruangan.', customClass:{popup:'swal-custom-popup', confirmButton:'swal-custom-confirm'}})"><i class="fa-solid fa-lock"></i> Menunggu Dibuka Pengawas</button>`;
    }

    return `
      <div class="lms-subject-card" style="border-color:${isExamOpen && !isExamCompleted ? '#10b981' : '#e2e8f0'};">
        <div style="padding:20px 22px; background:${isExamOpen && !isExamCompleted ? '#ecfdf5' : '#f8fafc'}; border-bottom:1.5px solid #e2e8f0; display:flex; flex-direction:column; gap:10px;">
          <div style="display:flex; justify-content:space-between; align-items:center; gap:8px;">
            <span style="font-size:11px; font-weight:800; color:#064e3b; text-transform:uppercase;"><i class="fa-solid fa-shield-halved"></i> ASESMEN CBT RESMI (70 MENIT)</span>
            ${statusBadgeHtml}
          </div>
          <h4 style="font-size:18.5px; font-weight:800; color:var(--text-main); line-height:1.3;">${escapeHtml(subObj.name)}</h4>
          <div style="font-size:12px; color:#64748b; font-weight:600;">
            <i class="fa-solid fa-list-ol" style="color:#059669;"></i> ${subObj.totalSoalUjian || 25} Butir Soal AKM &amp; HOTS &bull; Fullscreen Anti-Cheat
          </div>
        </div>
        <div class="lms-subject-body" style="padding:16px 22px;">
          ${actionBtnHtml}
        </div>
      </div>`;
  }).join('');
};

