// =========================================================================
// 30. PEMBARUAN V33:
//     - PENGEMASAN TAMPILAN HUB KATALOG MODUL / BAB BERUKURAN BESAR SAAT MEMBUKA
//       MODUL RUANG BELAJAR PADA DASHBOARD LMS (TERINSPIRASI GAMBAR LAMPIRAN)
//     - SETIAP MODUL/BAB MEMILIKI KARTU BESAR DENGAN HEADER PILL BERWARNA UNIK,
//       CHIP KOMPONEN, 5 TOMBOL PINTAS TAHAP INTERAKTIF, NAMA PENYUSUN (AUTHOR),
//       PROGRESS BAR REAL-TIME, PANEL VISUAL AKTIVITAS & REKOMENDASI TAHAP
//     - TRANSISI MULUS ANTARA HUB DAFTAR MODUL/BAB & RUANG BACA 5 TAHAP
// =========================================================================

let currentSubjectModulesHubFilterV33 = 'ALL';
let activeLMSModuleIndexV33 = 0;

function computeSingleModuleProgressV33(mod) {
  if (!mod) return { pct: 0, isDone: false, stepsDoneCount: 0, stepStates: [false, false, false, false, false], rec: null };
  const completedMap = globalLMSDashboard.completedMap || {};
  const rec = completedMap[mod.id] || null;
  const isDone = rec !== null && rec !== undefined;
  const ver = typeof getModuleVerificationStatusV15 === 'function'
    ? getModuleVerificationStatusV15(mod)
    : { readOk: false, subOk: false, cardsOk: false, reflOk: false, noteOk: false };

  const s1 = isDone || ver.readOk || ver.subOk;
  const s2 = isDone || (ver.readOk && ver.subOk);
  const s3 = isDone || ver.cardsOk;
  const s4 = isDone || ver.reflOk;
  const s5 = isDone;

  const stepStates = [!!s1, !!s2, !!s3, !!s4, !!s5];
  const stepsDoneCount = stepStates.filter(Boolean).length;
  const pct = isDone ? 100 : Math.min(95, stepsDoneCount * 20);

  return { pct, isDone, stepsDoneCount, stepStates, rec };
}

function setSubjectModulesHubFilterV33(filterKey) {
  if (typeof playStudentSFX === 'function') playStudentSFX('click');
  currentSubjectModulesHubFilterV33 = filterKey || 'ALL';
  const container = document.getElementById('lms-hub-filter-pills');
  if (container) {
    container.querySelectorAll('.lms-hub-filter-btn').forEach(btn => {
      btn.classList.toggle('active', btn.getAttribute('data-filter') === currentSubjectModulesHubFilterV33);
    });
  }
  renderSubjectModulesHubV33();
}

function bukaHubDaftarModulMapelV33() {
  if (typeof playStudentSFX === 'function') playStudentSFX('click');
  if ('speechSynthesis' in window) {
    try { window.speechSynthesis.cancel(); } catch (e) {}
  }
  const hubView = document.getElementById('lms-subject-modules-hub-view');
  const readerView = document.getElementById('lms-module-reader-view');
  if (hubView) hubView.classList.remove('hidden');
  if (readerView) readerView.classList.add('hidden');
  renderSubjectModulesHubV33();
  syncLMSBottomDockVisibilityV31();
  window.scrollTo({ top: 0, behavior: 'smooth' });
}

function masukKeRuangBacaModulV33(modIdx, targetStep) {
  if (typeof playStudentSFX === 'function') playStudentSFX('click');
  const modules = window.currentSubjectModulesList || [];
  if (!modules[modIdx]) modIdx = 0;
  activeLMSModuleIndexV33 = modIdx;

  const hubView = document.getElementById('lms-subject-modules-hub-view');
  const readerView = document.getElementById('lms-module-reader-view');
  if (hubView) hubView.classList.add('hidden');
  if (readerView) readerView.classList.remove('hidden');

  selectStudentLMSModule(modIdx);
  if (targetStep && targetStep >= 1 && targetStep <= 5) {
    switchLMSStep(targetStep);
  }
  renderCompactBabStripInReaderV33();
  syncLMSBottomDockVisibilityV31();
  window.scrollTo({ top: 0, behavior: 'smooth' });
}

function lanjutkanModulUtamaDariHubV33() {
  const modules = window.currentSubjectModulesList || [];
  if (modules.length === 0) return;
  // Cari modul pertama yang belum tuntas 100%, atau buka modul pertama
  let targetIdx = 0;
  for (let i = 0; i < modules.length; i++) {
    const prog = computeSingleModuleProgressV33(modules[i]);
    if (!prog.isDone) {
      targetIdx = i;
      break;
    }
  }
  masukKeRuangBacaModulV33(targetIdx, 1);
}

function renderCompactBabStripInReaderV33() {
  const modules = window.currentSubjectModulesList || [];
  const strip = document.getElementById('lms-reader-compact-bab-strip');
  const totalBadge = document.getElementById('lms-reader-total-bab-badge');
  const babPill = document.getElementById('lms-active-bab-number-pill');

  if (totalBadge) totalBadge.innerText = modules.length;
  if (babPill) babPill.innerText = `MODUL / BAB ${activeLMSModuleIndexV33 + 1} DARI ${modules.length}`;

  if (!strip) return;
  strip.innerHTML = modules.map((mod, idx) => {
    const prog = computeSingleModuleProgressV33(mod);
    const isAct = idx === activeLMSModuleIndexV33;
    return `
      <button type="button" class="lms-reader-bab-pill ${isAct ? 'active' : ''}" onclick="masukKeRuangBacaModulV33(${idx}, 1)" title="${escapeHtml(mod.judul)}">
        <i class="fa-solid ${prog.isDone ? 'fa-circle-check' : 'fa-book-open'}" style="color:${isAct ? '#fbbf24' : (prog.isDone ? '#10b981' : '#059669')};"></i>
        <span>Bab ${idx + 1}: ${escapeHtml(mod.judul.length > 28 ? mod.judul.substring(0, 28) + '...' : mod.judul)}</span>
        <span style="font-size:10px; opacity:0.85;">(${prog.pct}%)</span>
      </button>`;
  }).join('');
}

function renderSubjectModulesHubV33() {
  const mapelName = activeLMSSubject || 'Mata Pelajaran';
  const modules = window.currentSubjectModulesList || [];
  const kw = (document.getElementById('lms-hub-search-input')?.value || '').toLowerCase().trim();

  // 1. Update Hero Banner Mata Pelajaran
  const badgeMapel = document.getElementById('lms-hub-badge-mapel');
  if (badgeMapel) badgeMapel.innerHTML = `<i class="fa-solid fa-book-open-reader"></i> RUANG BELAJAR &bull; ${escapeHtml(mapelName.toUpperCase())}`;

  const badgeModCount = document.getElementById('lms-hub-badge-modcount');
  if (badgeModCount) badgeModCount.innerText = `${modules.length} Modul / Bab Konstruktif Tersedia`;

  const heroTitle = document.getElementById('lms-hub-hero-title');
  if (heroTitle) heroTitle.innerText = `Eksplorasi Modul & Bab ${mapelName}`;

  const heroDesc = document.getElementById('lms-hub-hero-desc');
  if (heroDesc) {
    heroDesc.innerText = `Setiap Modul/Bab ${mapelName} dikemas dalam kartu interaktif berukuran besar agar kamu mudah membedakan topik bahasan, memantau persentase penguasaan 5 tahap, dan melompat langsung ke bagian yang ingin dipelajari.`;
  }

  // Hitung statistik keseluruhan mapel ini
  let doneModsCount = 0;
  let totalScoreSum = 0;
  let totalMapelXP = 0;
  let totalPctSum = 0;
  let firstUnfinishedIdx = 0;
  let foundUnfinished = false;

  modules.forEach((m, idx) => {
    const p = computeSingleModuleProgressV33(m);
    totalPctSum += p.pct;
    if (p.isDone) {
      doneModsCount++;
      totalScoreSum += Number(p.rec?.skor) || 0;
      totalMapelXP += Number(p.rec?.xp) || 0;
    } else if (!foundUnfinished) {
      firstUnfinishedIdx = idx;
      foundUnfinished = true;
    }
  });

  const avgScoreMapel = doneModsCount > 0 ? Math.round(totalScoreSum / doneModsCount) : 0;
  const overallMapelPct = modules.length > 0 ? Math.round(totalPctSum / modules.length) : 0;

  if (document.getElementById('lms-hub-stat-done')) document.getElementById('lms-hub-stat-done').innerText = `${doneModsCount}/${modules.length} Bab`;
  if (document.getElementById('lms-hub-stat-avg')) document.getElementById('lms-hub-stat-avg').innerText = `${avgScoreMapel}/100`;
  if (document.getElementById('lms-hub-stat-xp')) document.getElementById('lms-hub-stat-xp').innerText = `${totalMapelXP} XP`;
  if (document.getElementById('lms-hub-stat-pct')) document.getElementById('lms-hub-stat-pct').innerText = `${overallMapelPct}%`;
  if (document.getElementById('lms-hub-stat-bar')) document.getElementById('lms-hub-stat-bar').style.width = `${overallMapelPct}%`;

  const continueLbl = document.getElementById('lms-hub-btn-continue-label');
  if (continueLbl && modules[firstUnfinishedIdx]) {
    continueLbl.innerText = doneModsCount === modules.length
      ? `Ulas Kembali Bab 1 (${modules[0].judul.substring(0, 22)}...)`
      : `Lanjutkan Bab ${firstUnfinishedIdx + 1}: ${modules[firstUnfinishedIdx].judul.substring(0, 24)}${modules[firstUnfinishedIdx].judul.length > 24 ? '...' : ''}`;
  }

  const counterEl = document.getElementById('lms-module-total-counter');
  if (counterEl) {
    counterEl.innerText = `Menampilkan ${modules.length} Modul / Bab Pembelajaran pada ${mapelName}`;
  }

  // 2. Render Grid Kartu Modul / Bab Berukuran Besar (Terinspirasi Kartu Running Courses di Gambar 2 + Tema Eduvance Gambar 1)
  const pillPalettes = [
    { grad: 'linear-gradient(135deg, #064e3b 0%, #059669 100%)', bar: '#059669', icon: 'fa-book-open-reader', tagBg: '#ecfdf5', tagCol: '#047857' },
    { grad: 'linear-gradient(135deg, #059669 0%, #f59e0b 100%)', bar: '#f59e0b', icon: 'fa-lightbulb', tagBg: '#fef3c7', tagCol: '#047857' },
    { grad: 'linear-gradient(135deg, #4f46e5 0%, #7c3aed 100%)', bar: '#7c3aed', icon: 'fa-compass-drafting', tagBg: '#f3e8ff', tagCol: '#6d28d9' },
    { grad: 'linear-gradient(135deg, #0284c7 0%, #06b6d4 100%)', bar: '#0284c7', icon: 'fa-atom', tagBg: '#e0f2fe', tagCol: '#0369a1' },
    { grad: 'linear-gradient(135deg, #be185d 0%, #ec4899 100%)', bar: '#ec4899', icon: 'fa-rocket', tagBg: '#fce7f3', tagCol: '#be185d' },
    { grad: 'linear-gradient(135deg, #047857 0%, #10b981 100%)', bar: '#10b981', icon: 'fa-microscope', tagBg: '#d1fae5', tagCol: '#065f46' }
  ];

  const selectorBar = document.getElementById('lms-module-selector-bar');
  if (selectorBar) {
    const filteredModules = modules.map((mod, idx) => ({ mod, idx, prog: computeSingleModuleProgressV33(mod) })).filter(item => {
      if (currentSubjectModulesHubFilterV33 === 'DONE' && !item.prog.isDone) return false;
      if (currentSubjectModulesHubFilterV33 === 'PROGRESS' && item.prog.isDone) return false;
      if (kw && !item.mod.judul.toLowerCase().includes(kw) && !(item.mod.tujuan || '').toLowerCase().includes(kw)) return false;
      return true;
    });

    if (filteredModules.length === 0) {
      selectorBar.innerHTML = `
        <div style="grid-column:1/-1; text-align:center; padding:42px 20px; background:#ffffff; border-radius:22px; border:1.5px dashed #cbd5e1; color:#64748b; font-weight:700;">
          <i class="fa-solid fa-folder-open" style="font-size:36px; color:#10b981; margin-bottom:10px; display:block;"></i>
          Tidak ada modul/bab yang cocok dengan filter pencarian ini.
        </div>`;
    } else {
      selectorBar.innerHTML = filteredModules.map(({ mod, idx, prog }) => {
        const pal = pillPalettes[idx % pillPalettes.length];
        const k = mod.konten || {};
        const subCount = (k.eksplorasi && Array.isArray(k.eksplorasi.sub_materi)) ? k.eksplorasi.sub_materi.length : 3;
        const cardCount = Array.isArray(k.kartu_pintar) ? k.kartu_pintar.length : 4;
        const kuisCount = Array.isArray(mod.kuis) ? mod.kuis.length : 3;
        const hasVideo = !!(k.video_interaktif && k.video_interaktif.url_asli);
        const authorName = mod.pembuat || 'Tim Guru SMPN 3 Bangil';

        const statusBadgeText = prog.isDone
          ? `✓ Tuntas (Skor ${prog.rec.skor})`
          : (prog.pct > 0 ? `Sedang Dipelajari (${prog.pct}%)` : '🔓 Siap Dipelajari');

        const stepIcons = [
          { s: 1, ic: 'fa-lightbulb', lbl: 'Pemantik' },
          { s: 2, ic: 'fa-compass', lbl: 'Materi' },
          { s: 3, ic: 'fa-clone', lbl: 'Kartu 3D' },
          { s: 4, ic: 'fa-puzzle-piece', lbl: 'Kasus' },
          { s: 5, ic: 'fa-trophy', lbl: 'Kuis XP' }
        ];

        const miniStepsHtml = stepIcons.map((st, sIdx) => {
          const isStepDone = prog.stepStates[sIdx];
          return `
            <button type="button" class="lms-mini-step-btn ${isStepDone ? 'step-done' : ''}" onclick="event.stopPropagation(); masukKeRuangBacaModulV33(${idx}, ${st.s});" title="Buka Bab ${idx + 1} — Tahap ${st.s}: ${st.lbl}">
              <i class="fa-solid ${isStepDone ? 'fa-circle-check' : st.ic}"></i>
              <span>${st.lbl}</span>
            </button>`;
        }).join('');

        return `
          <div id="btn-sel-mod-${idx}" class="lms-big-module-card ${idx === activeLMSModuleIndexV33 ? 'active-mod-card' : ''}" onclick="masukKeRuangBacaModulV33(${idx}, 1)">
            <div>
              <!-- Header Pill Berwarna Unik (Persis Kartu Kursus di Gambar 2) -->
              <div class="lms-big-mod-pill-banner" style="background: ${pal.grad};">
                <i class="fa-solid ${pal.icon} pill-watermark-icon"></i>
                <span class="lms-big-mod-bab-tag">
                  <i class="fa-solid ${pal.icon}"></i> MODUL / BAB ${idx + 1}
                </span>
                <span class="lms-big-mod-status-badge">${statusBadgeText}</span>
              </div>

              <!-- Judul Besar, Deskripsi Tujuan, & Chip Komponen -->
              <div class="lms-big-mod-body" style="margin-top:14px;">
                <h4 class="lms-big-mod-title">${escapeHtml(mod.judul)}</h4>
                <p class="lms-big-mod-desc">${escapeHtml(mod.tujuan || 'Eksplorasi konsep konstruktif 5 tahap, latihan kartu pintar 3D, studi kasus nyata, dan kuis HOTS.')}</p>

                <div class="lms-big-mod-chips-row">
                  <span class="lms-big-mod-chip"><i class="fa-solid fa-layer-group" style="color:#059669;"></i> ${subCount} Sub-Materi</span>
                  <span class="lms-big-mod-chip"><i class="fa-solid fa-clone" style="color:#7c3aed;"></i> ${cardCount} Kartu 3D</span>
                  <span class="lms-big-mod-chip"><i class="fa-solid fa-bolt" style="color:#059669;"></i> ${kuisCount} Kuis XP</span>
                  ${hasVideo ? `<span class="lms-big-mod-chip" style="background:#fef3c7; border-color:#fde68a; color:#047857;"><i class="fa-solid fa-clapperboard"></i> Studio Video AI</span>` : ''}
                </div>
              </div>
            </div>

            <div>
              <!-- 5 Pintasan Tahap Konstruktif di Dalam Kartu -->
              <div style="font-size:10px; font-weight:800; color:#64748b; text-transform:uppercase; margin-bottom:5px; letter-spacing:0.4px;">
                Lompat Cepat ke 5 Tahap Bab ${idx + 1}:
              </div>
              <div class="lms-big-mod-steps-strip">
                ${miniStepsHtml}
              </div>

              <!-- Footer Penyusun (Author), Progress Bar Berwarna, & Tombol Buka Bab -->
              <div class="lms-big-mod-footer" style="margin-top:12px;">
                <div class="lms-big-mod-author-prog-row">
                  <div class="lms-big-mod-author-box">
                    <div class="author-lbl">Penyusun Modul</div>
                    <div class="author-name">${escapeHtml(authorName)}</div>
                  </div>
                  <div class="lms-big-mod-prog-box">
                    <span class="prog-pct-lbl" style="color:${pal.bar};">${prog.pct}% Tuntas</span>
                    <div class="lms-big-mod-prog-track">
                      <div class="lms-big-mod-prog-fill" style="width:${Math.max(6, prog.pct)}%; background:${pal.bar};"></div>
                    </div>
                  </div>
                </div>

                <button type="button" class="lms-big-mod-cta-btn" style="background:${prog.isDone ? '#059669' : '#064e3b'};" onclick="event.stopPropagation(); masukKeRuangBacaModulV33(${idx}, 1);">
                  <i class="fa-solid ${prog.isDone ? 'fa-rotate-right' : 'fa-book-open-reader'}"></i>
                  <span>${prog.isDone ? `Ulas Kembali Bab ${idx + 1} (Skor ${prog.rec.skor})` : `Buka & Pelajari Modul Bab ${idx + 1}`}</span>
                  <i class="fa-solid fa-arrow-right"></i>
                </button>
              </div>
            </div>
          </div>`;
      }).join('');
    }
  }

  // 3. Render Panel Kiri Bawah: Visualisasi Aktivitas & Peta Ketuntasan 5 Tahap (Seperti Grafik Activity di Gambar 2)
  const actBox = document.getElementById('lms-hub-activity-visual-box');
  if (actBox) {
    const tr = typeof getStudentVerifiedTracker === 'function' ? getStudentVerifiedTracker() : { readTimers: {} };
    const rowsHtml = modules.map((m, idx) => {
      const p = computeSingleModuleProgressV33(m);
      const readSec = tr.readTimers && tr.readTimers[m.id] ? tr.readTimers[m.id] : 0;
      const readMin = Math.round(readSec / 60);
      const pal = pillPalettes[idx % pillPalettes.length];
      return `
        <div style="padding:12px 14px; border-radius:16px; background:#f8fafc; border:1px solid #fde68a; margin-bottom:10px; cursor:pointer; transition:0.2s;" onclick="masukKeRuangBacaModulV33(${idx}, 1)">
          <div style="display:flex; justify-content:space-between; align-items:center; gap:8px; margin-bottom:6px;">
            <span style="font-size:13px; font-weight:800; color:var(--text-main);">Bab ${idx + 1}: ${escapeHtml(m.judul)}</span>
            <span style="font-size:11.5px; font-weight:900; color:${pal.bar};">${p.stepsDoneCount}/5 Tahap (${p.pct}%)</span>
          </div>
          <div style="width:100%; height:9px; background:#e2e8f0; border-radius:99px; overflow:hidden; margin-bottom:6px;">
            <div style="width:${Math.max(5, p.pct)}%; height:100%; background:${pal.grad}; border-radius:99px;"></div>
          </div>
          <div style="display:flex; justify-content:space-between; font-size:11px; color:#64748b; font-weight:600;">
            <span><i class="fa-regular fa-clock" style="color:#059669;"></i> Waktu Eksplorasi: ${readMin > 0 ? readMin + ' menit' : readSec + ' detik'}</span>
            <span>${p.isDone ? `✓ Kuis Tuntas (${p.rec.skor}/100 • +${p.rec.xp} XP)` : 'Klik untuk lanjutkan belajar'}</span>
          </div>
        </div>`;
    }).join('');

    actBox.innerHTML = rowsHtml || `<div style="text-align:center; padding:24px; color:#64748b;">Belum ada aktivitas pada mata pelajaran ini.</div>`;
  }

  // 4. Render Panel Kanan Bawah: Rekomendasi Eksplorasi & Pintasan Cepat Tahapan (Seperti Suggested Courses di Gambar 2)
  const sugBox = document.getElementById('lms-hub-suggested-steps-list');
  if (sugBox) {
    const targetModIdx = firstUnfinishedIdx < modules.length ? firstUnfinishedIdx : 0;
    const targetMod = modules[targetModIdx] || getDefaultConstructiveModule(mapelName);
    const k = targetMod.konten || {};
    const cardsCount = Array.isArray(k.kartu_pintar) ? k.kartu_pintar.length : 4;
    const kuisCount = Array.isArray(targetMod.kuis) ? targetMod.kuis.length : 3;

    const suggestions = [
      {
        thumbBg: 'linear-gradient(135deg, #064e3b, #059669)',
        icon: 'fa-compass',
        category: `BAB ${targetModIdx + 1} • TAHAP 1 & 2`,
        title: `Eksplorasi Konsep & Pemantik: ${targetMod.judul}`,
        meta: 'Bacaan Konstruktif + Narator Suara',
        rating: '★ 5.0',
        sub: '+50 XP Aktif',
        action: `masukKeRuangBacaModulV33(${targetModIdx}, 2)`
      },
      {
        thumbBg: 'linear-gradient(135deg, #6d28d9, #8b5cf6)',
        icon: 'fa-clone',
        category: `BAB ${targetModIdx + 1} • TAHAP 3 (ACTIVE RECALL)`,
        title: `Latihan ${cardsCount} Kartu Pintar 3D Interaktif`,
        meta: 'Balik kartu & tandai istilah penting',
        rating: '★ 4.9',
        sub: '+30 XP Hafalan',
        action: `masukKeRuangBacaModulV33(${targetModIdx}, 3)`
      },
      {
        thumbBg: 'linear-gradient(135deg, #059669, #f59e0b)',
        icon: 'fa-trophy',
        category: `BAB ${targetModIdx + 1} • TAHAP 4 & 5 (EVALUASI HOTS)`,
        title: `Studi Kasus, Verifikasi AI Groq & ${kuisCount} Kuis XP`,
        meta: 'Uji pemahaman & klaim poin XP penuh',
        rating: '★ 5.0',
        sub: '+175 XP Total',
        action: `masukKeRuangBacaModulV33(${targetModIdx}, 5)`
      }
    ];

    sugBox.innerHTML = suggestions.map(s => `
      <div class="lms-suggested-item-card" onclick="${s.action}">
        <div style="display:flex; align-items:center; gap:14px; min-width:0; flex:1;">
          <div class="lms-suggested-thumb" style="background:${s.thumbBg};">
            <i class="fa-solid ${s.icon}"></i>
          </div>
          <div style="min-width:0; flex:1;">
            <div style="font-size:10px; font-weight:900; color:#059669; text-transform:uppercase; letter-spacing:0.4px;">${escapeHtml(s.category)}</div>
            <div style="font-size:14px; font-weight:800; color:var(--text-main); line-height:1.3; margin-top:2px; white-space:nowrap; overflow:hidden; text-overflow:ellipsis;">${escapeHtml(s.title)}</div>
            <div style="display:flex; align-items:center; gap:8px; margin-top:5px; flex-wrap:wrap;">
              <span style="font-size:11px; color:#64748b; font-weight:600;">${escapeHtml(s.meta)}</span>
              <span style="background:#d1fae5; color:#059669; padding:2px 8px; border-radius:99px; font-size:10px; font-weight:800;">${s.sub}</span>
            </div>
          </div>
        </div>
        <div style="text-align:right; flex-shrink:0;">
          <div style="font-size:12px; font-weight:900; color:#059669;">${s.rating}</div>
          <span style="font-size:11px; font-weight:800; color:#064e3b;">Buka &rarr;</span>
        </div>
      </div>`).join('');
  }
}

// 5. Override `openStudentLMS` agar saat siswa mengklik Mata Pelajaran di Dashboard LMS,
//    sistem langsung menampilkan HUB KATALOG MODUL/BAB BERUKURAN BESAR yang tertata rapi dan interaktif!
openStudentLMS = function(mapelName) {
  if (isExamActive || document.body.classList.contains('cbt-exam-lockdown') || document.body.classList.contains('cbt-portal-environment')) {
    if (typeof showStudentToast === 'function') {
      showStudentToast('Fitur LMS dinonaktifkan pada environment Ujian CBT agar kamu fokus penuh pada ujian!', 'warning');
    }
    return;
  }
  if (typeof isSubjectLMSLockedForStudent === 'function' && isSubjectLMSLockedForStudent(mapelName)) {
    showLockedLMSAlertModal(mapelName);
    return;
  }

  ensureNotFullscreenInLMS();
  activeLMSSubject = mapelName;
  document.getElementById('dashboard-section')?.classList.add('hidden');
  document.getElementById('lms-learning-section')?.classList.remove('hidden');

  const badgeEl = document.getElementById('lms-active-mapel-badge');
  if (badgeEl) badgeEl.innerText = mapelName.toUpperCase();

  const subObj = (globalLMSDashboard.subjects || []).find(s => s.name === mapelName);
  const modules = (subObj && subObj.modules && subObj.modules.length > 0)
    ? subObj.modules
    : [getDefaultConstructiveModule(mapelName)];

  window.currentSubjectModulesList = modules;
  activeLMSModuleIndexV33 = 0;
  activeLMSModule = modules[0];
  currentSubjectModulesHubFilterV33 = 'ALL';

  // Reset pencarian & tampilkan Hub Katalog Modul/Bab Besar terlebih dahulu
  const searchInp = document.getElementById('lms-hub-search-input');
  if (searchInp) searchInp.value = '';

  const hubView = document.getElementById('lms-subject-modules-hub-view');
  const readerView = document.getElementById('lms-module-reader-view');
  if (hubView) hubView.classList.remove('hidden');
  if (readerView) readerView.classList.add('hidden');

  renderSubjectModulesHubV33();
  syncAITutorDrawerContent();
  syncLMSBottomDockVisibilityV31();
  window.scrollTo({ top: 0, behavior: 'smooth' });
};

// Pastikan `resumeLastLMSModule` langsung membuka Ruang Baca pada bab & tahap terakhir yang disimpan
resumeLastLMSModule = function(mapelName, modIdx, stepNum) {
  if (typeof playStudentSFX === 'function') playStudentSFX('click');
  openStudentLMS(mapelName);
  setTimeout(() => {
    masukKeRuangBacaModulV33(modIdx || 0, stepNum || 1);
  }, 60);
};

// Perbarui `syncLMSBottomDockVisibilityV31` agar 8-Icon Bottom Bar muncul saat di Ruang Baca Modul,
// sedangkan saat berada di Hub Katalog Modul/Bab di Smartphone, tampilkan 4-Icon Bottom Bar utama
const _v32SyncLMSBottomDockVisibility = syncLMSBottomDockVisibilityV31;
syncLMSBottomDockVisibilityV31 = function() {
  const lmsSec = document.getElementById('lms-learning-section');
  const readerView = document.getElementById('lms-module-reader-view');
  const examSec = document.getElementById('exam-section');
  const resSec = document.getElementById('result-section');
  const assignView = document.getElementById('eduview-assignments');
  const mobDashNav = document.getElementById('eduvance-mobile-bottom-nav');

  const isLmsSectionVisible = lmsSec && !lmsSec.classList.contains('hidden');
  const isReaderActive = isLmsSectionVisible && readerView && !readerView.classList.contains('hidden');
  const isExamOpen = (examSec && !examSec.classList.contains('hidden')) || (resSec && !resSec.classList.contains('hidden')) || isExamActive;
  const isCbtPortalOpen = !isLmsSectionVisible && !isExamOpen && assignView && !assignView.classList.contains('hidden');

  if (isExamOpen || isCbtPortalOpen) {
    _v32SyncLMSBottomDockVisibility();
    return;
  }

  document.body.classList.remove('cbt-exam-lockdown', 'cbt-portal-environment');

  if (isReaderActive) {
    const dock = restoreLMSFluidDockToDOMV32();
    if (dock) {
      dock.classList.remove('hidden');
      dock.style.display = 'flex';
      for (let s = 1; s <= 5; s++) {
        const pill = document.getElementById('dock-step-' + s);
        if (pill) {
          pill.classList.toggle('active', s === activeLMSStep);
          pill.classList.toggle('done-step', s < activeLMSStep);
        }
      }
    }
    if (mobDashNav) mobDashNav.style.display = 'none';
  } else {
    detachLMSFluidDockFromDOMV32();
    if (mobDashNav) mobDashNav.style.display = '';
  }
};




