function unduhRangkumanModulOtomatisTxtV37() {
  if (!activeLMSModule) return;
  const k = activeLMSModule.konten || {};
  const subArr = (k.eksplorasi && Array.isArray(k.eksplorasi.sub_materi)) ? k.eksplorasi.sub_materi : [];
  const cardsArr = Array.isArray(k.kartu_pintar) ? k.kartu_pintar : [];
  let txt = `INTISARI MODUL PEMBELAJARAN SICIBINAGA KELAS 7\r\n`;
  txt += `Mata Pelajaran : ${activeLMSSubject}\r\n`;
  txt += `Judul Modul    : ${activeLMSModule.judul}\r\n`;
  txt += `Tujuan         : ${activeLMSModule.tujuan}\r\n`;
  txt += `====================================================\r\n\r\n`;
  txt += `[A] PEMANTIK KONTEKSTUAL:\r\n${k.pemantik || '-'}\r\n\r\n`;
  txt += `[B] PILAR KONSEP UTAMA:\r\n`;
  subArr.forEach((s, i) => {
    txt += `${i + 1}. ${s.judul_sub}\r\n   Uraian: ${s.uraian}\r\n   Contoh Nyata: ${s.contoh_nyata || '-'}\r\n\r\n`;
  });
  txt += `[C] ISTILAH PENTING (KARTU PINTAR 3D):\r\n`;
  cardsArr.forEach((c, i) => {
    txt += `- ${c.istilah}: ${c.definisi}\r\n`;
  });
  const blob = new Blob([txt], { type: 'text/plain;charset=utf-8' });
  const a = document.createElement('a');
  a.href = URL.createObjectURL(blob);
  a.download = `Intisari_${activeLMSModule.judul.replace(/\s+/g, '_')}.txt`;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  showStudentToast('Berkas rangkuman materi berhasil diunduh!', 'success');
}

async function unggahLampiranDiskusiSiswaV37(fileInput) {
  if (!fileInput || !fileInput.files || !fileInput.files.length) return;
  const prevEl = document.getElementById('trn-disc-attachment-preview');
  if (prevEl) prevEl.innerHTML = `<i class="fa-solid fa-spinner fa-spin"></i> Mengunggah gambar...`;
  try {
    const url = await uploadImageToGoogleScript(fileInput);
    trnUploadedImageUrlV37 = url || '';
    if (prevEl) prevEl.innerHTML = `<i class="fa-solid fa-circle-check"></i> Gambar siap dilampirkan!`;
  } catch (e) {
    if (prevEl) prevEl.innerHTML = `<span style="color:#e11d48;">Gagal mengunggah gambar.</span>`;
  }
}

function kirimDiskusiBaruTrenningV37() {
  if (!activeLMSModule) return;
  const titleInp = document.getElementById('trn-disc-inp-title');
  const bodyInp = document.getElementById('trn-disc-inp-body');
  const btn = document.getElementById('btn-trn-send-disc');
  const judulDiskusi = (titleInp ? titleInp.value : '').trim();
  const pertanyaan = (bodyInp ? bodyInp.value : '').trim();

  if (!pertanyaan && !judulDiskusi) {
    showStudentToast('Tuliskan judul atau isi pertanyaan diskusimu terlebih dahulu!', 'warning');
    return;
  }

  if (btn) {
    btn.innerHTML = '<i class="fa-solid fa-spinner fa-spin"></i>';
    btn.disabled = true;
  }

  const sectionNames = {
    1: 'Section 1 • Pemantik & Tujuan',
    2: `Section 1 • Chapter ${trnActiveSubConceptIdxV37 + 1}`,
    3: 'Section 2 • Kartu Pintar 3D',
    4: 'Section 2 • Studi Kasus & Refleksi',
    5: 'Section 3 • Kuis Formatif HOTS'
  };

  google.script.run.withSuccessHandler(res => {
    if (btn) {
      btn.innerHTML = 'Send';
      btn.disabled = false;
    }
    if (res && res.success) {
      if (titleInp) titleInp.value = '';
      if (bodyInp) bodyInp.value = '';
      trnUploadedImageUrlV37 = '';
      if (!Array.isArray(activeLMSModule.qnaList)) activeLMSModule.qnaList = [];
      activeLMSModule.qnaList.push(res.item);
      renderTrnRightSidebarContentV37();
      showStudentToast('Topik diskusi berhasil diterbitkan!', 'success');
    }
  }).submitStudentRichDiscussionV37({
    idModul: activeLMSModule.id,
    mapel: activeLMSSubject,
    judulModul: activeLMSModule.judul,
    namaSiswa: studentData.name || 'Siswa',
    kelas: studentData.kelas || '7',
    judulDiskusi: judulDiskusi || pertanyaan.substring(0, 45),
    pertanyaan: pertanyaan || judulDiskusi,
    sectionLabel: sectionNames[activeLMSStep] || 'Section 1',
    lampiranGambar: trnUploadedImageUrlV37 || ''
  });
}

function toggleLikeDiskusiV37(idQna) {
  playStudentSFX('click');
  if (!activeLMSModule || !Array.isArray(activeLMSModule.qnaList)) return;
  const item = activeLMSModule.qnaList.find(x => x.idQna === idQna);
  if (item) {
    if (!item.meta) item.meta = { likes: 0, replies: [] };
    item.meta.likes = (Number(item.meta.likes) || 0) + 1;
    renderTrnRightSidebarContentV37();
  }
  google.script.run.submitDiscussionReplyOrLikeV37({
    idQna: idQna,
    actionType: 'LIKE',
    namaUser: studentData.name || 'Siswa'
  });
}

function openTrnDiscussionModalV37(targetIdOrAll) {
  ensureTrenningOverlaysInDOMV37();
  playStudentSFX('click');
  const modal = document.getElementById('trnDiscussionFullModal');
  const box = document.getElementById('trnDiscussionModalContent');
  if (!modal || !box || !activeLMSModule) return;
  modal.classList.add('active');

  const qnaArr = Array.isArray(activeLMSModule.qnaList) ? activeLMSModule.qnaList : [];
  if (targetIdOrAll === 'ALL' || !targetIdOrAll) {
    renderAllDiscussionsModalListV37(box, qnaArr);
  } else {
    const found = qnaArr.find(q => q.idQna === targetIdOrAll);
    if (found) renderSingleDiscussionThreadModalV37(box, found);
    else renderAllDiscussionsModalListV37(box, qnaArr);
  }
}

function closeTrnDiscussionModalV37() {
  stopTrnVoiceRecordingV37(false);
  const modal = document.getElementById('trnDiscussionFullModal');
  if (modal) modal.classList.remove('active');
}

function renderAllDiscussionsModalListV37(box, qnaArr) {
  const listHtml = qnaArr.slice().reverse().map(item => {
    const m = item.meta || {};
    const titleTxt = m.judulDiskusi || (item.pertanyaan || '').substring(0, 55);
    const repliesCount = (Array.isArray(m.replies) ? m.replies.length : 0) + (item.balasanGuru ? 1 : 0);
    const safeId = item.idQna.replace(/'/g, "\\'");
    return `
      <div class="trn-disc-thread-card" onclick="openTrnDiscussionModalV37('${safeId}')" style="margin-bottom:12px;">
        <div style="font-size:11px; font-weight:800; color:#64748b; margin-bottom:4px;">${escapeHtml(m.sectionLabel || 'Section 1 • Eksplorasi Materi')}</div>
        <div style="font-size:15.5px; font-weight:800; color:var(--text-main); margin-bottom:6px;">${escapeHtml(titleTxt)}</div>
        <div style="font-size:13px; color:#475569; line-height:1.55;">${escapeHtml(item.pertanyaan)}</div>
        <div style="display:flex; align-items:center; gap:16px; margin-top:12px; font-size:12px; font-weight:700; color:#475569;">
          <span><i class="fa-regular fa-thumbs-up"></i> ${Number(m.likes) || 0} Suka</span>
          <span><i class="fa-regular fa-comment-dots"></i> ${repliesCount} Balasan</span>
          <span style="margin-left:auto; font-size:11px; color:#94a3b8;">Oleh <b>${escapeHtml(item.namaSiswa)}</b> &bull; ${escapeHtml(item.waktu)}</span>
        </div>
      </div>`;
  }).join('');

  box.innerHTML = `
    <div style="padding:18px 24px; border-bottom:1.5px solid #e2e8f0; display:flex; justify-content:space-between; align-items:center;">
      <h3 style="font-size:18px; font-weight:900; margin:0;">Discussion (${qnaArr.length} Topik)</h3>
      <button type="button" onclick="closeTrnDiscussionModalV37()" style="background:none; border:none; font-size:18px; color:#64748b; cursor:pointer;"><i class="fa-solid fa-xmark"></i></button>
    </div>
    <div style="padding:20px 24px; overflow-y:auto; max-height:76vh;">
      ${listHtml || `<div style="text-align:center; padding:40px; color:#94a3b8;">Belum ada diskusi pada bab ini.</div>`}
    </div>`;
}

function renderVoiceWaveformPlayerHTMLV37(audioDataUrl, durationLbl) {
  if (!audioDataUrl) return '';
  const bars = [40, 75, 55, 90, 60, 85, 45, 95, 70, 50, 80, 60, 40, 75, 50].map(h => `<span style="height:${h}%;"></span>`).join('');
  return `
    <div class="trn-voice-waveform-pill">
      <button type="button" onclick="const a=this.nextElementSibling.nextElementSibling; if(a.paused){a.play(); this.innerHTML='<i class=\'fa-solid fa-pause\'></i>';}else{a.pause(); this.innerHTML='<i class=\'fa-solid fa-play\'></i>';}" style="width:30px; height:30px; border-radius:50%; background:#4f46e5; color:white; border:none; cursor:pointer; display:flex; align-items:center; justify-content:center; font-size:11px;">
        <i class="fa-solid fa-play"></i>
      </button>
      <div class="trn-wave-bars">${bars}</div>
      <audio src="${audioDataUrl}" onended="this.previousElementSibling.previousElementSibling.innerHTML='<i class=\'fa-solid fa-play\'></i>'"></audio>
      <span style="font-size:11px; font-weight:800; color:#475569;">${escapeHtml(durationLbl || '0:08')}</span>
    </div>`;
}

