async function toggleTrnVoiceRecordingV37() {
  const btn = document.getElementById('btn-trn-voice-rec');
  const lbl = document.getElementById('lbl-trn-voice-rec');
  if (trnMediaRecorderV37 && trnMediaRecorderV37.state === 'recording') {
    stopTrnVoiceRecordingV37(true);
    return;
  }

  if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
    showStudentToast('Browser perangkat ini belum mengizinkan akses mikrofon.', 'warning');
    return;
  }

  try {
    const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
    trnAudioChunksV37 = [];
    trnRecordingSecondsV37 = 0;
    trnMediaRecorderV37 = new MediaRecorder(stream);

    trnMediaRecorderV37.ondataavailable = e => {
      if (e.data && e.data.size > 0) trnAudioChunksV37.push(e.data);
    };

    trnMediaRecorderV37.onstop = () => {
      stream.getTracks().forEach(t => t.stop());
      if (trnAudioChunksV37.length > 0) {
        const blob = new Blob(trnAudioChunksV37, { type: 'audio/webm' });
        const reader = new FileReader();
        reader.onloadend = () => {
          trnRecordedVoiceDataUrlV37 = reader.result;
          const m = Math.floor(trnRecordingSecondsV37 / 60);
          const s = (trnRecordingSecondsV37 % 60).toString().padStart(2, '0');
          trnRecordedVoiceDurationV37 = `${m}:${s}`;
          const slot = document.getElementById('trn-voice-preview-slot');
          if (slot) {
            slot.innerHTML = renderVoiceWaveformPlayerHTMLV37(trnRecordedVoiceDataUrlV37, trnRecordedVoiceDurationV37);
          }
        };
        reader.readAsDataURL(blob);
      }
    };

    trnMediaRecorderV37.start();
    if (btn) btn.style.borderColor = '#e11d48';
    if (lbl) lbl.innerHTML = `<span style="color:#e11d48;">● Merekam 0:00 (Klik Selesai)</span>`;
    trnRecordingTimerV37 = setInterval(() => {
      trnRecordingSecondsV37++;
      const m = Math.floor(trnRecordingSecondsV37 / 60);
      const s = (trnRecordingSecondsV37 % 60).toString().padStart(2, '0');
      if (lbl) lbl.innerHTML = `<span style="color:#e11d48;">● Merekam ${m}:${s} (Klik Selesai)</span>`;
      if (trnRecordingSecondsV37 >= 30) stopTrnVoiceRecordingV37(true);
    }, 1000);
  } catch (err) {
    showStudentToast('Izin mikrofon diperlukan untuk merekam Voice Note.', 'warning');
  }
}

function stopTrnVoiceRecordingV37(saveResult) {
  if (trnRecordingTimerV37) {
    clearInterval(trnRecordingTimerV37);
    trnRecordingTimerV37 = null;
  }
  if (trnMediaRecorderV37 && trnMediaRecorderV37.state === 'recording') {
    if (!saveResult) trnAudioChunksV37 = [];
    trnMediaRecorderV37.stop();
  }
  const lbl = document.getElementById('lbl-trn-voice-rec');
  if (lbl) lbl.innerText = 'Rekam Ulang Voice Note';
}

function kirimBalasanDiskusiTrenningV37(idQna) {
  const inp = document.getElementById('trn-reply-inp-text');
  const teks = (inp ? inp.value : '').trim();
  if (!teks && !trnRecordedVoiceDataUrlV37) {
    showStudentToast('Tulis balasan atau rekam Voice Note terlebih dahulu!', 'warning');
    return;
  }

  const item = (activeLMSModule.qnaList || []).find(x => x.idQna === idQna);
  const newReply = {
    idReply: 'REP-' + Date.now(),
    nama: studentData.name || 'Siswa',
    role: 'Learner',
    kelas: studentData.kelas || '7',
    waktu: 'Baru saja',
    teks: teks,
    voiceNoteDataUrl: trnRecordedVoiceDataUrlV37 || '',
    voiceDuration: trnRecordedVoiceDurationV37 || ''
  };

  if (item) {
    if (!item.meta) item.meta = { likes: 0, replies: [] };
    if (!Array.isArray(item.meta.replies)) item.meta.replies = [];
    item.meta.replies.push(newReply);
  }

  const voiceUrlToSend = trnRecordedVoiceDataUrlV37;
  const voiceDurToSend = trnRecordedVoiceDurationV37;
  trnRecordedVoiceDataUrlV37 = '';
  trnRecordedVoiceDurationV37 = '';

  const box = document.getElementById('trnDiscussionModalContent');
  if (box && item) renderSingleDiscussionThreadModalV37(box, item);
  renderTrnRightSidebarContentV37();
  showStudentToast('Balasan diskusi berhasil dikirim!', 'success');

  google.script.run.submitDiscussionReplyOrLikeV37({
    idQna: idQna,
    actionType: 'REPLY',
    namaUser: studentData.name || 'Siswa',
    roleUser: 'Learner',
    kelasUser: studentData.kelas || '7',
    teksBalasan: teks,
    voiceNoteDataUrl: voiceUrlToSend,
    voiceDuration: voiceDurToSend
  });
}

