let trnActiveFileCategoryFilterV38 = 'ALL'; // 'ALL' | 'VIDEO' | 'PDF' | 'DOC' | 'TXT' | 'OTHER'

function getFileCategoryVisualMetaV38(cat) {
  const c = (cat || 'FILE').toUpperCase();
  const map = {
    VIDEO: { icon: 'fa-solid fa-file-video', bg: '#fff1f2', col: '#e11d48', border: '#fecdd3', label: 'VIDEO' },
    PDF:   { icon: 'fa-solid fa-file-pdf',   bg: '#fef2f2', col: '#dc2626', border: '#fecaca', label: 'PDF' },
    DOC:   { icon: 'fa-solid fa-file-word',  bg: '#eff6ff', col: '#2563eb', border: '#bfdbfe', label: 'DOC / WORD' },
    TXT:   { icon: 'fa-solid fa-file-lines', bg: '#fffbeb', col: '#10b981', border: '#a7f3d0', label: 'DOC TEXT' },
    PPT:   { icon: 'fa-solid fa-file-powerpoint', bg: '#fff7ed', col: '#ea580c', border: '#fed7aa', label: 'SLIDE PPT' },
    XLS:   { icon: 'fa-solid fa-file-excel', bg: '#ecfdf5', col: '#059669', border: '#a7f3d0', label: 'SPREADSHEET' },
    ZIP:   { icon: 'fa-solid fa-file-zipper', bg: '#ecfdf5', col: '#0d9488', border: '#a7f3d0', label: 'ARSIP ZIP' },
    AUDIO: { icon: 'fa-solid fa-file-audio', bg: '#f5f3ff', col: '#7c3aed', border: '#ddd6fe', label: 'AUDIO' },
    IMAGE: { icon: 'fa-solid fa-file-image', bg: '#ecfeff', col: '#0891b2', border: '#a5f3fc', label: 'GAMBAR' }
  };
  return map[c] || { icon: 'fa-solid fa-file-arrow-down', bg: '#eef2ff', col: '#4f46e5', border: '#c7d2fe', label: c || 'DOKUMEN' };
}

