function polesBagianModulDenganAIV40(inputId, sectionLabel) {
  const el = document.getElementById(inputId);
  if (!el) return;
  const origVal = el.value;
  el.value = 'Sedang menyempurnakan teks bersama AI Groq...';
  el.disabled = true;

  google.script.run.withSuccessHandler(res => {
    el.disabled = false;
    if (res && res.success && res.polishedText) {
      el.value = res.polishedText;
      showStudentToast(`${sectionLabel} berhasil diperkaya oleh AI Groq!`, 'success');
    } else {
      el.value = origVal;
      showStudentToast('Gagal menghubungi AI Groq.', 'warning');
    }
  }).polishModuleSectionWithAIGroqV40({
    mapel: activeLMSSubject,
    judulModul: trnWorkingModuleCopyV40 ? trnWorkingModuleCopyV40.judul : '',
    sectionType: sectionLabel,
    currentText: origVal
  });
}

function simpanPerubahanModulLiveV40() {
  if (!isAuthorizedTeacherForCurrentMapelV40(activeLMSSubject)) {
    showStudentToast('Akses ditolak: Hanya Akun Guru/Admin yang dapat menyimpan perubahan modul.', 'error');
    return;
  }
  flushCurrentEditorTabInputsV40();
  const btn = document.getElementById('btn-save-live-module-v40');
  if (btn) {
    btn.innerHTML = '<i class="fa-solid fa-spinner fa-spin"></i> Menyimpan Live ke Server...';
    btn.disabled = true;
  }

  const syncCBT = !!document.getElementById('chk-live-ed-sync-cbt-v40')?.checked;
  const payload = {
    id: trnWorkingModuleCopyV40.id,
    mapel: activeLMSSubject,
    judul: trnWorkingModuleCopyV40.judul,
    tujuan: trnWorkingModuleCopyV40.tujuan,
    konten: trnWorkingModuleCopyV40.konten,
    kuis: trnWorkingModuleCopyV40.kuis,
    pembuat: trnWorkingModuleCopyV40.pembuat || trnLiveAdminSessionV39.name,
    syncToBankSoal: syncCBT
  };

  google.script.run.withSuccessHandler(res => {
    if (btn) {
      btn.innerHTML = '<i class="fa-solid fa-floppy-disk"></i> Simpan Perubahan Secara Live';
      btn.disabled = false;
    }
    if (res && res.success && res.moduleData) {
      const updated = res.moduleData;
      updated.qnaList = activeLMSModule.qnaList || [];
      Object.assign(activeLMSModule, updated);

      const subObj = (globalLMSDashboard.subjects || []).find(s => s.name === activeLMSSubject);
      if (subObj && Array.isArray(subObj.modules)) {
        const mIdx = subObj.modules.findIndex(x => x.id === updated.id || x.id === trnWorkingModuleCopyV40.id);
        if (mIdx !== -1) subObj.modules[mIdx] = activeLMSModule;
        else subObj.modules.push(activeLMSModule);
        subObj.totalModules = subObj.modules.length;
      }

      closeLiveModuleFullEditorV40();
      renderConstructiveWorkspace();
      renderSubjectModulesHubV33();
      playStudentSFX('success');
      showStudentToast('Seluruh perubahan modul berhasil disimpan secara Live!', 'success');
    } else {
      Swal.fire({ icon: 'error', title: 'Gagal Menyimpan', text: res ? res.message : 'Terjadi kesalahan server.', customClass: { popup: 'swal-custom-popup' } });
    }
  }).saveLiveModuleFullEditV40(payload);
}

function buatModulBaruLangsungModeGuruV40() {
  if (!isAuthorizedTeacherForCurrentMapelV40(activeLMSSubject)) {
    toggleLiveAdminModeInSidebarV39();
    return;
  }
  const newMod = getDefaultConstructiveModule(activeLMSSubject);
  newMod.id = 'MOD-' + Date.now();
  newMod.judul = `Bab Baru: Eksplorasi ${activeLMSSubject}`;
  newMod.pembuat = trnLiveAdminSessionV39.name || 'Guru Pengampu';
  if (!Array.isArray(window.currentSubjectModulesList)) window.currentSubjectModulesList = [];
  window.currentSubjectModulesList.push(newMod);
  activeLMSModuleIndexV33 = window.currentSubjectModulesList.length - 1;
  activeLMSModule = newMod;
  openLiveModuleFullEditorV40('step1');
}


// =========================================================================
// 37. PEMBARUAN V41:
//     1. PENGHAPUSAN TOTAL TOMBOL AI DRAWER & MULAI BELAJAR DI HEADER UTAMA
//        (MENCEGAH FAT-FINGER AGAR FOKUS BELAJAR SISWA TIDAK TERGANGGU)
//     2. FITUR MODERASI DISKUSI INTERAKTIF: HAPUS MANUAL TOPIK DISKUSI SISWA,
//        HAPUS BALASAN KOMENTAR, & EDIT TEKS DISKUSI OLEH ADMIN/GURU DI MODE GURU
// =========================================================================

// Pastikan jika ada sisa elemen tombol AI Drawer atau Mulai Belajar di Topbar langsung dibersihkan saat boot
function enforceCleanTopbarHeaderV41() {
  document.querySelectorAll('.eduvance-btn-start-studying, .eduvance-topbar-actions button[onclick*="openEduvanceAIChatQuick"], .eduvance-topbar-actions button[onclick*="triggerStartStudyingQuick"]').forEach(el => {
    el.remove();
  });
}
window.addEventListener('DOMContentLoaded', enforceCleanTopbarHeaderV41);
setTimeout(enforceCleanTopbarHeaderV41, 300);

// 1. Fungsi Hapus Manual Topik Diskusi Siswa oleh Admin/Guru (Mode Guru)
function hapusTopikDiskusiSiswaModeGuruV41(idQna) {
  playStudentSFX('click');
  const isAdminPanel = document.body.classList.contains('admin-mode');
  if (!isAdminPanel && (!trnLiveAdminSessionV39 || !trnLiveAdminSessionV39.active)) {
    showStudentToast('Aktifkan Mode Guru terlebih dahulu untuk memoderasi/menghapus diskusi!', 'warning');
    toggleLiveAdminModeInSidebarV39();
    return;
  }

  const qnaArr = (activeLMSModule && Array.isArray(activeLMSModule.qnaList)) ? activeLMSModule.qnaList : adminLMSQnAList;
  const item = (qnaArr || []).find(x => x.idQna === idQna);
  const titlePreview = item ? ((item.meta && item.meta.judulDiskusi) || item.pertanyaan || 'Topik Diskusi') : idQna;

  Swal.fire({
    title: '<i class="fa-solid fa-trash-can" style="color:#e11d48;"></i> Hapus Topik Diskusi Ini?',
    html: `Anda akan menghapus secara permanen diskusi dari <b>${escapeHtml(item ? item.namaSiswa : 'Siswa')}</b>:<br><br><div style="background:#fff1f2; border:1px solid #fecdd3; padding:10px 12px; border-radius:10px; font-size:13px; color:#881337; font-weight:700;">"${escapeHtml(titlePreview.substring(0, 110))}"</div>`,
    icon: 'warning',
    showCancelButton: true,
    confirmButtonColor: '#e11d48',
    confirmButtonText: '<i class="fa-solid fa-trash"></i> Ya, Hapus Permanen',
    cancelButtonText: 'Batal',
    customClass: { popup: 'swal-custom-popup', confirmButton: 'swal-custom-confirm' }
  }).then(res => {
    if (res.isConfirmed) {
      // Hapus instan di state lokal (0ms)
      if (activeLMSModule && Array.isArray(activeLMSModule.qnaList)) {
        activeLMSModule.qnaList = activeLMSModule.qnaList.filter(x => x.idQna !== idQna);
      }
      if (Array.isArray(adminLMSQnAList)) {
        adminLMSQnAList = adminLMSQnAList.filter(x => x.idQna !== idQna);
      }

      renderTrnRightSidebarContentV37();
      if (typeof renderAdminLMSQnATable === 'function') renderAdminLMSQnATable();

      const modal = document.getElementById('trnDiscussionFullModal');
      const box = document.getElementById('trnDiscussionModalContent');
      if (modal && modal.classList.contains('active') && box && activeLMSModule) {
        renderAllDiscussionsModalListV37(box, activeLMSModule.qnaList || []);
      }

      showStudentToast('Topik diskusi berhasil dihapus oleh Moderator (Mode Guru)!', 'success');

      google.script.run.withSuccessHandler(srvRes => {
        if (!srvRes || !srvRes.success) {
          showStudentToast(srvRes ? srvRes.message : 'Gagal menghapus di server.', 'warning');
        }
      }).deleteDiscussionThreadOrReplyV41({
        idQna: idQna,
        deleteType: 'THREAD'
      });
    }
  });
}

// 2. Fungsi Hapus Manual Balasan Komentar Tertentu oleh Admin/Guru (Mode Guru)
function hapusBalasanDiskusiModeGuruV41(idQna, idReply, tipeHapus) {
  playStudentSFX('click');
  const isAdminPanel = document.body.classList.contains('admin-mode');
  if (!isAdminPanel && (!trnLiveAdminSessionV39 || !trnLiveAdminSessionV39.active)) {
    showStudentToast('Aktifkan Mode Guru terlebih dahulu untuk menghapus komentar balasan!', 'warning');
    return;
  }

  const delMode = tipeHapus || 'REPLY'; // 'REPLY' | 'OFFICIAL_ANSWER' | 'CLEAR_REPLIES'
  Swal.fire({
    title: delMode === 'CLEAR_REPLIES' ? 'Bersihkan Semua Balasan?' : 'Hapus Komentar Balasan Ini?',
    text: delMode === 'CLEAR_REPLIES'
      ? 'Seluruh komentar balasan pada topik diskusi ini akan dihapus.'
      : 'Komentar balasan yang dipilih akan dihapus secara permanen dari sesi diskusi.',
    icon: 'warning',
    showCancelButton: true,
    confirmButtonColor: '#e11d48',
    confirmButtonText: 'Ya, Hapus',
    cancelButtonText: 'Batal',
    customClass: { popup: 'swal-custom-popup', confirmButton: 'swal-custom-confirm' }
  }).then(res => {
    if (res.isConfirmed) {
      const item = (activeLMSModule && Array.isArray(activeLMSModule.qnaList))
        ? activeLMSModule.qnaList.find(x => x.idQna === idQna)
        : null;

      if (item) {
        if (!item.meta) item.meta = { likes: 0, replies: [] };
        if (delMode === 'REPLY' && Array.isArray(item.meta.replies)) {
          item.meta.replies = item.meta.replies.filter(r => r.idReply !== idReply);
        } else if (delMode === 'OFFICIAL_ANSWER') {
          item.balasanGuru = '';
          item.namaGuru = '';
          item.waktuBalas = '';
          if (Array.isArray(item.meta.replies)) {
            item.meta.replies = item.meta.replies.filter(r => !r.isOfficialAnswer);
          }
          item.meta.isResolved = false;
        } else if (delMode === 'CLEAR_REPLIES') {
          item.balasanGuru = '';
          item.namaGuru = '';
          item.waktuBalas = '';
          item.meta.replies = [];
          item.meta.isResolved = false;
        }
      }

      renderTrnRightSidebarContentV37();
      const modal = document.getElementById('trnDiscussionFullModal');
      const box = document.getElementById('trnDiscussionModalContent');
      if (modal && modal.classList.contains('active') && box && item) {
        renderSingleDiscussionThreadModalV37(box, item);
      }

      showStudentToast('Komentar balasan berhasil dihapus!', 'success');

      google.script.run.deleteDiscussionThreadOrReplyV41({
        idQna: idQna,
        deleteType: delMode,
        idReply: idReply || ''
      });
    }
  });
}

// 3. Fungsi Moderasi / Edit Teks Pertanyaan Siswa oleh Admin/Guru di Mode Guru
function editModerasiTopikDiskusiV41(idQna) {
  playStudentSFX('click');
  if (!trnLiveAdminSessionV39 || !trnLiveAdminSessionV39.active) return;
  const item = (activeLMSModule && Array.isArray(activeLMSModule.qnaList))
    ? activeLMSModule.qnaList.find(x => x.idQna === idQna)
    : null;
  if (!item) return;
  const m = item.meta || {};

  Swal.fire({
    title: '<i class="fa-solid fa-pen-to-square" style="color:#2563eb;"></i> Moderasi Teks Diskusi Siswa',
    html: `
      <div style="text-align:left; font-size:13.5px;">
        <label class="edit-label">Judul Topik Diskusi</label>
        <input type="text" id="inp-mod-disc-title-v41" class="swal-custom-input" style="width:100%; margin-bottom:12px; background:#f8fafc;" value="${escapeHtml(m.judulDiskusi || '')}">
        <label class="edit-label">Isi Pertanyaan / Komentar Siswa</label>
        <textarea id="inp-mod-disc-body-v41" class="swal-custom-input" rows="4" style="width:100%; background:#f8fafc;">${escapeHtml(item.pertanyaan || '')}</textarea>
      </div>`,
    showCancelButton: true,
    confirmButtonText: 'Simpan Moderasi',
    cancelButtonText: 'Batal',
    customClass: { popup: 'swal-custom-popup', confirmButton: 'swal-custom-confirm' },
    preConfirm: () => {
      const j = document.getElementById('inp-mod-disc-title-v41').value.trim();
      const p = document.getElementById('inp-mod-disc-body-v41').value.trim();
      if (!p) {
        Swal.showValidationMessage('Isi pertanyaan tidak boleh kosong!');
        return false;
      }
      return { j, p };
    }
  }).then(res => {
    if (res.isConfirmed && res.value) {
      if (!item.meta) item.meta = {};
      item.meta.judulDiskusi = res.value.j;
      item.pertanyaan = res.value.p;
      renderTrnRightSidebarContentV37();
      showStudentToast('Teks diskusi berhasil dirapikan!', 'success');

      google.script.run.editDiscussionThreadTextByAdminV41({
        idQna: idQna,
        judulDiskusi: res.value.j,
        pertanyaan: res.value.p
      });
    }
  });
}

// 4. Suntikkan Tombol Moderasi (Hapus Topik, Hapus Balasan, Edit Teks) pada Sidebar Kanan & Modal Diskusi Saat Mode Guru Aktif
const _v40OrigRenderTrnRightSidebarContent = renderTrnRightSidebarContentV37;
renderTrnRightSidebarContentV37 = function() {
  _v40OrigRenderTrnRightSidebarContent();
  if (trnActiveRightTabV37 !== 'discussion' || !activeLMSModule) return;
  if (!trnLiveAdminSessionV39 || !trnLiveAdminSessionV39.active) return;

  const qnaArr = Array.isArray(activeLMSModule.qnaList) ? activeLMSModule.qnaList : [];
  const cards = document.querySelectorAll('#trn-right-pane-body .trn-disc-thread-card');

  // Tambahkan bar moderasi pada setiap kartu diskusi di sidebar kanan
  const kw = (document.getElementById('trn-side-search-input')?.value || '').toLowerCase().trim();
  const myNameLow = (studentData.name || '').toLowerCase().trim();
  const filteredThreads = qnaArr.slice().reverse().filter(item => {
    const m = item.meta || {};
    const reps = Array.isArray(m.replies) ? m.replies : [];
    const hasOfficial = !!(item.balasanGuru && item.balasanGuru.trim() !== '') || reps.some(r => r.isOfficialAnswer || r.isBestSolution);
    const isResolved = !!m.isResolved || hasOfficial;
    if (trnDiscussionFilterModeV39 === 'RESOLVED' && !isResolved) return false;
    if (trnDiscussionFilterModeV39 === 'UNANSWERED' && isResolved) return false;
    if (trnDiscussionFilterModeV39 === 'MINE') {
      const isMyThread = (item.namaSiswa || '').toLowerCase().trim() === myNameLow;
      const isMyReply = reps.some(r => (r.nama || '').toLowerCase().trim() === myNameLow);
      if (!isMyThread && !isMyReply) return false;
    }
    if (!kw) return true;
    return (item.pertanyaan || '').toLowerCase().includes(kw) ||
           (item.namaSiswa || '').toLowerCase().includes(kw) ||
           ((m.judulDiskusi || '').toLowerCase().includes(kw)) ||
           (item.balasanGuru || '').toLowerCase().includes(kw);
  });

  cards.forEach((cardEl, idx) => {
    const item = filteredThreads[idx];
    if (!item || cardEl.querySelector('.trn-mod-action-bar')) return;
    const safeId = item.idQna.replace(/'/g, "\\'");
    const hasOfficial = !!(item.balasanGuru && item.balasanGuru.trim() !== '');

    const modBar = document.createElement('div');
    modBar.className = 'trn-mod-action-bar';
    modBar.setAttribute('onclick', 'event.stopPropagation();');
    modBar.innerHTML = `
      <span style="font-size:9.5px; font-weight:900; color:#e11d48; margin-right:auto; text-transform:uppercase;">
        <i class="fa-solid fa-shield-halved"></i> Moderasi Guru:
      </span>
      <button type="button" class="trn-btn-mod-edit" onclick="editModerasiTopikDiskusiV41('${safeId}')" title="Rapikan/Edit Teks Pertanyaan Siswa">
        <i class="fa-solid fa-pen"></i> Edit
      </button>
      ${hasOfficial ? `
        <button type="button" class="trn-btn-mod-delete" onclick="hapusBalasanDiskusiModeGuruV41('${safeId}', '', 'OFFICIAL_ANSWER')" title="Hapus Jawaban Resmi Guru">
          <i class="fa-solid fa-eraser"></i> Hapus Jawaban
        </button>` : ''}
      <button type="button" class="trn-btn-mod-delete" onclick="hapusTopikDiskusiSiswaModeGuruV41('${safeId}')" title="Hapus Permanen Topik Diskusi Siswa Ini">
        <i class="fa-solid fa-trash-can"></i> Hapus Diskusi
      </button>`;
    cardEl.appendChild(modBar);
  });
};

