// --- B. PECAH TEKS TUJUAN PEMBELAJARAN MENJADI POIN CAPAIAN KOMPETENSI TERSTRUKTUR ---
function extractStructuredLearningGoalsV42(rawTujuan, kObj) {
  const clean = (rawTujuan || '').toString().trim();
  if (!clean) {
    return [
      'Memahami konsep dasar dan mengidentifikasi fenomena nyata terkait materi.',
      'Menganalisis hubungan sebab-akibat serta menerapkan konsep pada studi kasus.',
      'Menyelesaikan evaluasi formatif berstandar HOTS secara mandiri dan reflektif.'
    ];
  }

  // Pisahkan berdasarkan kalimat (titik) atau penomoran
  let sentences = clean
    .split(/(?<=[.!?])\s+|\r?\n/)
    .map(s => s.replace(/^[\d\-\*\•\)\.]+\s*/, '').trim())
    .filter(s => s.length >= 18);

  if (sentences.length === 1 && sentences[0].length > 140) {
    // Jika 1 kalimat sangat panjang, pecah berdasarkan konjungsi kunci
    sentences = sentences[0]
      .split(/;\s*|\s+(?:serta|sekaligus|di sisi lain,|selain itu,)\s+/i)
      .map(s => s.trim())
      .filter(s => s.length >= 18);
  }

  // Jika masih hanya 1 kalimat, perkaya dengan sub-materi sebagai indikator capaian
  if (sentences.length <= 1 && kObj && kObj.eksplorasi && Array.isArray(kObj.eksplorasi.sub_materi)) {
    kObj.eksplorasi.sub_materi.slice(0, 3).forEach(sm => {
      if (sm && sm.judul_sub) {
        sentences.push(`Menguasai pilar kompetensi: ${sm.judul_sub} beserta penerapannya.`);
      }
    });
  }

  return sentences.slice(0, 5);
}

// Ekstrak Kata Kunci / Kompetensi Inti dari teks Tujuan Pembelajaran (misal kata di dalam kurung atau istilah penting)
function extractCompetencyKeywordsV42(rawTujuan, activeSubj, kObj) {
  const keywords = new Set();
  if (activeSubj) keywords.add(activeSubj);
  const parenMatches = (rawTujuan || '').match(/\(([^)]+)\)/g) || [];
  parenMatches.forEach(m => {
    const inner = m.replace(/[()]/g, '').trim();
    if (inner.length >= 3 && inner.length <= 36) keywords.add(inner);
  });

  if (kObj && Array.isArray(kObj.kartu_pintar)) {
    kObj.kartu_pintar.slice(0, 4).forEach(c => {
      if (c && c.istilah) keywords.add(c.istilah);
    });
  }
  if (keywords.size < 3) {
    ['Berpikir Kritis (HOTS)', 'Literasi Kontekstual', 'Pemecahan Masalah'].forEach(k => keywords.add(k));
  }
  return Array.from(keywords).slice(0, 6);
}

function toggleTujuanGoalCheckItemV42(modId, goalIdx, totalGoals) {
  playStudentSFX('click');
  const key = `${modId}_goal_${goalIdx}`;
  const wasChecked = !!trnTujuanGoalChecksMapV42[key];
  trnTujuanGoalChecksMapV42[key] = !wasChecked;
  localStorage.setItem('trn_tujuan_goal_checks_v42', JSON.stringify(trnTujuanGoalChecksMapV42));

  let checkedCount = 0;
  for (let i = 0; i < totalGoals; i++) {
    if (trnTujuanGoalChecksMapV42[`${modId}_goal_${i}`]) checkedCount++;
  }

  if (!wasChecked) {
    showStudentToast(`Capaian tujuan #${goalIdx + 1} ditandai dipahami! (${checkedCount}/${totalGoals})`, 'success');
    if (checkedCount === totalGoals && totalGoals > 0) {
      pushStudentNotificationV42({
        id: `NOTIF-GOALS-${modId}`,
        category: 'XP_BADGE',
        title: `🎯 Seluruh Tujuan Pembelajaran Dipahami! (+15 XP)`,
        desc: `Kamu telah menandai pemahaman pada seluruh ${totalGoals} indikator tujuan pembelajaran di modul "${activeLMSModule ? activeLMSModule.judul : 'Modul LMS'}".`,
        mapel: activeLMSSubject,
        idModul: modId,
        targetStep: 2,
        actionLabel: 'Lanjut Eksplorasi Materi',
        icon: 'fa-graduation-cap',
        color: '#6d28d9',
        bg: '#f5f3ff'
      });
    }
  }
  renderConstructiveWorkspace();
}

function switchTujuanInteractiveTabV42(tabKey) {
  playStudentSFX('click');
  trnTujuanActiveTabV42 = tabKey;
  renderConstructiveWorkspace();
}

// --- C. RENDER HERO CARD TUJUAN PEMBELAJARAN TERBIMBING V42 PADA TAHAP 1 ---
function buildTujuanPembelajaranHeroCardV42() {
  if (!activeLMSModule) return '';
  const mod = activeLMSModule;
  const k = mod.konten || {};
  const subArr = (k.eksplorasi && Array.isArray(k.eksplorasi.sub_materi)) ? k.eksplorasi.sub_materi : [];
  const goalsList = extractStructuredLearningGoalsV42(mod.tujuan, k);
  const keywordTags = extractCompetencyKeywordsV42(mod.tujuan, activeLMSSubject, k);

  let checkedGoalsCount = 0;
  goalsList.forEach((_, idx) => {
    if (trnTujuanGoalChecksMapV42[`${mod.id}_goal_${idx}`]) checkedGoalsCount++;
  });
  const goalsPct = goalsList.length > 0 ? Math.round((checkedGoalsCount / goalsList.length) * 100) : 100;

  // Hitung jumlah siswa online di ruang belajar atau tampilkan indikator target modul
  let onlinePeersCount = 0;
  for (let id in (daftarSiswaOnline || {})) {
    let st = daftarSiswaOnline[id] && daftarSiswaOnline[id][0];
    if (st && st.tipe === 'siswa') onlinePeersCount++;
  }
  const studentsOnlineDisplay = onlinePeersCount > 0
    ? `${onlinePeersCount} Siswa Aktif`
    : `${checkedGoalsCount}/${goalsList.length} Target`;

  const nowTime = new Date().toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit' });

  // Isi Tab Panel Tujuan Pembelajaran
  let tabContentHtml = '';
  if (trnTujuanActiveTabV42 === 'peta') {
    const itemsHtml = goalsList.map((gText, idx) => {
      const isChecked = !!trnTujuanGoalChecksMapV42[`${mod.id}_goal_${idx}`];
      return `
        <div class="tujuan-goal-check-item-v42 ${isChecked ? 'goal-checked' : ''}" onclick="toggleTujuanGoalCheckItemV42('${mod.id.replace(/'/g, "\\'")}', ${idx}, ${goalsList.length})">
          <div style="width:26px; height:26px; border-radius:8px; background:${isChecked ? '#10b981' : '#ede9fe'}; color:${isChecked ? '#ffffff' : '#6d28d9'}; display:flex; align-items:center; justify-content:center; font-size:13px; font-weight:900; flex-shrink:0; margin-top:1px;">
            ${isChecked ? '<i class="fa-solid fa-check"></i>' : (idx + 1)}
          </div>
          <div style="flex:1; min-width:0;">
            <div style="font-size:13.8px; font-weight:700; color:var(--text-main); line-height:1.55;">
              ${escapeHtml(gText)}
            </div>
            <div style="font-size:11px; font-weight:800; color:${isChecked ? '#059669' : '#7c3aed'}; margin-top:3px;">
              ${isChecked ? '✓ Target capaian ini sudah kamu tandai dipahami' : 'Klik untuk menandai bahwa kamu siap mencapai target ini'}
            </div>
          </div>
        </div>`;
    }).join('');

    tabContentHtml = `
      <div style="display:flex; justify-content:space-between; align-items:center; flex-wrap:wrap; gap:8px; margin-bottom:12px;">
        <div style="font-size:13px; font-weight:800; color:#4c1d95;">
          <i class="fa-solid fa-list-check" style="color:#7c3aed;"></i> Peta Indikator Capaian Tujuan Pembelajaran (${checkedGoalsCount}/${goalsList.length} Dipahami)
        </div>
        <span style="background:#ede9fe; color:#5b21b6; padding:3px 10px; border-radius:99px; font-size:11px; font-weight:900;">Kesiapan Tujuan: ${goalsPct}%</span>
      </div>
      ${itemsHtml}
      <div style="display:flex; flex-wrap:wrap; gap:6px; margin-top:12px; padding-top:10px; border-top:1px dashed #e2e8f0; align-items:center;">
        <span style="font-size:11px; font-weight:800; color:#64748b;"><i class="fa-solid fa-tags" style="color:#7c3aed;"></i> Fokus Kompetensi Bab:</span>
        ${keywordTags.map(kw => `<span style="background:#f5f3ff; color:#6d28d9; border:1px solid #ddd6fe; padding:3px 10px; border-radius:99px; font-size:11px; font-weight:800;">#${escapeHtml(kw)}</span>`).join('')}
      </div>`;
  } else if (trnTujuanActiveTabV42 === 'narasi') {
    tabContentHtml = `
      <div style="font-size:13px; font-weight:800; color:#4c1d95; margin-bottom:8px;">
        <i class="fa-solid fa-book-open-reader" style="color:#7c3aed;"></i> Deskripsi Utuh Tujuan Pembelajaran Terbimbing
      </div>
      <p style="font-size:15px; font-weight:600; color:var(--text-main); line-height:1.75; margin-bottom:14px;">
        ${formatSoalText(mod.tujuan || '')}
      </p>
      <div style="display:flex; justify-content:space-between; align-items:center; flex-wrap:wrap; gap:10px; padding-top:10px; border-top:1px dashed #e2e8f0; font-size:12px; color:#64748b; font-weight:700;">
        <span><i class="fa-solid fa-chalkboard-user" style="color:#6d28d9;"></i> Disusun oleh: <b style="color:var(--text-main);">${escapeHtml(mod.pembuat || 'Guru Pengampu SMPN 3 Bangil')}</b></span>
        <button type="button" onclick="bacakanTeksTujuanSpesifikV42()" style="background:#ede9fe; color:#5b21b6; border:1px solid #c4b5fd; padding:6px 13px; border-radius:99px; font-size:11.5px; font-weight:800; cursor:pointer;">
          <i class="fa-solid fa-volume-high"></i> Dengarkan Audio Tujuan Pembelajaran
        </button>
      </div>`;
  } else {
    tabContentHtml = `
      <div style="font-size:13px; font-weight:800; color:#4c1d95; margin-bottom:8px;">
        <i class="fa-solid fa-wand-magic-sparkles" style="color:#7c3aed;"></i> Mengapa Materi Ini Penting Untuk Masa Depanmu?
      </div>
      <div style="font-size:13.8px; color:var(--text-main); line-height:1.65; background:#f5f3ff; border-left:4px solid #7c3aed; padding:12px 16px; border-radius:12px; margin-bottom:12px;">
        Memahami tujuan pembelajaran sejak awal membantumu fokus pada <b>${subArr.length} pilar konsep utama</b> di bab ini, sehingga kamu tidak sekadar menghafal teks, melainkan mampu mengambil keputusan cerdas di dunia nyata dan siap menaklukkan soal-soal HOTS!
      </div>
      <button type="button" onclick="toggleAITutorDrawer(); setTimeout(()=>kirimPertanyaanCepatAI('Jelaskan secara singkat dan seru apa manfaat utama mempelajari tujuan pembelajaran bab ini bagi siswa SMP Kelas 7!'), 250);" style="background:linear-gradient(135deg, #7c3aed, #6d28d9); color:white; border:none; padding:9px 16px; border-radius:11px; font-size:12px; font-weight:800; cursor:pointer; display:inline-flex; align-items:center; gap:7px;">
        <i class="fa-solid fa-robot"></i> Diskusikan Tujuan Bab Ini Bersama AI Tutor
      </button>`;
  }

  return `
    <div class="tujuan-hero-banner-v42" id="tujuan-hero-banner-v42">
      <div class="tujuan-hero-top-grid-v42">
        <div>
          <div class="tujuan-live-status-row-v42">
            <span class="tujuan-live-pill-v42"><span class="live-dot"></span> LIVE NOW</span>
            <span class="tujuan-time-meta-v42">&bull; SESI AKTIF (${escapeHtml(nowTime)} WIB) &bull; TUJUAN PEMBELAJARAN TERBIMBING</span>
          </div>

          <h2 class="tujuan-hero-headline-v42">${escapeHtml(mod.judul || 'Modul Pembelajaran Konstruktif')}</h2>

          <!-- 3 Kartu Glassmorphism (Persis Struktur Subject | Grade | Students Online pada Gambar Referensi) -->
          <div class="tujuan-meta-cards-row-v42">
            <div class="tujuan-meta-glass-card-v42">
              <div class="tujuan-meta-lbl-v42">Mata Pelajaran</div>
              <div class="tujuan-meta-val-v42" title="${escapeHtml(activeLMSSubject || 'Mapel')}">${escapeHtml(activeLMSSubject || 'Informatika')}</div>
            </div>
            <div class="tujuan-meta-glass-card-v42">
              <div class="tujuan-meta-lbl-v42">Kelas &amp; Penyusun</div>
              <div class="tujuan-meta-val-v42" title="${escapeHtml(mod.pembuat || 'Guru')}">Kls ${escapeHtml(studentData.kelas || '7')}, ${escapeHtml((mod.pembuat || 'Guru').split(',')[0])}</div>
            </div>
            <div class="tujuan-meta-glass-card-v42">
              <div class="tujuan-meta-lbl-v42">Target &amp; Keaktifan</div>
              <div class="tujuan-meta-val-v42">${escapeHtml(studentsOnlineDisplay)}</div>
            </div>
          </div>

          <!-- Barisan Tombol Aksi Utama (Persis Tombol Pill "Start the class (>)" pada Gambar Referensi) -->
          <div class="tujuan-cta-actions-row-v42">
            <button type="button" class="tujuan-btn-start-pill-v42" onclick="switchLMSStep(2)">
              <span>Mulai Eksplorasi Materi</span>
              <span class="arrow-circle"><i class="fa-solid fa-chevron-right"></i></span>
            </button>
            <button type="button" class="tujuan-btn-secondary-pill-v42" onclick="bacakanTeksTujuanSpesifikV42()">
              <i class="fa-solid fa-volume-high"></i> <span>Dengarkan Tujuan</span>
            </button>
          </div>
        </div>

        <!-- Ilustrasi 3D Topi Toga Wisuda (Graduation Cap) Menggantikan Gambar Daun -->
        <div class="tujuan-toga-art-wrap-v42">
          ${get3DGraduationCapSVGHTMLV42()}
        </div>
      </div>

      <!-- Panel Interaktif Tujuan Pembelajaran Terbimbing (3 Tab Canggih: Peta Capaian, Narasi Utuh, & Manfaat AI) -->
      <div class="tujuan-interactive-panel-v42">
        <div class="tujuan-tabs-bar-v42">
          <button type="button" class="tujuan-tab-pill-v42 ${trnTujuanActiveTabV42 === 'peta' ? 'active' : ''}" onclick="switchTujuanInteractiveTabV42('peta')">
            <i class="fa-solid fa-bullseye"></i> Peta Capaian &amp; Ceklis Tujuan (${checkedGoalsCount}/${goalsList.length})
          </button>
          <button type="button" class="tujuan-tab-pill-v42 ${trnTujuanActiveTabV42 === 'narasi' ? 'active' : ''}" onclick="switchTujuanInteractiveTabV42('narasi')">
            <i class="fa-solid fa-align-left"></i> Narasi Lengkap Tujuan
          </button>
          <button type="button" class="tujuan-tab-pill-v42 ${trnTujuanActiveTabV42 === 'ai' ? 'active' : ''}" onclick="switchTujuanInteractiveTabV42('ai')">
            <i class="fa-solid fa-wand-magic-sparkles"></i> Kompas Manfaat &amp; Tanya AI
          </button>
        </div>
        <div>
          ${tabContentHtml}
        </div>
      </div>
    </div>`;
}

function bacakanTeksTujuanSpesifikV42() {
  if (!('speechSynthesis' in window) || !activeLMSModule) {
    showStudentToast('Fitur narator suara tidak didukung di browser ini.', 'warning');
    return;
  }
  window.speechSynthesis.cancel();
  const teks = `Tujuan Pembelajaran untuk bab ${activeLMSModule.judul}. ${activeLMSModule.tujuan || ''}`;
  const utter = new SpeechSynthesisUtterance(teks);
  utter.lang = 'id-ID';
  utter.rate = 0.98;
  window.speechSynthesis.speak(utter);
  showStudentToast('Membacakan Tujuan Pembelajaran Terbimbing...', 'info');
}

// Suntikkan Hero Card Tujuan Pembelajaran V42 ke Tahap 1 di dalam Ruang Baca Modul
const _v41OrigRenderConstructiveWorkspace = renderConstructiveWorkspace;
renderConstructiveWorkspace = function() {
  _v41OrigRenderConstructiveWorkspace();
  if (!activeLMSModule || activeLMSStep !== 1) return;

  const flowContainer = document.querySelector('.trn-article-content-flow');
  if (!flowContainer) return;

  // Cari kotak hijau Tujuan Pembelajaran lama di Tahap 1 dan ganti dengan Hero Card Lavender + Topi Toga 3D V42
  const firstBox = flowContainer.querySelector('div[style*="linear-gradient(135deg, #ecfdf5, #d1fae5)"]');
  if (firstBox) {
    const k = activeLMSModule.konten || {};
    let galeriTujuan = Array.isArray(k.galeri_tujuan) ? k.galeri_tujuan : (k.gambar_tujuan ? [{ url: k.gambar_tujuan, caption: 'Ilustrasi Visual Materi' }] : []);
    let visualTujuanHtml = '';
    if (galeriTujuan.length > 0) {
      let itemsHtml = galeriTujuan.map((g, gIdx) => `
        <div class="student-visual-card">
          <img src="${g.url}" alt="Gambar Materi ${gIdx + 1}" onclick="openLightbox('${g.url}')" title="Klik untuk memperbesar gambar">
          <div style="padding:10px 14px; display:flex; justify-content:space-between; align-items:center; gap:8px;">
            <span style="font-size:12.5px; font-weight:800; color:#065f46; text-align:left;"><i class="fa-solid fa-image" style="color:#059669;"></i> ${escapeHtml(g.caption || ('Media Visual #' + (gIdx + 1)))}</span>
            <button onclick="openLightbox('${g.url}')" style="background:#059669; color:white; border:none; padding:5px 10px; border-radius:8px; font-size:11px; font-weight:800; cursor:pointer; white-space:nowrap;">
              <i class="fa-solid fa-magnifying-glass-plus"></i> Perbesar
            </button>
          </div>
        </div>`).join('');

      visualTujuanHtml = `
        <div class="student-visual-tujuan-box">
          <div style="display:flex; justify-content:space-between; align-items:center; flex-wrap:wrap; gap:8px;">
            <div style="font-size:14.5px; font-weight:800; color:#047857;">
              <i class="fa-solid fa-chalkboard-user"></i> Media Visual &amp; Ilustrasi Materi dari Guru (Klik Gambar untuk Zoom)
            </div>
            <span style="background:#d1fae5; color:#065f46; padding:4px 10px; border-radius:99px; font-size:11px; font-weight:800;">${galeriTujuan.length} Gambar Pendukung</span>
          </div>
          <div class="student-visual-grid">${itemsHtml}</div>
        </div>`;
    }

    const pemantikBoxHtml = `
      <div style="background:white; border-radius:22px; padding:24px; border:1.5px solid #e2e8f0; border-left:6px solid #7c3aed; box-shadow:0 8px 25px rgba(109, 40, 217, 0.06); margin-bottom:20px;">
        <h4 style="font-size:16px; font-weight:800; color:#5b21b6; margin-bottom:10px;"><i class="fa-solid fa-wand-magic-sparkles"></i> Pertanyaan Pemantik &amp; Apersepsi Kontekstual</h4>
        <p style="font-size:15.5px; color:var(--text-main); line-height:1.8;">${formatSoalText(k.pemantik || 'Mari amati bagaimana topik ini bekerja dalam kehidupan sehari-hari kita!')}</p>
      </div>`;

    firstBox.outerHTML = buildTujuanPembelajaranHeroCardV42() + visualTujuanHtml + buildStudentVideoAnalysisHubHTML(activeLMSModule) + pemantikBoxHtml;
  }
};


// =========================================================================
// D. SISTEM PUSAT NOTIFIKASI & FOLLOW-UP AKTIVITAS REAL-TIME PER AKUN SISWA (V42)
// =========================================================================

function getStudentNotifStorageKeyV42() {
  const emailKey = (studentData && (studentData.email || studentData.name)) ? (studentData.email || studentData.name).toLowerCase().replace(/\s+/g, '_') : 'guest';
  return `sicibinaga_notifs_v42_${emailKey}`;
}

function getStudentAccountMetaKeyV42() {
  const emailKey = (studentData && (studentData.email || studentData.name)) ? (studentData.email || studentData.name).toLowerCase().replace(/\s+/g, '_') : 'guest';
  return `sicibinaga_notif_meta_v42_${emailKey}`;
}

function loadStudentNotificationsListV42() {
  try {
    const raw = localStorage.getItem(getStudentNotifStorageKeyV42());
    const arr = raw ? JSON.parse(raw) : [];
    return Array.isArray(arr) ? arr : [];
  } catch (e) {
    return [];
  }
}

function saveStudentNotificationsListV42(list) {
  try {
    const trimmed = (Array.isArray(list) ? list : []).slice(0, 80);
    localStorage.setItem(getStudentNotifStorageKeyV42(), JSON.stringify(trimmed));
  } catch (e) {}
}

function pushStudentNotificationV42(notifObj, showToastPopup = true) {
  if (!studentData || (!studentData.name && !studentData.email)) return;
  let list = loadStudentNotificationsListV42();
  const notifId = notifObj.id || ('NOTIF-' + Date.now() + '-' + Math.random().toString(36).substring(2, 6));

  // Cegah duplikasi untuk ID event yang sama
  if (list.some(x => x.id === notifId)) {
    return;
  }

  const nowStr = notifObj.time || new Date().toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit' }) + ' WIB';
  const newEntry = {
    id: notifId,
    category: notifObj.category || 'XP_BADGE', // 'DISCUSSION' | 'XP_BADGE' | 'MODULE'
    title: notifObj.title || 'Aktivitas Baru Tercatat',
    desc: notifObj.desc || '',
    time: nowStr,
    unread: notifObj.unread !== false,
    mapel: notifObj.mapel || activeLMSSubject || '',
    idModul: notifObj.idModul || (activeLMSModule ? activeLMSModule.id : ''),
    idQna: notifObj.idQna || '',
    targetStep: notifObj.targetStep || 1,
    targetNav: notifObj.targetNav || '',
    actionLabel: notifObj.actionLabel || 'Buka & Tindak Lanjuti',
    icon: notifObj.icon || 'fa-bell',
    color: notifObj.color || '#4f46e5',
    bg: notifObj.bg || '#eef2ff'
  };

  list.unshift(newEntry);
  saveStudentNotificationsListV42(list);
  updateNotificationBellBadgeV42();

  const pop = document.getElementById('eduvance-notification-popover-v42');
  if (pop && !pop.classList.contains('hidden')) {
    renderStudentNotificationCenterListV42();
  }

  if (showToastPopup && typeof showStudentToast === 'function') {
    showStudentToast(`🔔 <b>${escapeHtml(newEntry.title)}</b>`, 'info');
  }
}

function updateNotificationBellBadgeV42() {
  const list = loadStudentNotificationsListV42();
  const unreadCount = list.filter(x => x.unread).length;
  const badgeEl = document.getElementById('eduvance-notif-count-badge');
  const bellBtn = document.getElementById('btn-eduvance-notif-bell');
  const popUnreadEl = document.getElementById('notif-pop-unread-pill-v42');

  if (badgeEl) {
    if (unreadCount > 0) {
      badgeEl.classList.remove('hidden');
      badgeEl.innerText = unreadCount > 99 ? '99+' : unreadCount;
    } else {
      badgeEl.classList.add('hidden');
    }
  }
  if (bellBtn) {
    const ic = bellBtn.querySelector('i');
    if (ic) ic.className = unreadCount > 0 ? 'fa-solid fa-bell' : 'fa-regular fa-bell';
  }
  if (popUnreadEl) {
    popUnreadEl.innerText = `${unreadCount} Belum Dibaca`;
  }
}

function toggleStudentNotificationCenterV42() {
  playStudentSFX('click');
  const pop = document.getElementById('eduvance-notification-popover-v42');
  if (!pop) return;

  // Tutup popover tema jika sedang terbuka
  const comfortPop = document.getElementById('eduvance-comfort-popover');
  if (comfortPop) comfortPop.classList.add('hidden');

  const isHidden = pop.classList.toggle('hidden');
  if (!isHidden) {
    syncLocalProgressAndBadgesToNotificationsV42(false);
    renderStudentNotificationCenterListV42();
    pollStudentNotificationsFromServerV42(true);
  }
}

function switchStudentNotifFilterV42(filterKey) {
  playStudentSFX('click');
  studentNotifActiveFilterV42 = filterKey || 'ALL';
  ['ALL', 'UNREAD', 'DISCUSSION', 'XP_BADGE', 'MODULE'].forEach(k => {
    const b = document.getElementById('ntab-v42-' + k);
    if (b) b.classList.toggle('active', k === studentNotifActiveFilterV42);
  });
  renderStudentNotificationCenterListV42();
}

function markAllStudentNotificationsReadV42() {
  playStudentSFX('click');
  const list = loadStudentNotificationsListV42();
  list.forEach(item => { item.unread = false; });
  saveStudentNotificationsListV42(list);
  updateNotificationBellBadgeV42();
  renderStudentNotificationCenterListV42();
  showStudentToast('Seluruh notifikasi telah ditandai sudah dibaca.', 'success');
}

function executeNotificationFollowUpV42(notifId) {
  playStudentSFX('click');
  const list = loadStudentNotificationsListV42();
  const item = list.find(x => x.id === notifId);
  if (!item) return;

  item.unread = false;
  saveStudentNotificationsListV42(list);
  updateNotificationBellBadgeV42();

  const pop = document.getElementById('eduvance-notification-popover-v42');
  if (pop) pop.classList.add('hidden');

  // Arahkan siswa langsung ke lokasi aktivitas (Follow-Up Action)
  if (item.targetNav === 'grades') {
    if (typeof kembaliKeDashboardSiswa === 'function' && !document.getElementById('lms-learning-section')?.classList.contains('hidden')) {
      document.getElementById('lms-learning-section').classList.add('hidden');
      document.getElementById('dashboard-section').classList.remove('hidden');
    }
    switchEduvanceNav('grades');
    return;
  }

  if (item.mapel) {
    openStudentLMS(item.mapel);
    setTimeout(() => {
      const modules = window.currentSubjectModulesList || [];
      let mIdx = 0;
      if (item.idModul) {
        const foundIdx = modules.findIndex(m => m.id === item.idModul);
        if (foundIdx !== -1) mIdx = foundIdx;
      }
      if (typeof masukKeRuangBacaModulV33 === 'function') {
        masukKeRuangBacaModulV33(mIdx, item.targetStep || 1);
      } else {
        selectStudentLMSModule(mIdx);
        switchLMSStep(item.targetStep || 1);
      }

      if (item.category === 'DISCUSSION' || item.idQna) {
        setTimeout(() => {
          switchTrnRightTabV37('discussion');
          if (item.idQna) {
            trnExpandedInlineThreadIdV39 = item.idQna;
            renderTrnRightSidebarContentV37();
          }
        }, 200);
      }
    }, 150);
  }
}

function renderStudentNotificationCenterListV42() {
  const box = document.getElementById('eduvance-notif-list-body-v42');
  if (!box) return;
  const list = loadStudentNotificationsListV42();

  const filtered = list.filter(item => {
    if (studentNotifActiveFilterV42 === 'UNREAD') return !!item.unread;
    if (studentNotifActiveFilterV42 === 'DISCUSSION') return item.category === 'DISCUSSION';
    if (studentNotifActiveFilterV42 === 'XP_BADGE') return item.category === 'XP_BADGE';
    if (studentNotifActiveFilterV42 === 'MODULE') return item.category === 'MODULE';
    return true;
  });

  if (filtered.length === 0) {
    box.innerHTML = `
      <div style="text-align:center; padding:36px 16px; color:#94a3b8;">
        <i class="fa-regular fa-bell-slash" style="font-size:32px; color:#cbd5e1; margin-bottom:10px; display:block;"></i>
        <div style="font-size:13px; font-weight:800; color:var(--text-main);">Belum Ada Notifikasi pada Kategori Ini</div>
        <div style="font-size:11.5px; margin-top:4px;">Seluruh pembaruan XP, kenaikan level, lencana, kuis, dan balasan diskusi akan muncul secara real-time di sini.</div>
      </div>`;
    return;
  }

  box.innerHTML = filtered.map(item => {
    const safeId = item.id.replace(/'/g, "\\'");
    return `
      <div class="eduvance-notif-item-card ${item.unread ? 'unread' : ''}" onclick="executeNotificationFollowUpV42('${safeId}')">
        <div class="eduvance-notif-icon-circle" style="background:${item.bg || '#eef2ff'}; color:${item.color || '#4f46e5'};">
          <i class="fa-solid ${item.icon || 'fa-bell'}"></i>
        </div>
        <div style="flex:1; min-width:0;">
          <div style="display:flex; justify-content:space-between; align-items:flex-start; gap:6px;">
            <div style="font-size:12.8px; font-weight:800; color:var(--text-main); line-height:1.35;">${escapeHtml(item.title)}</div>
            ${item.unread ? `<span style="width:8px; height:8px; border-radius:50%; background:#4f46e5; flex-shrink:0; margin-top:4px;"></span>` : ''}
          </div>
          <div style="font-size:11.8px; color:#475569; line-height:1.45; margin-top:3px;">${escapeHtml(item.desc)}</div>
          <div style="display:flex; justify-content:space-between; align-items:center; margin-top:7px; gap:8px;">
            <span style="font-size:10px; color:#94a3b8; font-weight:700;"><i class="fa-regular fa-clock"></i> ${escapeHtml(item.time)}</span>
            <button type="button" class="eduvance-notif-followup-btn">
              <span>${escapeHtml(item.actionLabel || 'Tindak Lanjuti')}</span>
              <i class="fa-solid fa-arrow-right"></i>
            </button>
          </div>
        </div>
      </div>`;
  }).join('');
}

// Deteksi otomatis setiap kali XP bertambah, Siswa Naik Level, atau Lencana Baru Terbuka
function syncLocalProgressAndBadgesToNotificationsV42(allowToast = true) {
  if (!studentData || (!studentData.name && !studentData.email)) return;
  let meta = {};
  try {
    meta = JSON.parse(localStorage.getItem(getStudentAccountMetaKeyV42()) || '{}');
  } catch (e) { meta = {}; }

  const currentXP = (globalLMSDashboard.totalXP || 0) + (typeof getStudentBonusActivityXP === 'function' ? getStudentBonusActivityXP() : 0);
  const rankInfo = typeof getStudentRankInfoV15 === 'function' ? getStudentRankInfoV15(currentXP) : { current: { level: 1, title: 'Tunas Pembelajar' } };
  const currentLevel = rankInfo.current.level;

  // 1. Notifikasi Selamat Datang & Orientasi Awal Akun
  if (!meta.welcomeSent) {
    meta.welcomeSent = true;
    pushStudentNotificationV42({
      id: `NOTIF-WELCOME-${studentData.email || studentData.name}`,
      category: 'XP_BADGE',
      title: `👋 Selamat Datang, ${studentData.name}!`,
      desc: `Akun belajarmu di Kelas ${studentData.kelas || '7'} aktif. Saat ini kamu berada di Level ${currentLevel} (${rankInfo.current.title}) dengan ${currentXP} XP.`,
      targetNav: 'grades',
      actionLabel: 'Cek Peta Level & Lencana',
      icon: 'fa-graduation-cap',
      color: '#059669',
      bg: '#ecfdf5'
    }, false);
  }

  // 2. Deteksi Kenaikan Level (Level Up!)
  if (meta.lastLevel !== undefined && currentLevel > meta.lastLevel) {
    pushStudentNotificationV42({
      id: `NOTIF-LEVELUP-LV${currentLevel}`,
      category: 'XP_BADGE',
      title: `🎉 NAIK LEVEL! Kamu Mencapai Level ${currentLevel}: ${rankInfo.current.title}`,
      desc: `Luar biasa! Total perolehan XP kamu kini mencapai ${currentXP} XP. Terus pertahankan semangat eksplorasimu!`,
      targetNav: 'grades',
      actionLabel: 'Lihat Gelar Level Baru',
      icon: 'fa-crown',
      color: '#059669',
      bg: '#fef3c7'
    }, allowToast);
  }

  // 3. Deteksi Penambahan Poin XP
  if (meta.lastXP !== undefined && currentXP > meta.lastXP) {
    const diffXP = currentXP - meta.lastXP;
    pushStudentNotificationV42({
      id: `NOTIF-XPGAIN-${currentXP}`,
      category: 'XP_BADGE',
      title: `⚡ +${diffXP} Poin XP Baru Diperoleh! (Total: ${currentXP} XP)`,
      desc: `Aktivitas belajar terverifikasimu berhasil menambah +${diffXP} XP. ${rankInfo.xpNeededText}`,
      targetNav: 'grades',
      actionLabel: 'Lihat Progres XP',
      icon: 'fa-bolt',
      color: '#0284c7',
      bg: '#e0f2fe'
    }, allowToast);
  }

  // 4. Deteksi Pembukaan Lencana Kehormatan Baru
  const unlockedBadges = (window.currentStudentBadgesListV16 || []).filter(b => b && b.unlocked);
  const prevBadgeNames = Array.isArray(meta.unlockedBadgeNames) ? meta.unlockedBadgeNames : [];
  unlockedBadges.forEach(b => {
    if (!prevBadgeNames.includes(b.name)) {
      pushStudentNotificationV42({
        id: `NOTIF-BADGE-${b.name.replace(/\s+/g, '_')}`,
        category: 'XP_BADGE',
        title: `🏅 Lencana Baru Terbuka: ${b.name} (${b.rarity})`,
        desc: `${b.desc}`,
        targetNav: 'grades',
        actionLabel: 'Buka Koleksi Lencana',
        icon: b.icon || 'fa-award',
        color: '#7c3aed',
        bg: '#f5f3ff'
      }, allowToast);
      prevBadgeNames.push(b.name);
    }
  });

  meta.lastXP = currentXP;
  meta.lastLevel = currentLevel;
  meta.unlockedBadgeNames = prevBadgeNames;
  localStorage.setItem(getStudentAccountMetaKeyV42(), JSON.stringify(meta));
  updateNotificationBellBadgeV42();
}

// Sinkronisasi Real-Time ke Server untuk Mendeteksi Balasan Diskusi dari Guru / Siswa Lain & Progres Kuis/Modul
function pollStudentNotificationsFromServerV42(silent = true) {
  if (!studentData || (!studentData.name && !studentData.email)) return;
  const statusEl = document.getElementById('notif-pop-sync-status-v42');
  if (statusEl && !silent) {
    statusEl.innerHTML = `<i class="fa-solid fa-spinner fa-spin" style="color:#4f46e5;"></i> Memeriksa balasan diskusi & aktivitas terbaru...`;
  }

  google.script.run.withSuccessHandler(res => {
    if (statusEl) {
      const nowTime = new Date().toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit', second: '2-digit' });
      statusEl.innerHTML = `<i class="fa-solid fa-circle-check" style="color:#10b981;"></i> Terupdate Real-Time (${nowTime})`;
    }
    if (res && res.success && Array.isArray(res.serverEvents)) {
      const existingList = loadStudentNotificationsListV42();
      const existingIds = new Set(existingList.map(x => x.id));
      let newRepliesCount = 0;

      res.serverEvents.forEach(ev => {
        if (!existingIds.has(ev.id)) {
          pushStudentNotificationV42(ev, !silent || ev.category === 'DISCUSSION');
          if (ev.category === 'DISCUSSION') newRepliesCount++;
        }
      });

      if (!silent && newRepliesCount === 0) {
        showStudentToast('Pusat Notifikasi sudah menampilkan data terbaru!', 'info');
      }
    }
  }).getStudentRealtimeNotificationsFeedV42({
    nama: studentData.name || '',
    email: studentData.email || '',
    kelas: studentData.kelas || ''
  });
}

