function simpanFotoDanKataMutiaraSiswaV44() {
  playStudentSFX('click');
  const mottoEl = document.getElementById('inp-student-custom-motto-v44');
  const mottoVal = (mottoEl ? mottoEl.value : '').trim() || 'Belajar hari ini adalah investasi terbaik untuk masa depanku! 🌟';
  const currentProf = getStudentCustomProfileV44();
  const newAvatarUrl = window.__pendingAvatarDataUrlV44 !== undefined ? window.__pendingAvatarDataUrlV44 : currentProf.avatarUrl;

  const xpNow = (globalLMSDashboard.totalXP || 0) + (typeof getStudentBonusActivityXP === 'function' ? getStudentBonusActivityXP() : 0);
  const rankObj = typeof getStudentRankInfoV15 === 'function' ? getStudentRankInfoV15(xpNow) : { current: { level: 1, title: 'Tunas Pembelajar' } };

  const savedLocal = {
    avatarUrl: newAvatarUrl,
    motto: mottoVal,
    updatedAt: new Date().toISOString()
  };
  try {
    localStorage.setItem(getStudentCustomProfileStorageKeyV44(), JSON.stringify(savedLocal));
  } catch (e) {}

  if (studentData && studentData.name) {
    globalStudentProfilesMapV44[studentData.name.toLowerCase().trim()] = {
      email: studentData.email || '',
      nama: studentData.name,
      kelas: studentData.kelas || '7',
      avatarUrl: newAvatarUrl,
      motto: mottoVal,
      level: rankObj.current.level,
      totalXP: xpNow
    };
  }

  syncStudentCustomAvatarAndMottoToUIV44();

  const btn = document.getElementById('btn-save-custom-profile-v44');
  if (btn) {
    btn.innerHTML = '<i class="fa-solid fa-spinner fa-spin"></i> Menyimpan ke Server...';
    btn.disabled = true;
  }

  google.script.run.withSuccessHandler(res => {
    if (btn) {
      btn.innerHTML = '<i class="fa-solid fa-check-double"></i> Foto & Status Motivasi Tersimpan!';
      btn.disabled = false;
    }
    if (res && res.success && res.profile && res.profile.avatarUrl) {
      savedLocal.avatarUrl = res.profile.avatarUrl;
      try { localStorage.setItem(getStudentCustomProfileStorageKeyV44(), JSON.stringify(savedLocal)); } catch (e) {}
      if (studentData && studentData.name) {
        globalStudentProfilesMapV44[studentData.name.toLowerCase().trim()].avatarUrl = res.profile.avatarUrl;
      }
      syncStudentCustomAvatarAndMottoToUIV44();
    }
    playStudentSFX('success');
    showStudentToast('Profil, Foto & Kata Mutiara berhasil diperbarui!', 'success');
    if (typeof renderTrnRightSidebarContentV37 === 'function' && activeLMSModule) {
      renderTrnRightSidebarContentV37();
    }
  }).withFailureHandler(() => {
    if (btn) {
      btn.innerHTML = '<i class="fa-solid fa-floppy-disk"></i> Simpan Foto & Status Motivasi';
      btn.disabled = false;
    }
    showStudentToast('Tersimpan di perangkat! Sinkronisasi server akan dilanjutkan otomatis.', 'info');
  }).saveStudentCustomProfileV44({
    email: (studentData && studentData.email) || '',
    nama: (studentData && studentData.name) || 'Siswa',
    kelas: (studentData && studentData.kelas) || '7',
    avatarBase64: window.__pendingAvatarDataUrlV44 || '',
    avatarUrl: currentProf.avatarUrl || '',
    motto: mottoVal,
    level: rankObj.current.level,
    totalXP: xpNow
  });
}

