function buildArenaPlayingStageHTMLV45(displayCoins) {
  const qs = liveArenaStateV45.questions || [];
  const q = qs[liveArenaStateV45.currentIndex] || {
    soal: 'Pertanyaan Turnamen',
    a: 'Opsi A', b: 'Opsi B', c: 'Opsi C', d: 'Opsi D', kunci: 'A'
  };
  const totalQ = qs.length;
  const curNo = liveArenaStateV45.currentIndex + 1;
  const sel = liveArenaStateV45.selectedOpt;
  const rev = liveArenaStateV45.isRevealed;
  const kunci = (q.kunci || 'A').toUpperCase();

  const defaultIllust = 'https://images.unsplash.com/photo-1516321318423-f06f85e504b3?auto=format&fit=crop&w=900&q=80';
  const imgUrl = q.imageUrl && q.imageUrl.trim() !== '' ? q.imageUrl : defaultIllust;

  const optsHtml = ['A', 'B', 'C', 'D'].map(letter => {
    const textOpt = q[letter.toLowerCase()] || q[letter] || '';
    if (!textOpt) return '';

    let stateClass = '';
    let rightBadgeHtml = '';

    if (!rev && sel === letter) {
      stateClass = 'selected-pending';
      rightBadgeHtml = `<span class="arena-cancel-chip-v45" onclick="event.stopPropagation(); cancelArenaOptionSelectionV45();">Cancel</span>`;
    } else if (rev) {
      if (letter === kunci) {
        stateClass = 'revealed-correct';
        rightBadgeHtml = `<i class="fa-solid fa-circle-check" style="font-size:18px;"></i>`;
      } else if (sel === letter && letter !== kunci) {
        stateClass = 'revealed-wrong';
        rightBadgeHtml = `<i class="fa-solid fa-circle-xmark" style="font-size:18px;"></i>`;
      }
    }

    return `
      <button type="button" class="arena-opt-pill-v45 ${stateClass}" onclick="selectArenaOptionV45('${letter}')">
        <span>${escapeHtml(textOpt)}</span>
        ${rightBadgeHtml}
      </button>`;
  }).join('');

  let bottomActionHtml = '';
  if (sel && !rev) {
    bottomActionHtml = `
      <button type="button" class="arena-claim-coins-btn-v45" onclick="lockAndVerifyArenaAnswerV45()">
        <i class="fa-solid fa-bolt"></i> KUNCI JAWABAN &amp; CEK SKOR!
      </button>`;
  } else if (rev) {
    const isCorrect = (sel === kunci);
    bottomActionHtml = `
      <button type="button" class="arena-claim-coins-btn-v45" onclick="proceedAfterArenaRevealV45()" style="background:${isCorrect ? 'linear-gradient(135deg, #10b981, #059669)' : 'linear-gradient(135deg, #6366f1, #4f46e5)'};">
        ${isCorrect ? `🪙 CLAIM COINS (+${liveArenaStateV45.lastEarnedCoins} KOIN)` : 'LANJUT KE SOAL BERIKUTNYA &rarr;'}
      </button>`;
  }

  return `
    <div class="arena-dark-stage-v45">
      <div>
        <div class="arena-stage-topbar-v45">
          <button type="button" class="arena-btn-close-stage-v45" onclick="exitArenaToLobbyV45()" title="Keluar ke Lobby Arena">
            <i class="fa-solid fa-xmark"></i>
          </button>

          <div id="arena-live-timer-circle-v45" class="arena-timer-circle-v45 ${liveArenaStateV45.timeLeft <= 5 ? 'urgent' : ''}">
            ${String(liveArenaStateV45.timeLeft).padStart(2, '0')}
          </div>

          <div class="arena-coin-pill-v45" style="background:rgba(255,255,255,0.15); color:#ffffff; border-color:rgba(255,255,255,0.28);">
            <span>${displayCoins}</span>
            <span class="arena-coin-icon-v45">★</span>
          </div>
        </div>

        <div style="text-align:center; font-size:13px; font-weight:800; color:#ddd6fe; margin-bottom:10px;">
          ${escapeHtml(liveArenaStateV45.activeSubject)} Live Quiz &bull; Streak: 🔥 ${liveArenaStateV45.streak}x
        </div>

        <div class="arena-question-media-box-v45">
          <img src="${imgUrl}" alt="Ilustrasi Soal">
        </div>

        <div style="font-size:12px; font-weight:800; color:#c4b5fd; margin-bottom:6px;">
          Question ${curNo} of ${totalQ}
        </div>
        <div style="font-size:20px; font-weight:900; line-height:1.35; color:#ffffff;">
          ${formatSoalText(q.soal)}
        </div>

        <div class="arena-options-stack-v45">
          ${optsHtml}
        </div>
      </div>

      <div>
        ${bottomActionHtml}
      </div>
    </div>`;
}

