// --- BAGIAN A: ANTI-STUCK IPHONE/IOS DENGAN ANTI-CHEAT VIEWPORT LOCKDOWN ---
function isAppleIOSDeviceV46() {
  const ua = navigator.userAgent || '';
  return /iPhone|iPod|iPad/i.test(ua) || (navigator.platform === 'MacIntel' && navigator.maxTouchPoints > 1);
}

function isNativeFullscreenSupportedOnDeviceV46() {
  // iPhone iOS tidak memiliki documentElement.requestFullscreen().
  // Jika dipaksa menampilkan popup "Kembali ke Fullscreen", iPhone akan stuck selamanya.
  if (/iPhone|iPod/i.test(navigator.userAgent || '')) return false;
  const elem = document.documentElement;
  if (!elem) return false;
  const hasFn = typeof elem.requestFullscreen === 'function' ||
                typeof elem.webkitRequestFullscreen === 'function' ||
                typeof elem.msRequestFullscreen === 'function';
  if (!hasFn) return false;
  if (document.fullscreenEnabled === false || document.webkitFullscreenEnabled === false) return false;
  return true;
}

// Variabel pemantau lebar layar awal saat ujian dimulai (mendeteksi Split-Screen / Slide-Over di iOS/iPadOS/Android)
let initialExamViewportWidthV46 = 0;

const _v45OrigEnterFullScreen = enterFullScreen;
enterFullScreen = function() {
  initialExamViewportWidthV46 = window.innerWidth || document.documentElement.clientWidth || 0;
  if (!isNativeFullscreenSupportedOnDeviceV46()) {
    // Di iPhone: kunci scroll & sembunyikan bar atas dengan scroll halus tanpa memicu error Fullscreen API
    try { window.scrollTo(0, 1); } catch (e) {}
    return;
  }
  _v45OrigEnterFullScreen();
};

// Override enforceFullScreenBlock agar di iPhone tidak terjebak loop popup "LAYAR TERKUNCI!",
// melainkan mengawasi Split-Screen / Resize mencurigakan secara cerdas!
enforceFullScreenBlock = function() {
  if (!isExamActive) return;

  // 1. Jika perangkat adalah iPhone atau browser iOS yang tidak mendukung Fullscreen API:
  //    Tetap jalankan proteksi anti-kecurangan ketat (deteksi Split-Screen / Jendela Mengambang)
  if (!isNativeFullscreenSupportedOnDeviceV46()) {
    const curW = window.innerWidth || document.documentElement.clientWidth || 0;
    if (initialExamViewportWidthV46 > 0 && curW > 0 && curW < initialExamViewportWidthV46 * 0.72) {
      handleSecurityViolation("Terdeteksi Split-Screen / Layar Ganda di Perangkat");
    }
    return;
  }

  // 2. Untuk Android & Laptop/PC yang mendukung Fullscreen API penuh: tetap wajibkan Fullscreen 100%!
  if (!document.fullscreenElement && !document.webkitFullscreenElement && !document.msFullscreenElement) {
    handleSecurityViolation("Keluar Fullscreen");
    if (!Swal.isVisible()) {
      Swal.fire({
        title: 'LAYAR TERKUNCI!',
        text: 'Anda terdeteksi keluar dari mode layar penuh (Fullscreen). Ujian tidak dapat dilanjutkan sebelum Anda kembali ke mode Layar Penuh.',
        icon: 'error',
        allowOutsideClick: false,
        allowEscapeKey: false,
        confirmButtonText: '<i class="fa-solid fa-expand"></i> Kembali ke Fullscreen',
        customClass: { popup: 'swal-custom-popup', confirmButton: 'swal-custom-confirm' }
      }).then((result) => {
        if (result.isConfirmed) { enterFullScreen(); window.focus(); }
      });
    }
  }
};

// Pastikan di iPhone saat beralih aplikasi (pagehide / visibilitychange) tetap tercatat sebagai pelanggaran ujian
window.addEventListener('pagehide', () => {
  if (isExamActive) {
    handleSecurityViolation("Keluar Aplikasi / Swipe Home iOS");
  }
});


