function addNewBlankArenaQuestionV46() {
  playStudentSFX('click');
  syncCurrentArenaStudioInputsFromDOMV46();
  arenaStudioWorkingStateV46.customQuestions.push({
    id: 'ARQ-' + Date.now(),
    kategori: 'Tebak Cepat',
    poinKoin: 100,
    soal: '',
    a: '',
    b: '',
    c: '',
    d: '',
    kunci: 'A',
    pembahasan: '',
    imageUrl: ''
  });
  renderArenaStudioModalBodyV46();
  const bodyEl = document.getElementById('arena-studio-modal-body-v46');
  if (bodyEl) bodyEl.scrollTop = bodyEl.scrollHeight;
}

function deleteArenaQuestionV46(idx) {
  playStudentSFX('click');
  syncCurrentArenaStudioInputsFromDOMV46();
  arenaStudioWorkingStateV46.customQuestions.splice(idx, 1);
  renderArenaStudioModalBodyV46();
}

function duplicateArenaQuestionV46(idx) {
  playStudentSFX('click');
  syncCurrentArenaStudioInputsFromDOMV46();
  const orig = arenaStudioWorkingStateV46.customQuestions[idx];
  if (!orig) return;
  const copy = JSON.parse(JSON.stringify(orig));
  copy.id = 'ARQ-' + Date.now();
  arenaStudioWorkingStateV46.customQuestions.splice(idx + 1, 0, copy);
  renderArenaStudioModalBodyV46();
}

function moveArenaQuestionV46(idx, dir) {
  playStudentSFX('click');
  syncCurrentArenaStudioInputsFromDOMV46();
  const target = idx + dir;
  const arr = arenaStudioWorkingStateV46.customQuestions;
  if (target < 0 || target >= arr.length) return;
  const temp = arr[idx];
  arr[idx] = arr[target];
  arr[target] = temp;
  renderArenaStudioModalBodyV46();
}

function clearAllArenaCustomQuestionsV46() {
  Swal.fire({
    title: 'Kosongkan Daftar Soal Arena?',
    text: 'Seluruh butir soal pada editor ini akan dihapus dari daftar kerja.',
    icon: 'warning',
    showCancelButton: true,
    confirmButtonColor: '#e11d48',
    confirmButtonText: 'Ya, Kosongkan',
    cancelButtonText: 'Batal',
    customClass: { popup: 'swal-custom-popup', confirmButton: 'swal-custom-confirm' }
  }).then(res => {
    if (res.isConfirmed) {
      arenaStudioWorkingStateV46.customQuestions = [];
      renderArenaStudioModalBodyV46();
    }
  });
}

async function uploadArenaQuestionImageV46(qIdx, fileInputEl) {
  if (!fileInputEl || !fileInputEl.files || !fileInputEl.files[0]) return;
  syncCurrentArenaStudioInputsFromDOMV46();
  try {
    showStudentToast('Mengunggah gambar ilustrasi soal Arena...', 'info');
    const url = await uploadImageToGoogleScript(fileInputEl);
    if (url && arenaStudioWorkingStateV46.customQuestions[qIdx]) {
      arenaStudioWorkingStateV46.customQuestions[qIdx].imageUrl = url;
      const inp = document.getElementById(`inp-aq-img-${qIdx}`);
      if (inp) inp.value = url;
      showStudentToast('Gambar ilustrasi soal berhasil diunggah!', 'success');
    }
  } catch (e) {
    showStudentToast('Gagal mengunggah gambar: ' + e, 'error');
  }
}

function generateVariedArenaQuestionsWithGroqV46() {
  const topikEl = document.getElementById('inp-aigen-topik-v46');
  const gayaEl = document.getElementById('inp-aigen-gaya-v46');
  const jmlEl = document.getElementById('inp-aigen-jumlah-v46');
  const btn = document.getElementById('btn-run-aigen-arena-v46');

  const topik = (topikEl ? topikEl.value : '').trim() || ('Eksplorasi Seru ' + arenaStudioWorkingStateV46.mapel);
  const gaya = gayaEl ? gayaEl.value : 'CAMPURAN_SERU';
  const jumlah = Number(jmlEl ? jmlEl.value : 10) || 10;

  if (btn) {
    btn.innerHTML = '<i class="fa-solid fa-spinner fa-spin"></i> AI Groq Sedang Merakit Soal Turnamen Variatif...';
    btn.disabled = true;
  }

  google.script.run.withSuccessHandler(res => {
    if (btn) {
      btn.innerHTML = '<i class="fa-solid fa-wand-magic-sparkles"></i> Rakit & Tambahkan ke Daftar Soal Arena';
      btn.disabled = false;
    }
    if (res && res.success && Array.isArray(res.questions) && res.questions.length > 0) {
      arenaStudioWorkingStateV46.customQuestions.push(...res.questions);
      playStudentSFX('success');
      showStudentToast(res.message || `Berhasil menambahkan ${res.questions.length} soal variatif!`, 'success');
      switchArenaStudioTabV46('QUESTIONS');
    } else {
      showStudentToast((res && res.message) || 'Gagal merakit soal AI.', 'warning');
    }
  }).withFailureHandler(err => {
    if (btn) {
      btn.innerHTML = '<i class="fa-solid fa-wand-magic-sparkles"></i> Rakit & Tambahkan ke Daftar Soal Arena';
      btn.disabled = false;
    }
    showStudentToast('Gagal menghubungi server: ' + err, 'error');
  }).generateArenaVariedQuestionsGroqV46({
    mapel: arenaStudioWorkingStateV46.mapel,
    topik: topik,
    gaya: gaya,
    jumlah: jumlah
  });
}

function importQuestionsFromLMSAndBankToStudioV46() {
  playStudentSFX('click');
  showStudentToast('Menarik soal dari Modul LMS & Bank Soal...', 'info');
  google.script.run.withSuccessHandler(res => {
    if (res && Array.isArray(res.questions) && res.questions.length > 0) {
      const existingTexts = new Set(arenaStudioWorkingStateV46.customQuestions.map(q => (q.soal || '').trim().toLowerCase()));
      let added = 0;
      res.questions.forEach((q, idx) => {
        if (q && q.soal && !existingTexts.has(q.soal.trim().toLowerCase())) {
          arenaStudioWorkingStateV46.customQuestions.push({
            id: q.id || ('IMP-' + Date.now() + '-' + idx),
            kategori: q.kategori || 'Eksplorasi Konsep',
            poinKoin: 100,
            soal: q.soal,
            a: q.a || '',
            b: q.b || '',
            c: q.c || '',
            d: q.d || '',
            kunci: (q.kunci || 'A').toUpperCase(),
            pembahasan: q.pembahasan || '',
            imageUrl: q.imageUrl || ''
          });
          added++;
        }
      });
      showStudentToast(`Berhasil mengimpor ${added} soal ke editor Arena! Silakan sesuaikan sesuka hati.`, 'success');
      switchArenaStudioTabV46('QUESTIONS');
    } else {
      showStudentToast('Belum ada soal di Modul LMS / Bank Soal mapel ini.', 'warning');
    }
  }).getArenaQuestionsForSubjectV45(arenaStudioWorkingStateV46.mapel);
}

function saveArenaFullStudioChangesV46() {
  playStudentSFX('click');
  syncCurrentArenaStudioInputsFromDOMV46();

  const validQuestions = arenaStudioWorkingStateV46.customQuestions.filter(q => q && q.soal && q.soal.trim() !== '');
  const metaHeaderObj = {
    __isArenaMetaV46: true,
    questionSourceMode: arenaStudioWorkingStateV46.questionSourceMode || 'CUSTOM_FIRST',
    customTitle: arenaStudioWorkingStateV46.customTitle || '',
    customSubtitle: arenaStudioWorkingStateV46.customSubtitle || '',
    bannerColor: arenaStudioWorkingStateV46.bannerColor || ''
  };

  const payloadCustomArray = [metaHeaderObj, ...validQuestions];
  const mapelName = arenaStudioWorkingStateV46.mapel;

  const newCfg = {
    mapel: mapelName,
    enabled: arenaStudioWorkingStateV46.enabled,
    accessMode: arenaStudioWorkingStateV46.accessMode,
    allowedClasses: arenaStudioWorkingStateV46.allowedClasses,
    roomPin: arenaStudioWorkingStateV46.roomPin,
    timerSeconds: arenaStudioWorkingStateV46.timerSeconds,
    customQuestions: payloadCustomArray
  };

  liveArenaStateV45.configByMapel[mapelName] = newCfg;

  const btn = document.getElementById('btn-save-arena-studio-v46');
  if (btn) {
    btn.innerHTML = '<i class="fa-solid fa-spinner fa-spin"></i> Menyimpan ke Server & Broadcast...';
    btn.disabled = true;
  }

  if (supabaseArenaChannelV45) {
    try {
      supabaseArenaChannelV45.send({
        type: 'broadcast',
        event: 'arena_config_sync',
        payload: { mapel: mapelName, config: newCfg }
      });
    } catch (e) {}
  }

  google.script.run.withSuccessHandler(res => {
    if (btn) {
      btn.innerHTML = '<i class="fa-solid fa-floppy-disk"></i> Simpan Seluruh Soal & Konten Arena';
      btn.disabled = false;
    }
    playStudentSFX('success');
    showStudentToast((res && res.message) || `Berhasil menyimpan ${validQuestions.length} soal & konfigurasi Arena ${mapelName}!`, 'success');
    closeArenaFullStudioModalV46();
    renderLiveArenaRootV45();
  }).withFailureHandler(err => {
    if (btn) {
      btn.innerHTML = '<i class="fa-solid fa-floppy-disk"></i> Simpan Seluruh Soal & Konten Arena';
      btn.disabled = false;
    }
    showStudentToast('Tersimpan secara lokal, gagal sinkron server: ' + err, 'warning');
  }).saveLiveArenaConfigAdminV45({
    mapelKey: mapelName,
    enabled: newCfg.enabled,
    accessMode: newCfg.accessMode,
    allowedClasses: newCfg.allowedClasses,
    roomPin: newCfg.roomPin,
    timerSeconds: newCfg.timerSeconds,
    customQuestions: payloadCustomArray,
    updatedBy: (typeof trnLiveAdminSessionV39 !== 'undefined' && trnLiveAdminSessionV39 && trnLiveAdminSessionV39.name) || 'Guru / Admin'
  });
}

// Perbarui selectAndLaunchSubjectArenaV45 agar menghormati Soal Kustom Studio V46 & Kategori/Poin Koin per Soal
selectAndLaunchSubjectArenaV45 = function(mapelName) {
  playStudentSFX('click');
  liveArenaStateV45.activeSubject = mapelName;
  renderLiveArenaLeaderboardPanelV45();

  const access = isStudentAllowedInSubjectArenaV45(mapelName);
  if (!access.allowed) {
    Swal.fire({
      icon: 'warning',
      title: 'Arena Belum Dibuka Untuk Kelasmu',
      text: access.reason,
      customClass: { popup: 'swal-custom-popup', confirmButton: 'swal-custom-confirm' }
    });
    return;
  }

  const cfg = liveArenaStateV45.configByMapel[mapelName] || {};
  const parsed = getArenaMetaAndQuestionsParsedV46(cfg);

  // Jika Guru/Admin sudah menyusun soal kustom di Studio V46 dan mode adalah CUSTOM_ONLY atau CUSTOM_FIRST, langsung gunakan!
  if (parsed.questions.length > 0 && parsed.meta.questionSourceMode !== 'CUSTOM_PLUS_LMS') {
    liveArenaStateV45.questions = shuffleArray(parsed.questions).slice(0, 25);
    liveArenaStateV45.currentIndex = 0;
    liveArenaStateV45.selectedOpt = '';
    liveArenaStateV45.isRevealed = false;
    liveArenaStateV45.sessionCoins = 0;
    liveArenaStateV45.correctCount = 0;
    liveArenaStateV45.streak = 0;
    liveArenaStateV45.maxStreak = 0;
    liveArenaStateV45.timerSec = Number(cfg.timerSeconds) || 20;
    liveArenaStateV45.stage = 'PLAYING';
    startArenaQuestionTimerV45();
    renderLiveArenaRootV45();
    return;
  }

  Swal.fire({
    title: 'Menyiapkan Arena ' + mapelName + '...',
    html: 'Menyinkronkan soal turnamen variatif & papan peringkat real-time...',
    allowOutsideClick: false,
    didOpen: () => Swal.showLoading(),
    customClass: { popup: 'swal-custom-popup' }
  });

  google.script.run.withSuccessHandler(res => {
    Swal.close();
    let serverList = (res && Array.isArray(res.questions)) ? res.questions.filter(q => q && !q.__isArenaMetaV46 && q.soal) : [];
    let combined = [...parsed.questions];

    serverList.forEach(sq => {
      if (!combined.some(cq => (cq.soal || '').trim().toLowerCase() === (sq.soal || '').trim().toLowerCase())) {
        combined.push(sq);
      }
    });

    if (combined.length === 0) {
      const defMod = getDefaultConstructiveModule(mapelName);
      combined = defMod.kuis || [];
    }

    liveArenaStateV45.questions = shuffleArray(combined).slice(0, 20);
    liveArenaStateV45.currentIndex = 0;
    liveArenaStateV45.selectedOpt = '';
    liveArenaStateV45.isRevealed = false;
    liveArenaStateV45.sessionCoins = 0;
    liveArenaStateV45.correctCount = 0;
    liveArenaStateV45.streak = 0;
    liveArenaStateV45.maxStreak = 0;
    liveArenaStateV45.timerSec = Number(cfg.timerSeconds) || 20;
    liveArenaStateV45.stage = 'PLAYING';

    startArenaQuestionTimerV45();
    renderLiveArenaRootV45();
  }).getArenaQuestionsForSubjectV45(mapelName);
};

// =========================================================================
// 42. PEMBARUAN V47: PERBAIKAN TOMBOL CEKLIS PEMAHAMAN DI SETIAP PILAR (SUB-MATERI)
//     & PEMINDAHAN CHECKLIST READING TIP DARI BAWAH AI TUTOR KE SETIAP KARTU PILAR
// =========================================================================

(function applySubConceptPillarChecklistFixV47() {
  const _v46OrigRenderConstructiveWorkspace = renderConstructiveWorkspace;

  renderConstructiveWorkspace = function() {
    _v46OrigRenderConstructiveWorkspace();
    if (!activeLMSModule) return;

    const ws = document.getElementById('lms-constructive-workspace');
    if (!ws) return;

    // 1. Hapus kotak checklist "Reading Tip" yang berada di bawah tombol AI Tutor
    //    agar siswa tidak bingung dengan dua jenis checklist yang berbeda lokasi.
    ws.querySelectorAll('.trn-reading-tip-box').forEach(el => el.remove());

    // 2. Khusus pada Tahap 2 (Eksplorasi Konsep):
    //    Pastikan SETIAP kartu Pilar (1, 2, 3, dst.) memiliki tombol
    //    "Tandai Sudah Membaca & Memahami Pilar Ini" yang akurat sesuai indeks pilarnya.
    if (activeLMSStep === 2) {
      const k = activeLMSModule.konten || {};
      const subArr = (k.eksplorasi && Array.isArray(k.eksplorasi.sub_materi)) ? k.eksplorasi.sub_materi : [];
      const tr = getStudentVerifiedTracker();
      const modId = activeLMSModule.id;

      // Bersihkan tombol subcheck lama yang salah posisi (misal yang masuk ke header video)
      ws.querySelectorAll('[id^="btn-subcheck-"]').forEach(btn => {
        const wrap = btn.parentElement;
        if (wrap) wrap.remove();
      });
      ws.querySelectorAll('.pillar-check-action-row-v47, #pillar-mastery-summary-bar-v47').forEach(el => el.remove());

      // Cari secara spesifik hanya kartu-kartu Pilar Sub-Materi (yang memiliki ikon fa-layer-group pada h4)
      const pillarCards = [];
      ws.querySelectorAll('h4').forEach(h4El => {
        const iconEl = h4El.querySelector('i.fa-layer-group');
        const parentCard = h4El.parentElement;
        if (iconEl && parentCard && !parentCard.classList.contains('student-video-analysis-hub')) {
          pillarCards.push(parentCard);
        }
      });

      // Suntikkan tombol ceklis interaktif & indikator klaim XP di setiap kartu Pilar (Pilar 1, 2, 3, dst.)
      pillarCards.forEach((cardEl, idx) => {
        if (idx >= subArr.length) return;
        const key = `${modId}_sub_${idx}`;
        const isChecked = !!(lmsSubConceptChecked[key] || (tr.subChecked && tr.subChecked[key]));

        cardEl.classList.add('submateri-interactive-card');
        cardEl.style.borderColor = isChecked ? '#10b981' : '#e2e8f0';
        cardEl.style.background = isChecked ? 'linear-gradient(180deg, #ffffff 0%, #fffbeb 100%)' : '#ffffff';

        cardEl.insertAdjacentHTML('beforeend', `
          <div class="pillar-check-action-row-v47" style="margin-top:16px; padding-top:14px; border-top:1.5px dashed ${isChecked ? '#6ee7b7' : '#e2e8f0'}; display:flex; justify-content:space-between; align-items:center; flex-wrap:wrap; gap:10px;">
            <div onclick="toggleSubConceptCheckV47(${idx})" style="display:flex; align-items:center; gap:8px; font-size:12.5px; font-weight:700; color:${isChecked ? '#047857' : '#64748b'}; cursor:pointer;">
              <input type="checkbox" ${isChecked ? 'checked' : ''} readonly style="width:18px; height:18px; accent-color:#059669; pointer-events:none;">
              <span>🎯 ${isChecked ? `Pilar #${idx + 1} Tuntas Dibaca & Dipahami` : `Checklist Pemahaman Pilar #${idx + 1}`}</span>
            </div>
            <button type="button" id="btn-subcheck-${idx}" class="submateri-Interactive-check-btn ${isChecked ? 'understood' : ''}" onclick="toggleSubConceptCheckV47(${idx})" style="min-height:42px; padding:8px 16px; border-radius:12px; font-weight:800; cursor:pointer;">
              <i class="fa-${isChecked ? 'solid' : 'regular'} fa-circle-check"></i>
              <span>${isChecked ? 'Pilar Konsep Ini Sudah Aku Baca & Pahami! (+XP)' : 'Tandai Sudah Membaca & Memahami Pilar Ini'}</span>
            </button>
          </div>
        `);
      });

      // Tambahkan bar status progres gabungan seluruh pilar di bagian bawah sebelum tombol navigasi tahap
      const donePillarsCount = subArr.filter((_, idx) => {
        const key = `${modId}_sub_${idx}`;
        return !!(lmsSubConceptChecked[key] || (tr.subChecked && tr.subChecked[key]));
      }).length;
      const allPillarsDone = subArr.length > 0 && donePillarsCount >= subArr.length;

      const summaryHtml = `
        <div id="pillar-mastery-summary-bar-v47" style="margin-top:18px; padding:14px 18px; border-radius:16px; background:${allPillarsDone ? '#ecfdf5' : '#fef3c7'}; border:1.5px solid ${allPillarsDone ? '#10b981' : '#fde68a'}; display:flex; justify-content:space-between; align-items:center; flex-wrap:wrap; gap:10px;">
          <div style="font-size:13px; font-weight:800; color:${allPillarsDone ? '#065f46' : '#065f46'}; display:flex; align-items:center; gap:8px;">
            <i class="fa-solid ${allPillarsDone ? 'fa-circle-check' : 'fa-list-check'}" style="font-size:16px;"></i>
            <span>${allPillarsDone
              ? `Luar Biasa! Seluruh ${subArr.length} Pilar Konsep telah kamu baca & pahami (+25 XP Terverifikasi).`
              : `Progres Membaca Pilar: ${donePillarsCount} dari ${subArr.length} Pilar ditandai selesai. Centang seluruh pilar di atas untuk mengklaim +25 XP!`}</span>
          </div>
          <span style="background:${allPillarsDone ? '#059669' : '#059669'}; color:#ffffff; padding:4px 12px; border-radius:99px; font-size:11.5px; font-weight:900;">
            ${donePillarsCount}/${subArr.length} Pilar Tuntas
          </span>
        </div>
      `;

      const lastPillarCard = pillarCards[pillarCards.length - 1];
      if (lastPillarCard) {
        lastPillarCard.insertAdjacentHTML('afterend', summaryHtml);
      }
    }
  };
})();

function toggleSubConceptCheckV47(subIdx) {
  if (!activeLMSModule) return;
  const modId = activeLMSModule.id;
  const key = `${modId}_sub_${subIdx}`;
  const tr = getStudentVerifiedTracker();
  if (!tr.subChecked) tr.subChecked = {};

  const currentState = !!(lmsSubConceptChecked[key] || tr.subChecked[key]);
  const nextState = !currentState;

  lmsSubConceptChecked[key] = nextState;
  if (nextState) {
    tr.subChecked[key] = true;
    const tipKey = `${modId}_step_${activeLMSStep}`;
    if (typeof trnReadingTipCheckedMapV37 !== 'undefined') {
      trnReadingTipCheckedMapV37[tipKey] = true;
      localStorage.setItem('trn_reading_tip_v37', JSON.stringify(trnReadingTipCheckedMapV37));
    }
    playStudentSFX('success');
    showStudentToast(`Pilar Konsep #${subIdx + 1} ditandai selesai dibaca & dipahami! (+XP)`, 'success');
  } else {
    delete tr.subChecked[key];
    playStudentSFX('click');
  }

  saveStudentVerifiedTracker(tr);
  renderConstructiveWorkspace();
  if (typeof renderTrnRightSidebarContentV37 === 'function') {
    renderTrnRightSidebarContentV37();
  }
  if (typeof renderStudentEngagementWidgets === 'function') {
    renderStudentEngagementWidgets();
  }
  if (typeof updateStudentHeroLevelBannerV15 === 'function') {
    updateStudentHeroLevelBannerV15();
  }
}


