// PENGETATAN LOGIKA MENDAPATKAN XP MODUL/BAB LMS (UNTUK NAIK LEVEL)
getModuleVerificationStatusV15 = function(mod) {
  if (!mod) return { allReady: false, items: [], verifiedXPBonus: 0 };
  const tr = getStudentVerifiedTracker();
  const modId = mod.id;
  const k = mod.konten || {};
  const subArr = (k.eksplorasi && Array.isArray(k.eksplorasi.sub_materi)) ? k.eksplorasi.sub_materi : [];
  const cardsArr = Array.isArray(k.kartu_pintar) ? k.kartu_pintar : [];

  const readSec = tr.readTimers[modId] || 0;
  const readOk = readSec >= 60;

  let checkedSubCount = 0;
  subArr.forEach((_, idx) => {
    if (lmsSubConceptChecked[`${modId}_sub_${idx}`] || (tr.subChecked && tr.subChecked[`${modId}_sub_${idx}`])) checkedSubCount++;
  });
  const subOk = subArr.length === 0 ? true : (checkedSubCount >= subArr.length);

  let masteredCardCount = 0;
  cardsArr.forEach((_, idx) => {
    const st = lmsFlashcardMastery[`${modId}_card_${idx}`] || (tr.cardsMastered && tr.cardsMastered[`${modId}_card_${idx}`]);
    if (st === 'mastered') masteredCardCount++;
  });
  const cardsOk = cardsArr.length === 0 ? true : (masteredCardCount >= cardsArr.length);

  const reflText = (studentLMSReflectionText || '').trim();
  const wordCount = reflText ? reflText.split(/\s+/).filter(Boolean).length : 0;
  const aiEval = tr.aiEvaluated[modId];
  const reflOk = (wordCount >= 12) && (aiEval && aiEval.passed && Number(aiEval.score || 70) >= 70);

  const savedNote = (localStorage.getItem(getStudentNoteKey()) || '').trim();
  const noteOk = savedNote.length >= 25;

  const items = [
    { key: 'read', label: `Baca Materi Aktif (${Math.min(60, readSec)}/60 dtk)`, done: readOk, xp: 20, step: 2 },
    { key: 'sub', label: `Pahami Seluruh Pilar (${checkedSubCount}/${subArr.length} Pilar)`, done: subOk, xp: 25, step: 2 },
    { key: 'cards', label: `Hafalkan Kartu 3D (${masteredCardCount}/${cardsArr.length} Kartu)`, done: cardsOk, xp: 25, step: 3 },
    { key: 'refl', label: `Lulus Evaluasi Refleksi AI (Skor ≥ 70)`, done: reflOk, xp: 35, step: 4 },
    { key: 'note', label: `Tulis Rangkuman Catatan Pintar (Min. 25 Karakter)`, done: noteOk, xp: 15, step: 2 }
  ];

  const verifiedXPBonus = items.reduce((acc, it) => acc + (it.done ? it.xp : 0), 0);
  const strictAllReady = readOk && subOk && cardsOk && reflOk && noteOk;
  return { allReady: strictAllReady, items, verifiedXPBonus, readOk, subOk, cardsOk, reflOk, noteOk };
};

const _v47StrictOrigPeriksaKuis = periksaKuisDanKlaimXP;
periksaKuisDanKlaimXP = function() {
  if (!activeLMSModule) return;
  const kuis = Array.isArray(activeLMSModule.kuis) ? activeLMSModule.kuis : [];
  if (kuis.length > 0 && Object.keys(studentLMSQuizAnswers).length >= kuis.length) {
    const verStatus = getModuleVerificationStatusV15(activeLMSModule);
    if (verStatus.allReady) {
      let benar = 0;
      kuis.forEach((q, idx) => {
        if ((studentLMSQuizAnswers[idx] || '').toUpperCase() === (q.kunci || 'A').toUpperCase()) benar++;
      });
      const skor = Math.round((benar / kuis.length) * 100);
      if (skor < 75) {
        Swal.fire({
          icon: 'warning',
          title: `Skor Kuis Kamu: ${skor}/100 (Belum Mencapai KKM 75)`,
          html: `Dalam aturan <b>XP Level Ketat SICIBINAGA</b>, kamu wajib meraih <b>Skor Kuis Formatif minimal 75/100</b> pada bab ini untuk mendapatkan <b>XP Naik Level</b>!<br><br>Pelajari kembali petunjuk pada soal yang salah, perbaiki jawabanmu, lalu klik <b>Periksa Jawaban & Klaim XP</b> kembali.`,
          confirmButtonText: 'Siap, Aku Perbaiki Jawaban!',
          customClass: { popup: 'swal-custom-popup', confirmButton: 'swal-custom-confirm' }
        });
        return;
      }
    }
  }
  _v47StrictOrigPeriksaKuis();
};

function getEquippedBadgeIdForStudentV48(targetName) {
  const myName = ((studentData && studentData.name) || '').toLowerCase().trim();
  const lookup = (targetName ? targetName : myName).toLowerCase().trim();

  if (!targetName || lookup === myName) {
    if (arenaBadgeStoreStateV48.myBadgeData && arenaBadgeStoreStateV48.myBadgeData.equippedBadge) {
      return arenaBadgeStoreStateV48.myBadgeData.equippedBadge;
    }
    const localSaved = localStorage.getItem(`arena_badge_v48_${(studentData && studentData.email) || myName}`);
    if (localSaved) {
      try {
        const parsed = JSON.parse(localSaved);
        if (parsed && parsed.equippedBadge) return parsed.equippedBadge;
      } catch (e) {}
    }
  }

  const peerData = arenaBadgeStoreStateV48.allStudentsBadges && arenaBadgeStoreStateV48.allStudentsBadges[lookup];
  return (peerData && peerData.equippedBadge) ? peerData.equippedBadge : '';
}

function getBadgeCatalogItemByIdV48(badgeId) {
  return ARENA_AVATAR_BADGES_CATALOG_V48.find(b => b.id === badgeId) || null;
}

function applyUniversalBadgeFrameToAvatarElementsV48() {
  const myBadgeId = getEquippedBadgeIdForStudentV48();
  const badgeObj = getBadgeCatalogItemByIdV48(myBadgeId);

  ['eduvance-sidebar-avatar', 'eduvance-footer-avatar', 'eduvance-topbar-avatar', 'profmodal-avatar', 'prof-custom-avatar-preview-v44'].forEach(id => {
    const el = document.getElementById(id);
    if (!el) return;
    el.querySelectorAll('.universal-badge-frame-overlay-v48').forEach(old => old.remove());
    if (badgeObj) {
      el.insertAdjacentHTML('beforeend', `<div class="universal-badge-frame-overlay-v48" title="Bingkai Badge: ${escapeHtml(badgeObj.name)} (${badgeObj.tier})">${renderBadgeFrameSVGByIdV48(badgeObj.id, false)}</div>`);
    }
  });
}

const _v47OrigSyncCustomAvatar = syncStudentCustomAvatarAndMottoToUIV44;
syncStudentCustomAvatarAndMottoToUIV44 = function() {
  _v47OrigSyncCustomAvatar();
  applyUniversalBadgeFrameToAvatarElementsV48();
};

const _v47OrigBuildForumStudentBadgeCardHTML = buildForumStudentBadgeCardHTMLV44;
buildForumStudentBadgeCardHTMLV44 = function(namaSiswa, kelasSiswa, waktuStr) {
  const baseHtml = _v47OrigBuildForumStudentBadgeCardHTML(namaSiswa, kelasSiswa, waktuStr);
  const eqBadgeId = getEquippedBadgeIdForStudentV48(namaSiswa);
  const badgeObj = getBadgeCatalogItemByIdV48(eqBadgeId);
  if (!badgeObj) return baseHtml;

  const frameOverlayHtml = `<div class="universal-badge-frame-overlay-v48" title="Badge Live Arena: ${escapeHtml(badgeObj.name)}">${renderBadgeFrameSVGByIdV48(badgeObj.id, false)}</div>`;
  const badgePillHtml = `<span style="background:linear-gradient(135deg,#f59e0b,#059669); color:#ffffff; padding:2px 8px; border-radius:99px; font-size:9.5px; font-weight:900; display:inline-flex; align-items:center; gap:4px;"><i class="fa-solid fa-shield-halved"></i> ${escapeHtml(badgeObj.name)}</span>`;

  let enhanced = baseHtml.replace(
    /<div class="disc-user-avatar-v44">([\s\S]*?)<\/div>/,
    `<div class="disc-user-avatar-v44">$1${frameOverlayHtml}</div>`
  );
  enhanced = enhanced.replace(
    /<span class="disc-level-xp-pill-v44"/,
    `${badgePillHtml} <span class="disc-level-xp-pill-v44"`
  );
  return enhanced;
};

function fetchArenaBadgeStoreFromServerV48(callback) {
  if (typeof google === 'undefined' || !google.script || !google.script.run) return;
  const email = (studentData && studentData.email) || '';
  const nama = (studentData && studentData.name) || '';
  google.script.run.withSuccessHandler(res => {
    if (res && res.success) {
      if (res.myBadgeData) {
        arenaBadgeStoreStateV48.myBadgeData = res.myBadgeData;
        try {
          localStorage.setItem(`arena_badge_v48_${email || nama.toLowerCase()}`, JSON.stringify(res.myBadgeData));
        } catch (e) {}
      }
      if (res.allStudentsBadges) {
        arenaBadgeStoreStateV48.allStudentsBadges = res.allStudentsBadges;
      }
      applyUniversalBadgeFrameToAvatarElementsV48();
      if (typeof renderTrnRightSidebarContentV37 === 'function' && activeLMSModule) {
        renderTrnRightSidebarContentV37();
      }
    }
    if (callback) callback();
  }).getArenaBadgeStoreDataV48(email, nama);
}

const _v47OrigLoadSubjects = loadSubjects;
loadSubjects = async function() {
  await _v47OrigLoadSubjects();
  fetchArenaBadgeStoreFromServerV48();
};

function getMyAvailableArenaPointsV48() {
  return Math.max(0, Number(arenaBadgeStoreStateV48.myBadgeData && arenaBadgeStoreStateV48.myBadgeData.availablePoints) || 0) + (Number(liveArenaStateV45.sessionCoins) || 0);
}

