function handleArenaBadgeCardClickV48(badgeId) {
  playStudentSFX('click');
  const b = getBadgeCatalogItemByIdV48(badgeId);
  if (!b) return;

  const ownedArr = arenaBadgeStoreStateV48.myBadgeData.ownedBadges || [];
  const isOwned = ownedArr.includes(b.id);
  const isEquipped = (getEquippedBadgeIdForStudentV48() === b.id);
  const availablePoints = getMyAvailableArenaPointsV48();
  const initial = ((studentData && studentData.name) || 'S').trim().charAt(0).toUpperCase();

  Swal.fire({
    title: b.name,
    html: `
      <div style="text-align:center;">
        <div style="width:130px; height:130px; margin:8px auto 14px auto; padding:12px; border-radius:26px; background:${b.cardBg}; display:flex; align-items:center; justify-content:center; box-shadow:0 14px 30px rgba(0,0,0,0.2);">
          ${renderBadgeFrameSVGByIdV48(b.id, true, initial)}
        </div>
        <span style="background:#f5f3ff; color:#6d28d9; border:1px solid #ddd6fe; padding:4px 12px; border-radius:99px; font-size:11px; font-weight:900;">
          ${escapeHtml(b.tierLabel)} &bull; Harga: ${b.price} Poin Arena
        </span>
        <p style="font-size:13px; color:#475569; line-height:1.55; margin-top:12px;">
          ${escapeHtml(b.desc)}
        </p>
        <div style="margin-top:12px; padding:10px 14px; border-radius:12px; background:#fef3c7; color:#065f46; font-size:12.5px; font-weight:800;">
          Saldo Poin Arena Kamu: <b>${availablePoints} Poin</b>
        </div>
      </div>`,
    showCancelButton: true,
    confirmButtonText: isEquipped
      ? 'Lepas Bingkai dari Avatar'
      : (isOwned ? 'Pasang ke Avatar Sekarang' : `Tukarkan (${b.price} Poin)`),
    cancelButtonText: 'Tutup',
    customClass: { popup: 'swal-custom-popup', confirmButton: 'swal-custom-confirm' }
  }).then(res => {
    if (!res.isConfirmed) return;
    const actionType = isEquipped ? 'UNEQUIP' : (isOwned ? 'EQUIP' : 'REDEEM');

    if (actionType === 'REDEEM' && availablePoints < b.price) {
      Swal.fire({
        icon: 'warning',
        title: 'Poin Arena Belum Cukup!',
        text: `Kamu membutuhkan ${b.price} Poin Arena untuk menukarkan "${b.name}", sedangkan saldo poinmu saat ini ${availablePoints} Poin. Ayo selesaikan kuis di Live Arena!`,
        customClass: { popup: 'swal-custom-popup', confirmButton: 'swal-custom-confirm' }
      });
      return;
    }

    Swal.fire({
      title: actionType === 'REDEEM' ? 'Menukarkan Poin Arena...' : 'Memperbarui Bingkai Avatar...',
      allowOutsideClick: false,
      didOpen: () => Swal.showLoading(),
      customClass: { popup: 'swal-custom-popup' }
    });

    google.script.run.withSuccessHandler(r => {
      Swal.close();
      if (r && r.success && r.myBadgeData) {
        arenaBadgeStoreStateV48.myBadgeData = r.myBadgeData;
        if (studentData && studentData.name) {
          arenaBadgeStoreStateV48.allStudentsBadges[studentData.name.toLowerCase().trim()] = r.myBadgeData;
        }
        try {
          localStorage.setItem(`arena_badge_v48_${(studentData && studentData.email) || (studentData && studentData.name || '').toLowerCase()}`, JSON.stringify(r.myBadgeData));
        } catch (e) {}

        playStudentSFX('success');
        if (actionType === 'REDEEM') launchConfettiCelebration();
        applyUniversalBadgeFrameToAvatarElementsV48();
        renderLiveArenaRootV45();
        showStudentToast(r.message || 'Bingkai Badge berhasil diperbarui!', 'success');
      } else {
        Swal.fire({
          icon: 'error',
          title: 'Gagal Memproses',
          text: (r && r.message) || 'Terjadi kesalahan saat menghubungi server.',
          customClass: { popup: 'swal-custom-popup', confirmButton: 'swal-custom-confirm' }
        });
      }
    }).redeemOrEquipArenaAvatarBadgeV48({
      email: (studentData && studentData.email) || '',
      nama: (studentData && studentData.name) || 'Siswa',
      kelas: (studentData && studentData.kelas) || '7A',
      badgeId: b.id,
      badgePrice: b.price,
      actionType: actionType
    });
  });
}

finishArenaTournamentSessionV45 = function() {
  if (liveArenaStateV45.timerInterval) clearInterval(liveArenaStateV45.timerInterval);
  liveArenaStateV45.stage = 'SUMMARY';
  launchConfettiCelebration();

  const earnedThisSession = Number(liveArenaStateV45.sessionCoins) || 0;
  arenaBadgeStoreStateV48.myBadgeData.availablePoints = (Number(arenaBadgeStoreStateV48.myBadgeData.availablePoints) || 0) + earnedThisSession;
  arenaBadgeStoreStateV48.myBadgeData.totalEarned = (Number(arenaBadgeStoreStateV48.myBadgeData.totalEarned) || 0) + earnedThisSession;
  liveArenaStateV45.sessionCoins = 0;

  renderLiveArenaRootV45();

  const activeSub = liveArenaStateV45.activeSubject || 'Umum';
  const cfg = liveArenaStateV45.configByMapel[activeSub] || {};

  google.script.run.withSuccessHandler(res => {
    if (res && res.success) {
      arenaBadgeStoreStateV48.myBadgeData.availablePoints = res.availablePoints;
      arenaBadgeStoreStateV48.myBadgeData.totalEarned = res.totalEarnedPoints;
      showStudentToast(res.message, 'success');
    }
    fetchLiveArenaServerStateV45(() => {
      renderLiveArenaLeaderboardPanelV45();
    });
  }).submitLiveArenaScoreV45({
    mapel: activeSub,
    email: (studentData && studentData.email) || '',
    nama: (studentData && studentData.name) || 'Siswa',
    kelas: (studentData && studentData.kelas) || '7A',
    coins: earnedThisSession,
    benar: liveArenaStateV45.correctCount,
    totalSoal: (liveArenaStateV45.questions || []).length || 1,
    streak: liveArenaStateV45.maxStreak,
    roomPin: cfg.roomPin || '778899',
    accessMode: cfg.accessMode || 'MULTI'
  });
};

const _v47OrigRenderArenaLb = renderLiveArenaLeaderboardPanelV45;
renderLiveArenaLeaderboardPanelV45 = function() {
  _v47OrigRenderArenaLb();
  const slot = document.getElementById('arena-live-leaderboard-slot-v45');
  if (!slot) return;
  slot.querySelectorAll('.arena-lb-row-v45').forEach(row => {
    const nameEl = row.querySelector('div[style*="font-weight:800"]');
    if (!nameEl) return;
    const rawName = nameEl.innerText.replace('(Kamu)', '').trim();
    const eqId = getEquippedBadgeIdForStudentV48(rawName);
    const bObj = getBadgeCatalogItemByIdV48(eqId);
    if (bObj && !row.querySelector('.lb-badge-mini-v48')) {
      nameEl.insertAdjacentHTML('beforeend', ` <span class="lb-badge-mini-v48" style="background:#fbbf24; color:#1e1b4b; padding:1px 6px; border-radius:99px; font-size:9px; font-weight:900; margin-left:4px;"><i class="fa-solid fa-shield-halved"></i> ${escapeHtml(bObj.name)}</span>`);
    }
  });
};


// =========================================================================
// 42. PEMBARUAN V56:
//     1. PENGHAPUSAN TOTAL MENU DIKTE SUARA DI AI TUTOR
//     2. SOLID BOTTOM BUTTON BAR PERMANEN KHUSUS LIVE ARENA
//        (BERANDA ARENA, DISKUSI KUIS, TUKAR POIN TOKO, BADGE SAYA)
//        DENGAN AUTO-MINIMIZE OTOMATIS SAAT FULLSCREEN MENGERJAKAN KUIS
// =========================================================================

function syncArenaPermanentBottomBarV56() {
  const bar = document.getElementById('arena-permanent-bottom-bar-v56');
  if (!bar) return;

  const isArenaViewActive = (
    typeof eduvanceActiveNav !== 'undefined' &&
    eduvanceActiveNav === 'arena' &&
    !document.getElementById('eduview-arena')?.classList.contains('hidden') &&
    document.getElementById('lms-learning-section')?.classList.contains('hidden') &&
    !isExamActive &&
    !document.body.classList.contains('admin-mode')
  );

  if (!isArenaViewActive) {
    bar.classList.add('hidden');
    bar.classList.remove('minimized-fullscreen');
    document.body.classList.remove('arena-has-perm-bottom-bar-v56');
    return;
  }

  bar.classList.remove('hidden');
  document.body.classList.add('arena-has-perm-bottom-bar-v56');

  // Auto-minimize saat siswa sedang mengerjakan kuis Live Arena (mode fullscreen PLAYING / AWARD)
  const isPlayingFullscreen = (
    liveArenaStateV45.stage === 'PLAYING' ||
    liveArenaStateV45.stage === 'AWARD' ||
    document.body.classList.contains('arena-quiz-fullscreen-active')
  );
  bar.classList.toggle('minimized-fullscreen', isPlayingFullscreen);

  // Sinkronkan jumlah Badge Saya pada tombol ke-4
  const ownedCount = (
    arenaBadgeStoreStateV48 &&
    arenaBadgeStoreStateV48.myBadgeData &&
    Array.isArray(arenaBadgeStoreStateV48.myBadgeData.ownedBadges)
  ) ? arenaBadgeStoreStateV48.myBadgeData.ownedBadges.length : 0;

  const badgeLbl = document.getElementById('arenadock-lbl-mybadges');
  if (badgeLbl) {
    badgeLbl.textContent = `Badge Saya (${ownedCount})`;
  }

  // Sinkronkan tombol aktif sesuai subView ('HOME', 'DISCUSSION', 'SHOP', 'MY_BADGES')
  const curSub = (arenaBadgeStoreStateV48 && arenaBadgeStoreStateV48.subView) || 'HOME';
  ['HOME', 'DISCUSSION', 'SHOP', 'MY_BADGES'].forEach(key => {
    const btn = document.getElementById('arenadock-btn-' + key);
    if (btn) {
      btn.classList.toggle('active', curSub === key);
    }
  });
}

// =========================================================================
// 44. PEMBARUAN V50 & V51:
//     1. PORTAL FULLSCREEN IMERSIF ANTI-BLANK PUTIH SAAT MULAI KUIS LIVE ARENA
//        (DENGAN FALLBACK SOAL INSTAN, 10-STEP PROGRESS BAR, & BADGE JENJANG)
//     2. FORUM DISKUSI POSITIF & INTUITIF DI DALAM LIVE ARENA (REAL-TIME SUPABASE + SHEETS)
//     3. SERVER BANK SOAL DINAMIS MODE GURU (10 SOAL BERJENJANG MUDAH -> HOTS,
//        ROTASI BERGANTIAN & AUTO-REGENERATE GROQ openai/oss120b SAAT SISWA BENAR SEMUA 10/10)
// =========================================================================

let arenaPositiveDiscussionStateV50 = {
  postsByMapel: {},
  selectedCategory: '💡 Berbagi Tips Konsep',
  activeReplyPostId: ''
};

let arenaDynamicServerPacksV50 = {
  packsByMapel: {},
  editingPackId: '',
  editingPackName: ''
};

// Pastikan Portal Fullscreen Langsung Berada di Body (Bebas dari Transform/Backdrop-Filter Trap!)
function ensureArenaFullscreenPortalV51() {
  let portal = document.getElementById('arena-fullscreen-portal-v51');
  if (!portal) {
    document.body.insertAdjacentHTML('beforeend', `<div id="arena-fullscreen-portal-v51" class="print-hidden"></div>`);
    portal = document.getElementById('arena-fullscreen-portal-v51');
  }
  return portal;
}

// --- A. INTEGRASI REAL-TIME SUPABASE UNTUK DISKUSI POSITIF & ROTASI SOAL DINAMIS ---
const _v49OrigInitSupabaseArena = initSupabaseLiveArenaChannelV45;
initSupabaseLiveArenaChannelV45 = function() {
  _v49OrigInitSupabaseArena();
  if (!supabaseArenaChannelV45 || supabaseArenaChannelV45.__v50Bound) return;
  supabaseArenaChannelV45.__v50Bound = true;

  try {
    supabaseArenaChannelV45
      .on('broadcast', { event: 'arena_positive_post' }, (payload) => {
        const d = (payload && payload.payload) || {};
        if (!d.mapel || !d.post) return;
        if (!arenaPositiveDiscussionStateV50.postsByMapel[d.mapel]) {
          arenaPositiveDiscussionStateV50.postsByMapel[d.mapel] = [];
        }
        const list = arenaPositiveDiscussionStateV50.postsByMapel[d.mapel];
        if (!list.some(p => p.idPesan === d.post.idPesan)) {
          list.unshift(d.post);
          if (eduvanceActiveNav === 'arena' && arenaBadgeStoreStateV48.subView === 'DISCUSSION') {
            renderLiveArenaRootV45();
          }
        }
      })
      .on('broadcast', { event: 'arena_pack_rotated_v50' }, (payload) => {
        const d = (payload && payload.payload) || {};
        if (!d.mapel) return;
        showStudentToast(
          d.message || `🔄 Paket Soal Live Arena ${d.mapel} telah diperbarui secara dinamis!`,
          'info'
        );
        fetchLiveArenaServerStateV45(() => {
          if (eduvanceActiveNav === 'arena' && liveArenaStateV45.stage === 'HUB') {
            renderLiveArenaRootV45();
          }
        });
      });
  } catch (e) {}
};

// --- B. KONTROL FULLSCREEN OTOMATIS SAAT MENGERJAKAN QUIZ LIVE ARENA ---
function enterArenaQuizFullscreenV50() {
  ensureArenaFullscreenPortalV51();
  document.body.classList.add('arena-quiz-fullscreen-active');
  try {
    const elem = document.documentElement;
    if (typeof isNativeFullscreenSupportedOnDeviceV46 === 'function' && isNativeFullscreenSupportedOnDeviceV46()) {
      const isFs = document.fullscreenElement || document.webkitFullscreenElement || document.msFullscreenElement;
      if (!isFs) {
        if (typeof elem.requestFullscreen === 'function') elem.requestFullscreen().catch(() => {});
        else if (typeof elem.webkitRequestFullscreen === 'function') elem.webkitRequestFullscreen();
      }
    } else {
      window.scrollTo({ top: 0, behavior: 'smooth' });
    }
  } catch (e) {}
}

function exitArenaQuizFullscreenV50() {
  document.body.classList.remove('arena-quiz-fullscreen-active');
  const portal = document.getElementById('arena-fullscreen-portal-v51');
  if (portal) {
    portal.classList.remove('active');
    portal.innerHTML = '';
  }
  if (!isExamActive) {
    exitFullScreenOnly();
  }
}

function toggleArenaFullscreenManualV50() {
  const isFs = document.fullscreenElement || document.webkitFullscreenElement || document.msFullscreenElement;
  if (isFs) {
    exitFullScreenOnly();
  } else {
    enterArenaQuizFullscreenV50();
  }
}

const _v49OrigExitArenaToLobby = exitArenaToLobbyV45;
exitArenaToLobbyV45 = function() {
  exitArenaQuizFullscreenV50();
  _v49OrigExitArenaToLobby();
};

// Override renderLiveArenaRootV45 agar saat stage PLAYING atau AWARD, panggung kuis dirender langsung di Portal Fullscreen V51 (Anti-Blank Putih!)
const _v50OrigRenderLiveArenaRoot = renderLiveArenaRootV45;
renderLiveArenaRootV45 = function() {
  const portal = ensureArenaFullscreenPortalV51();
  const displayCoins = getMyAvailableArenaPointsV48();

  if (liveArenaStateV45.stage === 'PLAYING') {
    document.body.classList.add('arena-quiz-fullscreen-active');
    portal.classList.add('active');
    portal.innerHTML = buildArenaPlayingStageHTMLV45(displayCoins);
    return;
  } else if (liveArenaStateV45.stage === 'AWARD') {
    document.body.classList.add('arena-quiz-fullscreen-active');
    portal.classList.add('active');
    portal.innerHTML = buildArenaMagnificentAwardHTMLV45(displayCoins);
    return;
  } else {
    // Saat di HUB atau SUMMARY, matikan portal fullscreen agar kembali ke tampilan normal
    portal.classList.remove('active');
    portal.innerHTML = '';
    document.body.classList.remove('arena-quiz-fullscreen-active');
    _v50OrigRenderLiveArenaRoot();
  }
};

