// 2. Penyederhanaan Syarat Klaim XP (`getModuleVerificationStatusV15`):
//    - 3 Misi Utama (Wajib): (1) Baca Materi / Ceklis Paham, (2) Balik Kartu 3D, (3) Tulis Pendapat >= 10 Kata di Tantangan.
//    - 2 Misi Bonus XP (Opsional, tidak menghalangi klaim kuis): Waktu Baca >= 45 dtk (+20 XP) & Catatan Pintar (+15 XP).
getModuleVerificationStatusV15 = function(mod) {
  if (!mod) return { allReady: false, items: [], verifiedXPBonus: 0 };
  const tr = getStudentVerifiedTracker();
  const modId = mod.id;
  const k = mod.konten || {};
  const subArr = (k.eksplorasi && Array.isArray(k.eksplorasi.sub_materi)) ? k.eksplorasi.sub_materi : [];
  const cardsArr = Array.isArray(k.kartu_pintar) ? k.kartu_pintar : [];

  // Misi 1: Baca Materi (Ceklis sub-konsep ATAU sudah membaca >= 30 detik)
  const readSec = tr.readTimers[modId] || 0;
  let checkedSubCount = 0;
  subArr.forEach((_, idx) => {
    if (lmsSubConceptChecked[`${modId}_sub_${idx}`] || (tr.subChecked && tr.subChecked[`${modId}_sub_${idx}`])) {
      checkedSubCount++;
    }
  });
  const subOk = subArr.length === 0 ? true : (checkedSubCount >= subArr.length || (checkedSubCount >= 1 && readSec >= 30));
  const readOk = readSec >= 30 || subOk;

  // Misi 2: Tebak Kartu 3D (Dibalik ATAU ditandai Sudah Hafal / Perlu Diulang)
  let interactedCardCount = 0;
  cardsArr.forEach((_, idx) => {
    const key = `${modId}_card_${idx}`;
    const st = lmsFlashcardMastery[key] || (tr.cardsMastered && tr.cardsMastered[key]);
    const flipped = tr.cardsFlipped && tr.cardsFlipped[key];
    if (st === 'mastered' || st === 'review' || flipped) interactedCardCount++;
  });
  const cardsOk = cardsArr.length === 0 ? true : (interactedCardCount >= cardsArr.length);

  // Misi 3: Tulis Pendapat di Tantangan (Minimal 10 kata sudah diketik ATAU sudah diverifikasi AI)
  const reflInputEl = document.getElementById('inp-lms-refleksi');
  const currentReflVal = (reflInputEl ? reflInputEl.value : (studentLMSReflectionText || '')).trim();
  if (currentReflVal) studentLMSReflectionText = currentReflVal;
  const wordCount = currentReflVal ? currentReflVal.split(/\s+/).filter(Boolean).length : 0;
  const aiEval = tr.aiEvaluated && tr.aiEvaluated[modId];
  const reflOk = (wordCount >= 10) || !!(aiEval && aiEval.passed);

  // Bonus Opsional: Catatan Pintar & Waktu Baca Tekun
  const savedNote = (localStorage.getItem(getStudentNoteKey()) || '').trim();
  const noteOk = savedNote.length >= 15;
  const bonusReadOk = readSec >= 45;

  const items = [
    { key: 'sub', label: `Misi 1: Baca Materi (${checkedSubCount}/${subArr.length} Paham)`, done: subOk, xp: 25, step: 2, isCore: true },
    { key: 'cards', label: `Misi 2: Buka Kartu 3D (${interactedCardCount}/${cardsArr.length} Kartu)`, done: cardsOk, xp: 30, step: 3, isCore: true },
    { key: 'refl', label: `Misi 3: Tulis Pendapat (${Math.min(10, wordCount)}/10 Kata)`, done: reflOk, xp: 45, step: 4, isCore: true },
    { key: 'read', label: `Bonus XP: Baca Tekun (${Math.min(45, readSec)}/45 dtk)`, done: bonusReadOk, xp: 20, step: 2, isCore: false },
    { key: 'note', label: `Bonus XP: Isi Catatan Pintar`, done: noteOk, xp: 15, step: 2, isCore: false }
  ];

  const verifiedXPBonus = items.reduce((acc, it) => acc + (it.done ? it.xp : 0), 0);
  // Hanya 3 Misi Utama yang menjadi syarat wajib klaim kuis (Anti-Ribet!)
  const coreAllReady = subOk && cardsOk && reflOk;
  return {
    allReady: coreAllReady,
    items,
    verifiedXPBonus,
    readOk,
    subOk,
    cardsOk,
    reflOk,
    noteOk,
    checkedSubCount,
    totalSubs: subArr.length,
    interactedCardCount,
    totalCards: cardsArr.length,
    wordCount
  };
};

// 3. Fungsi Klik Kartu 3D: Saat kartu dibalik, otomatis tandai Sudah Dibaca/Hafal agar siswa tidak lupa klik tombol kedua!
function handleAutoFlipAndMasterCardV59(cardIdx, cardBoxEl) {
  if (!activeLMSModule) return;
  const modId = activeLMSModule.id;
  const key = `${modId}_card_${cardIdx}`;
  const tr = getStudentVerifiedTracker();
  if (!tr.cardsFlipped) tr.cardsFlipped = {};
  if (!tr.cardsMastered) tr.cardsMastered = {};

  tr.cardsFlipped[key] = true;
  if (!lmsFlashcardMastery[key]) {
    lmsFlashcardMastery[key] = 'mastered';
    tr.cardsMastered[key] = 'mastered';
    saveStudentVerifiedTracker(tr);
    if (typeof updateFlashcardMasteryUI === 'function') updateFlashcardMasteryUI();
    updateV59TopMissionChipsUI();
    if (typeof showStudentToast === 'function') {
      showStudentToast(`Kartu #${cardIdx + 1} terbuka & tercatat dipahami! (+XP)`, 'success');
    }
  }
}

// 4. Fungsi "Tandai Semua Paham & Lanjut ke Tebak Kartu" di Tahap 2 (Satu Klik Praktis)
function tandaiSemuaPilarPahamDanLanjutV59() {
  if (!activeLMSModule) return;
  const modId = activeLMSModule.id;
  const k = activeLMSModule.konten || {};
  const subArr = (k.eksplorasi && Array.isArray(k.eksplorasi.sub_materi)) ? k.eksplorasi.sub_materi : [];
  const tr = getStudentVerifiedTracker();
  if (!tr.subChecked) tr.subChecked = {};

  subArr.forEach((_, idx) => {
    const key = `${modId}_sub_${idx}`;
    lmsSubConceptChecked[key] = true;
    tr.subChecked[key] = true;
  });
  saveStudentVerifiedTracker(tr);
  playStudentSFX('success');
  showStudentToast('Semua materi ditandai paham! (+25 XP) Lanjut ke Tebak Kartu 3D.', 'success');
  switchLMSStep(3);
}

// 5. Fungsi Gabungan di Tahap 4: "Simpan Pendapat, Cek AI & Lanjut ke Kuis XP" (Tanpa Harus Klik 2 Tombol Terpisah!)
function simpanPendapatDanLanjutKuisV59() {
  if (!activeLMSModule) return;
  const reflInput = document.getElementById('inp-lms-refleksi');
  const reflText = (reflInput ? reflInput.value : (studentLMSReflectionText || '')).trim();
  studentLMSReflectionText = reflText;

  const words = reflText ? reflText.split(/\s+/).filter(Boolean) : [];
  if (words.length < 10) {
    playStudentSFX('click');
    Swal.fire({
      icon: 'info',
      title: 'Sedikit Lagi! Tulis Minimal 10 Kata Ya ✍️',
      html: `Saat ini pendapatmu baru <b>${words.length} kata</b>.<br><br>Tuliskan 1–2 kalimat sederhana (minimal 10 kata) tentang apa yang kamu pahami atau solusimu untuk cerita di atas, lalu klik tombol ini lagi!`,
      confirmButtonText: 'Siap, Aku Tambahkan!',
      customClass: { popup: 'swal-custom-popup', confirmButton: 'swal-custom-confirm' }
    }).then(() => {
      if (reflInput) reflInput.focus();
    });
    return;
  }

  // Otomatis tandai refleksi lulus agar siswa langsung bisa lanjut mengerjakan Kuis di Tahap 5 tanpa terhambat
  const tr = getStudentVerifiedTracker();
  if (!tr.aiEvaluated) tr.aiEvaluated = {};
  if (!tr.aiEvaluated[activeLMSModule.id] || !tr.aiEvaluated[activeLMSModule.id].passed) {
    tr.aiEvaluated[activeLMSModule.id] = {
      score: 85,
      passed: true,
      feedback: 'Pendapat reflektifmu sudah jelas dan memenuhi syarat ketuntasan (+45 XP)!'
    };
    saveStudentVerifiedTracker(tr);
  }

  // Jalankan juga evaluasi AI Groq di latar belakang jika siswa belum menekan tombol Cek AI
  try {
    if (typeof verifikasiJurnalRefleksiAIGroq === 'function') {
      verifikasiJurnalRefleksiAIGroq();
    }
  } catch (e) {}

  playStudentSFX('success');
  showStudentToast('Pendapatmu tersimpan (+45 XP)! Sekarang waktunya Kuis XP!', 'success');
  setTimeout(() => {
    switchLMSStep(5);
  }, 320);
}

// 6. Update Real-time Counter Kata saat Siswa Mengetik di Tahap 4
function updateRefleksiWordCountRealtimeV59(val) {
  studentLMSReflectionText = val;
  const words = (val || '').trim().split(/\s+/).filter(Boolean).length;
  const badge = document.getElementById('v59-refl-word-badge');
  if (badge) {
    const isReady = words >= 10;
    badge.className = 'v59-word-counter-pill ' + (isReady ? 'ready' : '');
    badge.innerHTML = isReady
      ? `<i class="fa-solid fa-circle-check"></i> ${words} Kata (Syarat Minimal 10 Kata Terpenuhi ✓)`
      : `<i class="fa-solid fa-pen"></i> ${words} / 10 Kata (Tambahkan ${10 - words} kata lagi)`;
  }
  if (words >= 10 && activeLMSModule) {
    const tr = getStudentVerifiedTracker();
    if (!tr.aiEvaluated) tr.aiEvaluated = {};
    if (!tr.aiEvaluated[activeLMSModule.id]) {
      tr.aiEvaluated[activeLMSModule.id] = { score: 85, passed: true, feedback: 'Tuntas menulis refleksi.' };
      saveStudentVerifiedTracker(tr);
    }
    updateV59TopMissionChipsUI();
  }
}

// 7. Update Tampilan 3 Chip Misi di Banner Atas
function updateV59TopMissionChipsUI() {
  if (!activeLMSModule) return;
  const ver = getModuleVerificationStatusV15(activeLMSModule);
  const c1 = document.getElementById('v59-chip-misi-1');
  const c2 = document.getElementById('v59-chip-misi-2');
  const c3 = document.getElementById('v59-chip-misi-3');
  if (c1) {
    c1.className = 'v59-mission-chip ' + (ver.subOk ? 'done' : '');
    c1.innerHTML = `<i class="fa-solid ${ver.subOk ? 'fa-circle-check' : 'fa-book-open'}"></i> <span>1. Baca (${ver.checkedSubCount}/${ver.totalSubs})</span>`;
  }
  if (c2) {
    c2.className = 'v59-mission-chip ' + (ver.cardsOk ? 'done' : '');
    c2.innerHTML = `<i class="fa-solid ${ver.cardsOk ? 'fa-circle-check' : 'fa-clone'}"></i> <span>2. Kartu (${ver.interactedCardCount}/${ver.totalCards})</span>`;
  }
  if (c3) {
    c3.className = 'v59-mission-chip ' + (ver.reflOk ? 'done' : '');
    c3.innerHTML = `<i class="fa-solid ${ver.reflOk ? 'fa-circle-check' : 'fa-comment-dots'}"></i> <span>3. Pendapat ${ver.reflOk ? '✓' : ''}</span>`;
  }
}

// 8. Kemas Ulang Tampilan Video Pembelajaran agar Sederhana:
//    - Hanya tampil di Langkah 1 (tidak diduplikasi lagi di Langkah 2).
//    - Video & Rangkuman langsung tampil bersih, sedangkan Soal Latihan Video disimpan dalam Accordion "Bonus XP Video (Opsional)" agar tidak dikira kuis wajib.
const _v58OrigBuildVideoHub = buildStudentVideoAnalysisHubHTML;
