// 10. Override Utama `renderConstructiveWorkspace` untuk Menyajikan Workflow 5 Langkah Baru yang Bersih, Jelas, dan User-Friendly
const _v58OrigRenderConstructiveWorkspace = renderConstructiveWorkspace;
renderConstructiveWorkspace = function() {
  _v58OrigRenderConstructiveWorkspace();
  if (!activeLMSModule) return;

  const ws = document.getElementById('lms-constructive-workspace');
  if (!ws) return;

  const stepMeta = V59_SIMPLE_STEPS_META[(activeLMSStep || 1) - 1] || V59_SIMPLE_STEPS_META[0];
  const ver = getModuleVerificationStatusV15(activeLMSModule);
  const prog = computeSingleModuleProgressV33(activeLMSModule);

  // A. Update Judul Instruksi Kontekstual di Header
  const ctxTitleEl = document.getElementById('lms-step-Contextual-title');
  if (ctxTitleEl) {
    ctxTitleEl.innerText = stepMeta.guideInstruction;
  }

  // B. Suntikkan Stepper 5 Langkah Modern + Banner Instruksi "1 Kalimat Aktif" di Atas Konten Artikel
  const leftCanvas = ws.querySelector('.trn-reader-left-canvas > div:first-child');
  if (leftCanvas && !document.getElementById('v59-stepper-top-bar')) {
    const stepperPillsHtml = V59_SIMPLE_STEPS_META.map((st, idx) => {
      const isAct = (st.num === activeLMSStep);
      const isDone = prog.stepStates[idx];
      return `
        <button type="button" class="v59-step-pill-btn ${isAct ? 'active' : (isDone ? 'done' : '')}" onclick="switchLMSStep(${st.num})">
          <span class="v59-step-num-badge">${isDone && !isAct ? '<i class="fa-solid fa-check"></i>' : st.num}</span>
          <span style="white-space:nowrap; overflow:hidden; text-overflow:ellipsis;">${st.shortLabel.split('. ')[1]}</span>
        </button>`;
    }).join('');

    const topWorkflowHeaderHtml = `
      <div class="v59-modern-stepper-bar" id="v59-stepper-top-bar">
        ${stepperPillsHtml}
      </div>

      <div class="v59-action-guide-banner">
        <div class="v59-guide-left">
          <div class="v59-guide-icon-pulse">
            <i class="fa-solid ${stepMeta.icon}"></i>
          </div>
          <div style="min-width:0; flex:1;">
            <div class="v59-guide-step-eyebrow">${escapeHtml(stepMeta.guideTitle)}</div>
            <div class="v59-guide-main-instruction">${escapeHtml(stepMeta.guideInstruction)}</div>
          </div>
        </div>
        <div class="v59-3mission-chips">
          <div id="v59-chip-misi-1" class="v59-mission-chip ${ver.subOk ? 'done' : ''}" onclick="switchLMSStep(2)" title="Misi 1: Baca Materi di Langkah 2">
            <i class="fa-solid ${ver.subOk ? 'fa-circle-check' : 'fa-book-open'}"></i>
            <span>1. Baca (${ver.checkedSubCount}/${ver.totalSubs})</span>
          </div>
          <div id="v59-chip-misi-2" class="v59-mission-chip ${ver.cardsOk ? 'done' : ''}" onclick="switchLMSStep(3)" title="Misi 2: Balik Kartu 3D di Langkah 3">
            <i class="fa-solid ${ver.cardsOk ? 'fa-circle-check' : 'fa-clone'}"></i>
            <span>2. Kartu (${ver.interactedCardCount}/${ver.totalCards})</span>
          </div>
          <div id="v59-chip-misi-3" class="v59-mission-chip ${ver.reflOk ? 'done' : ''}" onclick="switchLMSStep(4)" title="Misi 3: Tulis 1 Kalimat Pendapat di Langkah 4">
            <i class="fa-solid ${ver.reflOk ? 'fa-circle-check' : 'fa-comment-dots'}"></i>
            <span>3. Pendapat ${ver.reflOk ? '✓' : ''}</span>
          </div>
        </div>
      </div>
    `;

    leftCanvas.insertAdjacentHTML('afterbegin', topWorkflowHeaderHtml);
  }

  // C. Penyederhanaan Spesifik per Langkah (1 s.d. 5)
  if (activeLMSStep === 1) {
    // Ubah teks tombol CTA bawah di Langkah 1 agar jelas mengarah ke Langkah 2
    ws.querySelectorAll('button[onclick="switchLMSStep(2)"]').forEach(btn => {
      if (!btn.classList.contains('tujuan-btn-start-pill-v42')) {
        btn.innerHTML = `<i class="fa-solid fa-book-open-reader"></i> Lanjut ke Langkah 2: Baca Materi Inti <i class="fa-solid fa-arrow-right"></i>`;
      }
    });
  } else if (activeLMSStep === 2) {
    // Sederhanakan teks tombol ceklis di setiap kotak materi menjadi "✅ Aku Sudah Paham Bagian Ini"
    ws.querySelectorAll('[id^="btn-subcheck-"]').forEach((btn) => {
      const isDone = btn.classList.contains('understood');
      btn.innerHTML = isDone
        ? `<i class="fa-solid fa-circle-check"></i> <span>Sudah Paham! (+XP Tercatat)</span>`
        : `<i class="fa-regular fa-circle-check"></i> <span>✅ Aku Sudah Paham Bagian Ini</span>`;
    });

    // Tambahkan tombol praktis 1-klik "Semua Materi Sudah Kupahami -> Lanjut ke Tebak Kartu" di bawah daftar pilar
    const summaryBar = document.getElementById('pillar-mastery-summary-bar-v47');
    if (summaryBar && !ver.subOk) {
      summaryBar.insertAdjacentHTML('beforeend', `
        <button type="button" onclick="tandaiSemuaPilarPahamDanLanjutV59()" style="background:linear-gradient(135deg, #16a34a, #15803d); color:#ffffff; border:none; padding:9px 16px; border-radius:11px; font-size:12px; font-weight:900; cursor:pointer; display:inline-flex; align-items:center; gap:6px; box-shadow:0 4px 12px rgba(22,163,74,0.25);">
          <i class="fa-solid fa-check-double"></i> Tandai Semua Paham &amp; Lanjut Langkah 3 &rarr;
        </button>
      `);
    }
  } else if (activeLMSStep === 3) {
    // Otomatis catat kartu sudah dibaca/hafal begitu siswa menyentuh kartu 3D untuk membaliknya!
    const boxes = ws.querySelectorAll('.flashcard-box');
    boxes.forEach((box, idx) => {
      box.setAttribute('onclick', `this.classList.toggle('flipped'); handleAutoFlipAndMasterCardV59(${idx}, this);`);
    });
  } else if (activeLMSStep === 4) {
    // Sederhanakan tampilan Tantangan & Jurnal Refleksi:
    // Pasang indikator penghitung kata real-time & gabungkan tombol Lanjut agar otomatis memverifikasi!
    const reflArea = document.getElementById('inp-lms-refleksi');
    if (reflArea) {
      reflArea.setAttribute('placeholder', 'Tulis 1-2 kalimat pendapatmu atau kesimpulan singkat dari cerita di atas (minimal 10 kata)...');
      reflArea.setAttribute('oninput', 'updateRefleksiWordCountRealtimeV59(this.value)');
      const wordsNow = (reflArea.value || '').trim().split(/\s+/).filter(Boolean).length;
      const isReadyNow = wordsNow >= 10;

      if (!document.getElementById('v59-refl-word-badge')) {
        reflArea.insertAdjacentHTML('beforebegin', `
          <div style="display:flex; justify-content:space-between; align-items:center; flex-wrap:wrap; gap:8px; margin-bottom:10px;">
            <span style="font-size:13px; font-weight:800; color:#047857;">
              <i class="fa-solid fa-pen-to-square"></i> Tulis Pendapat Singkatmu (Minimal 10 Kata):
            </span>
            <span id="v59-refl-word-badge" class="v59-word-counter-pill ${isReadyNow ? 'ready' : ''}">
              ${isReadyNow
                ? `<i class="fa-solid fa-circle-check"></i> ${wordsNow} Kata (Syarat Minimal 10 Kata Terpenuhi ✓)`
                : `<i class="fa-solid fa-pen"></i> ${wordsNow} / 10 Kata (Tambahkan ${Math.max(0, 10 - wordsNow)} kata lagi)`}
            </span>
          </div>
        `);
      }
    }

    // Ubah tombol "Lanjut Kuis Interaktif" di bawah Langkah 4 agar menjalankan simpanPendapatDanLanjutKuisV59()
    ws.querySelectorAll('button[onclick="switchLMSStep(5)"]').forEach(btn => {
      btn.setAttribute('onclick', 'simpanPendapatDanLanjutKuisV59()');
      btn.innerHTML = `<i class="fa-solid fa-circle-check"></i> Simpan Pendapat &amp; Lanjut ke Kuis XP <i class="fa-solid fa-arrow-right"></i>`;
    });
  } else if (activeLMSStep === 5) {
    // Perjelas tombol utama klaim XP di Langkah 5
    const submitQuizBtn = document.getElementById('btn-submit-lms-quiz');
    if (submitQuizBtn && !submitQuizBtn.innerText.includes('Periksa Ulang')) {
      submitQuizBtn.innerHTML = `<i class="fa-solid fa-trophy"></i> Periksa Jawaban, Lihat Pembahasan &amp; Ambil Poin XP Sekarang!`;
    }
  }

  // D. Perbarui juga Tombol Navigasi Bawah ("Back" & "Next Chapter") di Trenning Split Reader agar Berbahasa Indonesia & Ramah Siswa
  const backBtn = ws.querySelector('.trn-btn-nav-back');
  if (backBtn) {
    backBtn.innerHTML = `<i class="fa-solid fa-arrow-left"></i> Langkah Sebelumnya`;
    backBtn.style.visibility = (activeLMSStep === 1 && trnActiveSubConceptIdxV37 === 0) ? 'hidden' : 'visible';
  }
  const nextBtn = ws.querySelector('.trn-btn-nav-next');
  if (nextBtn) {
    if (activeLMSStep === 4) {
      nextBtn.setAttribute('onclick', 'simpanPendapatDanLanjutKuisV59()');
      nextBtn.innerHTML = `<span>Simpan Pendapat &amp; Lanjut Kuis XP</span> <i class="fa-solid fa-arrow-right"></i>`;
    } else if (activeLMSStep < 5) {
      const nextMeta = V59_SIMPLE_STEPS_META[activeLMSStep] || V59_SIMPLE_STEPS_META[4];
      nextBtn.innerHTML = `<span>Lanjut ke ${nextMeta.shortLabel}</span> <i class="fa-solid fa-arrow-right"></i>`;
    } else {
      nextBtn.innerHTML = `<span>Selesai &amp; Kembali ke Daftar Bab</span> <i class="fa-solid fa-check"></i>`;
    }
  }

  // E. Perbarui Label Sidebar Kanan ("Content" -> "5 Langkah", "Discussion" -> "Diskusi", "File" -> "Berkas")
  const tabC = document.getElementById('trn-tabbtn-content');
  const tabD = document.getElementById('trn-tabbtn-discussion');
  const tabF = document.getElementById('trn-tabbtn-file');
  if (tabC) tabC.innerHTML = `<i class="fa-solid fa-list-ol"></i> 5 Langkah`;
  if (tabD) tabD.innerHTML = `<i class="fa-regular fa-comments"></i> Diskusi`;
  if (tabF) tabF.innerHTML = `<i class="fa-regular fa-folder-open"></i> Bahan Ajar`;
};



