// 1. Buka Bab Secara Instan Tanpa Pop-up Loading Palsu 420ms
bukaModulDenganAnimasiTrenningV37 = function(modIdx, targetStep, subConceptIdx) {
  if (typeof subConceptIdx === 'number') {
    trnActiveSubConceptIdxV37 = subConceptIdx;
  }
  masukKeRuangBacaModulV33(modIdx, targetStep || 1);
};

// 2. Fungsi Buka/Tutup Laci Kontekstual (Diskusi Kelas / Berkas Bahan Ajar)
function toggleV60ContextualSideDrawer(tabName) {
  if (typeof playStudentSFX === 'function') playStudentSFX('click');
  const shell = document.getElementById('trn-reader-shell-box');
  if (!shell) return;

  const isCurrentlyOpen = shell.classList.contains('v60-side-drawer-open');
  if (isCurrentlyOpen && trnActiveRightTabV37 === tabName) {
    shell.classList.remove('v60-side-drawer-open');
    return;
  }

  trnActiveRightTabV37 = tabName || 'discussion';
  shell.classList.add('v60-side-drawer-open');
  if (typeof renderTrnRightSidebarContentV37 === 'function') {
    renderTrnRightSidebarContentV37();
  }

  const rightPane = shell.querySelector('.trn-reader-right-pane');
  if (rightPane && !document.getElementById('v60-drawer-close-head')) {
    const titleMap = {
      discussion: '💬 Ruang Diskusi & Tanya Guru',
      file: '📎 Berkas Bahan Ajar & Catatan',
      content: '📑 Daftar Langkah Modul'
    };
    rightPane.insertAdjacentHTML('afterbegin', `
      <div id="v60-drawer-close-head" style="padding:14px 18px; background:#064e3b; color:#ffffff; display:flex; justify-content:space-between; align-items:center; border-bottom:2px solid #fbbf24;">
        <span id="v60-drawer-head-title" style="font-size:14px; font-weight:900;">${titleMap[trnActiveRightTabV37] || 'Panel Modul'}</span>
        <button type="button" onclick="document.getElementById('trn-reader-shell-box')?.classList.remove('v60-side-drawer-open')" style="background:rgba(255,255,255,0.2); border:none; color:#ffffff; width:32px; height:32px; border-radius:50%; cursor:pointer; font-weight:800;">
          <i class="fa-solid fa-xmark"></i>
        </button>
      </div>
    `);
  } else {
    const headTitle = document.getElementById('v60-drawer-head-title');
    if (headTitle) {
      headTitle.innerText = tabName === 'file' ? '📎 Berkas Bahan Ajar & Catatan' : '💬 Ruang Diskusi & Tanya Guru';
    }
  }
}

// 3. Kemas Ulang Hub Modul Mata Pelajaran agar Ringkas & Fokus pada Daftar Bab
const _v59OrigRenderSubjectModulesHub = renderSubjectModulesHubV33;
renderSubjectModulesHubV33 = function() {
  _v59OrigRenderSubjectModulesHub();
  const hubView = document.getElementById('lms-subject-modules-hub-view');
  if (!hubView) return;

  const modules = window.currentSubjectModulesList || [];
  const mapelName = activeLMSSubject || 'Mata Pelajaran';
  let doneCount = 0;
  let firstUnfinishedIdx = 0;
  let foundUnfinished = false;

  modules.forEach((m, idx) => {
    const p = computeSingleModuleProgressV33(m);
    if (p.isDone) doneCount++;
    else if (!foundUnfinished) {
      firstUnfinishedIdx = idx;
      foundUnfinished = true;
    }
  });

  const existingCleanHeader = document.getElementById('v60-clean-hub-banner');
  if (existingCleanHeader) existingCleanHeader.remove();

  const targetMod = modules[firstUnfinishedIdx] || modules[0];
  const toolbar = hubView.querySelector('.lms-hub-top-toolbar');
  if (toolbar && targetMod) {
    toolbar.insertAdjacentHTML('afterend', `
      <div class="v60-clean-hub-header" id="v60-clean-hub-banner">
        <div>
          <span style="background:#fbbf24; color:#0f172a; padding:4px 12px; border-radius:99px; font-size:11px; font-weight:900; text-transform:uppercase;">
            <i class="fa-solid fa-book-open-reader"></i> ${escapeHtml(mapelName)} &bull; ${doneCount}/${modules.length} Bab Selesai
          </span>
          <h2 class="v60-clean-hub-title">Pilih Bab Materi untuk Mulai Belajar</h2>
          <p class="v60-clean-hub-sub">Klik salah satu kartu bab di bawah ini untuk membaca materi secara bertahap dan mengerjakan kuis evaluasi.</p>
        </div>
        <button type="button" onclick="masukKeRuangBacaModulV33(${firstUnfinishedIdx}, 1)" style="background:#fbbf24; color:#0f172a; border:none; padding:13px 22px; border-radius:14px; font-size:13.5px; font-weight:900; cursor:pointer; display:inline-flex; align-items:center; gap:8px; box-shadow:0 8px 20px rgba(0,0,0,0.2);">
          <i class="fa-solid fa-play"></i>
          <span>${doneCount === modules.length ? 'Ulas Kembali Bab 1' : 'Lanjutkan Bab ' + (firstUnfinishedIdx + 1)}</span>
        </button>
      </div>
    `);
  }
};

// 4. Kemas Ulang Ruang Baca 5 Langkah agar Sederhana, Fokus 1 Kolom, & Bebas Distraksi
const _v59OrigRenderConstructiveWorkspace = renderConstructiveWorkspace;
renderConstructiveWorkspace = function() {
  _v59OrigRenderConstructiveWorkspace();
  if (!activeLMSModule) return;

  const ws = document.getElementById('lms-constructive-workspace');
  if (!ws) return;

  const k = activeLMSModule.konten || {};
  const qnaCount = Array.isArray(activeLMSModule.qnaList) ? activeLMSModule.qnaList.length : 0;
  const fileCount = Array.isArray(k.berkas_bahan_ajar) ? k.berkas_bahan_ajar.length : 0;
  const pctStep = Math.min(100, (activeLMSStep || 1) * 20);

  // A. Rapikan Topbar Ruang Baca menjadi 1 Baris Bersih dengan Tombol Alat Kontekstual
  const topbarLeft = ws.querySelector('.trn-reader-topbar-left');
  if (topbarLeft) {
    topbarLeft.innerHTML = `
      <div class="v60-reader-clean-toolbar">
        <div style="display:flex; align-items:center; gap:10px; min-width:0;">
          <button type="button" onclick="bukaHubDaftarModulMapelV33()" class="v60-tool-pill-btn" style="background:#d1fae5; border-color:#6ee7b7; color:#064e3b;">
            <i class="fa-solid fa-arrow-left"></i> <span>Daftar Bab</span>
          </button>
          <span style="font-size:14px; font-weight:800; color:var(--text-main); white-space:nowrap; overflow:hidden; text-overflow:ellipsis;">
            ${escapeHtml(activeLMSModule.judul)}
          </span>
        </div>

        <div class="v60-reader-tools-group">
          <button type="button" id="btn-lms-tts" onclick="toggleNarratorTTS()" class="v60-tool-pill-btn" title="Dengarkan Suara Pembaca Materi">
            <i class="fa-solid fa-volume-high" style="color:#059669;"></i> <span>Suara</span>
          </button>
          <button type="button" onclick="toggleAITutorDrawer()" class="v60-tool-pill-btn" title="Tanya Asisten AI">
            <i class="fa-solid fa-robot" style="color:#7c3aed;"></i> <span>Tanya AI</span>
          </button>
          <button type="button" onclick="toggleV60ContextualSideDrawer('discussion')" class="v60-tool-pill-btn" title="Buka Diskusi Kelas & Tanya Guru">
            <i class="fa-regular fa-comments" style="color:#0284c7;"></i> <span>Diskusi (${qnaCount})</span>
          </button>
          <button type="button" onclick="toggleV60ContextualSideDrawer('file')" class="v60-tool-pill-btn" title="Buka File Bahan Ajar & Catatan">
            <i class="fa-solid fa-paperclip" style="color:#059669;"></i> <span>Bahan Ajar (${fileCount})</span>
          </button>
          <button type="button" onclick="toggleStudentNotesDrawer()" class="v60-tool-pill-btn" title="Buka Buku Catatan Pintar">
            <i class="fa-regular fa-note-sticky" style="color:#10b981;"></i> <span>Catatan</span>
          </button>
        </div>
      </div>
      <div class="trn-reader-prog-strip" style="margin-top:8px;">
        <div class="trn-reader-prog-fill" style="width:${pctStep}%;"></div>
      </div>
    `;
  }

  // B. Pada Langkah 4 (Tantangan): Sembunyikan tombol verifikasi AI kedua yang membingungkan
  if (activeLMSStep === 4) {
    const verifyBtn = document.getElementById('btn-verify-reflection-ai');
    if (verifyBtn && verifyBtn.parentElement) {
      verifyBtn.parentElement.style.display = 'none';
    }
  }

  // C. Pada Langkah 5 (Kuis XP): Hapus kartu promosi AI Tutor besar di bawah kuis agar halaman kuis bersih
  if (activeLMSStep === 5) {
    ws.querySelectorAll('div[style*="linear-gradient(135deg, #2e1065"]').forEach(el => el.remove());
  }
};



