// -------------------------------------------------------------------------
// BAGIAN 2: SMART PARSER & IMPORTER FILE WORD (.DOCX) PINTAR & KOMPREHENSIF
// -------------------------------------------------------------------------

function normalizeAnswerKeyStringV63(rawKey) {
  if (!rawKey) return '';
  let clean = rawKey.toString().trim().toUpperCase();
  clean = clean.replace(/^(?:KUNCI\s*JAWABAN|KUNCI|JAWABAN\s*BENAR|JAWABAN|ANS|ANSWER|JWB|KEY)[\s\:\=\.\-]*/i, '').trim();
  clean = clean.split(/[\(\-\;]/)[0].trim();
  const singleOptMatch = clean.match(/^([A-E])[\.\)\s]+.*$/i);
  if (singleOptMatch) return singleOptMatch[1].toUpperCase();
  return clean.replace(/\s+/g, '');
}

function detectQuestionTypeAutoV63(item) {
  if (item.tipe && item.tipe !== 'PG') return item.tipe;
  const k = (item.kunci || '').toUpperCase().trim();
  const soalLow = (item.soal || '').toLowerCase();

  if (/^[BS](\,[BS]){2,4}$/.test(k)) return 'BS';
  if (k.includes('|') || (item.options.D && item.options.D.includes('|'))) return 'MJ';
  if (/^[A-D](\,[A-D])+$/i.test(k)) return 'PGK';
  if (/\bSEBAB\b/.test(item.soal || '') && (!item.options.A || item.options.A.trim() === '')) return 'SA';
  if (!item.options.A && !item.options.B && !item.options.C && !item.options.D && k.length > 1) return 'IS';
  if (soalLow.includes('pilih lebih dari satu') || soalLow.includes('jawaban benar lebih dari satu')) return 'PGK';
  return 'PG';
}

function smartParseComprehensiveDocxV63(rawText, rawHtml = '') {
  let externalAnswerMap = {};
  let structuredLines = [];

  if (rawHtml && rawHtml.trim() !== '') {
    const tempDiv = document.createElement('div');
    tempDiv.innerHTML = rawHtml;

    const tables = tempDiv.querySelectorAll('table');
    let parsedFromTable = [];
    tables.forEach(tbl => {
      const trs = tbl.querySelectorAll('tr');
      trs.forEach((tr) => {
        const cells = Array.from(tr.querySelectorAll('td, th')).map(c => c.innerText.replace(/\s+/g, ' ').trim());
        if (cells.length >= 6) {
          const firstCell = cells[0].toLowerCase();
          if (firstCell === 'no' || firstCell === 'nomor' || cells[1].toLowerCase() === 'soal') return;
          if (/^\d+$/.test(cells[0]) && cells[1].length > 3) {
            parsedFromTable.push({
              no: parseInt(cells[0], 10),
              soal: cells[1],
              options: {
                A: cells[2] || '',
                B: cells[3] || '',
                C: cells[4] || '',
                D: cells[5] || ''
              },
              kunci: normalizeAnswerKeyStringV63(cells[6] || 'A') || 'A',
              tipe: (cells[7] || 'PG').toUpperCase().trim()
            });
          }
        } else if (cells.length >= 2) {
          const c0 = cells[0].replace(/[\.\)]/g, '').trim();
          if (/^\d+$/.test(c0) && cells[1].length > 5) {
            structuredLines.push(`${c0}. ${cells[1]}`);
            if (cells[2]) structuredLines.push(`Kunci: ${cells[2]}`);
          }
        }
      });
    });

    if (parsedFromTable.length > 0 && structuredLines.length === 0) {
      return parsedFromTable.map((it, idx) => {
        const finalType = detectQuestionTypeAutoV63(it);
        return [
          idx + 1,
          it.soal.trim(),
          it.options.A.trim(),
          it.options.B.trim(),
          it.options.C.trim(),
          it.options.D.trim(),
          it.kunci || 'A',
          '', '', '', '', '',
          finalType
        ];
      });
    }

    tempDiv.querySelectorAll('p, li').forEach(el => {
      let txt = el.innerText.trim();
      if (!txt) return;
      const optMatch = txt.match(/^([A-Da-d])[\.\)]\s*(.+)$/);
      if (optMatch) {
        const strongEl = el.querySelector('strong, b, u');
        if (strongEl && strongEl.innerText.trim().length >= txt.length * 0.65) {
          txt = `*${txt}`;
        }
      }
      structuredLines.push(txt);
    });
  }

  const baseText = structuredLines.length > 0 ? structuredLines.join('\n') : (rawText || '');

  let normalizedText = baseText
    .replace(/\r\n/g, '\n')
    .replace(/\t/g, ' ')
    .replace(/([^\n])\s+([A-Da-d][\.\)]\s+)/g, (match, prevChar, optPrefix) => {
      return `${prevChar}\n${optPrefix}`;
    });

  const allKeyMatches = normalizedText.matchAll(/(?:^|\s|\n)(\d{1,3})\s*[\.\:\-\)]\s*([A-E](?:\,[A-E])*|[BS](?:\,[BS]){3})(?=\s|$|\n|\,|\;)/g);
  for (const m of allKeyMatches) {
    const qNum = parseInt(m[1], 10);
    const kVal = m[2].toUpperCase().trim();
    if (qNum >= 1 && qNum <= 200) {
      externalAnswerMap[qNum] = kVal;
    }
  }

  const rawLines = normalizedText.split('\n');
  let parsedItems = [];
  let currentItem = null;
  let lastOpt = null;
  let inKeySection = false;

  for (let i = 0; i < rawLines.length; i++) {
    let line = rawLines[i].trim();
    if (!line) continue;

    if (/^(?:DAFTAR\s+KUNCI\s+JAWABAN|KUNCI\s+JAWABAN\s+UJIAN|KUNCI\s+JAWABAN\s*:?\s*)$/i.test(line)) {
      inKeySection = true;
      continue;
    }
    if (inKeySection) {
      const mKeyRow = line.match(/^(\d{1,3})\s*[\.\:\-\)]\s*([A-Ea-e\,\|BSbs]+)/);
      if (mKeyRow) {
        externalAnswerMap[parseInt(mKeyRow[1], 10)] = mKeyRow[2].toUpperCase().trim();
      }
      continue;
    }

    if (/^(?:MATA\s*PELAJARAN|KELAS\s*\/|WAKTU\s*\:|PILIHLAH\s+JAWABAN|PETUNJUK\s+UMUM|SOAL\s+PILIHAN\s+GANDA)/i.test(line) && !currentItem) {
      continue;
    }

    let matchTipe = line.match(/^(?:tipe\s*soal|tipe|jenis\s*soal)[\s\:\=\.\-]*(PGK|PG|BS|SA|MJ|IS)/i);
    if (matchTipe && currentItem) {
      currentItem.tipe = matchTipe[1].toUpperCase();
      continue;
    }

    let matchKey = line.match(/^(?:kunci\s*jawaban|kunci|jawaban\s*benar|jawaban|ans|answer|jwb|key)[\s\:\=\.\-]*(.+)$/i);
    if (matchKey) {
      if (currentItem) {
        let extractedK = normalizeAnswerKeyStringV63(matchKey[1]);
        if (extractedK) currentItem.kunci = extractedK;
      }
      continue;
    }

    let matchOpt = line.match(/^(\*)?\s*[\(\[]?([A-Da-d])[\.\)\]]\s*(.*)/);
    if (matchOpt && currentItem) {
      let hasLeadingStar = !!matchOpt[1];
      let optLetter = matchOpt[2].toUpperCase();
      let optText = matchOpt[3].trim();

      let hasTrailingMarker = false;
      if (/(\*|\((?:benar|kunci)\)|\[(?:benar|kunci)\])$/i.test(optText)) {
        hasTrailingMarker = true;
        optText = optText.replace(/(\*|\((?:benar|kunci)\)|\[(?:benar|kunci)\])$/i, '').trim();
      }

      currentItem.options[optLetter] = optText;
      lastOpt = optLetter;

      if (hasLeadingStar || hasTrailingMarker) {
        currentItem._starredOpts.push(optLetter);
      }
      continue;
    }

    let matchQ = line.match(/^(?:soal\s*(?:no\.?)?\s*|no\.?\s*)?[\(\[]?(\d{1,3})[\.\)\]\:]\s*(.+)/i);
    if (matchQ) {
      let qNo = parseInt(matchQ[1], 10);
      let qText = matchQ[2].trim();

      if (/^[A-Ea-e]$/.test(qText)) {
        externalAnswerMap[qNo] = qText.toUpperCase();
        continue;
      }

      if (currentItem && (currentItem.options.A !== '' || currentItem.options.B !== '' || currentItem.kunci !== '')) {
        parsedItems.push(currentItem);
        currentItem = null;
      }

      if (!currentItem) {
        currentItem = {
          no: qNo,
          soal: qText,
          options: { A: '', B: '', C: '', D: '' },
          kunci: '',
          _starredOpts: [],
          tipe: 'PG'
        };
        lastOpt = null;
        continue;
      }
    }

    if (currentItem && currentItem.options.A && currentItem.options.B && currentItem.options.C && currentItem.options.D && currentItem.kunci) {
      parsedItems.push(currentItem);
      currentItem = {
        no: parsedItems.length + 1,
        soal: line,
        options: { A: '', B: '', C: '', D: '' },
        kunci: '',
        _starredOpts: [],
        tipe: 'PG'
      };
      lastOpt = null;
      continue;
    }

    if (currentItem) {
      if (lastOpt) {
        currentItem.options[lastOpt] += ' ' + line;
      } else {
        currentItem.soal += (currentItem.soal ? '\n' : '') + line;
      }
    } else if (line.length > 12) {
      currentItem = {
        no: parsedItems.length + 1,
        soal: line,
        options: { A: '', B: '', C: '', D: '' },
        kunci: '',
        _starredOpts: [],
        tipe: 'PG'
      };
      lastOpt = null;
    }
  }

  if (currentItem && currentItem.soal) {
    parsedItems.push(currentItem);
  }

  return parsedItems.map((item, idx) => {
    const nomorUrut = idx + 1;
    let finalKey = item.kunci;

    if (!finalKey && item._starredOpts && item._starredOpts.length > 0) {
      finalKey = item._starredOpts.join(',');
    }
    if (!finalKey && externalAnswerMap[item.no]) {
      finalKey = externalAnswerMap[item.no];
    }
    if (!finalKey && externalAnswerMap[nomorUrut]) {
      finalKey = externalAnswerMap[nomorUrut];
    }
    if (!finalKey) {
      finalKey = 'A';
    }

    item.kunci = finalKey.toUpperCase().trim();
    const finalType = detectQuestionTypeAutoV63(item);

    return [
      nomorUrut,
      (item.soal || '').trim(),
      (item.options.A || '').trim(),
      (item.options.B || '').trim(),
      (item.options.C || '').trim(),
      (item.options.D || '').trim(),
      item.kunci,
      '', '', '', '', '',
      finalType
    ];
  });
}

smartParseText = function(text) {
  return smartParseComprehensiveDocxV63(text, '');
};

function tampilkanModalReviewImportWordV63(fileName, parsedRows) {
  parsedSoalData = parsedRows;
  const mapelList = Object.keys(masterKeys || {});
  if (currentSettingsData && currentSettingsData.length > 0) {
    currentSettingsData.forEach(s => { if (s.mapel && !mapelList.includes(s.mapel)) mapelList.push(s.mapel); });
  }
  mapelList.sort();

  const currentMapelSelected = document.getElementById('viewerMapelFilter')?.value || (mapelList[0] || '');
  const mapelOptsHtml = `<option value="">-- Pilih Mata Pelajaran Tujuan --</option>` +
    mapelList.map(m => `<option value="${escapeHtml(m)}" ${m === currentMapelSelected ? 'selected' : ''}>${escapeHtml(m)}</option>`).join('');

  const previewRowsHtml = parsedRows.map((r, i) => `
    <tr>
      <td style="text-align:center; font-weight:800;">${i + 1}</td>
      <td style="white-space:normal; min-width:220px; font-size:12.5px;">${formatSoalText(r[1])}</td>
      <td style="font-size:12px;">${escapeHtml(r[2])}</td>
      <td style="font-size:12px;">${escapeHtml(r[3])}</td>
      <td style="font-size:12px;">${escapeHtml(r[4])}</td>
      <td style="font-size:12px;">${escapeHtml(r[5])}</td>
      <td style="text-align:center;">
        <input type="text" value="${escapeHtml(r[6])}" onchange="parsedSoalData[${i}][6]=this.value.toUpperCase().trim()" style="width:64px; text-align:center; font-weight:900; color:#047857; background:#ecfdf5; border:1.5px solid #10b981; border-radius:8px; padding:4px;">
      </td>
      <td style="text-align:center;">
        <select onchange="parsedSoalData[${i}][12]=this.value" style="padding:4px 6px; border-radius:8px; border:1px solid #cbd5e1; font-weight:800; font-size:11px;">
          <option value="PG" ${r[12]==='PG'?'selected':''}>PG</option>
          <option value="PGK" ${r[12]==='PGK'?'selected':''}>PGK</option>
          <option value="BS" ${r[12]==='BS'?'selected':''}>BS</option>
          <option value="SA" ${r[12]==='SA'?'selected':''}>SA</option>
          <option value="MJ" ${r[12]==='MJ'?'selected':''}>MJ</option>
          <option value="IS" ${r[12]==='IS'?'selected':''}>IS</option>
        </select>
      </td>
    </tr>`).join('');

  Swal.fire({
    title: `<i class="fa-solid fa-file-word" style="color:#2563eb;"></i> Hasil Ekstraksi Pintar Dokumen Word (${parsedRows.length} Soal)`,
    width: '980px',
    html: `
      <div style="text-align:left; font-size:13px;">
        <div style="background:#ecfdf5; border:1.5px solid #6ee7b7; border-radius:14px; padding:12px 16px; margin-bottom:14px; display:flex; justify-content:space-between; align-items:center; flex-wrap:wrap; gap:10px;">
          <div>
            <div style="font-weight:800; color:#065f46;"><i class="fa-solid fa-circle-check"></i> File: ${escapeHtml(fileName)}</div>
            <div style="font-size:12px; color:#047857;">Seluruh struktur soal, opsi A–D, tipe soal, dan kunci jawaban Admin telah disesuaikan otomatis. Anda juga dapat menyunting langsung kunci di tabel bawah sebelum disimpan.</div>
          </div>
        </div>

        <div style="display:grid; grid-template-columns: 1.2fr 1fr; gap:12px; margin-bottom:14px;">
          <div>
            <label class="edit-label">Mata Pelajaran Tujuan di Spreadsheet</label>
            <select id="docxTargetMapelSelect" class="edit-input" style="padding:10px 14px; font-weight:800;">
              ${mapelOptsHtml}
            </select>
          </div>
          <div>
            <label class="edit-label">Metode Penulisan ke Bank Soal</label>
            <select id="docxSaveModeSelect" class="edit-input" style="padding:10px 14px; font-weight:800;">
              <option value="APPEND">Tambahkan / Sambung di Bawah Soal yang Ada</option>
              <option value="OVERWRITE">Timpa / Ganti Seluruh Soal pada Mapel Ini</option>
            </select>
          </div>
        </div>

        <div class="admin-table-container" style="max-height:340px; margin-top:0;">
          <table>
            <thead>
              <tr>
                <th style="width:40px;">No</th>
                <th>Teks Soal</th>
                <th>Opsi A</th>
                <th>Opsi B</th>
                <th>Opsi C</th>
                <th>Opsi D</th>
                <th style="text-align:center;">Kunci</th>
                <th style="text-align:center;">Tipe</th>
              </tr>
            </thead>
            <tbody>${previewRowsHtml}</tbody>
          </table>
        </div>
      </div>`,
    showCancelButton: true,
    confirmButtonText: '<i class="fa-solid fa-cloud-arrow-up"></i> Tulis & Sinkronkan ke Bank Soal Sekarang',
    cancelButtonText: 'Simpan ke Draft Dulu',
    customClass: { popup: 'swal-custom-popup', confirmButton: 'swal-custom-confirm' },
    preConfirm: () => {
      const targetMapel = document.getElementById('docxTargetMapelSelect').value;
      const saveMode = document.getElementById('docxSaveModeSelect').value;
      if (!targetMapel) {
        Swal.showValidationMessage('Pilih Mata Pelajaran tujuan terlebih dahulu!');
        return false;
      }
      return { targetMapel, isAppend: saveMode === 'APPEND' };
    }
  }).then(res => {
    const btnSync = document.getElementById('btnSyncSoal');
    if (res.isConfirmed && res.value) {
      const viewerSel = document.getElementById('viewerMapelFilter');
      if (viewerSel) viewerSel.value = res.value.targetMapel;
      currentSoalMapel = res.value.targetMapel;
      eksekusiPushSoal(res.value.targetMapel, res.value.isAppend);
    } else {
      if (btnSync) btnSync.style.display = 'inline-flex';
    }
  });
}

(function bindComprehensiveDocxInputV63() {
  const oldInput = document.getElementById('docxInput');
  if (!oldInput) return;
  const newInput = oldInput.cloneNode(true);
  oldInput.parentNode.replaceChild(newInput, oldInput);

  newInput.addEventListener('change', function (e) {
    if (!e.target.files || !e.target.files.length) return;
    const file = e.target.files[0];
    const lbl = document.getElementById('fileNameDocx');
    if (lbl) lbl.innerText = file.name;

    Swal.fire({
      title: 'Menganalisis Dokumen Word...',
      html: 'Mengekstrak struktur soal, opsi jawaban A–D, dan kunci jawaban secara pintar...',
      allowOutsideClick: false,
      didOpen: () => Swal.showLoading(),
      customClass: { popup: 'swal-custom-popup' }
    });

    const reader = new FileReader();
    reader.onload = function (event) {
      const arrayBuf = event.target.result;
      Promise.all([
        mammoth.extractRawText({ arrayBuffer: arrayBuf }),
        mammoth.convertToHtml({ arrayBuffer: arrayBuf })
      ]).then(([rawRes, htmlRes]) => {
        Swal.close();
        const extracted = smartParseComprehensiveDocxV63(rawRes.value || '', htmlRes.value || '');
        if (extracted && extracted.length > 0) {
          tampilkanModalReviewImportWordV63(file.name, extracted);
        } else {
          Swal.fire({
            icon: 'error',
            title: 'Tidak Ditemukan Pola Soal',
            text: 'Pastikan dokumen Word (.docx) berisi teks soal dan opsi jawaban yang dapat dibaca.',
            customClass: { popup: 'swal-custom-popup', confirmButton: 'swal-custom-confirm' }
          });
        }
      }).catch(err => {
        Swal.fire({
          icon: 'error',
          title: 'Gagal Membaca File Word',
          text: err ? err.toString() : 'Pastikan format file adalah .docx (Microsoft Word).',
          customClass: { popup: 'swal-custom-popup' }
        });
      });
    };
    reader.readAsArrayBuffer(file);
  });
})();

