function populateModalMapelDropdownV63(selectedMapel) {
  const sel = document.getElementById('eMapelSelect');
  if (!sel) return;
  let mapels = Object.keys(masterKeys || {});
  if (currentSettingsData && currentSettingsData.length > 0) {
    currentSettingsData.forEach(s => { if (s.mapel && !mapels.includes(s.mapel)) mapels.push(s.mapel); });
  }
  mapels.sort();
  sel.innerHTML = `<option value="">-- Pilih Mata Pelajaran --</option>` +
    mapels.map(m => `<option value="${escapeHtml(m)}" ${m === selectedMapel ? 'selected' : ''}>${escapeHtml(m)}</option>`).join('');
}

function handleModalMapelChange(newMapel) {
  if (!newMapel) return;
  currentSoalMapel = newMapel;
  const viewerSel = document.getElementById('viewerMapelFilter');
  if (viewerSel && viewerSel.value !== newMapel) {
    viewerSel.value = newMapel;
    fetchSoalViewerAdmin();
  }
}

function adjustModalFieldsByTipe(tipe) {
  const t = (tipe || 'PG').toUpperCase();
  const helper = document.getElementById('eKunciHelperText');
  const kunciInp = document.getElementById('eKunci');
  const lblA = document.getElementById('lblOptA');
  const lblB = document.getElementById('lblOptB');
  const lblC = document.getElementById('lblOptC');
  const lblD = document.getElementById('lblOptD');

  if (lblA) lblA.innerText = t === 'BS' ? 'Pernyataan 1 (A)' : (t === 'MJ' ? 'Premis 1 (A)' : 'Opsi A');
  if (lblB) lblB.innerText = t === 'BS' ? 'Pernyataan 2 (B)' : (t === 'MJ' ? 'Premis 2 (B)' : 'Opsi B');
  if (lblC) lblC.innerText = t === 'BS' ? 'Pernyataan 3 (C)' : (t === 'MJ' ? 'Premis 3 (C)' : 'Opsi C');
  if (lblD) lblD.innerText = t === 'BS' ? 'Pernyataan 4 (D)' : (t === 'MJ' ? 'Pilihan Pasangan (Pisah |)' : 'Opsi D');

  if (helper && kunciInp) {
    if (t === 'PG') {
      kunciInp.placeholder = 'Contoh: A';
      helper.innerText = '*Ketik 1 huruf opsi yang benar: A, B, C, atau D.';
    } else if (t === 'PGK') {
      kunciInp.placeholder = 'Contoh: A,C';
      helper.innerText = '*Ketik huruf opsi yang benar dipisahkan tanda koma (contoh: A,C atau B,D).';
    } else if (t === 'BS') {
      kunciInp.placeholder = 'Contoh: B,S,B,S';
      helper.innerText = '*Ketik 4 urutan Benar (B) atau Salah (S) dipisahkan koma (contoh: B,S,B,S).';
    } else if (t === 'MJ') {
      kunciInp.placeholder = 'Contoh: Pilihan2,Pilihan1,Pilihan3';
      helper.innerText = '*Pada Opsi D isi pilihan dipisah tanda pipa (Pil1|Pil2|Pil3|Pil4). Pada Kunci isi pasangan yang benar untuk Premis 1, 2, 3 dipisah koma.';
    } else if (t === 'SA') {
      kunciInp.placeholder = 'Contoh: A';
      helper.innerText = '*Gunakan kata SEBAB di antara pernyataan dan alasan pada Teks Soal. Kunci diisi A, B, C, D, atau E.';
    } else if (t === 'IS') {
      kunciInp.placeholder = 'Contoh: Fotosintesis';
      helper.innerText = '*Ketik kata/angka jawaban singkat yang benar (Opsi A-D boleh dikosongkan).';
    }
  }
}

tambahSoalBaru = function() {
  let mapel = document.getElementById('viewerMapelFilter')?.value || currentSoalMapel || '';
  if (!mapel) {
    const mapelKeys = Object.keys(masterKeys || {});
    if (mapelKeys.length > 0) {
      mapel = mapelKeys[0];
      const viewerSel = document.getElementById('viewerMapelFilter');
      if (viewerSel) viewerSel.value = mapel;
      fetchSoalViewerAdmin();
    }
  }

  currentSoalMapel = mapel;
  isEditMode = false;

  const nextNo = (Array.isArray(currentSoalDataArray) ? currentSoalDataArray.length : 0) + 1;
  const titleEl = document.getElementById('modalEditorTitle');
  if (titleEl) {
    titleEl.innerHTML = `<i class="fa-solid fa-plus-circle"></i> <span id="modalEditorActionText">Tambah Soal Baru</span> <span id="eNoLabel" style="background:#d1fae5; color:#047857; padding:3px 10px; border-radius:99px; font-size:13px;">#${nextNo} ${mapel ? '• ' + escapeHtml(mapel) : ''}</span>`;
  }

  populateModalMapelDropdownV63(mapel);

  if (document.getElementById('eRowIndex')) document.getElementById('eRowIndex').value = '';
  if (document.getElementById('eNo')) document.getElementById('eNo').value = nextNo;
  if (document.getElementById('eSoalText')) document.getElementById('eSoalText').value = '';
  if (document.getElementById('eOptA')) document.getElementById('eOptA').value = '';
  if (document.getElementById('eOptB')) document.getElementById('eOptB').value = '';
  if (document.getElementById('eOptC')) document.getElementById('eOptC').value = '';
  if (document.getElementById('eOptD')) document.getElementById('eOptD').value = '';
  if (document.getElementById('eKunci')) document.getElementById('eKunci').value = 'A';
  if (document.getElementById('eTipeSoal')) {
    document.getElementById('eTipeSoal').value = 'PG';
    adjustModalFieldsByTipe('PG');
  }

  ['eSoalFile', 'eOptAFile', 'eOptBFile', 'eOptCFile', 'eOptDFile', 'eSoalOldImg', 'eOptAOldImg', 'eOptBOldImg', 'eOptCOldImg', 'eOptDOldImg'].forEach(id => {
    const el = document.getElementById(id);
    if (el) el.value = '';
  });
  ['eSoalPreview', 'eOptAPreview', 'eOptBPreview', 'eOptCPreview', 'eOptDPreview'].forEach(id => {
    const el = document.getElementById(id);
    if (el) { el.src = ''; el.style.display = 'none'; }
  });

  const modal = document.getElementById('editSoalModal');
  if (modal) {
    modal.style.display = 'flex';
    setTimeout(() => {
      document.getElementById('eSoalText')?.focus();
    }, 100);
  }
};

bukaModalEditSoal = function(index) {
  isEditMode = true;
  let data = currentSoalDataArray[index];
  if (!data) return;

  const noSoal = data[0] || (index + 1);
  const titleEl = document.getElementById('modalEditorTitle');
  if (titleEl) {
    titleEl.innerHTML = `<i class="fa-solid fa-pen-to-square"></i> <span id="modalEditorActionText">Edit Soal No.</span> <span id="eNoLabel">${noSoal}</span>`;
  }

  populateModalMapelDropdownV63(currentSoalMapel);

  document.getElementById('eRowIndex').value = index;
  document.getElementById('eNo').value = noSoal;
  document.getElementById('eSoalText').value = data[1] || '';
  document.getElementById('eOptA').value = data[2] || '';
  document.getElementById('eOptB').value = data[3] || '';
  document.getElementById('eOptC').value = data[4] || '';
  document.getElementById('eOptD').value = data[5] || '';
  document.getElementById('eKunci').value = data[6] ? data[6].toString().trim().toUpperCase() : 'A';
  const tipeVal = data[12] ? data[12].toString().trim().toUpperCase() : 'PG';
  document.getElementById('eTipeSoal').value = tipeVal;
  adjustModalFieldsByTipe(tipeVal);

  ['eSoalFile', 'eOptAFile', 'eOptBFile', 'eOptCFile', 'eOptDFile'].forEach(id => {
    const el = document.getElementById(id);
    if (el) el.value = '';
  });
  const setupPreview = (oldImgVal, inputId, previewId) => {
    const inp = document.getElementById(inputId);
    const img = document.getElementById(previewId);
    if (inp) inp.value = oldImgVal || '';
    if (img) {
      if (oldImgVal) { img.src = oldImgVal; img.style.display = 'block'; }
      else { img.src = ''; img.style.display = 'none'; }
    }
  };
  setupPreview(data[7] || '', 'eSoalOldImg', 'eSoalPreview');
  setupPreview(data[8] || '', 'eOptAOldImg', 'eOptAPreview');
  setupPreview(data[9] || '', 'eOptBOldImg', 'eOptBPreview');
  setupPreview(data[10] || '', 'eOptCOldImg', 'eOptCPreview');
  setupPreview(data[11] || '', 'eOptDOldImg', 'eOptDPreview');

  document.getElementById('editSoalModal').style.display = 'flex';
};

simpanEditSoal = async function() {
  let index = document.getElementById('eRowIndex').value;
  let mapel = document.getElementById('eMapelSelect')?.value || document.getElementById('viewerMapelFilter')?.value || currentSoalMapel;
  if (!mapel) {
    Swal.fire({ icon: 'warning', title: 'Pilih Mata Pelajaran', text: 'Silakan pilih Mata Pelajaran tujuan terlebih dahulu.' });
    return;
  }
  currentSoalMapel = mapel;
  const soalText = (document.getElementById('eSoalText')?.value || '').trim();
  const hasImgFile = document.getElementById('eSoalFile')?.files?.length > 0 || !!document.getElementById('eSoalOldImg')?.value;
  if (!soalText && !hasImgFile) {
    Swal.fire({ icon: 'warning', title: 'Soal Masih Kosong', text: 'Tuliskan teks pertanyaan soal atau unggah gambar soal terlebih dahulu.' });
    return;
  }

  Swal.fire({
    title: 'Menyimpan Soal ke Server...',
    html: 'Mengunggah gambar (jika ada) dan menyinkronkan ke Spreadsheet.',
    allowOutsideClick: false,
    didOpen: () => Swal.showLoading(),
    customClass: { popup: 'swal-custom-popup' }
  });

  try {
    let [urlSoal, urlA, urlB, urlC, urlD] = await Promise.all([
      uploadImageToGoogleScript(document.getElementById('eSoalFile')),
      uploadImageToGoogleScript(document.getElementById('eOptAFile')),
      uploadImageToGoogleScript(document.getElementById('eOptBFile')),
      uploadImageToGoogleScript(document.getElementById('eOptCFile')),
      uploadImageToGoogleScript(document.getElementById('eOptDFile'))
    ]);

    let updatedRowData = [
      document.getElementById('eNo').value || (currentSoalDataArray.length + 1),
      soalText,
      document.getElementById('eOptA').value,
      document.getElementById('eOptB').value,
      document.getElementById('eOptC').value,
      document.getElementById('eOptD').value,
      (document.getElementById('eKunci').value || 'A').trim().toUpperCase(),
      urlSoal || document.getElementById('eSoalOldImg').value || '',
      urlA || document.getElementById('eOptAOldImg').value || '',
      urlB || document.getElementById('eOptBOldImg').value || '',
      urlC || document.getElementById('eOptCOldImg').value || '',
      urlD || document.getElementById('eOptDOldImg').value || '',
      document.getElementById('eTipeSoal').value || 'PG'
    ];

    if (isEditMode && index !== '') {
      currentSoalDataArray[index] = updatedRowData;
      google.script.run.withSuccessHandler(res => {
        if (res.success) {
          catatRiwayatAksiAdmin('ADMIN', mapel, 'EDIT SOAL NO. ' + updatedRowData[0]);
          closeEditModal();
          fetchSoalViewerAdmin();
          refreshMasterKeysAdmin();
          Swal.fire({ icon: 'success', title: 'Tersimpan!', text: 'Perubahan soal berhasil diperbarui.', timer: 1500, showConfirmButton: false, customClass: { popup: 'swal-custom-popup' } });
        } else {
          Swal.fire({ icon: 'error', title: 'Gagal', text: res.message, customClass: { popup: 'swal-custom-popup' } });
        }
      }).updateSoalAdminRow(mapel, index, updatedRowData);
    } else {
      google.script.run.withSuccessHandler(res => {
        if (res.success) {
          catatRiwayatAksiAdmin('ADMIN', mapel, 'TAMBAH SOAL BARU');
          closeEditModal();
          const viewerSel = document.getElementById('viewerMapelFilter');
          if (viewerSel) viewerSel.value = mapel;
          fetchSoalViewerAdmin();
          refreshMasterKeysAdmin();
          Swal.fire({ icon: 'success', title: 'Soal Ditambahkan!', text: 'Soal baru berhasil disimpan ke Bank Soal ' + mapel + '.', timer: 1600, showConfirmButton: false, customClass: { popup: 'swal-custom-popup' } });
        } else {
          Swal.fire({ icon: 'error', title: 'Gagal', text: res.message, customClass: { popup: 'swal-custom-popup' } });
        }
      }).appendSoalMasalAdmin(mapel, [updatedRowData]);
    }
  } catch (error) {
    Swal.fire({ icon: 'error', title: 'Gagal Upload', text: error.toString(), customClass: { popup: 'swal-custom-popup' } });
  }
};

// -------------------------------------------------------------------------
// BAGIAN 4: PERBAIKAN TABEL REKAP NILAI PTS/PAS, CETAK BERITA ACARA TERURUT,
//           DAN EKSPOR EXCEL (.XLSX) UTUH DENGAN TATA LETAK RAPI
// -------------------------------------------------------------------------

renderTableAdmin = function() {
  const vMapel = document.getElementById('mapelFilter').value;
  const vKelas = document.getElementById('kelasFilter').value;
  const tbody = document.getElementById('resultBody');
  const btnPreview = document.getElementById('btnPreview');
  const btnExport = document.getElementById('btnExport');

  let filteredData = finalGradedData.filter(d => (vMapel === 'ALL' || d.mapel === vMapel) && (vKelas === 'ALL' || d.kelas === vKelas));
  if (btnPreview) btnPreview.disabled = !(filteredData.length > 0);
  if (btnExport) {
    btnExport.disabled = !(filteredData.length > 0);
    btnExport.innerHTML = '<i class="fa-solid fa-file-excel"></i> Ekspor Excel (.XLSX)';
  }

  if (filteredData.length === 0) {
    tbody.innerHTML = `<tr><td colspan="9" style="text-align:center; padding: 60px; color:var(--text-muted); font-weight:600;"><i class="fa-solid fa-satellite-dish" style="font-size:40px; color:#cbd5e1; margin-bottom:15px; display:block;"></i>Data belum tersedia untuk filter ini.</td></tr>`;
    return;
  }

  filteredData.sort((a, b) => {
    const cmpNama = (a.nama || '').localeCompare(b.nama || '', 'id', { sensitivity: 'base' });
    if (cmpNama !== 0) return cmpNama;
    return (a.kelas || '').localeCompare(b.kelas || '', 'id', { sensitivity: 'base' });
  });

  let htmlContent = '';
  filteredData.forEach((s, idx) => {
    let isDisqualified = s.vCount >= 7;
    let secBadge = s.vCount === 0
      ? '<span style="color:var(--success); font-weight:800;"><i class="fa-solid fa-check"></i> Aman (0 Pelanggaran)</span>'
      : `<div class="violation-badge"><span class="v-count" style="${isDisqualified ? 'background:#e11d48; color:white; border-color:#be123c;' : ''}">${s.vCount}x Pelanggaran${isDisqualified ? ' (Diskualifikasi)' : ''}</span><span class="v-log-list">${escapeHtml((s.vLogs || []).join(', '))}</span></div>`;
    let safeNama = (s.nama || '').replace(/'/g, "\\'");
    let safeMapel = (s.mapel || '').replace(/'/g, "\\'");
    let resetBtn = `<button onclick="resetSiswaRealtime('${safeNama}', '${safeMapel}')" title="Hapus Riwayat Ujian Siswa" style="background:#ef4444; color:white; border:none; padding:8px 12px; border-radius:10px; font-weight:800; cursor:pointer; font-size:12px;"><i class="fa-solid fa-rotate-left"></i> Reset</button>`;
    let rowStyle = isDisqualified ? 'background-color: #fff1f2;' : '';

    htmlContent += `<tr style="${rowStyle}">
      <td>${idx + 1}</td>
      <td><b>${escapeHtml(s.nama)}</b></td>
      <td>${escapeHtml(s.kelas)}</td>
      <td><span style="background:var(--bg-color); padding:4px 8px; border-radius:6px; font-size:12px; font-weight:800; color:var(--teal);">${escapeHtml(s.mapel)}</span></td>
      <td style="color:var(--success); font-weight:800; text-align:center;">${s.benar}</td>
      <td style="color:var(--danger); font-weight:800; text-align:center;">${s.salah}</td>
      <td style="text-align:center;"><span style="background:var(--success); color:white; padding:6px 14px; border-radius:12px; font-weight:800; display:inline-block;">${s.nilai}</span></td>
      <td>${secBadge}</td>
      <td style="text-align:center;">${resetBtn}</td>
    </tr>`;
  });
  tbody.innerHTML = htmlContent;
};

executePrintBeritaAcara = function() {
  const vMapel = document.getElementById('mapelFilter').value;
  const vKelas = document.getElementById('kelasFilter').value;
  let targetData = finalGradedData.filter(d => (vMapel === 'ALL' || d.mapel === vMapel) && (vKelas === 'ALL' || d.kelas === vKelas));
  if (targetData.length === 0) {
    Swal.fire({ icon: 'warning', title: 'Data Kosong', text: 'Tidak ada data nilai untuk dicetak pada filter ini.' });
    return;
  }

  targetData.sort((a, b) => {
    const cmpNama = (a.nama || '').localeCompare(b.nama || '', 'id', { sensitivity: 'base' });
    if (cmpNama !== 0) return cmpNama;
    return (a.kelas || '').localeCompare(b.kelas || '', 'id', { sensitivity: 'base' });
  });

  let tNilai = 0;
  let tbodyR = document.getElementById('r-printBody');
  let htmlCetak = '';

  targetData.forEach((s, i) => {
    const nilaiNum = Number(s.nilai) || 0;
    tNilai += nilaiNum;
    const jmlPelanggaran = Number(s.vCount) || 0;
    const statusPelanggaranText = jmlPelanggaran === 0
      ? '0 (Aman / Tertib)'
      : `${jmlPelanggaran}x Pelanggaran${jmlPelanggaran >= 7 ? ' (Diskualifikasi)' : ''}`;
    const catatanLogLengkap = (jmlPelanggaran > 0 && Array.isArray(s.vLogs) && s.vLogs.length > 0)
      ? s.vLogs.join('; ')
      : 'Tertib / Tidak ada pelanggaran keamanan selama ujian';

    htmlCetak += `
      <tr>
        <td style="text-align:center;">${i + 1}</td>
        <td><b>${escapeHtml(s.nama)}</b>${vKelas === 'ALL' ? ` <span style="font-size:11px; color:#334155;">(${escapeHtml(s.kelas)})</span>` : ''}${vMapel === 'ALL' ? `<br><small>Mapel: ${escapeHtml(s.mapel)}</small>` : ''}</td>
        <td style="text-align:center;">${s.benar}</td>
        <td style="text-align:center;">${s.salah}</td>
        <td style="text-align:center;"><b>${nilaiNum}</b></td>
        <td style="text-align:center; color:${jmlPelanggaran > 0 ? '#b91c1c' : '#0f172a'}; font-weight:bold;">${statusPelanggaranText}</td>
        <td class="v-log-print" style="font-size:11px; line-height:1.4;">${escapeHtml(catatanLogLengkap)}</td>
      </tr>`;
  });

  tbodyR.innerHTML = htmlCetak;
  document.getElementById('r-mapel').innerText = vMapel === 'ALL' ? 'Semua Mata Pelajaran' : vMapel;
  document.getElementById('r-kelas').innerText = vKelas === 'ALL' ? 'Semua Kelas (7A - 7H)' : vKelas;
  document.getElementById('r-peserta').innerText = targetData.length;
  document.getElementById('r-avg').innerText = (tNilai / targetData.length).toFixed(2);
  document.getElementById('r-tanggal').innerText = new Intl.DateTimeFormat('id-ID', { day: 'numeric', month: 'long', year: 'numeric' }).format(new Date());

  catatRiwayatAksiAdmin('ADMIN', vMapel, 'CETAK BERITA ACARA');
  document.body.classList.add('print-berita');
  setTimeout(() => {
    window.print();
    document.body.classList.remove('print-berita');
  }, 400);
};

exportToExcelAdmin = function() {
  const vMapel = document.getElementById('mapelFilter').value;
  const vKelas = document.getElementById('kelasFilter').value;
  let targetData = finalGradedData.filter(d => (vMapel === 'ALL' || d.mapel === vMapel) && (vKelas === 'ALL' || d.kelas === vKelas));

  if (targetData.length === 0) {
    Swal.fire({ icon: 'warning', title: 'Data Kosong', text: 'Tidak ada data nilai untuk diekspor.', customClass: { popup: 'swal-custom-popup' } });
    return;
  }

  targetData.sort((a, b) => {
    const cmpKelas = (a.kelas || '').localeCompare(b.kelas || '', 'id', { sensitivity: 'base' });
    if (vKelas === 'ALL' && cmpKelas !== 0) return cmpKelas;
    return (a.nama || '').localeCompare(b.nama || '', 'id', { sensitivity: 'base' });
  });

  const judulSekolah = (globalConfig && globalConfig.title) ? globalConfig.title.toUpperCase() : 'SMPN 3 BANGIL - SICIBINAGA KELAS 7';
  const labelMapel = vMapel === 'ALL' ? 'Semua Mata Pelajaran' : vMapel;
  const labelKelas = vKelas === 'ALL' ? 'Semua Kelas (7A - 7H)' : vKelas;
  const waktuCetak = new Date().toLocaleString('id-ID');

  let totalNilaiSum = 0;
  let nilaiMax = 0;
  let nilaiMin = 100;

  const sheetRows = [
    [`REKAPITULASI NILAI UJIAN (PTS/PAS) & CATATAN PELANGGARAN - ${judulSekolah}`],
    [`Mata Pelajaran: ${labelMapel}`, '', `Kelas / Rombel: ${labelKelas}`, '', `Total Peserta: ${targetData.length} Siswa`, '', `Waktu Unduh: ${waktuCetak}`],
    [],
    ['No', 'Nama Lengkap Siswa', 'Kelas', 'Mata Pelajaran', 'Jml Benar', 'Jml Salah', 'Nilai Akhir', 'Status Ketuntasan (KKM 75)', 'Jml Pelanggaran', 'Status Kedisiplinan', 'Rincian Catatan Log Waktu Pelanggaran']
  ];

  targetData.forEach((s, idx) => {
    const nilaiNum = Number(s.nilai) || 0;
    const benarNum = Number(s.benar) || 0;
    const salahNum = Number(s.salah) || 0;
    const vCountNum = Number(s.vCount) || 0;

    totalNilaiSum += nilaiNum;
    if (nilaiNum > nilaiMax) nilaiMax = nilaiNum;
    if (nilaiNum < nilaiMin) nilaiMin = nilaiNum;

    const ketuntasan = nilaiNum >= 75 ? 'TUNTAS' : 'BELUM TUNTAS';
    const statusDisiplin = vCountNum === 0
      ? 'Tertib / Aman'
      : (vCountNum >= 7 ? 'Diskualifikasi (>=7x)' : `Melanggar (${vCountNum}x)`);
    const logsText = (vCountNum > 0 && Array.isArray(s.vLogs) && s.vLogs.length > 0)
      ? s.vLogs.join(' | ')
      : 'Aman (Tidak ada catatan pelanggaran)';

    sheetRows.push([
      idx + 1,
      s.nama || '-',
      s.kelas || '-',
      s.mapel || '-',
      benarNum,
      salahNum,
      nilaiNum,
      ketuntasan,
      vCountNum,
      statusDisiplin,
      logsText
    ]);
  });

  const avgNilai = parseFloat((totalNilaiSum / targetData.length).toFixed(2));
  sheetRows.push([]);
  sheetRows.push(['', 'RATA-RATA NILAI PESERTA', '', '', '', '', avgNilai, '', '', '', '']);
  sheetRows.push(['', 'NILAI TERTINGGI (MAX)', '', '', '', '', nilaiMax, '', '', '', '']);
  sheetRows.push(['', 'NILAI TERENDAH (MIN)', '', '', '', '', nilaiMin, '', '', '', '']);

  if (typeof XLSX !== 'undefined') {
    const ws = XLSX.utils.aoa_to_sheet(sheetRows);
    ws['!merges'] = [
      { s: { r: 0, c: 0 }, e: { r: 0, c: 10 } }
    ];
    ws['!cols'] = [
      { wch: 6 },
      { wch: 34 },
      { wch: 10 },
      { wch: 22 },
      { wch: 12 },
      { wch: 12 },
      { wch: 14 },
      { wch: 24 },
      { wch: 16 },
      { wch: 22 },
      { wch: 55 }
    ];

    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, 'Rekap_Nilai_PTS_PAS');
    const cleanFileName = `Rekap_Nilai_PTS_PAS_${vMapel}_${vKelas}.xlsx`.replace(/[^a-zA-Z0-9_\-\.]/g, '_');
    XLSX.writeFile(wb, cleanFileName);
    catatRiwayatAksiAdmin('ADMIN', vMapel, 'EKSPOR EXCEL (.XLSX)');
  }
};



// =========================================================================
// 52. PEMBARUAN V64: DUKUNGAN PENUH AUTO-NUMBERING WORD (<OL>/<LI> MAMMOTH),
//     DETEKSI 4 BARIS OPSI TANPA HURUF A-D, & EKSTRAKSI OTOMATIS GAMBAR SOAL
// =========================================================================

smartParseComprehensiveDocxV63 = function(rawText, rawHtml = '') {
  let externalAnswerMap = {};
  let structuredLines = [];
  let embeddedImagesByNo = {};

  // 1. Jika ada HTML dari Mammoth, tangani <ol>/<li> (Auto-Numbering Word!) dan Tabel Word
  if (rawHtml && rawHtml.trim() !== '') {
    const tempDiv = document.createElement('div');
    tempDiv.innerHTML = rawHtml;

    // A. Cek apakah dokumen murni berbentuk Tabel Word (Minimal 6 kolom: No | Soal | A | B | C | D | Kunci)
    const tables = tempDiv.querySelectorAll('table');
    let parsedFromTable = [];
    tables.forEach(tbl => {
      const trs = tbl.querySelectorAll('tr');
      trs.forEach(tr => {
        const cells = Array.from(tr.querySelectorAll('td, th')).map(c => c.innerText.replace(/\s+/g, ' ').trim());
        if (cells.length >= 6) {
          const firstCell = cells[0].toLowerCase();
          if (firstCell === 'no' || firstCell === 'nomor' || cells[1].toLowerCase() === 'soal') return;
          if (/^\d+$/.test(cells[0]) && cells[1].length > 3) {
            parsedFromTable.push({
              no: parseInt(cells[0], 10),
              soal: cells[1],
              options: { A: cells[2] || '', B: cells[3] || '', C: cells[4] || '', D: cells[5] || '' },
              kunci: normalizeAnswerKeyStringV63(cells[6] || 'A') || 'A',
              tipe: (cells[7] || 'PG').toUpperCase().trim()
            });
          }
        }
      });
    });

    if (parsedFromTable.length > 0) {
      return parsedFromTable.map((it, idx) => [
        idx + 1, it.soal.trim(), it.options.A.trim(), it.options.B.trim(),
        it.options.C.trim(), it.options.D.trim(), it.kunci || 'A',
        '', '', '', '', '', detectQuestionTypeAutoV63(it)
      ]);
    }

    // B. Konversi tabel stimulus kecil (kurang dari 6 kolom, seperti tabel Besaran & Satuan) menjadi teks baris rapi di dalam soal
    tables.forEach(tbl => {
      const trs = Array.from(tbl.querySelectorAll('tr'));
      const tableTextLines = trs.map(tr => {
        return Array.from(tr.querySelectorAll('td, th')).map(c => c.innerText.replace(/\s+/g, ' ').trim()).join(' | ');
      }).filter(Boolean);
      const pReplacement = document.createElement('p');
      pReplacement.innerText = tableTextLines.join('\n');
      tbl.parentNode.replaceChild(pReplacement, tbl);
    });

    // C. Telusuri elemen blok (<ol>, <ul>, <p>) untuk memulihkan nomor soal & huruf opsi A-D dari Auto-Numbering Word!
    let autoQCounter = 1;
    const topElements = Array.from(tempDiv.children);

    for (let idx = 0; idx < topElements.length; idx++) {
      const el = topElements[idx];
      const tag = (el.tagName || '').toUpperCase();

      if (tag === 'OL' || tag === 'UL') {
        const lis = Array.from(el.querySelectorAll(':scope > li'));
        // Jika <ol> berisi tepat 4 atau 5 item pendek setelah pertanyaan, maka itu adalah Opsi A, B, C, D!
        const prevLine = structuredLines.length > 0 ? structuredLines[structuredLines.length - 1] : '';
        const isAfterQuestion = prevLine !== '' && !/^[A-Ea-e][\.\)]\s/.test(prevLine) && !/^Kunci\s*:/i.test(prevLine);

        if ((lis.length === 4 || lis.length === 5) && isAfterQuestion) {
          const letters = ['A', 'B', 'C', 'D', 'E'];
          lis.forEach((li, liIdx) => {
            let txt = li.innerText.replace(/\s+/g, ' ').trim();
            txt = txt.replace(/^[\(\[]?[A-Ea-e][\.\)\]]\s*/, '');
            const strongEl = li.querySelector('strong, b, u');
            const starPrefix = (strongEl && strongEl.innerText.trim().length >= txt.length * 0.65) ? '*' : '';
            structuredLines.push(`${starPrefix}${letters[liIdx]}. ${txt}`);
          });
        } else {
          // <ol> adalah daftar Nomor Soal (atau <ol> bersarang yang memiliki sub-list opsi)
          lis.forEach(li => {
            const nestedLists = Array.from(li.querySelectorAll('ol, ul'));
            let nestedOpts = [];
            nestedLists.forEach(nl => {
              Array.from(nl.querySelectorAll('li')).forEach(nli => {
                nestedOpts.push(nli.innerText.replace(/\s+/g, ' ').trim());
              });
              nl.remove();
            });

            const imgEl = li.querySelector('img');
            if (imgEl && imgEl.src && imgEl.src.startsWith('data:image')) {
              embeddedImagesByNo[autoQCounter] = imgEl.src;
            }

            let qTxt = li.innerText.trim();
            if (qTxt) {
              if (!/^\d+[\.\)]\s/.test(qTxt)) {
                structuredLines.push(`${autoQCounter}. ${qTxt}`);
              } else {
                structuredLines.push(qTxt);
              }
              autoQCounter++;
            }

            if (nestedOpts.length >= 4) {
              const letters = ['A', 'B', 'C', 'D', 'E'];
              nestedOpts.slice(0, 4).forEach((ot, oIdx) => {
                let cleanOt = ot.replace(/^[\(\[]?[A-Ea-e][\.\)\]]\s*/, '');
                structuredLines.push(`${letters[oIdx]}. ${cleanOt}`);
              });
            }
          });
        }
      } else {
        const imgEl = el.querySelector ? el.querySelector('img') : null;
        if (imgEl && imgEl.src && imgEl.src.startsWith('data:image')) {
          const currentTargetQ = Math.max(1, autoQCounter - 1);
          if (!embeddedImagesByNo[currentTargetQ]) {
            embeddedImagesByNo[currentTargetQ] = imgEl.src;
          }
        }
        let txt = (el.innerText || '').trim();
        if (txt) {
          const optMatch = txt.match(/^([A-Da-d])[\.\)]\s*(.+)$/);
          if (optMatch && el.querySelector) {
            const strongEl = el.querySelector('strong, b, u');
            if (strongEl && strongEl.innerText.trim().length >= txt.length * 0.65) {
              txt = `*${txt}`;
            }
          }
          structuredLines.push(txt);
        }
      }
    }
  }

  const baseText = structuredLines.length > 0 ? structuredLines.join('\n') : (rawText || '');

  // 2. Pecah opsi yang ditulis menyamping (inline) dalam satu baris: "A. ... B. ... C. ... D. ..."
  let normalizedText = baseText
    .replace(/\r\n/g, '\n')
    .replace(/\t/g, ' ')
    .replace(/([^\n])\s+([A-Da-d][\.\)]\s+)/g, (match, prevChar, optPrefix) => {
      return `${prevChar}\n${optPrefix}`;
    });

  // 3. Deteksi daftar Kunci Jawaban kolektif di akhir dokumen
  const allKeyMatches = normalizedText.matchAll(/(?:^|\s|\n)(\d{1,3})\s*[\.\:\-\)]\s*([A-E](?:\,[A-E])*|[BS](?:\,[BS]){3})(?=\s|$|\n|\,|\;)/g);
  for (const m of allKeyMatches) {
    const qNum = parseInt(m[1], 10);
    const kVal = m[2].toUpperCase().trim();
    if (qNum >= 1 && qNum <= 200) {
      externalAnswerMap[qNum] = kVal;
    }
  }

  const rawLines = normalizedText.split('\n');
  let parsedItems = [];
  let currentItem = null;
  let lastOpt = null;
  let inKeySection = false;

  for (let i = 0; i < rawLines.length; i++) {
    let line = rawLines[i].trim();
    if (!line) continue;

    if (/^(?:DAFTAR\s+KUNCI\s+JAWABAN|KUNCI\s+JAWABAN\s+UJIAN|KUNCI\s+JAWABAN\s*:?\s*)$/i.test(line)) {
      inKeySection = true;
      continue;
    }
    if (inKeySection) {
      const mKeyRow = line.match(/^(\d{1,3})\s*[\.\:\-\)]\s*([A-Ea-e\,\|BSbs]+)/);
      if (mKeyRow) {
        externalAnswerMap[parseInt(mKeyRow[1], 10)] = mKeyRow[2].toUpperCase().trim();
      }
      continue;
    }

    if (/^(?:SOAL\s+IPA\s+PTS|MATA\s*PELAJARAN|KELAS\s*\/|WAKTU\s*\:|PILIHLAH\s+JAWABAN|PETUNJUK\s+UMUM|PETUNJUK\s+FORMAT|SOAL\s+PILIHAN\s+GANDA)/i.test(line) && !currentItem) {
      continue;
    }

    let matchTipe = line.match(/^(?:tipe\s*soal|tipe|jenis\s*soal)[\s\:\=\.\-]*(PGK|PG|BS|SA|MJ|IS)/i);
    if (matchTipe && currentItem) {
      currentItem.tipe = matchTipe[1].toUpperCase();
      continue;
    }

    let matchKey = line.match(/^(?:kunci\s*jawaban|kunci|jawaban\s*benar|jawaban|ans|answer|jwb|key)[\s\:\=\.\-]*(.+)$/i);
    if (matchKey) {
      if (currentItem) {
        let extractedK = normalizeAnswerKeyStringV63(matchKey[1]);
        if (extractedK) currentItem.kunci = extractedK;
      }
      continue;
    }

    let matchOpt = line.match(/^(\*)?\s*[\(\[]?([A-Da-d])[\.\)\]]\s*(.*)/);
    if (matchOpt && currentItem) {
      let hasLeadingStar = !!matchOpt[1];
      let optLetter = matchOpt[2].toUpperCase();
      let optText = matchOpt[3].trim();

      let hasTrailingMarker = false;
      if (/(\*|\((?:benar|kunci)\)|\[(?:benar|kunci)\])$/i.test(optText)) {
        hasTrailingMarker = true;
        optText = optText.replace(/(\*|\((?:benar|kunci)\)|\[(?:benar|kunci)\])$/i, '').trim();
      }

      currentItem.options[optLetter] = optText;
      lastOpt = optLetter;

      if (hasLeadingStar || hasTrailingMarker) {
        currentItem._starredOpts.push(optLetter);
      }
      continue;
    }

    let matchQ = line.match(/^(?:soal\s*(?:no\.?)?\s*|no\.?\s*)?[\(\[]?(\d{1,3})[\.\)\]\:]\s*(.+)/i);
    if (matchQ) {
      let qNo = parseInt(matchQ[1], 10);
      let qText = matchQ[2].trim();

      if (/^[A-Ea-e]$/.test(qText)) {
        externalAnswerMap[qNo] = qText.toUpperCase();
        continue;
      }

      if (currentItem && (currentItem.options.A !== '' || currentItem.options.B !== '' || currentItem.kunci !== '')) {
        parsedItems.push(currentItem);
        currentItem = null;
      }

      if (!currentItem) {
        currentItem = {
          no: qNo,
          soal: qText,
          options: { A: '', B: '', C: '', D: '' },
          kunci: '',
          _starredOpts: [],
          tipe: 'PG'
        };
        lastOpt = null;
        continue;
      }
    }

    if (currentItem && currentItem.options.A && currentItem.options.B && currentItem.options.C && currentItem.options.D) {
      parsedItems.push(currentItem);
      currentItem = {
        no: parsedItems.length + 1,
        soal: line,
        options: { A: '', B: '', C: '', D: '' },
        kunci: '',
        _starredOpts: [],
        tipe: 'PG'
      };
      lastOpt = null;
      continue;
    }

    if (currentItem) {
      if (lastOpt) {
        currentItem.options[lastOpt] += ' ' + line;
      } else {
        currentItem.soal += (currentItem.soal ? '\n' : '') + line;
      }
    }
  }

  if (currentItem && currentItem.soal) {
    parsedItems.push(currentItem);
  }

  return parsedItems.map((item, idx) => {
    const nomorUrut = idx + 1;
    let finalKey = item.kunci;

    if (!finalKey && item._starredOpts && item._starredOpts.length > 0) {
      finalKey = item._starredOpts.join(',');
    }
    if (!finalKey && externalAnswerMap[item.no]) {
      finalKey = externalAnswerMap[item.no];
    }
    if (!finalKey && externalAnswerMap[nomorUrut]) {
      finalKey = externalAnswerMap[nomorUrut];
    }
    if (!finalKey) {
      finalKey = 'A';
    }

    item.kunci = finalKey.toUpperCase().trim();
    const finalType = detectQuestionTypeAutoV63(item);

    return [
      nomorUrut,
      (item.soal || '').trim(),
      (item.options.A || '').trim(),
      (item.options.B || '').trim(),
      (item.options.C || '').trim(),
      (item.options.D || '').trim(),
      item.kunci,
      '', '', '', '', '',
      finalType
    ];
  });
};



// =========================================================================
// 53. PEMBARUAN V65: FULL SUPPORT SELURUH FITUR DI IPHONE / IPAD (iOS)
//     (LMS, SUARA TTS, VOICE NOTE DISKUSI, LIVE ARENA, & UJIAN CBT ANTI-FALSE-BLUR)
// =========================================================================

function isIOSDeviceV65() {
  const ua = navigator.userAgent || '';
  const platform = navigator.platform || '';
  return /iPhone|iPod|iPad/i.test(ua) ||
         /iPhone|iPod|iPad/i.test(platform) ||
         (platform === 'MacIntel' && navigator.maxTouchPoints > 1);
}

// 1. Di iPhone/iPad (terutama karena aplikasi Google Apps Script berjalan di dalam iframe),
//    mengetuk tombol/input atau menutup keyboard iOS sering memicu `window.blur` palsu meskipun
//    siswa sama sekali tidak keluar dari aplikasi. Oleh karena itu, di iOS pelanggaran hanya
//    dicatat jika dokumen benar-benar disembunyikan (`document.hidden === true` / pindah tab / tekan Home)
//    atau terdeteksi Split-Screen!
(function patchIOSExamSecurityAndFeaturesV65() {
  if (!isIOSDeviceV65()) return;

  document.body.classList.add('ios-full-support-mode');

  // Override startStrictMode khusus iOS agar tidak memicu pelanggaran palsu akibat `!document.hasFocus()` di dalam iframe GAS
  startStrictMode = function() {
    if (strictInterval) clearInterval(strictInterval);
    strictInterval = setInterval(() => {
      if (!isExamActive) {
        clearInterval(strictInterval);
        return;
      }
      if (document.hidden) {
        handleSecurityViolation("Pindah Tab / Keluar Aplikasi di iPhone/iOS");
      }
      enforceFullScreenBlock();
    }, 1500);
  };

  // Override handleSecurityViolation agar mengabaikan trigger palsu "Buka Aplikasi Lain" / "Kehilangan Fokus / Buka Overlay"
  // jika halaman di iPhone sebenarnya masih terlihat aktif (`!document.hidden`)
  const _origHandleSecV65 = handleSecurityViolation;
  handleSecurityViolation = function(tipePelanggaran = "Pindah Tab / Keluar Aplikasi") {
    if (!isExamActive) return;
    if (isIOSDeviceV65() && !document.hidden) {
      if (tipePelanggaran === "Buka Aplikasi Lain" || tipePelanggaran === "Kehilangan Fokus / Buka Overlay" || tipePelanggaran === "Keluar Fullscreen") {
        return; // Abaikan false-positive fokus iframe di iPhone selama layar ujian masih aktif terbuka
      }
    }
    _origHandleSecV65(tipePelanggaran);
  };

  // Unlock AudioContext & SpeechSynthesis (Suara AI Tutor & Narator Materi) pada sentuhan pertama di iPhone iOS
  let iosAudioUnlocked = false;
  document.addEventListener('touchstart', function unlockIOSAudioOnce() {
    if (iosAudioUnlocked) return;
    iosAudioUnlocked = true;
    try {
      const AudioCtx = window.AudioContext || window.webkitAudioContext;
      if (AudioCtx) {
        const ctx = new AudioCtx();
        if (ctx.state === 'suspended') ctx.resume();
        const buf = ctx.createBuffer(1, 1, 22050);
        const src = ctx.createBufferSource();
        src.buffer = buf;
        src.connect(ctx.destination);
        if (src.start) src.start(0);
      }
      if ('speechSynthesis' in window) {
        const warmUtter = new SpeechSynthesisUtterance('');
        warmUtter.volume = 0;
        window.speechSynthesis.speak(warmUtter);
      }
    } catch (e) {}
  }, { passive: true, once: true });
})();



