// =========================================================================
// 55. PEMBARUAN V68:
//     KATALOG MENU RUANG BELAJAR (LMS) DENGAN ARSITEKTUR UI & UX BENTO STYLE
//     (SPOTLIGHT CARD, 3 STAT TILES INTERAKTIF, FILTER & SORTING CERDAS)
// =========================================================================
let currentLMSBentoFilterV68 = 'ALL';

function setLMSBentoFilterV68(filterMode) {
  playStudentSFX('click');
  currentLMSBentoFilterV68 = filterMode;
  ['ALL', 'HAS_MOD', 'PROGRESS', 'DONE', 'LOCKED'].forEach(k => {
    const btn = document.getElementById('lms-filter-' + k);
    if (btn) btn.classList.toggle('active', k === filterMode);
  });
  renderLMSBentoCatalogV68();
}

function triggerLMSBentoQuickResumeV68() {
  playStudentSFX('click');
  if (typeof isGlobalLMSLockedForStudent === 'function' && isGlobalLMSLockedForStudent()) {
    if (typeof showLockedLMSAlertModal === 'function') showLockedLMSAlertModal();
    return;
  }
  const saved = (studentData && studentData.email)
    ? JSON.parse(localStorage.getItem(`lms_last_${studentData.email}`) || 'null')
    : null;
  if (saved && saved.mapel && !(typeof isSubjectLMSLockedForStudent === 'function' && isSubjectLMSLockedForStudent(saved.mapel))) {
    if (typeof resumeLastLMSModule === 'function') {
      resumeLastLMSModule(saved.mapel, saved.modIdx || 0, saved.step || 1);
      return;
    }
    openStudentLMS(saved.mapel);
    return;
  }
  const subjs = globalLMSDashboard.subjects || [];
  const preferred = subjs.find(s => (Number(s.totalModules) || (s.modules ? s.modules.length : 0)) > 0 && !(typeof isSubjectLMSLockedForStudent === 'function' && isSubjectLMSLockedForStudent(s.name)))
    || subjs.find(s => !(typeof isSubjectLMSLockedForStudent === 'function' && isSubjectLMSLockedForStudent(s.name)));
  if (preferred) {
    openStudentLMS(preferred.name);
  } else if (typeof showLockedLMSAlertModal === 'function') {
    showLockedLMSAlertModal();
  }
}

function renderLMSBentoCatalogV68() {
  const lmsGrid = document.getElementById('subject-grid');
  if (!lmsGrid) return;

  const searchKw = (document.getElementById('studentSearchMapel')?.value || '').toLowerCase().trim();
  const sortMode = document.getElementById('lms-bento-sort-select')?.value || 'SMART';
  const allSubjects = globalLMSDashboard.subjects || [];
  const completedMap = globalLMSDashboard.completedMap || {};

  const lastVisited = (studentData && studentData.email)
    ? JSON.parse(localStorage.getItem(`lms_last_${studentData.email}`) || 'null')
    : null;

  // Perbarui label tombol Lanjutkan di Hero Bento LMS
  const resumeLbl = document.getElementById('lms-bento-resume-label');
  if (resumeLbl) {
    if (lastVisited && lastVisited.mapel) {
      resumeLbl.innerText = `Lanjutkan: ${lastVisited.mapel} (Tahap ${lastVisited.step || 1}/5)`;
    } else {
      resumeLbl.innerText = 'Mulai Eksplorasi Modul';
    }
  }

  let totalAllMods = 0;
  let totalDoneMods = 0;

  const enriched = allSubjects.map((subObj, idx) => {
    const mods = Array.isArray(subObj.modules) ? subObj.modules : [];
    const totMod = Number(subObj.totalModules) || mods.length;
    const doneMod = Number(subObj.completedModules) || mods.filter(m => completedMap[m.id] !== undefined).length;
    const isLocked = typeof isSubjectLMSLockedForStudent === 'function' ? isSubjectLMSLockedForStudent(subObj.name) : false;
    const pct = totMod > 0 ? Math.min(100, Math.round((doneMod / totMod) * 100)) : 0;

    const isDone = totMod > 0 && doneMod >= totMod;
    const isProgress = totMod > 0 && doneMod > 0 && doneMod < totMod;
    const hasModules = totMod > 0;
    const hasVideoAI = mods.some(m => m && m.konten && m.konten.video_interaktif && m.konten.video_interaktif.url_asli);
    const totalKuisCount = mods.reduce((acc, m) => acc + (Array.isArray(m.kuis) ? m.kuis.length : 0), 0);

    // Cari modul berikutnya yang belum tuntas untuk pratinjau
    const nextMod = mods.find(m => completedMap[m.id] === undefined) || mods[0] || null;
    const isLastVisited = !!(lastVisited && lastVisited.mapel && lastVisited.mapel === subObj.name);

    // Skor rata-rata kuis formatif di mapel ini
    const qScores = mods
      .map(m => completedMap[m.id] ? Number(completedMap[m.id].skor) : null)
      .filter(v => v !== null && !isNaN(v));
    const avgQuiz = qScores.length > 0 ? Math.round(qScores.reduce((a, b) => a + b, 0) / qScores.length) : null;

    totalAllMods += totMod;
    totalDoneMods += doneMod;

    // Prioritas Smart Sort: Last Visited -> Progress -> Has Modules (Unlocked) -> Done -> Empty -> Locked
    let smartRank = 5;
    if (isLocked) smartRank = 6;
    else if (isLastVisited && hasModules) smartRank = 0;
    else if (isProgress) smartRank = 1;
    else if (hasModules && !isDone) smartRank = 2;
    else if (isDone) smartRank = 3;
    else smartRank = 4;

    return {
      subObj, idx, name: subObj.name, mods, totMod, doneMod, pct,
      isLocked, isDone, isProgress, hasModules, hasVideoAI, totalKuisCount,
      nextMod, isLastVisited, avgQuiz, smartRank,
      meta: typeof getSubjectVisualMetaV67 === 'function'
        ? getSubjectVisualMetaV67(subObj.name, idx)
        : { icon: 'fa-book-open-reader', color: '#059669', bg: '#d1fae5' }
    };
  });

  const overallPct = totalAllMods > 0 ? Math.round((totalDoneMods / totalAllMods) * 100) : 0;
  const hasModCnt = enriched.filter(x => x.hasModules && !x.isLocked).length;
  const progCnt = enriched.filter(x => x.isProgress && !x.isLocked).length;
  const doneCnt = enriched.filter(x => x.isDone).length;
  const lockedCnt = enriched.filter(x => x.isLocked).length;

  const setTxt = (id, val) => { const el = document.getElementById(id); if (el) el.innerText = val; };
  setTxt('lms-bento-stat-pct', `${overallPct}%`);
  setTxt('lms-bento-stat-mods', `${totalDoneMods}/${totalAllMods} Modul tuntas`);
  setTxt('lms-bento-stat-hasmod', hasModCnt);
  setTxt('lms-bento-stat-done', doneCnt);

  setTxt('lms-pill-cnt-all', enriched.length);
  setTxt('lms-pill-cnt-hasmod', hasModCnt);
  setTxt('lms-pill-cnt-prog', progCnt);
  setTxt('lms-pill-cnt-done', doneCnt);
  setTxt('lms-pill-cnt-locked', lockedCnt);

  const lockPillBtn = document.getElementById('lms-filter-LOCKED');
  if (lockPillBtn) lockPillBtn.classList.toggle('hidden', lockedCnt === 0);

  let filtered = enriched.filter(item => {
    if (searchKw) {
      const inName = item.name.toLowerCase().includes(searchKw);
      const inMod = item.mods.some(m => (m.judul || '').toLowerCase().includes(searchKw));
      if (!inName && !inMod) return false;
    }
    if (currentLMSBentoFilterV68 === 'HAS_MOD') return item.hasModules && !item.isLocked;
    if (currentLMSBentoFilterV68 === 'PROGRESS') return item.isProgress && !item.isLocked;
    if (currentLMSBentoFilterV68 === 'DONE') return item.isDone;
    if (currentLMSBentoFilterV68 === 'LOCKED') return item.isLocked;
    return true;
  });

  filtered.sort((a, b) => {
    if (sortMode === 'PCT_DESC') return b.pct - a.pct || b.totMod - a.totMod || a.name.localeCompare(b.name);
    if (sortMode === 'MOD_DESC') return b.totMod - a.totMod || b.pct - a.pct || a.name.localeCompare(b.name);
    if (sortMode === 'NAME_ASC') return a.name.localeCompare(b.name);
    return a.smartRank - b.smartRank || b.totMod - a.totMod || a.name.localeCompare(b.name);
  });

  if (filtered.length === 0) {
    lmsGrid.innerHTML = `
      <div style="grid-column:1/-1; background:#ffffff; border:2px dashed #cbd5e1; border-radius:22px; padding:42px 20px; text-align:center; color:#64748b;">
        <i class="fa-solid fa-book-open" style="font-size:38px; color:#94a3b8; display:block; margin-bottom:10px;"></i>
        <div style="font-size:15px; font-weight:800; color:var(--text-main);">Tidak ada mata pelajaran LMS pada kategori ini</div>
        <div style="font-size:12.5px; margin-top:4px;">Pilih filter <b>Semua Mapel</b> atau bersihkan kolom pencarian untuk melihat seluruh ruang belajar.</div>
      </div>`;
    return;
  }

  let spotlightUsed = false;
  lmsGrid.innerHTML = filtered.map(item => {
    const safeName = item.name.replace(/'/g, "\'");
    const canSpotlight = !spotlightUsed && !item.isLocked && (item.isLastVisited || item.hasModules) && filtered.length > 1;
    if (canSpotlight) spotlightUsed = true;

    const cardClass = canSpotlight
      ? 'lms-bento-card-v68 bento-spotlight'
      : (item.isLocked
          ? 'lms-bento-card-v68 bento-locked'
          : (item.isDone
              ? 'lms-bento-card-v68 bento-done'
              : (item.hasModules ? 'lms-bento-card-v68 bento-hasmod' : 'lms-bento-card-v68 bento-empty')));

    const iconBg = canSpotlight ? 'rgba(255,255,255,0.2)' : item.meta.bg;
    const iconClr = canSpotlight ? '#fde047' : item.meta.color;

    let statusPillHtml = '';
    if (item.isLocked) {
      statusPillHtml = `<span class="lms-bento-status-pill" style="background:#ffe4e6; color:#be123c; border:1px solid #fecdd3;"><i class="fa-solid fa-lock"></i> Dikunci</span>`;
    } else if (canSpotlight) {
      statusPillHtml = `<span class="lms-bento-status-pill" style="background:#fde047; color:#064e3b;"><i class="fa-solid fa-fire"></i> ${item.isLastVisited ? 'TERAKHIR DIBUKA' : 'DIREKOMENDASIKAN'}</span>`;
    } else if (item.isDone) {
      statusPillHtml = `<span class="lms-bento-status-pill" style="background:#d1fae5; color:#047857; border:1px solid #6ee7b7;"><i class="fa-solid fa-circle-check"></i> Tuntas 100%</span>`;
    } else if (item.isProgress) {
      statusPillHtml = `<span class="lms-bento-status-pill" style="background:#e0f2fe; color:#0369a1; border:1px solid #7dd3fc;"><i class="fa-solid fa-hourglass-half"></i> ${item.pct}%</span>`;
    } else if (item.hasModules) {
      statusPillHtml = `<span class="lms-bento-status-pill" style="background:#ecfdf5; color:#059669; border:1px solid #a7f3d0;"><i class="fa-solid fa-unlock"></i> ${item.totMod} Bab</span>`;
    } else {
      statusPillHtml = `<span class="lms-bento-status-pill" style="background:#e2e8f0; color:#64748b;"><i class="fa-regular fa-compass"></i> Eksplorasi</span>`;
    }

    const previewText = item.isLocked
      ? 'Akses Ruang Belajar mata pelajaran ini sementara dikunci oleh Pengawas/Admin.'
      : (item.nextMod
          ? `${item.isDone ? 'Bab Tuntas:' : 'Bab Berikutnya:'} ${item.nextMod.judul}`
          : 'Tersedia modul eksplorasi konstruktif dasar & Asisten AI Tutor 24/7.');

    const barColor = canSpotlight
      ? 'linear-gradient(90deg, #fde047, #fbbf24)'
      : (item.isDone ? '#10b981' : (item.pct > 0 ? '#0284c7' : '#94a3b8'));

    const clickAction = item.isLocked
      ? `showLockedLMSAlertModal('${safeName}')`
      : `openStudentLMS('${safeName}')`;

    let ctaClass = 'btn-primary-lms';
    let ctaLabel = item.isProgress ? `Lanjutkan (${item.pct}%)` : (item.hasModules ? `Buka ${item.totMod} Modul` : 'Mulai Eksplorasi');
    let ctaIcon = item.isProgress ? 'fa-play' : 'fa-book-open-reader';

    if (item.isLocked) {
      ctaClass = 'btn-locked-lms';
      ctaLabel = 'Dikunci Admin';
      ctaIcon = 'fa-lock';
    } else if (canSpotlight) {
      ctaClass = 'btn-spotlight';
      ctaLabel = item.isLastVisited ? 'Lanjutkan Belajar Sekarang' : `Mulai Belajar (${item.totMod} Bab)`;
      ctaIcon = 'fa-circle-play';
    } else if (item.isDone) {
      ctaClass = 'btn-done-lms';
      ctaLabel = 'Tinjau Ulang Materi';
      ctaIcon = 'fa-rotate-left';
    } else if (!item.hasModules) {
      ctaClass = 'btn-empty-lms';
      ctaLabel = 'Buka Modul Dasar';
      ctaIcon = 'fa-compass';
    }

    return `
      <article class="${cardClass}" onclick="${clickAction}">
        <i class="fa-solid ${item.meta.icon} lms-bento-watermark"></i>

        <div class="lms-bento-card-head">
          <div class="lms-bento-ico" style="background:${iconBg}; color:${iconClr};">
            <i class="fa-solid ${item.meta.icon}"></i>
          </div>
          ${statusPillHtml}
        </div>

        <div class="lms-bento-body">
          <h4 class="lms-bento-title">${escapeHtml(item.name)}</h4>
          <div class="lms-bento-nextmod-preview">${escapeHtml(previewText)}</div>
          <div class="lms-bento-chips-row">
            <span class="lms-bento-chip"><i class="fa-solid fa-layer-group"></i> ${item.totMod > 0 ? item.totMod + ' Bab' : 'Modul Dasar'}</span>
            ${item.hasVideoAI ? `<span class="lms-bento-chip chip-video"><i class="fa-solid fa-clapperboard"></i> Video AI</span>` : ''}
            ${item.totalKuisCount > 0 ? `<span class="lms-bento-chip"><i class="fa-solid fa-bolt"></i> ${item.totalKuisCount} Kuis</span>` : ''}
            ${item.avgQuiz !== null ? `<span class="lms-bento-chip"><i class="fa-solid fa-star"></i> Skor ${item.avgQuiz}</span>` : ''}
          </div>
        </div>

        <div class="lms-bento-prog-block">
          <div class="lms-bento-prog-head">
            <span>Ketuntasan Modul (${item.doneMod}/${item.totMod})</span>
            <strong>${item.pct}%</strong>
          </div>
          <div class="lms-bento-prog-track">
            <div class="lms-bento-prog-fill" style="width:${item.pct}%; background:${barColor};"></div>
          </div>
        </div>

        <button type="button" class="lms-bento-cta-btn ${ctaClass}" onclick="event.stopPropagation(); ${clickAction}">
          <i class="fa-solid ${ctaIcon}"></i> ${ctaLabel}
        </button>
      </article>`;
  }).join('');
}

