// =========================================================================
// 56. PEMBARUAN V69:
//     1. DUAL MODE UJIAN (PTS & PAS) DENGAN MENU MODE GURU/ADMIN DI PORTAL CBT
//     2. READ/WRITE SUPABASE RESPONSIF & TEPAT SASARAN PER MODE (ZERO-MIGRATION)
//     3. REALTIME SYNC ANTAR-PERANGKAT + FILTER MODE DI PANEL ADMIN & REKAP
// =========================================================================

let cbtExamModeStateV69 = {
  activeMode: (localStorage.getItem('sicibinaga_active_exam_mode_v69') === 'PAS') ? 'PAS' : 'PTS',
  updatedBy: 'Sistem',
  updatedAt: '-',
  realtimeSubscribed: false,
  supabaseStatus: 'READY',
  lastSyncLabel: 'Siap'
};

let activeExamSessionModeV69 = cbtExamModeStateV69.activeMode;
let cbtModeBroadcastChannelV69 = null;
let cbtStudentRealtimeChannelV69 = null;

function getActiveCBTExamModeV69() {
  return (cbtExamModeStateV69.activeMode === 'PAS') ? 'PAS' : 'PTS';
}

function getExamModeLongNameV69(mode) {
  return mode === 'PAS' ? 'Penilaian Akhir Semester (PAS)' : 'Penilaian Tengah Semester (PTS)';
}

function stripExamModePrefixV69(rawMapel) {
  return (rawMapel || '').toString().trim().replace(/^\[(PTS|PAS)\]\s*/i, '').trim();
}

function buildSupabaseMapelKeyV69(cleanSubject, modeOpt) {
  const mode = (modeOpt || getActiveCBTExamModeV69()).toString().trim().toUpperCase() === 'PAS' ? 'PAS' : 'PTS';
  const clean = stripExamModePrefixV69(cleanSubject);
  return `[${mode}] ${clean}`;
}

function parseSupabaseExamRowV69(rawMapel, decryptedObj) {
  const rawStr = (rawMapel || '').toString().trim();
  const match = rawStr.match(/^\[(PTS|PAS)\]\s*(.+)$/i);
  if (match) {
    return {
      examMode: match[1].toUpperCase(),
      cleanMapel: match[2].trim(),
      dbMapelKey: rawStr
    };
  }
  const metaMode = decryptedObj && decryptedObj.__exam_mode
    ? decryptedObj.__exam_mode.toString().trim().toUpperCase()
    : 'PTS';
  return {
    examMode: metaMode === 'PAS' ? 'PAS' : 'PTS',
    cleanMapel: rawStr,
    dbMapelKey: rawStr
  };
}

function isCBTTeacherModeActiveV69() {
  return !!(
    (typeof trnLiveAdminSessionV39 !== 'undefined' && trnLiveAdminSessionV39 && trnLiveAdminSessionV39.active) ||
    (window.currentStaffRole && (window.currentStaffRole === 'ADMIN' || window.currentStaffRole === 'GURU'))
  );
}

function setCBTSupabaseStatusBadgeV69(state, labelText) {
  cbtExamModeStateV69.supabaseStatus = state;
  cbtExamModeStateV69.lastSyncLabel = labelText;

  const badge = document.getElementById('cbt-supabase-live-status-v69');
  if (badge) {
    badge.classList.remove('syncing', 'error');
    if (state === 'SYNCING') {
      badge.classList.add('syncing');
      badge.innerHTML = `<i class="fa-solid fa-spinner fa-spin"></i> ${escapeHtml(labelText)}`;
    } else if (state === 'ERROR') {
      badge.classList.add('error');
      badge.innerHTML = `<i class="fa-solid fa-triangle-exclamation"></i> ${escapeHtml(labelText)}`;
    } else {
      badge.innerHTML = `<i class="fa-solid fa-database"></i> ${escapeHtml(labelText)}`;
    }
  }

  const examChip = document.getElementById('exam-supabase-sync-chip-v69');
  if (examChip) {
    if (state === 'SYNCING') {
      examChip.style.background = '#fef3c7';
      examChip.style.color = '#b45309';
      examChip.innerHTML = `<i class="fa-solid fa-spinner fa-spin"></i> ${escapeHtml(labelText)}`;
    } else if (state === 'ERROR') {
      examChip.style.background = '#ffe4e6';
      examChip.style.color = '#be123c';
      examChip.innerHTML = `<i class="fa-solid fa-wifi"></i> ${escapeHtml(labelText)}`;
    } else {
      examChip.style.background = '#f0fdf4';
      examChip.style.color = '#047857';
      examChip.innerHTML = `<i class="fa-solid fa-cloud-check"></i> ${escapeHtml(labelText)}`;
    }
  }
}

function syncCBTModeUIElementsV69() {
  const mode = getActiveCBTExamModeV69();
  const isPAS = mode === 'PAS';
  const isTeacher = isCBTTeacherModeActiveV69();

  const bar = document.getElementById('cbt-teacher-mode-bar-v69');
  if (bar) {
    bar.classList.toggle('mode-pas-theme', isPAS);
    bar.classList.toggle('teacher-unlocked', isTeacher);
  }

  const emblem = document.getElementById('cbt-active-mode-emblem-v69');
  if (emblem) {
    emblem.classList.toggle('mode-pts', !isPAS);
    emblem.classList.toggle('mode-pas', isPAS);
    emblem.innerHTML = isPAS ? '<i class="fa-solid fa-award"></i>' : '<i class="fa-solid fa-file-pen"></i>';
  }

  const pill = document.getElementById('cbt-active-mode-pill-v69');
  if (pill) {
    pill.classList.toggle('pill-pts', !isPAS);
    pill.classList.toggle('pill-pas', isPAS);
    pill.innerText = isPAS ? 'MODE PAS AKTIF' : 'MODE PTS AKTIF';
  }

  const desc = document.getElementById('cbt-active-mode-desc-v69');
  if (desc) {
    const teacherNote = isTeacher
      ? `Mode Guru/Admin Aktif (${escapeHtml((typeof trnLiveAdminSessionV39 !== 'undefined' && trnLiveAdminSessionV39 && trnLiveAdminSessionV39.name) || window.currentStaffName || 'Admin')}) — Pilih Mode PTS atau PAS di samping.`
      : `Rekaman jawaban &amp; status selesai diarahkan tepat sasaran ke database ${mode} Supabase.`;
    desc.innerHTML = `<b>${getExamModeLongNameV69(mode)}</b> &bull; ${teacherNote}`;
  }

  const switcher = document.getElementById('cbt-admin-mode-switcher-v69');
  if (switcher) switcher.classList.toggle('hidden', !isTeacher);

  const btnPTS = document.getElementById('btn-select-mode-PTS');
  const btnPAS = document.getElementById('btn-select-mode-PAS');
  if (btnPTS) btnPTS.classList.toggle('active', !isPAS);
  if (btnPAS) btnPAS.classList.toggle('active', isPAS);

  const btnTeacher = document.getElementById('btn-cbt-teacher-mode-toggle-v69');
  const lblTeacher = document.getElementById('lbl-cbt-teacher-mode-v69');
  if (btnTeacher) btnTeacher.classList.toggle('active-teacher', isTeacher);
  if (lblTeacher) lblTeacher.innerText = isTeacher ? 'Keluar Mode Guru' : 'Mode Guru / Admin';

  const heroBox = document.querySelector('#eduview-assignments .cbt-bento-hero-v67');
  if (heroBox) heroBox.classList.toggle('hero-mode-pas', isPAS);

  const heroTitle = document.querySelector('#eduview-assignments .cbt-bento-hero-title');
  if (heroTitle) {
    heroTitle.innerText = isPAS
      ? 'Portal Ujian PAS (Penilaian Akhir Semester)'
      : 'Portal Ujian PTS (Penilaian Tengah Semester)';
  }

  const examBadge = document.getElementById('exam-active-mode-badge-v69');
  if (examBadge) {
    const sessMode = isExamActive ? activeExamSessionModeV69 : mode;
    examBadge.innerText = `MODE ${sessMode}`;
    examBadge.style.background = sessMode === 'PAS' ? '#4338ca' : '#064e3b';
  }
}

function applyActiveModeHistoryToDashboardV69() {
  const mode = getActiveCBTExamModeV69();
  const byModeHist = globalLMSDashboard.examHistoryByMode || { PTS: {}, PAS: {} };
  const byModeScore = globalLMSDashboard.examScoresByMode || { PTS: {}, PAS: {} };

  globalLMSDashboard.examHistoryMap = Object.assign({}, byModeHist[mode] || {});
  globalLMSDashboard.examScoresMap = Object.assign({}, byModeScore[mode] || {});
}

async function refreshStudentExamHistoryFromSupabaseV69(silent = false) {
  if (!studentData || !studentData.name) return;
  setCBTSupabaseStatusBadgeV69('SYNCING', 'Membaca Supabase...');
  try {
    const { data, error } = await fetchStudentOwnExamHistoryV91(studentData.name);
    if (error) throw error;

    const histByMode = { PTS: {}, PAS: {} };
    const scoresByMode = { PTS: {}, PAS: {} };

    (data || []).forEach(row => {
      const parsed = parseSupabaseExamRowV69(row.mapel, null);
      const m = parsed.examMode;
      histByMode[m][parsed.cleanMapel] = row.created_at;
      if (row.nilai !== undefined && row.nilai !== null && !isNaN(Number(row.nilai))) {
        scoresByMode[m][parsed.cleanMapel] = Number(row.nilai);
      }
    });

    globalLMSDashboard.examHistoryByMode = histByMode;
    globalLMSDashboard.examScoresByMode = scoresByMode;
    applyActiveModeHistoryToDashboardV69();

    const activeMode = getActiveCBTExamModeV69();
    const doneInMode = Object.keys(globalLMSDashboard.examHistoryMap || {}).length;
    setCBTSupabaseStatusBadgeV69('READY', `Supabase Live • ${activeMode} (${doneInMode} Selesai)`);

    if (typeof renderCBTBentoPortalV67 === 'function') renderCBTBentoPortalV67();
    if (typeof renderEduvanceCourseDonuts === 'function') renderEduvanceCourseDonuts();
    if (typeof renderEduvanceKPICards === 'function') renderEduvanceKPICards();
    syncCBTModeUIElementsV69();
  } catch (err) {
    setCBTSupabaseStatusBadgeV69('ERROR', 'Supabase Offline (Retry)');
    if (!silent && typeof showStudentToast === 'function') {
      showStudentToast('Gagal menyinkronkan riwayat ujian Supabase: ' + err.message, 'error');
    }
  }
}

function fetchGlobalExamModeFromServerV69(callback) {
  if (typeof google === 'undefined' || !google.script || !google.script.run) {
    syncCBTModeUIElementsV69();
    if (callback) callback(getActiveCBTExamModeV69());
    return;
  }
  google.script.run.withSuccessHandler(res => {
    if (res && res.success && (res.mode === 'PTS' || res.mode === 'PAS')) {
      cbtExamModeStateV69.activeMode = res.mode;
      cbtExamModeStateV69.updatedBy = res.updatedBy || 'Guru / Admin';
      cbtExamModeStateV69.updatedAt = res.updatedAt || '-';
      localStorage.setItem('sicibinaga_active_exam_mode_v69', res.mode);
    }
    applyActiveModeHistoryToDashboardV69();
    syncCBTModeUIElementsV69();
    if (typeof renderCBTBentoPortalV67 === 'function') renderCBTBentoPortalV67();
    if (callback) callback(getActiveCBTExamModeV69());
  }).withFailureHandler(() => {
    syncCBTModeUIElementsV69();
    if (callback) callback(getActiveCBTExamModeV69());
  }).getExamModeConfigServerV69();
}

