function switchGlobalCBTExamModeV69(targetMode) {
  if (!isCBTTeacherModeActiveV69()) {
    toggleCBTTeacherModeV69();
    return;
  }
  const cleanMode = targetMode === 'PAS' ? 'PAS' : 'PTS';
  if (cleanMode === getActiveCBTExamModeV69()) return;

  Swal.fire({
    title: `Ubah Mode Ujian ke ${cleanMode}?`,
    html: `Seluruh sesi pengerjaan &amp; perekaman jawaban di Supabase akan diarahkan tepat sasaran ke <b>${getExamModeLongNameV69(cleanMode)}</b> (kunci database: <code>[${cleanMode}] Mapel</code>).<br><br>Data rekaman mode sebelumnya tetap aman dan tidak akan tertimpa.`,
    icon: 'question',
    showCancelButton: true,
    confirmButtonText: `Ya, Aktifkan Mode ${cleanMode}`,
    cancelButtonText: 'Batal',
    customClass: { popup: 'swal-custom-popup', confirmButton: 'swal-custom-confirm' }
  }).then(async (res) => {
    if (!res.isConfirmed) return;
    setCBTSupabaseStatusBadgeV69('SYNCING', `Menyimpan Mode ${cleanMode}...`);

    const staffName = (typeof trnLiveAdminSessionV39 !== 'undefined' && trnLiveAdminSessionV39 && trnLiveAdminSessionV39.name) || window.currentStaffName || 'Guru / Admin';
    cbtExamModeStateV69.activeMode = cleanMode;
    cbtExamModeStateV69.updatedBy = staffName;
    localStorage.setItem('sicibinaga_active_exam_mode_v69', cleanMode);

    try {
      if (cbtModeBroadcastChannelV69) {
        await cbtModeBroadcastChannelV69.send({
          type: 'broadcast',
          event: 'exam_mode_changed',
          payload: { mode: cleanMode, updatedBy: staffName, ts: Date.now() }
        });
      }
    } catch (e) {}

    google.script.run.withSuccessHandler(saveRes => {
      if (saveRes && saveRes.success) {
        cbtExamModeStateV69.updatedAt = saveRes.updatedAt || '-';
        if (typeof showStudentToast === 'function') {
          showStudentToast(`Mode Ujian resmi beralih ke ${cleanMode} & tersinkronisasi ke Supabase!`, 'success');
        }
      }
    }).saveExamModeConfigServerV69({ mode: cleanMode, updatedBy: staffName });

    applyActiveModeHistoryToDashboardV69();
    syncCBTModeUIElementsV69();
    await refreshStudentExamHistoryFromSupabaseV69(true);
  });
}

function initCBTExamModeRealtimeChannelV69() {
  if (!supabaseClient || cbtExamModeStateV69.realtimeSubscribed) return;
  cbtExamModeStateV69.realtimeSubscribed = true;

  cbtModeBroadcastChannelV69 = supabaseClient.channel('cbt-exam-mode-sync-v69', {
    config: { broadcast: { self: false } }
  });

  cbtModeBroadcastChannelV69
    .on('broadcast', { event: 'exam_mode_changed' }, async (msg) => {
      const incomingMode = msg && msg.payload && msg.payload.mode === 'PAS' ? 'PAS' : 'PTS';
      if (incomingMode !== cbtExamModeStateV69.activeMode) {
        cbtExamModeStateV69.activeMode = incomingMode;
        cbtExamModeStateV69.updatedBy = (msg.payload && msg.payload.updatedBy) || 'Guru / Admin';
        localStorage.setItem('sicibinaga_active_exam_mode_v69', incomingMode);
        applyActiveModeHistoryToDashboardV69();
        syncCBTModeUIElementsV69();
        await refreshStudentExamHistoryFromSupabaseV69(true);
        if (typeof showStudentToast === 'function') {
          showStudentToast(`Pengawas mengubah Mode Ujian menjadi ${getExamModeLongNameV69(incomingMode)}.`, 'info');
        }
      }
    })
    .subscribe();

  cbtStudentRealtimeChannelV69 = supabaseClient.channel('cbt-student-jawaban-sync-v69')
    .on('postgres_changes', { event: '*', schema: 'public', table: 'jawaban_ujian' }, (payload) => {
      if (!studentData || !studentData.name) return;
      const recNew = payload && payload.new;
      const recOld = payload && payload.old;
      const myName = studentData.name.trim().toLowerCase();
      const matchNew = recNew && recNew.nama && recNew.nama.trim().toLowerCase() === myName;
      const matchOld = recOld && recOld.nama && recOld.nama.trim().toLowerCase() === myName;
      if (matchNew || matchOld || payload.eventType === 'DELETE') {
        refreshStudentExamHistoryFromSupabaseV69(true);
      }
    })
    .subscribe();
}

