getStorageKey = function() {
  const sessMode = isExamActive ? activeExamSessionModeV69 : getActiveCBTExamModeV69();
  return `cbt_${sessMode}_${studentData.email}_${studentData.subject}`;
};

checkAndInitNewExam = async function(selectedSubject) {
  const mode = getActiveCBTExamModeV69();
  const dbKey = buildSupabaseMapelKeyV69(selectedSubject, mode);
  const candidateKeys = mode === 'PTS' ? [dbKey, selectedSubject] : [dbKey];

  Swal.fire({
    title: `Memeriksa Akses Ujian ${mode}...`,
    text: 'Menyinkronkan status pengerjaan dari Supabase...',
    didOpen: () => Swal.showLoading(),
    allowOutsideClick: false,
    customClass: { popup: 'swal-custom-popup' }
  });

  try {
    const histChk = await fetchStudentOwnExamHistoryV91(studentData.name);
    const error = histChk.error;
    const data = (histChk.data || []).filter(r => candidateKeys.includes(r.mapel));
    if (error) {
      Swal.fire({ icon: 'error', title: 'Koneksi Supabase Gagal', text: error.message, customClass: { popup: 'swal-custom-popup', confirmButton: 'swal-custom-confirm' } });
      return;
    }
    if (data && data.length > 0) {
      Swal.fire({
        icon: 'error',
        title: `Akses ${mode} Terkunci`,
        html: `Anda sudah mengumpulkan ujian <b>${escapeHtml(selectedSubject)}</b> pada <b>Mode ${mode}</b>.<br><br>Sistem menerapkan aturan <b>Satu Kali Submit per Mode Ujian</b>.`,
        customClass: { popup: 'swal-custom-popup', confirmButton: 'swal-custom-confirm' }
      });
      refreshStudentExamHistoryFromSupabaseV69(true);
      return;
    }
    activeExamSessionModeV69 = mode;
    Swal.close();
    initNewExam(selectedSubject);
  } catch (err) {
    Swal.fire({ icon: 'error', title: 'Koneksi API Gagal', text: 'Gagal memverifikasi status ujian: ' + err.message, customClass: { popup: 'swal-custom-popup', confirmButton: 'swal-custom-confirm' } });
  }
};

const _v68StartExam = startExam;
startExam = function(selectedSubject) {
  activeExamSessionModeV69 = getActiveCBTExamModeV69();
  syncCBTModeUIElementsV69();
  return _v68StartExam.apply(this, arguments);
};

silentAutoSync = async function() {
  if (!isExamActive || isSyncingAnswers || Object.keys(userAnswers).length === 0) return;
  isSyncingAnswers = true;
  const sessMode = activeExamSessionModeV69 || getActiveCBTExamModeV69();
  const dbMapelKey = buildSupabaseMapelKeyV69(studentData.subject, sessMode);

  setCBTSupabaseStatusBadgeV69('SYNCING', `Auto-Save ${sessMode}...`);

  const answersPayload = {
    '__security_vCount': violationCount,
    '__security_vLogs': violationLogs,
    '__exam_mode': sessMode,
    '__clean_mapel': studentData.subject,
    '__recorded_at': new Date().toISOString()
  };
  examData.forEach((q, idx) => {
    if (userAnswers[idx] !== undefined && userAnswers[idx] !== '') {
      answersPayload[q.id] = userAnswers[idx];
    }
  });

  try {
    const secureAnswers = encryptData(JSON.stringify(answersPayload));
    const { error } = await simpanJawabanKeSupabase({
      nama: studentData.name,
      kelas: studentData.kelas,
      mapel: dbMapelKey,
      jawaban: secureAnswers
    });
    if (error) throw error;
    const jam = new Date().toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit' });
    setCBTSupabaseStatusBadgeV69('READY', `Tersimpan ${sessMode} (${jam})`);
  } catch (e) {
    setCBTSupabaseStatusBadgeV69('ERROR', 'Auto-Save Tertunda');
  } finally {
    isSyncingAnswers = false;
  }
};

prosesKoreksiSiswa = async function(endToken, isForceSubmit) {
  const btnSubmit = document.getElementById('btn-submit');
  const sessMode = activeExamSessionModeV69 || getActiveCBTExamModeV69();
  const dbMapelKey = buildSupabaseMapelKeyV69(studentData.subject, sessMode);

  if (btnSubmit) {
    btnSubmit.innerHTML = `<i class="fa-solid fa-spinner fa-spin"></i> Mengirim Jawaban ${sessMode} ke Supabase...`;
    btnSubmit.disabled = true;
  }
  setCBTSupabaseStatusBadgeV69('SYNCING', `Mengirim ${sessMode}...`);

  const answersPayload = {
    '__security_vCount': violationCount,
    '__security_vLogs': violationLogs,
    '__exam_mode': sessMode,
    '__clean_mapel': studentData.subject,
    '__recorded_at': new Date().toISOString()
  };
  examData.forEach((q, idx) => {
    if (userAnswers[idx] !== undefined && userAnswers[idx] !== '') {
      answersPayload[q.id] = userAnswers[idx];
    }
  });

  try {
    const secureAnswers = encryptData(JSON.stringify(answersPayload));
    const { error } = await supabaseWithRetry(() =>
      simpanJawabanKeSupabase({
        nama: studentData.name,
        kelas: studentData.kelas,
        mapel: dbMapelKey,
        jawaban: secureAnswers
      })
    );
    if (error) throw error;

    setCBTSupabaseStatusBadgeV69('READY', `Terkirim ke Supabase (${sessMode})`);
    if (typeof recordStudentLMSActivityV67 === 'function') {
      recordStudentLMSActivityV67({
        category: 'LAINNYA',
        badge: `Ujian ${sessMode} Selesai`,
        title: `Mengumpulkan Jawaban ${sessMode} ${studentData.subject}`,
        mapel: studentData.subject,
        modul: getExamModeLongNameV69(sessMode),
        detail: `Jawaban ${sessMode} mata pelajaran ${studentData.subject} berhasil disimpan ke Supabase.`,
        metrics: [`Mode ${sessMode}`, 'Terkirim Supabase ✓'],
        icon: 'fa-file-signature',
        color: sessMode === 'PAS' ? '#4f46e5' : '#059669',
        bg: sessMode === 'PAS' ? '#e0e7ff' : '#d1fae5',
        actionCBT: true
      });
    }

    isExamActive = false;
    try { clearInterval(timerInterval); } catch (e) {}
    try { if (strictInterval) clearInterval(strictInterval); } catch (e) {}
    try { localStorage.removeItem(getStorageKey()); } catch (e) {}
    try { exitFullScreenOnly(); } catch (e) {}

    try {
      document.getElementById('exam-section').classList.add('hidden');
      document.getElementById('result-section').classList.remove('hidden');
      const resTitle = document.getElementById('result-title');
      if (violationCount >= 7) {
        resTitle.innerText = `Ujian ${sessMode} Dibatalkan (Kecurangan)`;
        resTitle.style.color = 'var(--danger)';
      } else {
        resTitle.innerText = `Ujian ${sessMode} Telah Diselesaikan!`;
      }
      document.getElementById('res-name').innerText = studentData.name;
    } catch (uiErr) {}
  } catch (error) {
    setCBTSupabaseStatusBadgeV69('ERROR', 'Gagal Kirim Supabase');
    Swal.fire({
      title: 'Gagal Mengirim ke Supabase',
      text: 'Koneksi tidak stabil. Periksa internet Anda lalu klik Coba Lagi: ' + error.message,
      icon: 'error',
      customClass: { popup: 'swal-custom-popup', confirmButton: 'swal-custom-confirm' }
    });
    if (btnSubmit) {
      btnSubmit.innerHTML = '<i class="fa-solid fa-check-double"></i> Coba Lagi Sekarang';
      btnSubmit.disabled = false;
    }
  }
};

prosesKoreksiAdmin = function(rawData) {
  finalGradedData = [];

  (rawData || []).forEach(row => {
    const rawMapel = row.mapel ? row.mapel.trim() : '';
    const kelasSiswa = row.kelas ? row.kelas.trim() : 'Unknown';

    let jwb = {};
    try {
      const rawDataFromSupabase = row.jawaban;
      const decNew = decryptData(rawDataFromSupabase);
      if (decNew && (decNew.includes('__security_vCount') || decNew.includes('__exam_mode'))) {
        jwb = JSON.parse(decNew);
      } else {
        const legacyDec = (function(hash) {
          try {
            let r = decodeURIComponent(atob(hash));
            let orig = '';
            for (let i = 0; i < r.length; i++) orig += String.fromCharCode(r.charCodeAt(i) ^ 153);
            return orig;
          } catch (e) { return null; }
        })(rawDataFromSupabase);
        if (legacyDec && legacyDec.includes('__security_vCount')) {
          jwb = JSON.parse(legacyDec);
        } else {
          jwb = typeof rawDataFromSupabase === 'string' ? JSON.parse(rawDataFromSupabase) : (rawDataFromSupabase || {});
        }
      }
    } catch (e) {
      jwb = {};
    }

    const parsedMeta = parseSupabaseExamRowV69(rawMapel, jwb);
    const mapelSiswa = parsedMeta.cleanMapel;
    const examMode = parsedMeta.examMode;
    const configMapel = masterKeys[mapelSiswa];
    if (!configMapel || !configMapel.keys) return;

    const secCount = jwb['__security_vCount'] || 0;
    const secLogs = jwb['__security_vLogs'] || [];
    let bnr = 0;

    for (let no in configMapel.keys) {
      const kunciSistem = String(configMapel.keys[no]).toUpperCase().replace(/\s+/g, '');
      let jwbSiswa = jwb[no];
      if (jwbSiswa === undefined && Array.isArray(jwb)) jwbSiswa = jwb[parseInt(no, 10) - 1];

      let poinSoalIni = 0;
      if (jwbSiswa !== undefined && jwbSiswa !== null && jwbSiswa !== '') {
        if (Array.isArray(jwbSiswa)) {
          const arrKunci = kunciSistem.split(',');
          const jwbSiswaClean = jwbSiswa.map(x => String(x).toUpperCase().replace(/\s+/g, ''));
          if (arrKunci.length === 3 && kunciSistem.length > 3) {
            let benarParsial = 0;
            for (let i = 0; i < 3; i++) if (jwbSiswaClean[i] === arrKunci[i]) benarParsial++;
            poinSoalIni = benarParsial / 3;
          } else {
            if ([...jwbSiswaClean].sort().join(',') === [...arrKunci].sort().join(',')) poinSoalIni = 1;
          }
        } else if (typeof jwbSiswa === 'object' && jwbSiswa !== null) {
          const arrKunci = kunciSistem.split(',');
          if (arrKunci.length === 4) {
            let benarParsial = 0;
            ['A', 'B', 'C', 'D'].forEach((k, i) => {
              if ((jwbSiswa[k] ? String(jwbSiswa[k]).toUpperCase().replace(/\s+/g, '') : '') === arrKunci[i]) benarParsial++;
            });
            poinSoalIni = benarParsial / 4;
          } else {
            const jwbBS = [jwbSiswa.A || '', jwbSiswa.B || '', jwbSiswa.C || '', jwbSiswa.D || ''].join(',').toUpperCase().replace(/\s+/g, '');
            if (jwbBS === kunciSistem) poinSoalIni = 1;
          }
        } else {
          if (String(jwbSiswa).toUpperCase().replace(/\s+/g, '') === kunciSistem) poinSoalIni = 1;
        }
      }
      bnr += poinSoalIni;
    }

    const totalSoal = configMapel.total > 0 ? configMapel.total : 1;
    const nilaiAkhirRaw = bnr * (100 / totalSoal);
    let nilaiAkhir = Number.isInteger(nilaiAkhirRaw) ? nilaiAkhirRaw : parseFloat(nilaiAkhirRaw.toFixed(2));
    let benarFinal = Number.isInteger(bnr) ? bnr : parseFloat(bnr.toFixed(2));
    let salahFinal = parseFloat(Math.max(0, totalSoal - bnr).toFixed(2));

    if (row.nilai !== undefined && row.nilai !== null && !isNaN(row.nilai)) {
      nilaiAkhir = parseFloat(row.nilai);
      benarFinal = Math.round((nilaiAkhir / 100) * totalSoal);
      salahFinal = Math.max(0, totalSoal - benarFinal);
    }
    if (jwb['__target_nilai'] !== undefined) {
      nilaiAkhir = parseFloat(jwb['__target_nilai']);
      benarFinal = parseInt(jwb['__target_benar'], 10) || Math.round((nilaiAkhir / 100) * totalSoal);
      salahFinal = parseInt(jwb['__target_salah'], 10) || Math.max(0, totalSoal - benarFinal);
    }

    finalGradedData.push({
      nama: row.nama || '-',
      kelas: kelasSiswa,
      mapel: mapelSiswa,
      examMode: examMode,
      dbMapelKey: parsedMeta.dbMapelKey,
      benar: benarFinal,
      salah: salahFinal,
      nilai: nilaiAkhir,
      vCount: secCount,
      vLogs: secLogs,
      rawJawaban: jwb
    });
  });

  populateFilterAdmin();
  renderTableAdmin();
  if (document.getElementById('analisisMapelFilter')?.value) renderAnalisisSoal();
  if (document.getElementById('admin-tot-selesai')) document.getElementById('admin-tot-selesai').innerText = rawData.length;
  if (typeof renderAllSrnViews === 'function') {
    try { renderAllSrnViews(); } catch (e) {}
  }
};

renderTableAdmin = function() {
  const vMode = document.getElementById('adminExamModeFilter')?.value || 'ALL';
  const vMapel = document.getElementById('mapelFilter').value;
  const vKelas = document.getElementById('kelasFilter').value;
  const tbody = document.getElementById('resultBody');
  const btnPreview = document.getElementById('btnPreview');
  const btnExport = document.getElementById('btnExport');

  const filteredData = finalGradedData.filter(d =>
    (vMode === 'ALL' || (d.examMode || 'PTS') === vMode) &&
    (vMapel === 'ALL' || d.mapel === vMapel) &&
    (vKelas === 'ALL' || d.kelas === vKelas)
  );
  btnPreview.disabled = !(filteredData.length > 0);
  btnExport.disabled = !(filteredData.length > 0);

  if (filteredData.length === 0) {
    tbody.innerHTML = `<tr><td colspan="9" style="text-align:center; padding: 60px; color:var(--text-muted); font-weight:600;"><i class="fa-solid fa-satellite-dish" style="font-size:40px; color:#cbd5e1; margin-bottom:15px; display:block;"></i>Data belum tersedia untuk filter Mode ${escapeHtml(vMode)}.</td></tr>`;
    return;
  }

  let htmlContent = '';
  filteredData.sort((a, b) => {
    const aV = a.vCount >= 7 ? 1 : 0;
    const bV = b.vCount >= 7 ? 1 : 0;
    if (bV !== aV) return bV - aV;
    return a.nama.localeCompare(b.nama);
  }).forEach((s, idx) => {
    const isDisqualified = s.vCount >= 7;
    const modeTag = (s.examMode || 'PTS') === 'PAS'
      ? `<span style="background:#e0e7ff; color:#3730a3; border:1px solid #a5b4fc; padding:2px 7px; border-radius:6px; font-size:10px; font-weight:900; margin-right:5px;">PAS</span>`
      : `<span style="background:#d1fae5; color:#065f46; border:1px solid #6ee7b7; padding:2px 7px; border-radius:6px; font-size:10px; font-weight:900; margin-right:5px;">PTS</span>`;
    const secBadge = s.vCount === 0
      ? '<span style="color:var(--success); font-weight:800;"><i class="fa-solid fa-check"></i> Aman</span>'
      : `<div class="violation-badge"><span class="v-count" style="${isDisqualified ? 'background:#e11d48; color:white; border-color:#be123c;' : ''}">${s.vCount}x Melanggar</span><span class="v-log-list">${escapeHtml(s.vLogs.slice(0, 2).join(', '))}${s.vCount > 2 ? '...' : ''}</span></div>`;
    const safeNama = s.nama.replace(/'/g, "\'");
    const safeDbKey = (s.dbMapelKey || s.mapel).replace(/'/g, "\'");
    const resetBtn = `<button onclick="resetSiswaRealtime('${safeNama}', '${safeDbKey}')" title="Hapus Riwayat Ujian (${s.examMode || 'PTS'})" style="background:#ef4444; color:white; border:none; padding:8px 12px; border-radius:10px; font-weight:800; cursor:pointer; font-size:12px;"><i class="fa-solid fa-rotate-left"></i> Reset</button>`;

    htmlContent += `<tr style="${isDisqualified ? 'background-color: #fff1f2;' : ''}">
      <td>${idx + 1}</td>
      <td><b>${escapeHtml(s.nama)}</b></td>
      <td>${escapeHtml(s.kelas)}</td>
      <td>${modeTag}<span style="background:var(--bg-color); padding:4px 8px; border-radius:6px; font-size:12px; font-weight:800; color:var(--teal);">${escapeHtml(s.mapel)}</span></td>
      <td style="color:var(--success); font-weight:800; text-align:center;">${s.benar}</td>
      <td style="color:var(--danger); font-weight:800; text-align:center;">${s.salah}</td>
      <td style="text-align:center;"><span style="background:var(--success); color:white; padding:6px 14px; border-radius:12px; font-weight:800; display:inline-block;">${s.nilai}</span></td>
      <td>${secBadge}</td>
      <td style="text-align:center;">${resetBtn}</td>
    </tr>`;
  });
  tbody.innerHTML = htmlContent;
};

