// Reset siswa di Supabase secara tepat sasaran (menghapus baris sesuai kunci `[PTS]` / `[PAS]` / legacy)
resetSiswaRealtime = function(namaSiswa, mapelTarget) {
  const cleanSubject = stripExamModePrefixV69(mapelTarget);
  const msgText = mapelTarget === '-'
    ? `Keluarkan paksa <b>${escapeHtml(namaSiswa)}</b> dari halaman Dashboard?`
    : `Hapus jawaban di Supabase &amp; keluarkan <b>${escapeHtml(namaSiswa)}</b> dari ujian <b>${escapeHtml(mapelTarget)}</b>?`;

  Swal.fire({
    title: 'Konfirmasi Reset & Kick',
    html: msgText,
    icon: 'warning',
    showCancelButton: true,
    confirmButtonText: 'Ya, Eksekusi',
    cancelButtonText: 'Batal',
    customClass: { popup: 'swal-custom-popup', confirmButton: 'swal-custom-confirm' }
  }).then(async (result) => {
    if (!result.isConfirmed) return;
    Swal.fire({ title: 'Memproses Reset di Supabase...', didOpen: () => Swal.showLoading(), allowOutsideClick: false, customClass: { popup: 'swal-custom-popup' } });
    try {
      if (mapelTarget !== '-') {
        const keysToDelete = [mapelTarget];
        if (mapelTarget === cleanSubject) {
          keysToDelete.push(buildSupabaseMapelKeyV69(cleanSubject, getActiveCBTExamModeV69()));
        }
        const { error } = await supabaseClient.from('jawaban_ujian').delete().eq('nama', namaSiswa).in('mapel', keysToDelete);
        if (error) throw error;
      }
      if (presenceChannel) {
        await presenceChannel.send({ type: 'broadcast', event: 'kick_user', payload: { namaSiswa: namaSiswa, mapel: cleanSubject || '-' } });
      }
      catatRiwayatAksiAdmin('ADMIN', mapelTarget === '-' ? 'DASHBOARD' : mapelTarget, `RESET & KICK: ${namaSiswa}`);
      Swal.fire({ icon: 'success', title: 'Berhasil', text: `Sesi ${namaSiswa} (${mapelTarget}) telah direset di Supabase.`, timer: 1800, showConfirmButton: false, customClass: { popup: 'swal-custom-popup' } });
      tarikDataSupabaseSilent();
    } catch (err) {
      Swal.fire({ icon: 'error', title: 'Error API Supabase', text: err.message, customClass: { popup: 'swal-custom-popup', confirmButton: 'swal-custom-confirm' } });
    }
  });
};

