// =========================================================================
// 57. PEMBARUAN V70:
//     BENTO STYLE UI/UX SEDERHANA & VISUAL WIDGET TIDAK MONOTON DI BERANDA
//     - PROGRES MATA PELAJARAN: GAUGE DECK + SPOTLIGHT + 2x2 RADIAL TILES + HORIZONTAL RAIL
//     - REKAMAN AKTIVITAS LMS: LIVE SPOTLIGHT + DISTRIBUTION STACKED BAR + CLEAN TIMELINE
// =========================================================================

let showAllActivitiesV70 = false;

function toggleShowAllActivitiesV70() {
  showAllActivitiesV70 = !showAllActivitiesV70;
  renderEduvanceTodayTimeline();
}

// -------------------------------------------------------------------------
// 1. RENDERER BENTO PROGRES MATA PELAJARAN (REKAP PERSENTASE) V70
// -------------------------------------------------------------------------
renderEduvanceCourseDonuts = function() {
  const grid = document.getElementById('eduvance-course-donut-grid');
  if (!grid) return;

  const kw = (document.getElementById('studentSearchMapel')?.value || '').toLowerCase().trim();
  const allSubjects = globalLMSDashboard.subjects || [];
  const completedMap = globalLMSDashboard.completedMap || {};
  const examHistory = globalLMSDashboard.examHistoryMap || {};
  const examScores = globalLMSDashboard.examScoresMap || {};
  const activeExamMode = typeof getActiveCBTExamModeV69 === 'function' ? getActiveCBTExamModeV69() : 'PTS';

  let sumTotalTasks = 0, sumDoneTasks = 0, sumTotalMods = 0, sumDoneMods = 0, sumDoneExams = 0;

  const enriched = allSubjects.map((s, idx) => {
    const mods = Array.isArray(s.modules) ? s.modules : [];
    const totMod = Number(s.totalModules) || mods.length;
    const doneMod = Number(s.completedModules) || mods.filter(m => completedMap[m.id] !== undefined).length;
    const isExamDone = examHistory[s.name] !== undefined;
    const isExamOpen = s.examStatus === 'AKTIF';

    const totalTasks = totMod + 1;
    const doneTasks = doneMod + (isExamDone ? 1 : 0);
    const overallPct = totalTasks > 0 ? Math.min(100, Math.round((doneTasks / totalTasks) * 100)) : 0;
    const lmsPct = totMod > 0 ? Math.min(100, Math.round((doneMod / totMod) * 100)) : null;

    const modScores = mods
      .map(m => completedMap[m.id] ? Number(completedMap[m.id].skor) : null)
      .filter(v => v !== null && !isNaN(v));
    if (examScores[s.name] !== undefined && !isNaN(Number(examScores[s.name]))) {
      modScores.push(Number(examScores[s.name]));
    }
    const avgScore = modScores.length > 0
      ? Math.round(modScores.reduce((a, b) => a + b, 0) / modScores.length)
      : null;

    sumTotalTasks += totalTasks;
    sumDoneTasks += doneTasks;
    sumTotalMods += totMod;
    sumDoneMods += doneMod;
    if (isExamDone) sumDoneExams++;

    return {
      raw: s, idx, name: s.name, totMod, doneMod, isExamDone, isExamOpen,
      totalTasks, doneTasks, overallPct, lmsPct, avgScore,
      meta: typeof getSubjectVisualMetaV67 === 'function'
        ? getSubjectVisualMetaV67(s.name, idx)
        : { icon: 'fa-book', color: '#059669', bg: '#d1fae5' }
    };
  });

  const overallTotalPct = sumTotalTasks > 0 ? Math.round((sumDoneTasks / sumTotalTasks) * 100) : 0;
  const totalLmsPct = sumTotalMods > 0 ? Math.round((sumDoneMods / sumTotalMods) * 100) : 0;
  const totalCbtPct = allSubjects.length > 0 ? Math.round((sumDoneExams / allSubjects.length) * 100) : 0;
  const tuntasCnt = enriched.filter(x => x.overallPct === 100).length;
  const progCnt = enriched.filter(x => x.overallPct > 0 && x.overallPct < 100).length;
  const belumCnt = enriched.filter(x => x.overallPct === 0).length;

  const subEl = document.getElementById('eduvance-course-progress-sub');
  if (subEl) {
    subEl.innerText = `${allSubjects.length} Mapel • ${sumDoneTasks}/${sumTotalTasks} target selesai (${overallTotalPct}%)`;
  }

  // 1. Top Bento Visual Deck (1 Gauge Tile + 2 Stacked Mini Tiles)
  const gR = 35, gCirc = 2 * Math.PI * gR;
  const gOff = gCirc - (overallTotalPct / 100) * gCirc;

  const topDeckHtml = `
    <div class="v70-prog-bento-deck">
      <div class="v70-prog-gauge-tile">
        <div class="v70-gauge-ring-wrap">
          <svg viewBox="0 0 86 86">
            <circle cx="43" cy="43" r="${gR}" fill="none" stroke="rgba(255,255,255,0.18)" stroke-width="8"></circle>
            <circle cx="43" cy="43" r="${gR}" fill="none" stroke="#fde047" stroke-width="8"
              stroke-dasharray="${gCirc.toFixed(1)}" stroke-dashoffset="${gOff.toFixed(1)}" stroke-linecap="round"></circle>
          </svg>
          <div class="v70-gauge-ring-text">
            <span class="v70-gauge-big-pct">${overallTotalPct}%</span>
            <span class="v70-gauge-small-lbl">TOTAL</span>
          </div>
        </div>
        <div class="v70-gauge-caption"><b>${tuntasCnt}/${allSubjects.length}</b> Mapel Tuntas</div>
      </div>

      <div class="v70-prog-mini-stack">
        <div class="v70-mini-metric-tile tile-lms" onclick="switchEduvanceNav('courses')" title="Buka Ruang Belajar LMS">
          <div class="v70-mini-metric-top">
            <span class="v70-mini-metric-lbl"><i class="fa-solid fa-book-open-reader"></i> Modul LMS</span>
            <span class="v70-mini-metric-val">${totalLmsPct}%</span>
          </div>
          <div class="v70-mini-bar-bg"><div class="v70-mini-bar-fg" style="width:${totalLmsPct}%; background:#2563eb;"></div></div>
          <div class="v70-mini-metric-sub">${sumDoneMods} dari ${sumTotalMods} modul selesai</div>
        </div>

        <div class="v70-mini-metric-tile tile-cbt" onclick="switchEduvanceNav('assignments')" title="Buka Portal Ujian CBT">
          <div class="v70-mini-metric-top">
            <span class="v70-mini-metric-lbl"><i class="fa-solid fa-file-signature"></i> Ujian ${activeExamMode}</span>
            <span class="v70-mini-metric-val">${totalCbtPct}%</span>
          </div>
          <div class="v70-mini-bar-bg"><div class="v70-mini-bar-fg" style="width:${totalCbtPct}%; background:#d97706;"></div></div>
          <div class="v70-mini-metric-sub">${sumDoneExams} dari ${allSubjects.length} mapel selesai</div>
        </div>
      </div>
    </div>`;

  // 2. Filter Chips Ringkas
  const filterHtml = `
    <div class="v70-pills-row">
      <button type="button" class="v70-pill-btn ${currentSubjectPctFilterV67 === 'ALL' ? 'active' : ''}" onclick="setSubjectPctFilterV67('ALL')">Semua (${enriched.length})</button>
      <button type="button" class="v70-pill-btn ${currentSubjectPctFilterV67 === 'DONE' ? 'active' : ''}" onclick="setSubjectPctFilterV67('DONE')">✓ Tuntas (${tuntasCnt})</button>
      <button type="button" class="v70-pill-btn ${currentSubjectPctFilterV67 === 'PROGRESS' ? 'active' : ''}" onclick="setSubjectPctFilterV67('PROGRESS')">⏳ Berjalan (${progCnt})</button>
      <button type="button" class="v70-pill-btn ${currentSubjectPctFilterV67 === 'ZERO' ? 'active' : ''}" onclick="setSubjectPctFilterV67('ZERO')">Belum (${belumCnt})</button>
    </div>`;

  // Filter & Sort Mapel
  let filtered = enriched.filter(item => {
    if (kw && !item.name.toLowerCase().includes(kw)) return false;
    if (currentSubjectPctFilterV67 === 'DONE') return item.overallPct === 100;
    if (currentSubjectPctFilterV67 === 'PROGRESS') return item.overallPct > 0 && item.overallPct < 100;
    if (currentSubjectPctFilterV67 === 'ZERO') return item.overallPct === 0;
    return true;
  });
  filtered.sort((a, b) => b.overallPct - a.overallPct || b.totMod - a.totMod || a.name.localeCompare(b.name));

  if (filtered.length === 0) {
    grid.innerHTML = topDeckHtml + filterHtml + `
      <div style="text-align:center; padding:24px 14px; background:#f8fafc; border:1.5px dashed #cbd5e1; border-radius:16px; color:#64748b; font-size:12.5px; font-weight:700;">
        Belum ada mata pelajaran pada filter ini.
      </div>`;
    return;
  }

  // 3. Bento Mosaic Grid: 1 Spotlight Tile (paling menonjol) + 4 Square Radial Tiles (2x2) + Horizontal Rail untuk sisanya
  const spotlightItem = filtered[0];
  const squareLimit = (showAllSubjectPctV67 || kw) ? filtered.length : Math.min(filtered.length, 5);
  const squareItems = filtered.slice(1, squareLimit);
  const railItems = (!showAllSubjectPctV67 && !kw && filtered.length > 5) ? filtered.slice(5) : [];

  // Spotlight Tile HTML
  const spR = 26, spCirc = 2 * Math.PI * spR;
  const spOff = spCirc - (spotlightItem.overallPct / 100) * spCirc;
  const safeSpotName = spotlightItem.name.replace(/'/g, "\'");
  const spotTagLabel = spotlightItem.overallPct === 100
    ? 'MAPEL TUNTAS 100%'
    : (spotlightItem.overallPct > 0 ? 'PROGRES TERTINGGI' : 'REKOMENDASI MULAI');

  const spotlightHtml = `
    <div class="v70-subj-spotlight-tile ${spotlightItem.overallPct === 100 ? 'spot-complete' : ''}" onclick="openStudentLMS('${safeSpotName}')">
      <div class="v70-spot-left">
        <span class="v70-spot-tag"><i class="fa-solid fa-star"></i> ${spotTagLabel}</span>
        <div class="v70-spot-title">${escapeHtml(spotlightItem.name)}</div>
        <div class="v70-spot-meta">
          <span class="v70-spot-chip">${spotlightItem.totMod > 0 ? `LMS ${spotlightItem.doneMod}/${spotlightItem.totMod} Bab` : 'Modul Dasar'}</span>
          <span class="v70-spot-chip">${spotlightItem.isExamDone ? `${activeExamMode} ✓` : (spotlightItem.isExamOpen ? `${activeExamMode} Terbuka` : `${activeExamMode} 0%`)}</span>
          ${spotlightItem.avgScore !== null ? `<span class="v70-spot-chip">Skor ${spotlightItem.avgScore}</span>` : ''}
        </div>
      </div>
      <div class="v70-spot-ring">
        <svg viewBox="0 0 64 64">
          <circle cx="32" cy="32" r="${spR}" fill="none" stroke="rgba(255,255,255,0.22)" stroke-width="6"></circle>
          <circle cx="32" cy="32" r="${spR}" fill="none" stroke="#fde047" stroke-width="6"
            stroke-dasharray="${spCirc.toFixed(1)}" stroke-dashoffset="${spOff.toFixed(1)}" stroke-linecap="round"></circle>
        </svg>
        <div class="v70-spot-ring-val">${spotlightItem.overallPct}%</div>
      </div>
    </div>`;

  // Square Radial Bento Tiles (2x2 yang tidak monoton)
  const sqR = 17, sqCirc = 2 * Math.PI * sqR;
  const squaresHtml = squareItems.map(item => {
    const safeName = item.name.replace(/'/g, "\'");
    const sqOff = sqCirc - (item.overallPct / 100) * sqCirc;
    const strokeCol = item.overallPct === 100 ? '#10b981' : (item.overallPct > 0 ? item.meta.color : '#cbd5e1');
    const cbtTxt = item.isExamDone ? 'CBT ✓' : (item.isExamOpen ? 'CBT Buka' : 'CBT 0%');
    const cbtBg = item.isExamDone ? '#d1fae5' : (item.isExamOpen ? '#fef3c7' : '#f1f5f9');
    const cbtClr = item.isExamDone ? '#047857' : (item.isExamOpen ? '#b45309' : '#64748b');

    return `
      <div class="v70-subj-square-tile" onclick="openStudentLMS('${safeName}')" title="Buka Ruang Belajar ${escapeHtml(item.name)}">
        <div class="v70-sq-top">
          <div class="v70-sq-radial-ico">
            <svg viewBox="0 0 44 44">
              <circle cx="22" cy="22" r="${sqR}" fill="${item.meta.bg}" stroke="#e2e8f0" stroke-width="4"></circle>
              <circle cx="22" cy="22" r="${sqR}" fill="none" stroke="${strokeCol}" stroke-width="4"
                stroke-dasharray="${sqCirc.toFixed(1)}" stroke-dashoffset="${sqOff.toFixed(1)}" stroke-linecap="round"></circle>
            </svg>
            <div class="v70-sq-radial-center" style="color:${item.meta.color};">
              <i class="fa-solid ${item.meta.icon}"></i>
            </div>
          </div>
          <div class="v70-sq-pct-big" style="color:${item.overallPct > 0 ? strokeCol : '#64748b'};">${item.overallPct}%</div>
        </div>
        <div class="v70-sq-name">${escapeHtml(item.name)}</div>
        <div class="v70-sq-foot">
          <span style="color:#64748b;">LMS ${item.doneMod}/${item.totMod}</span>
          <span class="v70-sq-badge" style="background:${cbtBg}; color:${cbtClr};">${cbtTxt}</span>
        </div>
      </div>`;
  }).join('');

  // Horizontal Bento Chip Rail untuk sisa mapel (agar Beranda HP tetap ringkas!)
  let railHtml = '';
  if (railItems.length > 0) {
    railHtml = `
      <div class="v70-compact-rail-wrap">
        <div class="v70-compact-rail-head">
          <span><i class="fa-solid fa-layer-group"></i> ${railItems.length} Mapel Lainnya (Geser &rarr;)</span>
          <button type="button" onclick="toggleShowAllSubjectPctV67()" style="border:none; background:none; color:#059669; font-size:11px; font-weight:900; cursor:pointer;">Lihat Grid Penuh</button>
        </div>
        <div class="v70-compact-rail-scroll">
          ${railItems.map(item => {
            const safeName = item.name.replace(/'/g, "\'");
            return `
              <div class="v70-rail-chip-card" onclick="openStudentLMS('${safeName}')">
                <span class="v70-rail-ico" style="background:${item.meta.bg}; color:${item.meta.color};"><i class="fa-solid ${item.meta.icon}"></i></span>
                <div>
                  <div style="font-size:11.5px; font-weight:800; color:var(--text-main); line-height:1.2;">${escapeHtml(item.name)}</div>
                  <div style="font-size:10px; font-weight:800; color:${item.overallPct > 0 ? '#059669' : '#64748b'};">${item.overallPct}% • ${item.doneMod}/${item.totMod} Bab</div>
                </div>
              </div>`;
          }).join('')}
        </div>
      </div>`;
  } else if (showAllSubjectPctV67 && !kw && filtered.length > 5) {
    railHtml = `
      <button type="button" class="v70-toggle-more-btn" onclick="toggleShowAllSubjectPctV67()">
        <i class="fa-solid fa-chevron-up"></i> Ringkas ke Mode Bento Kompak
      </button>`;
  }

  grid.innerHTML = topDeckHtml + filterHtml + `<div class="v70-subject-bento-mosaic">${spotlightHtml}${squaresHtml}</div>` + railHtml;
};

// -------------------------------------------------------------------------
// 2. RENDERER BENTO REKAMAN AKTIVITAS TERAKHIR LMS V70
// -------------------------------------------------------------------------
renderEduvanceTodayTimeline = function() {
  const box = document.getElementById('eduvance-today-timeline');
  if (!box) return;

  const rawActivities = typeof collectDetailedLMSActivitiesV67 === 'function' ? collectDetailedLMSActivitiesV67() : [];

  // Deduplikasi pintar agar tidak muncul 2 kartu hampir kembar untuk tahap/bab yang sama persis
  const cleanList = [];
  const seenRecentModStep = new Set();
  rawActivities.forEach(act => {
    const keySim = `${act.category}|${act.mapel}|${act.modul}|${act.badge}`;
    if (act.badge && act.badge.startsWith('Tahap ') && seenRecentModStep.has(keySim)) return;
    seenRecentModStep.add(keySim);
    cleanList.push(act);
  });

  const filtered = cleanList.filter(a => currentActivityFeedFilterV67 === 'ALL' || a.category === currentActivityFeedFilterV67);

  // Hitung distribusi kategori untuk Visual Stacked Bar Widget
  const totCnt = cleanList.length;
  const cntModul = cleanList.filter(x => x.category === 'MODUL').length;
  const cntRefl = cleanList.filter(x => x.category === 'REFLEKSI').length;
  const cntDisc = cleanList.filter(x => x.category === 'DISKUSI').length;
  const cntOther = cleanList.filter(x => x.category === 'LAINNYA').length;

  const pctM = totCnt ? Math.round((cntModul / totCnt) * 100) : 0;
  const pctR = totCnt ? Math.round((cntRefl / totCnt) * 100) : 0;
  const pctD = totCnt ? Math.round((cntDisc / totCnt) * 100) : 0;
  const pctO = totCnt ? Math.max(0, 100 - pctM - pctR - pctD) : 0;

  if (document.getElementById('eduvance-today-date-label')) {
    document.getElementById('eduvance-today-date-label').innerText = 'AKTIVITAS TERAKHIR LMS';
  }
  if (document.getElementById('eduvance-today-count-label')) {
    document.getElementById('eduvance-today-count-label').innerText =
      totCnt > 0 ? `${totCnt} jejak aktivitas belajar tercatat otomatis` : 'Belum ada aktivitas tercatat di LMS';
  }

  // Bento Top Pulse Deck (Latest Spotlight + Activity Mix Stacked Bar + Total Counter)
  const latest = cleanList[0] || null;
  let spotlightHtml = '';
  if (latest) {
    const safeMapel = (latest.actionMapel || '').replace(/'/g, "\'");
    const stepArg = latest.actionStep ? Number(latest.actionStep) : 'null';
    const cbtArg = latest.actionCBT ? 'true' : 'false';
    const pathStr = [latest.mapel, latest.modul].filter(Boolean).join(' • ');

    spotlightHtml = `
      <div class="v70-act-spotlight-tile" onclick="openActivityTargetV67('${safeMapel}', ${stepArg}, ${cbtArg})">
        <div class="v70-act-spot-left">
          <span class="v70-act-live-pill"><span class="v70-act-live-dot"></span> TERBARU • ${escapeHtml(latest.timeLabel)}</span>
          <div class="v70-act-spot-title">${escapeHtml(latest.title)}</div>
          <div class="v70-act-spot-sub">${escapeHtml(pathStr || latest.detail || 'Klik untuk lanjutkan aktivitas ini')}</div>
        </div>
        <span class="v70-act-spot-go-btn" title="Lanjutkan"><i class="fa-solid fa-arrow-right"></i></span>
      </div>`;
  }

  const pulseDeckHtml = `
    <div class="v70-act-bento-deck">
      ${spotlightHtml}
      <div class="v70-act-mix-tile">
        <div style="font-size:10px; font-weight:900; color:#64748b; text-transform:uppercase; letter-spacing:0.4px;">Komposisi Aktivitas</div>
        <div class="v70-mix-bar">
          ${pctM > 0 ? `<div class="v70-mix-seg" style="width:${pctM}%; background:#059669;" title="Modul & Kuis: ${cntModul}"></div>` : ''}
          ${pctR > 0 ? `<div class="v70-mix-seg" style="width:${pctR}%; background:#d97706;" title="Refleksi & Catatan: ${cntRefl}"></div>` : ''}
          ${pctD > 0 ? `<div class="v70-mix-seg" style="width:${pctD}%; background:#4f46e5;" title="Diskusi & AI: ${cntDisc}"></div>` : ''}
          ${pctO > 0 ? `<div class="v70-mix-seg" style="width:${pctO}%; background:#0284c7;" title="CBT & Lainnya: ${cntOther}"></div>` : ''}
        </div>
        <div class="v70-mix-legend">
          <span><span class="v70-mix-dot" style="background:#059669;"></span>Modul ${cntModul}</span>
          <span><span class="v70-mix-dot" style="background:#d97706;"></span>Refl ${cntRefl}</span>
          <span><span class="v70-mix-dot" style="background:#4f46e5;"></span>AI/QnA ${cntDisc}</span>
        </div>
      </div>

      <div class="v70-act-count-tile">
        <div style="display:flex; justify-content:space-between; align-items:center;">
          <span style="font-size:10px; font-weight:900; text-transform:uppercase; opacity:0.85;">Total Jejak</span>
          <i class="fa-solid fa-clock-rotate-left" style="font-size:14px;"></i>
        </div>
        <div style="font-size:24px; font-weight:900; line-height:1.05;">${totCnt} <small style="font-size:11px; font-weight:800;">aksi</small></div>
        <div style="font-size:10.5px; font-weight:700; opacity:0.85; white-space:nowrap; overflow:hidden; text-overflow:ellipsis;">${latest ? escapeHtml(latest.badge) : 'Siap mulai'}</div>
      </div>
    </div>`;

  const filterHtml = `
    <div class="v70-pills-row">
      <button type="button" class="v70-pill-btn ${currentActivityFeedFilterV67 === 'ALL' ? 'active' : ''}" onclick="setActivityFeedFilterV67('ALL')">Semua (${totCnt})</button>
      <button type="button" class="v70-pill-btn ${currentActivityFeedFilterV67 === 'MODUL' ? 'active' : ''}" onclick="setActivityFeedFilterV67('MODUL')">📚 Modul (${cntModul})</button>
      <button type="button" class="v70-pill-btn ${currentActivityFeedFilterV67 === 'REFLEKSI' ? 'active' : ''}" onclick="setActivityFeedFilterV67('REFLEKSI')">✍️ Refleksi (${cntRefl})</button>
      <button type="button" class="v70-pill-btn ${currentActivityFeedFilterV67 === 'DISKUSI' ? 'active' : ''}" onclick="setActivityFeedFilterV67('DISKUSI')">💬 Diskusi (${cntDisc})</button>
      <button type="button" class="v70-pill-btn ${currentActivityFeedFilterV67 === 'LAINNYA' ? 'active' : ''}" onclick="setActivityFeedFilterV67('LAINNYA')">🏆 CBT (${cntOther})</button>
    </div>`;

  // Tampilkan timeline bersih (lewati item #0 jika filter ALL karena sudah tampil di Spotlight atas, atau tampilkan semua bila hanya 1)
  const timelineSource = (currentActivityFeedFilterV67 === 'ALL' && filtered.length > 1) ? filtered.slice(1) : filtered;
  const visibleTimeline = showAllActivitiesV70 ? timelineSource.slice(0, 25) : timelineSource.slice(0, 4);

  let timelineHtml = '';
  if (filtered.length === 0) {
    timelineHtml = `
      <div style="text-align:center; padding:26px 14px; background:#f8fafc; border:1.5px dashed #cbd5e1; border-radius:16px; color:#64748b;">
        <i class="fa-solid fa-compass" style="font-size:26px; color:#94a3b8; display:block; margin-bottom:8px;"></i>
        <div style="font-size:13px; font-weight:800; color:var(--text-main);">Belum ada aktivitas di kategori ini</div>
        <div style="font-size:11.5px; margin-top:3px;">Buka modul di Ruang Belajar LMS agar setiap progresmu terekam otomatis di sini.</div>
      </div>`;
  } else {
    timelineHtml = `<div class="v70-timeline-rail">` + visibleTimeline.map(act => {
      const safeMapel = (act.actionMapel || '').replace(/'/g, "\'");
      const stepArg = act.actionStep ? Number(act.actionStep) : 'null';
      const cbtArg = act.actionCBT ? 'true' : 'false';
      const pathText = [act.mapel, act.modul].filter(Boolean).join(' › ');
      const chipsHtml = (act.metrics || []).slice(0, 3).map(m => `<span class="v70-tl-chip">${escapeHtml(m)}</span>`).join('');

      return `
        <div class="v70-tl-node" onclick="openActivityTargetV67('${safeMapel}', ${stepArg}, ${cbtArg})">
          <span class="v70-tl-dot" style="background:${act.color};"></span>
          <div class="v70-tl-top">
            <span class="v70-tl-badge" style="background:${act.bg}; color:${act.color};">
              <i class="fa-solid ${act.icon}"></i> ${escapeHtml(act.badge)}
            </span>
            <span class="v70-tl-time">${escapeHtml(act.timeLabel)}</span>
          </div>
          <div class="v70-tl-title">${escapeHtml(act.title)}</div>
          <div class="v70-tl-sub">${escapeHtml(pathText || act.detail)}</div>
          ${chipsHtml ? `<div class="v70-tl-chips">${chipsHtml}</div>` : ''}
        </div>`;
    }).join('') + `</div>`;
  }

  const moreBtnHtml = timelineSource.length > 4
    ? `<button type="button" class="v70-toggle-more-btn" onclick="toggleShowAllActivitiesV70()">
         <i class="fa-solid ${showAllActivitiesV70 ? 'fa-chevron-up' : 'fa-chevron-down'}"></i>
         ${showAllActivitiesV70 ? 'Ringkas Riwayat Aktivitas' : `Lihat ${timelineSource.length - 4} Aktivitas Lainnya`}
       </button>`
    : '';

  box.innerHTML = pulseDeckHtml + filterHtml + timelineHtml + moreBtnHtml;
};


