let currentArenaBentoFilterV71 = 'ALL';
let isSpinningArenaRouletteV71 = false;

function setArenaBentoFilterV71(mode) {
  playStudentSFX('click');
  currentArenaBentoFilterV71 = mode;
  renderLiveArenaRootV45();
}

function getStudentPersonalBestArenaMapV71() {
  const myNameLow = ((studentData && studentData.name) || '').trim().toLowerCase();
  const bestMap = {};
  if (!myNameLow) return bestMap;
  Object.entries(liveArenaStateV45.leaderboardByMapel || {}).forEach(([mp, arr]) => {
    (arr || []).forEach(it => {
      if ((it.nama || '').trim().toLowerCase() === myNameLow) {
        const prev = bestMap[mp];
        if (!prev || Number(it.coins) > Number(prev.coins)) {
          bestMap[mp] = it;
        }
      }
    });
  });
  return bestMap;
}

function getNextTargetBadgeProgressV71(availablePoints) {
  const owned = (arenaBadgeStoreStateV48 && arenaBadgeStoreStateV48.myBadgeData && Array.isArray(arenaBadgeStoreStateV48.myBadgeData.ownedBadges))
    ? arenaBadgeStoreStateV48.myBadgeData.ownedBadges : [];
  const catalog = Array.isArray(ARENA_AVATAR_BADGES_CATALOG_V48) ? ARENA_AVATAR_BADGES_CATALOG_V48 : [];
  const unowned = catalog
    .filter(b => !owned.includes(b.id))
    .sort((a, b) => (Number(a.price) || 0) - (Number(b.price) || 0));

  if (unowned.length === 0) {
    return {
      allOwned: true,
      ownedCount: owned.length,
      totalCount: catalog.length,
      pct: 100,
      label: 'Seluruh Koleksi Badge Avatar Telah Kamu Miliki! 🏆',
      rightText: `${owned.length}/${catalog.length} Badge`
    };
  }

  const nextB = unowned[0];
  const price = Math.max(1, Number(nextB.price) || 150);
  const pct = Math.min(100, Math.round((availablePoints / price) * 100));
  const diff = Math.max(0, price - availablePoints);

  return {
    allOwned: false,
    badge: nextB,
    ownedCount: owned.length,
    totalCount: catalog.length,
    pct,
    label: diff === 0
      ? `🎉 Poin cukup! Tukar "${nextB.name}" sekarang!`
      : `Target Badge: ${nextB.name} (Kurang ${diff} Poin)`,
    rightText: `${Math.min(availablePoints, price)}/${price} Poin`
  };
}

// Fitur Interaktif Seru: Roulette "Putar Kuis Acak"
function spinRandomArenaSubjectV71() {
  if (isSpinningArenaRouletteV71) return;
  const tiles = Array.from(document.querySelectorAll('#v71-arena-subj-grid .v71-subj-bento-tile'));
  const subjs = (globalLMSDashboard.subjects || []).map(s => s.name);
  const pool = subjs.length > 0 ? subjs : ['Matematika', 'IPA', 'Bahasa Indonesia', 'Bahasa Inggris', 'IPS', 'Informatika'];

  const openPool = pool.filter(s => {
    const chk = typeof isStudentAllowedInSubjectArenaV45 === 'function' ? isStudentAllowedInSubjectArenaV45(s) : { allowed: true };
    return chk.allowed;
  });

  if (openPool.length === 0) {
    playStudentSFX('click');
    Swal.fire({
      icon: 'info',
      title: 'Live Arena Sedang Istirahat 🔒',
      text: 'Saat ini seluruh sesi kuis Live Arena belum dibuka oleh Guru/Admin. Tunggu aba-aba dari Guru atau buka Toko Badge untuk melihat koleksi bingkai avatarmu!',
      confirmButtonText: 'Buka Toko Badge',
      showCancelButton: true,
      cancelButtonText: 'Tutup',
      customClass: { popup: 'swal-custom-popup', confirmButton: 'swal-custom-confirm' }
    }).then(r => { if (r.isConfirmed) switchArenaSubViewV48('SHOP'); });
    return;
  }

  isSpinningArenaRouletteV71 = true;
  const targetSub = openPool[Math.floor(Math.random() * openPool.length)];
  const openTiles = tiles.filter(el => openPool.includes(el.getAttribute('data-mapel')));

  if (openTiles.length <= 1) {
    isSpinningArenaRouletteV71 = false;
    selectAndLaunchSubjectArenaV45(targetSub);
    return;
  }

  let step = 0;
  const totalSteps = 10;
  const timer = setInterval(() => {
    tiles.forEach(t => t.classList.remove('v71-roulette-flash'));
    const pickEl = (step === totalSteps - 1)
      ? (openTiles.find(t => t.getAttribute('data-mapel') === targetSub) || openTiles[0])
      : openTiles[step % openTiles.length];

    if (pickEl) {
      pickEl.classList.add('v71-roulette-flash');
      if (step === 0 || step === totalSteps - 1) {
        try { pickEl.scrollIntoView({ behavior: 'smooth', block: 'center' }); } catch (e) {}
      }
    }
    playStudentSFX(step === totalSteps - 1 ? 'success' : 'click');
    step++;
    if (step >= totalSteps) {
      clearInterval(timer);
      setTimeout(() => {
        tiles.forEach(t => t.classList.remove('v71-roulette-flash'));
        isSpinningArenaRouletteV71 = false;
        if (typeof showStudentToast === 'function') {
          showStudentToast(`🎲 Tantangan Acak Terpilih: Kuis ${targetSub}! Bersiap!`, 'success');
        }
        selectAndLaunchSubjectArenaV45(targetSub);
      }, 360);
    }
  }, 90);
}

