let v78SubActivePhotoIdxMap = {}; // `${modId}_${subIdx}` -> active imgIdx
let v78SubExampleOpenMap = {};    // `${modId}_${subIdx}` -> boolean

function getSubMateriGalleryV78(sm) {
  if (!sm) return [];
  if (Array.isArray(sm.galeri_gambar) && sm.galeri_gambar.length > 0) {
    return sm.galeri_gambar
      .filter(g => g && (g.url || typeof g === 'string'))
      .map(g => (typeof g === 'string' ? { url: g, caption: 'Ilustrasi Materi' } : g));
  }
  if (sm.gambar_sub) {
    return [{ url: sm.gambar_sub, caption: sm.caption_gambar || 'Ilustrasi Materi' }];
  }
  return [];
}

function selectV78SubMateriPhoto(modId, subIdx, imgIdx) {
  playStudentSFX('click');
  v78SubActivePhotoIdxMap[`${modId}_${subIdx}`] = Number(imgIdx) || 0;
  renderConstructiveWorkspace();
}

function toggleV78SubExample(modId, subIdx) {
  playStudentSFX('click');
  const k = `${modId}_${subIdx}`;
  v78SubExampleOpenMap[k] = !v78SubExampleOpenMap[k];
  renderConstructiveWorkspace();
}

// Kompresi gambar ringan sisi klien (maks lebar 1280px, kualitas JPEG 0.84) agar upload cepat & tajam
function compressImageFileToBase64V78(file) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onerror = () => reject('Gagal membaca file gambar.');
    reader.onload = (ev) => {
      const dataUrl = ev.target.result;
      if (file.size <= 450 * 1024) {
        resolve(dataUrl);
        return;
      }
      const img = new Image();
      img.onerror = () => resolve(dataUrl);
      img.onload = () => {
        const maxW = 1280;
        let w = img.width, h = img.height;
        if (w > maxW) {
          h = Math.round((h * maxW) / w);
          w = maxW;
        }
        const canvas = document.createElement('canvas');
        canvas.width = w;
        canvas.height = h;
        const ctx = canvas.getContext('2d');
        ctx.drawImage(img, 0, 0, w, h);
        try {
          const compressed = canvas.toDataURL('image/jpeg', 0.84);
          resolve(compressed);
        } catch (e) {
          resolve(dataUrl);
        }
      };
      img.src = dataUrl;
    };
    reader.readAsDataURL(file);
  });
}

// Sinkronkan perubahan gambar ke seluruh cache objek modul di memori agar langsung tampil di Hub Bab & Reader
function syncUpdatedSubMateriGalleryLocalV78(newIdModul, subIdx, newGaleri) {
  if (!activeLMSModule) return;
  const oldId = activeLMSModule.id;
  if (newIdModul && newIdModul !== oldId) {
    activeLMSModule.id = newIdModul;
  }
  if (!activeLMSModule.konten) activeLMSModule.konten = {};
  if (!activeLMSModule.konten.eksplorasi) activeLMSModule.konten.eksplorasi = {};
  if (!Array.isArray(activeLMSModule.konten.eksplorasi.sub_materi)) activeLMSModule.konten.eksplorasi.sub_materi = [];
  const sm = activeLMSModule.konten.eksplorasi.sub_materi[subIdx];
  if (sm) {
    sm.galeri_gambar = Array.isArray(newGaleri) ? newGaleri : [];
    sm.gambar_sub = sm.galeri_gambar.length > 0 ? sm.galeri_gambar[0].url : '';
    sm.caption_gambar = sm.galeri_gambar.length > 0 ? sm.galeri_gambar[0].caption : '';
  }

  // Sinkronkan juga ke globalLMSDashboard.subjects agar persisten saat pindah mapel/bab
  const subObj = (globalLMSDashboard.subjects || []).find(s => s.name === activeLMSSubject);
  if (subObj) {
    if (!Array.isArray(subObj.modules)) subObj.modules = [];
    let targetInSub = subObj.modules.find(m => m.id === oldId || m.id === activeLMSModule.id);
    if (!targetInSub) {
      subObj.modules.push(activeLMSModule);
      subObj.totalModules = subObj.modules.length;
    } else {
      targetInSub.id = activeLMSModule.id;
      targetInSub.konten = activeLMSModule.konten;
    }
  }
}

// Modal Upload Gambar Manual Khusus Guru/Admin per Bagian Materi (Langkah 2)
function bukaModalUploadGambarMateriV78(subIdx, replaceMode = false) {
  playStudentSFX('click');
  const isTeacherAuth = typeof isAuthorizedTeacherForCurrentMapelV40 === 'function'
    ? isAuthorizedTeacherForCurrentMapelV40(activeLMSSubject)
    : !!(typeof trnLiveAdminSessionV39 !== 'undefined' && trnLiveAdminSessionV39 && trnLiveAdminSessionV39.active);

  if (!isTeacherAuth) {
    toggleLiveAdminModeInSidebarV39();
    return;
  }
  if (!activeLMSModule) return;

  const subArr = (activeLMSModule.konten && activeLMSModule.konten.eksplorasi && Array.isArray(activeLMSModule.konten.eksplorasi.sub_materi))
    ? activeLMSModule.konten.eksplorasi.sub_materi : [];
  const sm = subArr[subIdx] || {};
  const judulSub = sm.judul_sub || ('Bagian ' + (subIdx + 1));

  Swal.fire({
    title: `<i class="fa-solid fa-image" style="color:#4f46e5;"></i> ${replaceMode ? 'Ganti' : 'Upload'} Gambar Bagian ${subIdx + 1}`,
    width: '560px',
    html: `
      <div style="text-align:left; font-size:13px;">
        <div style="background:#eef2ff; border:1px solid #c7d2fe; border-radius:12px; padding:10px 13px; color:#312e81; margin-bottom:14px;">
          <b>Target Materi:</b> ${escapeHtml(judulSub)}<br>
          <span style="font-size:11.5px; color:#4338ca;">Gambar yang diunggah otomatis tersimpan di Google Drive &amp; langsung tampil dengan layout Editorial Bento untuk seluruh siswa.</span>
        </div>

        <label class="edit-label"><i class="fa-solid fa-cloud-arrow-up" style="color:#4f46e5;"></i> 1. Pilih File Gambar dari Perangkat (JPG / PNG / WEBP)</label>
        <input type="file" id="v78-inp-img-file" accept="image/*" class="swal-custom-input" style="width:100%; padding:10px !important; background:#f8fafc; margin-bottom:10px;" onchange="previewV78UploadFileModal(this)">
        <div id="v78-upload-preview-wrap" class="hidden" style="margin-bottom:12px; text-align:center; background:#f1f5f9; border-radius:12px; padding:8px; border:1px solid #cbd5e1;">
          <img id="v78-upload-preview-img" src="" style="max-height:170px; max-width:100%; border-radius:10px; object-fit:contain;">
        </div>

        <label class="edit-label"><i class="fa-solid fa-link" style="color:#059669;"></i> Atau Tempel Link Gambar / Google Drive (Opsional jika tidak pilih file)</label>
        <input type="text" id="v78-inp-img-url" class="swal-custom-input" style="width:100%; background:#f8fafc; margin-bottom:12px;" placeholder="https://... atau link share Google Drive">

        <label class="edit-label"><i class="fa-solid fa-pen" style="color:#d97706;"></i> Keterangan / Caption Gambar (Tampil di Bawah Gambar)</label>
        <input type="text" id="v78-inp-img-caption" class="swal-custom-input" style="width:100%; background:#f8fafc;" placeholder="Contoh: Ilustrasi penerapan ${escapeHtml(judulSub.substring(0, 32))}" value="Ilustrasi: ${escapeHtml(judulSub)}">
      </div>`,
    showCancelButton: true,
    confirmButtonText: '<i class="fa-solid fa-cloud-arrow-up"></i> Simpan &amp; Pasang Gambar',
    cancelButtonText: 'Batal',
    customClass: { popup: 'swal-custom-popup', confirmButton: 'swal-custom-confirm' },
    preConfirm: async () => {
      const fileInput = document.getElementById('v78-inp-img-file');
      const urlVal = (document.getElementById('v78-inp-img-url')?.value || '').trim();
      const capVal = (document.getElementById('v78-inp-img-caption')?.value || '').trim() || ('Ilustrasi Bagian ' + (subIdx + 1));

      if ((!fileInput || !fileInput.files || fileInput.files.length === 0) && !urlVal) {
        Swal.showValidationMessage('Pilih file gambar dari perangkat atau tempel link gambar terlebih dahulu!');
        return false;
      }

      let base64Data = '';
      let fileName = '';
      if (fileInput && fileInput.files && fileInput.files.length > 0) {
        const f = fileInput.files[0];
        fileName = f.name;
        base64Data = await compressImageFileToBase64V78(f);
      }
      return { base64Data, fileName, imageUrl: urlVal, caption: capVal };
    }
  }).then(res => {
    if (!res.isConfirmed || !res.value) return;
    Swal.fire({
      title: 'Mengunggah Gambar Materi...',
      html: `Menyimpan ilustrasi untuk <b>Bagian ${subIdx + 1}</b> ke server Google Drive &amp; Spreadsheet...`,
      allowOutsideClick: false,
      didOpen: () => Swal.showLoading(),
      customClass: { popup: 'swal-custom-popup' }
    });

    const uploaderName = (typeof trnLiveAdminSessionV39 !== 'undefined' && trnLiveAdminSessionV39 && trnLiveAdminSessionV39.name)
      || window.currentStaffName || 'Guru / Admin';

    google.script.run.withSuccessHandler(srvRes => {
      if (srvRes && srvRes.success) {
        syncUpdatedSubMateriGalleryLocalV78(srvRes.idModul, subIdx, srvRes.galeri);
        const newLen = Array.isArray(srvRes.galeri) ? srvRes.galeri.length : 1;
        v78SubActivePhotoIdxMap[`${activeLMSModule.id}_${subIdx}`] = Math.max(0, newLen - 1);
        renderConstructiveWorkspace();
        Swal.fire({
          icon: 'success',
          title: 'Gambar Terpasang!',
          text: srvRes.message,
          timer: 1700,
          showConfirmButton: false,
          customClass: { popup: 'swal-custom-popup' }
        });
      } else {
        Swal.fire({
          icon: 'error',
          title: 'Gagal Mengunggah',
          text: (srvRes && srvRes.message) || 'Terjadi kesalahan saat menyimpan gambar.',
          customClass: { popup: 'swal-custom-popup', confirmButton: 'swal-custom-confirm' }
        });
      }
    }).withFailureHandler(err => {
      Swal.fire({
        icon: 'error',
        title: 'Koneksi Gagal',
        text: err.toString(),
        customClass: { popup: 'swal-custom-popup', confirmButton: 'swal-custom-confirm' }
      });
    }).saveSubMateriImageAdminV78({
      idModul: activeLMSModule.id,
      mapel: activeLMSSubject,
      judulModul: activeLMSModule.judul,
      subIdx: subIdx,
      base64Data: res.value.base64Data,
      fileName: res.value.fileName,
      imageUrl: res.value.imageUrl,
      caption: res.value.caption,
      uploadedBy: uploaderName,
      replaceMode: replaceMode,
      fallbackModule: activeLMSModule
    });
  });
}

function previewV78UploadFileModal(inputEl) {
  const wrap = document.getElementById('v78-upload-preview-wrap');
  const img = document.getElementById('v78-upload-preview-img');
  if (!wrap || !img || !inputEl || !inputEl.files || !inputEl.files[0]) return;
  const r = new FileReader();
  r.onload = (e) => {
    img.src = e.target.result;
    wrap.classList.remove('hidden');
  };
  r.readAsDataURL(inputEl.files[0]);
}

