// 71. PEMBARUAN V86:
//     BERANDA MENU UJIAN AKHIR (CBT) — FLOWSYNC BENTO UI & UX INTERAKTIF
//     - QUICK LAUNCH EXAM (↗)
//     - DIAGNOSTIK KESIAPAN PERANGKAT & KEAMANAN REAL-TIME
//     - DETEKSI OTOMATIS SESI UJIAN TERSIMPAN (RESUME) & SYNC LIVE MODE PTS/PAS
// =========================================================================

function getActiveSavedCBTSessionsV86() {
  const mode = typeof getActiveCBTExamModeV69 === 'function' ? getActiveCBTExamModeV69() : 'PTS';
  const email = (studentData && studentData.email) ? studentData.email : '';
  const prefix = `cbt_${mode}_${email}_`;
  const sessions = [];
  if (!email) return sessions;
  try {
    for (let i = 0; i < localStorage.length; i++) {
      const k = localStorage.key(i);
      if (k && k.startsWith(prefix)) {
        const raw = JSON.parse(localStorage.getItem(k) || 'null');
        if (raw && raw.endTime && raw.endTime > Date.now()) {
          const mapelName = k.substring(prefix.length);
          const minsLeft = Math.max(1, Math.ceil((raw.endTime - Date.now()) / 60000));
          const answered = raw.userAnswers ? Object.keys(raw.userAnswers).length : 0;
          const total = Array.isArray(raw.examData) ? raw.examData.length : 0;
          sessions.push({ mapel: mapelName, minsLeft, answered, total });
        }
      }
    }
  } catch (e) {}
  return sessions;
}

function launchFirstOpenCBTExamV86() {
  if (typeof playStudentSFX === 'function') playStudentSFX('click');
  const saved = getActiveSavedCBTSessionsV86();
  if (saved.length > 0) {
    startExam(saved[0].mapel);
    return;
  }
  const allSubjects = globalLMSDashboard.subjects || [];
  const historyMap = globalLMSDashboard.examHistoryMap || {};
  const firstOpen = allSubjects.find(s => s.examStatus === 'AKTIF' && historyMap[s.name] === undefined);
  if (firstOpen) {
    startExam(firstOpen.name);
  } else {
    Swal.fire({
      icon: 'info',
      title: 'Belum Ada Sesi Ujian Terbuka',
      text: 'Saat ini belum ada mata pelajaran ujian yang berstatus Terbuka. Klik "Sinkronkan" saat Pengawas sudah membuka sesi.',
      customClass: { popup: 'swal-custom-popup', confirmButton: 'swal-custom-confirm' }
    });
  }
}

function cekKesiapanUjianSiswaV86() {
  if (typeof playStudentSFX === 'function') playStudentSFX('click');
  const mode = typeof getActiveCBTExamModeV69 === 'function' ? getActiveCBTExamModeV69() : 'PTS';
  const isOnline = navigator.onLine !== false;
  const saved = getActiveSavedCBTSessionsV86();
  const isIOS = /iPhone|iPad|iPod/i.test(navigator.userAgent || '');
  const browserOk = isIOS ? 'Safari / Chrome iOS (Didukung Penuh)' : 'Google Chrome Resmi (Terverifikasi)';

  const resumeBox = saved.length > 0
    ? `<div style="background:#ecfdf5; border:1.5px solid #3ef08e; border-radius:14px; padding:12px 14px; margin-top:12px; display:flex; justify-content:space-between; align-items:center; gap:10px; flex-wrap:wrap;">
         <div>
           <div style="font-size:11px; font-weight:900; color:#047857;">⏳ SESI UJIAN TERSIMPAN DITEMUKAN</div>
           <div style="font-size:13px; font-weight:800; color:#0b1120;">${escapeHtml(saved[0].mapel)} (${saved[0].answered}/${saved[0].total} soal • Sisa ${saved[0].minsLeft} mnt)</div>
         </div>
         <button type="button" onclick="Swal.close(); startExam('${saved[0].mapel.replace(/'/g, "\'")}');" style="background:#0b1120; color:#3ef08e; border:none; padding:8px 14px; border-radius:99px; font-size:12px; font-weight:900; cursor:pointer;">Lanjutkan &rarr;</button>
       </div>`
    : '';

  Swal.fire({
    title: '<i class="fa-solid fa-shield-halved" style="color:#10b981;"></i> Diagnostik Kesiapan Ujian CBT',
    width: '540px',
    html: `
      <div style="text-align:left; font-size:13px; line-height:1.6;">
        <div style="display:grid; grid-template-columns:1fr 1fr; gap:10px; margin-bottom:12px;">
          <div style="background:#f8fafc; border:1.5px solid #e2e8f0; border-radius:14px; padding:11px 13px;">
            <div style="font-size:10px; font-weight:900; color:#64748b;">STATUS JARINGAN</div>
            <div style="font-size:13.5px; font-weight:900; color:${isOnline ? '#059669' : '#e11d48'}; margin-top:2px;">
              <i class="fa-solid ${isOnline ? 'fa-wifi' : 'fa-triangle-exclamation'}"></i> ${isOnline ? 'Online & Siap' : 'Terputus'}
            </div>
          </div>
          <div style="background:#f8fafc; border:1.5px solid #e2e8f0; border-radius:14px; padding:11px 13px;">
            <div style="font-size:10px; font-weight:900; color:#64748b;">MODE DATABASE AKTIF</div>
            <div style="font-size:13.5px; font-weight:900; color:#2563eb; margin-top:2px;">
              <i class="fa-solid fa-database"></i> Mode ${mode} (Supabase)
            </div>
          </div>
        </div>

        <div style="background:#f0fdf4; border:1px solid #bbf7d0; border-radius:14px; padding:12px 14px; color:#064e3b;">
          <div style="font-weight:900; margin-bottom:6px;"><i class="fa-solid fa-circle-check" style="color:#10b981;"></i> Checklist Keamanan Perangkat:</div>
          <ul style="padding-left:18px; margin:0; font-size:12.5px;">
            <li><b>Browser:</b> ${browserOk}</li>
            <li><b>Durasi Ujian:</b> 70 Menit dengan <i>Auto-Save</i> terenkripsi ke Supabase.</li>
            <li><b>Aturan Fullscreen:</b> Jangan keluar layar penuh atau membuka aplikasi lain (batas maksimal 7x pelanggaran).</li>
          </ul>
        </div>
        ${resumeBox}
      </div>`,
    confirmButtonText: 'Saya Siap Mengerjakan Ujian',
    customClass: { popup: 'swal-custom-popup', confirmButton: 'swal-custom-confirm' }
  });
}

function syncV86FlowSyncStageMetadata() {
  const mode = typeof getActiveCBTExamModeV69 === 'function' ? getActiveCBTExamModeV69() : 'PTS';
  const modeLong = mode === 'PAS' ? 'Penilaian Akhir Semester (PAS)' : 'Penilaian Tengah Semester (PTS)';

  const now = new Date();
  const daysShort = ['MIN', 'SEN', 'SEL', 'RAB', 'KAM', 'JUM', 'SAB'];
  const elClock = document.getElementById('v86-cbt-live-clock');
  if (elClock) elClock.innerText = `${String(now.getHours()).padStart(2, '0')}:${String(now.getMinutes()).padStart(2, '0')}`;
  const elDay = document.getElementById('v86-cbt-day-short');
  if (elDay) elDay.innerText = daysShort[now.getDay()];
  const elDate = document.getElementById('v86-cbt-date-num');
  if (elDate) elDate.innerText = now.getDate();

  const elEyebrow = document.getElementById('v86-cbt-hero-eyebrow');
  if (elEyebrow) elEyebrow.innerText = `sicibinaga.my.id • MODE ${mode}`;

  const elHeadline = document.querySelector('#cbt-bento-summary-strip .v86-fs-hero-headline');
  if (elHeadline) {
    elHeadline.innerHTML = mode === 'PAS'
      ? 'Portal Ujian PAS<br>Cerdas &amp; Terkendali'
      : 'Portal Ujian PTS<br>Cerdas &amp; Terkendali';
  }

  const elMiniBadge = document.getElementById('v86-cbt-mode-mini-badge');
  if (elMiniBadge) elMiniBadge.innerText = mode;

  const elInlineMode = document.getElementById('v86-cbt-inline-mode-lbl');
  if (elInlineMode) elInlineMode.innerHTML = `<b>${mode}</b>`;

  const elConnTxt = document.getElementById('v86-cbt-conn-status-txt');
  if (elConnTxt) elConnTxt.innerText = `Terhubung • Database ${mode}`;

  const saved = getActiveSavedCBTSessionsV86();
  const elResumeHint = document.getElementById('v86-cbt-resume-hint');
  if (elResumeHint) {
    elResumeHint.innerHTML = saved.length > 0
      ? `<i class="fa-solid fa-clock-rotate-left" style="color:#fde047;"></i> Lanjut: ${escapeHtml(saved[0].mapel.substring(0, 12))}`
      : `<i class="fa-solid fa-circle-check" style="color:#3ef08e;"></i> ${modeLong.split(' ')[0]} Siap`;
  }
}

