// =========================================================================
// 72. PEMBARUAN V87:
//     DIFERENSIASI VISUAL BENTO MINIMALIS UNTUK TOMBOL FITUR
//     (SUARA, AI TUTOR, DISKUSI, CATATAN, BERKAS) vs 5 PIL LANGKAH BELAJAR
//     + PERBAIKAN INTERAKTIF STATUS SUARA NARATOR & INDIKATOR AKTIF
// =========================================================================

// Perbarui toggleNarratorTTS agar tetap menjaga struktur Minimalist Bento Tile (#btn-lms-tts)
const _v86OrigToggleNarratorTTS = toggleNarratorTTS;
toggleNarratorTTS = function() {
  const btn = document.getElementById('btn-lms-tts');
  if (!btn || !btn.classList.contains('v87-bento-tool-tile')) {
    return _v86OrigToggleNarratorTTS();
  }
  if (!('speechSynthesis' in window)) {
    Swal.fire({ icon: 'info', title: 'Tidak Didukung', text: 'Browser perangkat ini belum mendukung fitur pembaca suara otomatis.' });
    return;
  }

  const resetSoundTileUI = () => {
    const b = document.getElementById('btn-lms-tts');
    if (!b) return;
    b.classList.remove('is-speaking', 'speaking');
    const ico = b.querySelector('.v87-tile-ico');
    const bdg = b.querySelector('.v87-tile-badge');
    const lbl = b.querySelector('.v87-tile-label');
    if (ico) ico.innerHTML = '<i class="fa-solid fa-volume-high"></i>';
    if (bdg) { bdg.className = 'v87-tile-badge'; bdg.innerText = 'TTS'; }
    if (lbl) lbl.innerText = 'Suara';
  };

  if (window.speechSynthesis.speaking) {
    window.speechSynthesis.cancel();
    resetSoundTileUI();
    if (typeof showStudentToast === 'function') showStudentToast('Suara narator dihentikan.', 'info');
    return;
  }

  const canvas = document.querySelector('#lms-constructive-workspace .v72-main-step-canvas') || document.getElementById('lms-constructive-workspace');
  if (!canvas) return;
  const rawText = (canvas.innerText || '').replace(/\s+/g, ' ').trim();
  if (!rawText) return;

  const utter = new SpeechSynthesisUtterance(rawText.substring(0, 1800));
  utter.lang = 'id-ID';
  utter.rate = 0.98;
  utter.onend = resetSoundTileUI;
  utter.onerror = resetSoundTileUI;

  btn.classList.add('is-speaking', 'speaking');
  const ico = btn.querySelector('.v87-tile-ico');
  const bdg = btn.querySelector('.v87-tile-badge');
  const lbl = btn.querySelector('.v87-tile-label');
  if (ico) ico.innerHTML = '<i class="fa-solid fa-stop"></i>';
  if (bdg) { bdg.className = 'v87-tile-badge badge-live'; bdg.innerText = 'ON'; }
  if (lbl) lbl.innerText = 'Stop';

  window.speechSynthesis.speak(utter);
};

// Sinkronkan sorotan aktif pada ubin Bento saat pop-up AI Tutor / Diskusi / Catatan / Berkas dibuka atau ditutup
function syncV87ActiveToolTileHighlight(activeKey) {
  document.querySelectorAll('.v87-bento-tool-tile').forEach(el => {
    const k = el.getAttribute('data-v87-tool');
    el.classList.toggle('is-open', !!activeKey && k === activeKey);
  });
}

