// =========================================================================
// 77. PEMBARUAN V92: SECURITY HARDENING TAHAP 2
//     - ANTI LOGIN GANDA (SINGLE ACTIVE SESSION + REALTIME KICK + ADMIN ALERT)
//     - MONOTONIC SERVER-VERIFIED EXAM TIMER (KEBAL MANIPULASI JAM PERANGKAT)
//     - KONTROL HASHING PASSWORD BERTAHAP (SHA-256) DI PUSAT KEAMANAN ADMIN
// =========================================================================

let v92SessionGuardChannel = null;
let v92SessionServerPollInterval = null;
let v92IsForcedLoggedOut = false;

let v92ExamTimerAnchor = {
  active: false,
  remainingMs: 70 * 60 * 1000,
  perfStartMs: 0,
  deadlineMs: 0,
  durationMin: 70,
  serverVerified: false
};

// --- A. ANTI LOGIN GANDA (SINGLE SESSION LOCK) ---
function initSingleSessionGuardChannelV92() {
  if (!supabaseClient || v92SessionGuardChannel) return;
  try {
    v92SessionGuardChannel = supabaseClient.channel('sicibinaga-session-guard-v92', {
      config: { broadcast: { self: false } }
    });

    v92SessionGuardChannel
      .on('broadcast', { event: 'student_session_claim' }, (msg) => {
        const p = (msg && msg.payload) || {};
        if (!p.email || !p.sessionId) return;
        if (document.body.classList.contains('admin-mode')) return;
        if (!studentData || !studentData.email || !studentData.sessionId) return;

        if (p.email.toLowerCase() === studentData.email.toLowerCase() && p.sessionId !== studentData.sessionId) {
          handleForcedDuplicateLoginLogoutV92('Akun Anda baru saja login dari perangkat lain!');
        }
      })
      .on('broadcast', { event: 'duplicate_login_alert' }, (msg) => {
        const p = (msg && msg.payload) || {};
        if (!document.body.classList.contains('admin-mode')) return;
        if (!p.nama) return;
        if (typeof catatRiwayatAksiAdmin === 'function') {
          catatRiwayatAksiAdmin('KEAMANAN', p.kelas || '-', `LOGIN GANDA TERDETEKSI: ${p.nama}`);
        }
        if (typeof showStudentToast === 'function') {
          showStudentToast(`⚠️ Peringatan Login Ganda: ${p.nama} (${p.kelas || ''}) login di perangkat kedua! Sesi lama otomatis diputus.`, 'warning');
        }
      })
      .subscribe();
  } catch (e) {}
}

function startSingleSessionGuardAfterLoginV92(replacedPrevious) {
  v92IsForcedLoggedOut = false;
  initSingleSessionGuardChannelV92();

  // Siarkan klaim sesi tunggal agar perangkat lama langsung keluar seketika
  setTimeout(() => {
    try {
      if (v92SessionGuardChannel && studentData && studentData.email && studentData.sessionId) {
        v92SessionGuardChannel.send({
          type: 'broadcast',
          event: 'student_session_claim',
          payload: {
            email: studentData.email,
            name: studentData.name,
            kelas: studentData.kelas,
            sessionId: studentData.sessionId,
            ts: Date.now()
          }
        });
        if (replacedPrevious) {
          v92SessionGuardChannel.send({
            type: 'broadcast',
            event: 'duplicate_login_alert',
            payload: {
              email: studentData.email,
              nama: studentData.name,
              kelas: studentData.kelas,
              ts: Date.now()
            }
          });
        }
      }
    } catch (e) {}
  }, 500);

  // Backup validasi sisi server tiap 45 detik selama siswa berada dalam sesi ujian CBT aktif
  if (v92SessionServerPollInterval) clearInterval(v92SessionServerPollInterval);
  v92SessionServerPollInterval = setInterval(() => {
    if (!isExamActive || !studentData || !studentData.email || !studentData.sessionId || v92IsForcedLoggedOut) return;
    if (typeof google !== 'undefined' && google.script && google.script.run) {
      google.script.run.withSuccessHandler(res => {
        if (res && res.valid === false && res.duplicateLogin) {
          handleForcedDuplicateLoginLogoutV92(res.message);
        }
      }).validateStudentSessionServerV92(studentData.email, studentData.sessionId);
    }
  }, 45000);
}

async function handleForcedDuplicateLoginLogoutV92(reasonMsg) {
  if (v92IsForcedLoggedOut) return;
  v92IsForcedLoggedOut = true;

  // Jika sedang di tengah ujian, amankan jawaban yang sudah dikerjakan sebelum menutup sesi lama
  if (isExamActive) {
    try { await silentAutoSync(); } catch (e) {}
  }

  isExamActive = false;
  v92ExamTimerAnchor.active = false;
  if (timerInterval) clearInterval(timerInterval);
  if (strictInterval) clearInterval(strictInterval);
  if (v92SessionServerPollInterval) clearInterval(v92SessionServerPollInterval);

  if (typeof closeLMSToolsFullscreenModalV82 === 'function') closeLMSToolsFullscreenModalV82();
  if (typeof exitFullScreenOnly === 'function') exitFullScreenOnly();

  // Beritahu Monitor Admin bahwa perangkat lama telah dihentikan
  try {
    if (v92SessionGuardChannel && studentData && studentData.name) {
      v92SessionGuardChannel.send({
        type: 'broadcast',
        event: 'duplicate_login_alert',
        payload: {
          email: studentData.email,
          nama: studentData.name,
          kelas: studentData.kelas,
          ts: Date.now()
        }
      });
    }
  } catch (e) {}

  document.getElementById('exam-section')?.classList.add('hidden');
  document.getElementById('lms-learning-section')?.classList.add('hidden');
  document.getElementById('app-wrapper')?.classList.add('hidden');
  document.getElementById('dashboard-section')?.classList.add('hidden');
  document.getElementById('login-section')?.classList.remove('hidden');
  document.getElementById('btn-admin-login')?.classList.remove('hidden');

  const btnLogin = document.getElementById('btn-login');
  if (btnLogin) btnLogin.disabled = false;
  if (typeof applySicibinagaEnvironmentUIV88 === 'function') applySicibinagaEnvironmentUIV88();

  studentData = { kelas: '', name: '', email: '', subject: '', sessionId: '' };
  lastTrackedState = '';

  Swal.fire({
    icon: 'error',
    title: 'Login Ganda Terdeteksi!',
    html: `<div style="font-size:13.5px; line-height:1.6;">
      ${escapeHtml(reasonMsg || 'Akun Anda terdeteksi login di perangkat lain.')}<br><br>
      Demi keamanan &amp; keadilan ujian, <b>1 akun hanya diperbolehkan aktif pada 1 perangkat</b>. Sesi pada perangkat ini telah dihentikan otomatis.
    </div>`,
    allowOutsideClick: false,
    confirmButtonText: 'Saya Mengerti',
    customClass: { popup: 'swal-custom-popup', confirmButton: 'swal-custom-confirm' }
  });
}

// Aktifkan listener alert login ganda saat Admin masuk Dashboard
if (typeof initAdminPanel === 'function') {
  const _v91InitAdminV92 = initAdminPanel;
  initAdminPanel = function() {
    const out = _v91InitAdminV92.apply(this, arguments);
    initSingleSessionGuardChannelV92();
    return out;
  };
}

// --- B. VALIDASI WAKTU MULAI UJIAN DI SERVER & MONOTONIC TIMER (KEBAL UBAH JAM HP) ---
function applyServerExamTimerV92(timerObj) {
  if (!timerObj) return;
  const remMs = Math.max(0, Number(timerObj.remainingMs) || 0);
  v92ExamTimerAnchor = {
    active: true,
    remainingMs: remMs,
    perfStartMs: performance.now(),
    deadlineMs: Number(timerObj.deadlineMs) || (Date.now() + remMs),
    durationMin: Number(timerObj.durationMin) || 70,
    serverVerified: true
  };
  examEndTime = Date.now() + remMs;
}

function setMonotonicExamTimerFallbackV92(remMs) {
  const safeRem = Math.max(0, Number(remMs) || (70 * 60 * 1000));
  v92ExamTimerAnchor = {
    active: true,
    remainingMs: safeRem,
    perfStartMs: performance.now(),
    deadlineMs: Date.now() + safeRem,
    durationMin: Math.round(safeRem / 60000) || 70,
    serverVerified: false
  };
  examEndTime = Date.now() + safeRem;
}

// Override startTimer agar memakai jam monotonik performance.now() (100% kebal manipulasi jam HP!)
startTimer = function() {
  if (timerInterval) clearInterval(timerInterval);
  if (!v92ExamTimerAnchor.active) {
    setMonotonicExamTimerFallbackV92(Math.max(0, examEndTime - Date.now()));
  }

  const updateTick = () => {
    const elapsedMs = performance.now() - v92ExamTimerAnchor.perfStartMs;
    const remMs = Math.max(0, v92ExamTimerAnchor.remainingMs - elapsedMs);
    const timeRemaining = Math.floor(remMs / 1000);
    const tc = document.getElementById('timer-card');
    const disp = document.getElementById('timer-display');

    if (tc) {
      if (timeRemaining <= 300 && timeRemaining > 0) tc.classList.add('timer-warning');
      else tc.classList.remove('timer-warning');
    }

    if (timeRemaining <= 0) {
      isExamActive = false;
      v92ExamTimerAnchor.active = false;
      clearInterval(timerInterval);
      if (disp) disp.innerHTML = '00:00';
      finishExam(true);
      return;
    }

    const mm = Math.floor(timeRemaining / 60).toString().padStart(2, '0');
    const ss = (timeRemaining % 60).toString().padStart(2, '0');
    if (disp) disp.innerHTML = `${mm}:${ss}`;
  };

  updateTick();
  timerInterval = setInterval(updateTick, 1000);
};

// Override resumeExam agar saat siswa menyegarkan/melanjutkan sesi, timer langsung dikalibrasi ulang ke server!
const _v91OrigResumeExam = resumeExam;
resumeExam = function(savedState, selectedSubject) {
  const localRem = savedState && savedState.endTime ? Math.max(0, savedState.endTime - Date.now()) : (70 * 60 * 1000);
  setMonotonicExamTimerFallbackV92(localRem);
  _v91OrigResumeExam(savedState, selectedSubject);

  // Kalibrasi diam-diam ke waktu otoritatif server (mencegah kecurangan mundurkan jam HP saat refresh!)
  if (studentData && studentData.email && typeof google !== 'undefined' && google.script && google.script.run) {
    const sessMode = (typeof activeExamSessionModeV69 !== 'undefined' && activeExamSessionModeV69) ? activeExamSessionModeV69 : 'PTS';
    google.script.run.withSuccessHandler(tRes => {
      if (!tRes) return;
      if (tRes.duplicateLogin) {
        handleForcedDuplicateLoginLogoutV92(tRes.message);
        return;
      }
      if (tRes.success) {
        applyServerExamTimerV92(tRes);
        saveState();
        if (tRes.isExpired && isExamActive) {
          isExamActive = false;
          v92ExamTimerAnchor.active = false;
          if (timerInterval) clearInterval(timerInterval);
          if (typeof showStudentToast === 'function') {
            showStudentToast('Waktu server untuk sesi ujian ini telah habis. Jawaban otomatis dikumpulkan.', 'warning');
          }
          finishExam(true);
        }
      }
    }).startOrResumeExamTimerServerV92({
      email: studentData.email,
      name: studentData.name || '',
      kelas: studentData.kelas || '',
      subject: selectedSubject,
      examMode: sessMode,
      sessionId: studentData.sessionId || ''
    });
  }
};

// Override prosesKoreksiSiswa agar memvalidasi waktu selesai di server sebelum mengirim final ke Supabase
const _v91OrigProsesKoreksi = prosesKoreksiSiswa;
prosesKoreksiSiswa = async function(endToken, isForceSubmit) {
  const sessMode = (typeof activeExamSessionModeV69 !== 'undefined' && activeExamSessionModeV69) ? activeExamSessionModeV69 : 'PTS';
  if (studentData && studentData.email && studentData.subject && typeof google !== 'undefined' && google.script && google.script.run) {
    try {
      const valRes = await Promise.race([
        new Promise(resolve => {
          google.script.run
            .withSuccessHandler(resolve)
            .withFailureHandler(() => resolve(null))
            .validateExamSubmissionTimeServerV92({
              email: studentData.email,
              subject: studentData.subject,
              examMode: sessMode
            });
        }),
        new Promise(resolve => setTimeout(() => resolve(null), 5000))
      ]);
      if (valRes && valRes.success && !valRes.withinGrace) {
        violationLogs.push(`[SERVER_TIME] Submit terlambat (${valRes.lateFlag}, durasi ${valRes.elapsedMin} mnt)`);
      }
    } catch (e) {}
  }
  v92ExamTimerAnchor.active = false;
  return await _v91OrigProsesKoreksi(endToken, isForceSubmit);
};

