function setPresetExamDurationV93(mins) {
  const inp = document.getElementById('v93-inp-exam-duration');
  if (inp) inp.value = Number(mins) || 70;
  document.querySelectorAll('.v93-preset-chip').forEach(b => {
    b.classList.toggle('active', b.innerText.trim() === `${mins}m`);
  });
}

function syncDurationBarForSelectedMapelV93() {
  const sel = document.getElementById('viewerMapelFilter');
  const mapel = sel ? sel.value : '';
  const badge = document.getElementById('v93-dur-mapel-badge');
  const inp = document.getElementById('v93-inp-exam-duration');
  const sub = document.getElementById('v93-dur-status-sub');

  const defMin = Number(v93ExamDurationsCache.defaultMinutes) || 70;
  let activeDur = defMin;
  if (mapel && v93ExamDurationsCache.byMapel && v93ExamDurationsCache.byMapel[mapel]) {
    activeDur = Number(v93ExamDurationsCache.byMapel[mapel]);
  }

  if (badge) badge.innerText = mapel || 'Default Global';
  if (inp) inp.value = activeDur;
  document.querySelectorAll('.v93-preset-chip').forEach(b => {
    b.classList.toggle('active', b.innerText.trim() === `${activeDur}m`);
  });
  if (sub) {
    sub.innerHTML = mapel
      ? `Durasi aktif <b>${escapeHtml(mapel)}</b>: <b>${activeDur} menit</b> &bull; Perubahan langsung tersinkron real-time ke siswa.`
      : `Durasi default seluruh mapel: <b>${defMin} menit</b>. Pilih mata pelajaran di atas untuk mengatur durasi per mapel.`;
  }
}

