function saveBankSoalExamDurationV93(applyAll = false) {
  const mapel = document.getElementById('viewerMapelFilter')?.value || '';
  const durMin = parseInt(document.getElementById('v93-inp-exam-duration')?.value, 10);

  if (isNaN(durMin) || durMin < 10 || durMin > 240) {
    Swal.fire({ icon: 'warning', title: 'Durasi Tidak Valid', text: 'Masukkan durasi antara 10 hingga 240 menit.', customClass: { popup: 'swal-custom-popup', confirmButton: 'swal-custom-confirm' } });
    return;
  }
  if (!applyAll && !mapel) {
    Swal.fire({ icon: 'info', title: 'Pilih Mata Pelajaran', text: 'Pilih mata pelajaran di dropdown Bank Soal terlebih dahulu, atau klik tombol "Semua Mapel".', customClass: { popup: 'swal-custom-popup', confirmButton: 'swal-custom-confirm' } });
    return;
  }

  const doExecuteSave = () => {
    Swal.fire({
      title: 'Menyimpan & Menyiarkan Durasi...',
      html: applyAll
        ? `Menerapkan durasi <b>${durMin} menit</b> ke seluruh mata pelajaran &amp; menyinkronkan ke siswa secara real-time...`
        : `Menerapkan durasi <b>${durMin} menit</b> untuk <b>${escapeHtml(mapel)}</b> &amp; menyinkronkan ke siswa secara real-time...`,
      allowOutsideClick: false,
      didOpen: () => Swal.showLoading(),
      customClass: { popup: 'swal-custom-popup' }
    });

    google.script.run.withSuccessHandler(async (res) => {
      if (!res || !res.success) {
        Swal.fire({ icon: 'error', title: 'Gagal Menyimpan Durasi', text: (res && res.message) || 'Terjadi kesalahan server.', customClass: { popup: 'swal-custom-popup', confirmButton: 'swal-custom-confirm' } });
        return;
      }

      if (res.durationsMap) {
        v93ExamDurationsCache = {
          defaultMinutes: Number(res.durationsMap.defaultMinutes) || durMin,
          byMapel: res.durationsMap.byMapel || {}
        };
      }
      syncDurationBarForSelectedMapelV93();

      // Siarkan langsung secara real-time ke seluruh perangkat siswa yang sedang di Portal CBT maupun sedang mengerjakan ujian!
      try {
        if (presenceChannel && v93TelemetryEngine.subscribed) {
          await presenceChannel.send({
            type: 'broadcast',
            event: 'exam_duration_updated',
            payload: {
              scope: applyAll ? 'ALL' : 'MAPEL',
              mapel: applyAll ? 'ALL' : mapel,
              durationMin: durMin,
              updatedBy: window.currentStaffName || 'Admin',
              ts: Date.now()
            }
          });
        }
      } catch (bcErr) {}

      if (typeof catatRiwayatAksiAdmin === 'function') {
        catatRiwayatAksiAdmin(window.currentStaffName || 'ADMIN', applyAll ? 'SEMUA MAPEL' : mapel, `ATUR DURASI UJIAN -> ${durMin} MENIT`);
      }

      const activeNote = res.updatedSessionsCount > 0
        ? `<br><span style="color:#059669; font-weight:800;">✓ ${res.updatedSessionsCount} sesi ujian siswa aktif ikut diperbarui di server secara real-time!</span>`
        : '';
      Swal.fire({
        icon: 'success',
        title: 'Durasi Ujian Tersinkron!',
        html: `${escapeHtml(res.message)}${activeNote}`,
        timer: 2500,
        showConfirmButton: false,
        customClass: { popup: 'swal-custom-popup' }
      });
    }).withFailureHandler(err => {
      Swal.fire({ icon: 'error', title: 'Koneksi Gagal', text: err.toString(), customClass: { popup: 'swal-custom-popup' } });
    }).saveExamDurationAdminV93({
      adminSessionToken: window.currentAdminSessionTokenV91 || '',
      applyAll: !!applyAll,
      mapel: mapel,
      durationMin: durMin
    });
  };

  if (applyAll) {
    Swal.fire({
      icon: 'question',
      title: `Terapkan ${durMin} Menit ke Semua Mapel?`,
      html: `Seluruh mata pelajaran ujian (termasuk siswa yang sedang mengerjakan) akan langsung disinkronkan ke durasi <b>${durMin} menit</b>.`,
      showCancelButton: true,
      confirmButtonText: 'Ya, Terapkan Semua',
      cancelButtonText: 'Batal',
      customClass: { popup: 'swal-custom-popup', confirmButton: 'swal-custom-confirm' }
    }).then(r => { if (r.isConfirmed) doExecuteSave(); });
  } else {
    doExecuteSave();
  }
}

// Penerima Siaran Durasi Ujian Real-Time di Sisi Siswa (Portal CBT + Saat Sedang Mengerjakan Soal!)
function applyRealtimeExamDurationUpdateV93(payload) {
  if (!payload || !payload.durationMin) return;
  if (document.body.classList.contains('admin-mode')) return;

  const newDurMin = Number(payload.durationMin);
  if (isNaN(newDurMin) || newDurMin < 10) return;
  const isAll = payload.scope === 'ALL';
  const targetMapel = (payload.mapel || '').toString().trim();

  // 1. Perbarui data durasi pada daftar mapel Portal CBT
  if (globalLMSDashboard && Array.isArray(globalLMSDashboard.subjects)) {
    globalLMSDashboard.subjects.forEach(s => {
      if (isAll || (s.name && s.name.toLowerCase() === targetMapel.toLowerCase())) {
        s.durasiUjian = newDurMin;
      }
    });
    if (typeof renderCBTBentoPortalV67 === 'function') {
      try { renderCBTBentoPortalV67(); } catch (e) {}
    }
  }

  // 2. Jika siswa SEDANG MENGERJAKAN UJIAN mapel tersebut -> sesuaikan Timer Monotonik seketika tanpa gangguan!
  if (isExamActive && studentData && studentData.subject && (isAll || studentData.subject.toLowerCase() === targetMapel.toLowerCase())) {
    const oldDurMin = (typeof v92ExamTimerAnchor !== 'undefined' && v92ExamTimerAnchor.durationMin) ? Number(v92ExamTimerAnchor.durationMin) : 70;
    if (oldDurMin !== newDurMin && typeof v92ExamTimerAnchor !== 'undefined' && v92ExamTimerAnchor.active) {
      const elapsedSoFarMs = performance.now() - v92ExamTimerAnchor.perfStartMs;
      const currentRemMs = Math.max(0, v92ExamTimerAnchor.remainingMs - elapsedSoFarMs);
      const deltaMs = (newDurMin - oldDurMin) * 60000;
      const adjustedRemMs = Math.max(60000, currentRemMs + deltaMs); // Minimal sisa 1 menit jika dikurangi agar siswa sempat submit

      v92ExamTimerAnchor.remainingMs = adjustedRemMs;
      v92ExamTimerAnchor.perfStartMs = performance.now();
      v92ExamTimerAnchor.durationMin = newDurMin;
      v92ExamTimerAnchor.deadlineMs = Date.now() + adjustedRemMs;
      examEndTime = Date.now() + adjustedRemMs;
      try { saveState(); } catch (e) {}
    }

    if (typeof showStudentToast === 'function') {
      showStudentToast(`⏱️ Pengawas memperbarui durasi ujian ${studentData.subject} menjadi ${newDurMin} menit. Sisa waktu otomatis disesuaikan!`, 'info');
    }

    // Kalibrasi ulang presisi ke server agar 100% sinkron dengan LMS_Exam_Sessions
    if (studentData.email && typeof google !== 'undefined' && google.script && google.script.run) {
      const sessMode = (typeof activeExamSessionModeV69 !== 'undefined' && activeExamSessionModeV69) ? activeExamSessionModeV69 : 'PTS';
      google.script.run.withSuccessHandler(tRes => {
        if (tRes && tRes.success && typeof applyServerExamTimerV92 === 'function') {
          applyServerExamTimerV92(tRes);
          try { saveState(); } catch (e) {}
        }
      }).startOrResumeExamTimerServerV92({
        email: studentData.email,
        name: studentData.name || '',
        kelas: studentData.kelas || '',
        subject: studentData.subject,
        examMode: sessMode,
        sessionId: studentData.sessionId || ''
      });
    }
  } else if (!isExamActive && typeof showStudentToast === 'function') {
    const lbl = isAll ? 'seluruh mata pelajaran' : targetMapel;
    showStudentToast(`⏱️ Pengawas memperbarui durasi ujian ${lbl} menjadi ${newDurMin} menit.`, 'info');
  }
}


