function handleStudentKickedByHeartbeatV94(reasonMsg) {
  isExamActive = false;
  if (typeof v92ExamTimerAnchor !== 'undefined') v92ExamTimerAnchor.active = false;
  if (timerInterval) clearInterval(timerInterval);
  if (strictInterval) clearInterval(strictInterval);
  if (v94ScaleEngine.studentTimer) { clearInterval(v94ScaleEngine.studentTimer); v94ScaleEngine.studentTimer = null; }
  try { localStorage.removeItem(getStorageKey()); } catch (e) {}
  if (typeof closeLMSToolsFullscreenModalV82 === 'function') closeLMSToolsFullscreenModalV82();
  if (typeof exitFullScreenOnly === 'function') exitFullScreenOnly();

  document.getElementById('exam-section')?.classList.add('hidden');
  document.getElementById('lms-learning-section')?.classList.add('hidden');
  document.getElementById('dashboard-section')?.classList.add('hidden');
  document.getElementById('app-wrapper')?.classList.add('hidden');
  document.getElementById('login-section')?.classList.remove('hidden');
  document.getElementById('btn-admin-login')?.classList.remove('hidden');

  const btnLogin = document.getElementById('btn-login');
  if (btnLogin) btnLogin.disabled = false;
  if (typeof applySicibinagaEnvironmentUIV88 === 'function') applySicibinagaEnvironmentUIV88();

  studentData = { kelas: '', name: '', email: '', subject: '', sessionId: '' };
  lastTrackedState = '';

  Swal.fire({
    icon: 'error',
    title: 'Sesi Dihentikan Pengawas!',
    text: reasonMsg || 'Admin/Pengawas telah mereset atau mengeluarkan sesi Anda dari aplikasi.',
    allowOutsideClick: false,
    customClass: { popup: 'swal-custom-popup', confirmButton: 'swal-custom-confirm' }
  });
}

function applyRuntimeConfigFromHeartbeatV94(cfgObj) {
  if (!cfgObj || document.body.classList.contains('admin-mode')) return;
  const stamp = `${cfgObj.active_environment || ''}|${cfgObj.active_exam_mode || ''}|${cfgObj.default_duration_min || ''}|${JSON.stringify(cfgObj.durations_by_mapel || {})}`;
  if (stamp === v94ScaleEngine.lastAppliedRuntimeStamp) return;
  const isFirstSync = !v94ScaleEngine.lastAppliedRuntimeStamp;
  v94ScaleEngine.lastAppliedRuntimeStamp = stamp;

  // 1. Sinkronkan Environment (LMS / CBT / ALL) & Mode Ujian (PTS / PAS)
  const curEnv = typeof getActiveAppEnvironmentV88 === 'function' ? getActiveAppEnvironmentV88() : 'ALL';
  const curMode = typeof getActiveCBTExamModeV69 === 'function' ? getActiveCBTExamModeV69() : 'PTS';
  const newEnv = (cfgObj.active_environment || '').toString().toUpperCase();
  const newMode = (cfgObj.active_exam_mode || '').toString().toUpperCase();

  if (['LMS', 'CBT', 'ALL'].includes(newEnv) && newEnv !== curEnv) {
    if (typeof applySicibinagaEnvironmentUIV88 === 'function') applySicibinagaEnvironmentUIV88(newEnv, newMode || curMode);
    if (!isFirstSync && typeof showStudentToast === 'function') {
      const lbl = newEnv === 'CBT' ? 'Environment Ujian (CBT)' : (newEnv === 'LMS' ? 'Environment Belajar (LMS)' : 'Mode Terpadu');
      showStudentToast(`Admin mengaktifkan ${lbl}. Tampilan otomatis menyesuaikan!`, 'info');
    }
  }
  if (['PTS', 'PAS'].includes(newMode) && newMode !== curMode && typeof cbtExamModeStateV69 !== 'undefined') {
    cbtExamModeStateV69.activeMode = newMode;
    try { localStorage.setItem('sicibinaga_active_exam_mode_v69', newMode); } catch (e) {}
    if (typeof applyActiveModeHistoryToDashboardV69 === 'function') applyActiveModeHistoryToDashboardV69();
    if (typeof syncCBTModeUIElementsV69 === 'function') syncCBTModeUIElementsV69();
    if (typeof renderCBTBentoPortalV67 === 'function') renderCBTBentoPortalV67();
  }

  // 2. Sinkronkan Durasi Ujian Per Mapel secara real-time (termasuk saat sedang ujian!)
  const defMin = Number(cfgObj.default_duration_min) || 70;
  const byMapel = (cfgObj.durations_by_mapel && typeof cfgObj.durations_by_mapel === 'object') ? cfgObj.durations_by_mapel : {};

  if (globalLMSDashboard && Array.isArray(globalLMSDashboard.subjects)) {
    let changedPortal = false;
    globalLMSDashboard.subjects.forEach(s => {
      const targetMin = Number(byMapel[s.name]) || defMin;
      if (Number(s.durasiUjian) !== targetMin) {
        s.durasiUjian = targetMin;
        changedPortal = true;
      }
    });
    if (changedPortal && !isExamActive && typeof renderCBTBentoPortalV67 === 'function') {
      try { renderCBTBentoPortalV67(); } catch (e) {}
    }
  }

  if (isExamActive && studentData && studentData.subject && typeof v92ExamTimerAnchor !== 'undefined' && v92ExamTimerAnchor.active) {
    const activeDurTarget = Number(byMapel[studentData.subject]) || defMin;
    if (activeDurTarget >= 10 && Number(v92ExamTimerAnchor.durationMin) !== activeDurTarget) {
      applyRealtimeExamDurationUpdateV93({
        scope: 'MAPEL',
        mapel: studentData.subject,
        durationMin: activeDurTarget
      });
    }
  }
}

async function sendStudentHeartbeatV94(forceNow = false, claimSession = false) {
  if (v94ScaleEngine.heartbeatMode !== 'DB_RPC') {
    return _v93OrigBroadcastTelemetry(forceNow);
  }
  if (document.body.classList.contains('admin-mode')) return;
  if (!studentData || !studentData.name || !studentData.email) return;

  if (claimSession) v94ScaleEngine.pendingClaimSession = true;

  const now = Date.now();
  const payload = buildStudentLiveTelemetryPayloadV63();
  const sig = `${payload.zona}|${payload.subZona}|${payload.mapel}|${payload.detailAktivitas}|${payload.focusStatus}|${payload.vCount}`;
  const elapsed = now - v94ScaleEngine.lastHeartbeatSentMs;
  const changed = sig !== v94ScaleEngine.lastHeartbeatSig;
  const dueRegular = elapsed >= 14500;

  if (!forceNow && !v94ScaleEngine.pendingClaimSession && !dueRegular && !changed) return;

  // Throttle agar HP siswa tidak mengirim lebih cepat dari 4 detik (kecuali forceNow/claimSession)
  if (!forceNow && !v94ScaleEngine.pendingClaimSession && elapsed < 4000) {
    if (!v94ScaleEngine.studentDebounceTimer) {
      v94ScaleEngine.studentDebounceTimer = setTimeout(() => {
        v94ScaleEngine.studentDebounceTimer = null;
        sendStudentHeartbeatV94(false, false);
      }, 4100 - elapsed);
    }
    return;
  }

  if (v94ScaleEngine.studentInFlight) return;
  v94ScaleEngine.studentInFlight = true;

  const doClaim = !!v94ScaleEngine.pendingClaimSession;
  v94ScaleEngine.pendingClaimSession = false;
  v94ScaleEngine.lastHeartbeatSentMs = now;
  v94ScaleEngine.lastHeartbeatSig = sig;
  lastTrackedState = sig;

  try {
    const { data, error } = await supabaseClient.rpc('student_heartbeat_v94', {
      p_email: studentData.email,
      p_nama: studentData.name,
      p_kelas: studentData.kelas || '-',
      p_zona: payload.zona || 'BERANDA',
      p_sub_zona: payload.subZona || '',
      p_mapel: payload.mapel || '-',
      p_aktivitas_utama: payload.aktivitasUtama || '',
      p_detail_aktivitas: payload.detailAktivitas || '',
      p_progress_pct: Number(payload.progressPct) || 0,
      p_no_soal: Number(payload.noSoal) || 0,
      p_tot_soal: Number(payload.totSoal) || 0,
      p_jml_jawab: Number(payload.jmlJawab) || 0,
      p_sisa_mnt: Number(payload.sisaMnt) || 0,
      p_focus_status: payload.focusStatus || 'FOKUS_AKTIF',
      p_device: payload.device || '',
      p_v_count: Number(payload.vCount) || 0,
      p_session_id: studentData.sessionId || '',
      p_claim_session: doClaim
    });

    if (error) {
      const code = (error.code || '').toString();
      const msg = (error.message || '').toLowerCase();
      if (code === 'PGRST202' || code === '42883' || msg.includes('could not find the function')) {
        activateWebSocketFallbackV94('RPC student_heartbeat_v94 belum dibuat');
      }
      return;
    }

    if (data && typeof data === 'object') {
      if (data.status === 'DUPLICATE_SESSION') {
        if (typeof handleForcedDuplicateLoginLogoutV92 === 'function') {
          handleForcedDuplicateLoginLogoutV92(data.message || 'Akun Anda terdeteksi login di perangkat lain!');
        }
        return;
      }
      if (data.status === 'KICKED') {
        handleStudentKickedByHeartbeatV94(data.reason);
        return;
      }
      if (data.runtime_config) {
        applyRuntimeConfigFromHeartbeatV94(data.runtime_config);
      }
    }
  } catch (e) {
    // Abaikan sementara jika sinyal HP berkedip; akan mencoba lagi di heartbeat 15s berikutnya
  } finally {
    v94ScaleEngine.studentInFlight = false;
  }
}

function startStudentHeartbeatLoopV94() {
  if (document.body.classList.contains('admin-mode')) return;
  closeUnneededStudentWebSocketsV94();
  if (v94ScaleEngine.studentTimer) clearInterval(v94ScaleEngine.studentTimer);

  // Jitter acak 0 - 2.5 detik agar 255 siswa tersebar merata di PostgreSQL (tidak menumpuk di detik yang sama)
  const intervalMs = 15000 + Math.floor(Math.random() * 2500);
  v94ScaleEngine.studentTimer = setInterval(() => {
    if (!document.body.classList.contains('admin-mode') && studentData && studentData.email) {
      sendStudentHeartbeatV94(false, false);
    }
  }, intervalMs);
}

