// B. SISI ADMIN: POLLING RINGAN 1x/8 DETIK VIA CODE.GS (TAHAN 255-500+ SISWA)
// -------------------------------------------------------------------------

function hydrateAdminMonitorFromDbRowsV94(rows, serverNowMs) {
  const nowMs = Number(serverNowMs) || Date.now();
  const ONLINE_TTL_MS = 50000; // 50 detik (lebih dari 3x interval heartbeat 15 detik -> 0 false-offline!)
  const mergedOnline = {};
  const globalLogs = [];

  (rows || []).forEach(r => {
    if (!r || !r.nama) return;
    const normKey = r.nama.trim().toLowerCase();
    const updatedMs = r.updated_at ? Date.parse(r.updated_at) : 0;
    const isOnline = updatedMs > 0 && (nowMs - updatedMs) <= ONLINE_TTL_MS;

    const stateObj = {
      online_at: r.updated_at || new Date().toISOString(),
      waktuStr: updatedMs ? new Date(updatedMs).toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit', second: '2-digit' }) : '-',
      status: isOnline ? 'aktif' : 'offline',
      tipe: 'siswa',
      nama: r.nama,
      kelas: r.kelas || '-',
      mapel: r.mapel || '-',
      zona: r.zona || 'BERANDA',
      subZona: r.sub_zona || '',
      aktivitasUtama: r.aktivitas_utama || 'Aktif di Aplikasi',
      detailAktivitas: r.detail_aktivitas || '-',
      progressPct: Number(r.progress_pct) || 0,
      noSoal: Number(r.no_soal) || 0,
      totSoal: Number(r.tot_soal) || 0,
      jmlJawab: Number(r.jml_jawab) || 0,
      sisaMnt: Number(r.sisa_mnt) || 0,
      focusStatus: r.focus_status || 'FOKUS_AKTIF',
      device: r.device || '',
      vCount: Number(r.v_count) || 0,
      ts: updatedMs
    };

    if (isOnline) {
      mergedOnline['db_' + normKey] = [stateObj];
    }

    // Hydrate rekaman jejak individu langsung dari kolom JSONB `recent_logs` PostgreSQL (persisten walau browser di-refresh!)
    const logsArr = Array.isArray(r.recent_logs) ? r.recent_logs : [];
    const normalizedStudentLogs = logsArr.map(l => ({
      waktu: l.w || l.waktu || '-',
      tanggal: l.t || l.tanggal || '',
      nama: r.nama,
      kelas: r.kelas || '-',
      zona: l.z || l.zona || r.zona || 'BERANDA',
      mapel: l.m || l.mapel || r.mapel || '-',
      aktivitasUtama: l.a || l.aktivitasUtama || r.aktivitas_utama || '-',
      detailAktivitas: l.d || l.detailAktivitas || r.detail_aktivitas || '-',
      focusStatus: l.f || l.focusStatus || 'FOKUS_AKTIF',
      _ts: Number(l.ts) || updatedMs
    }));

    if (normalizedStudentLogs.length > 0) {
      rekamanJejakPerSiswaMapV63[normKey] = normalizedStudentLogs;
      // Ambil 15 log terbaru per siswa untuk papan log global agar cepat & ringan
      normalizedStudentLogs.slice(0, 15).forEach(entry => globalLogs.push(entry));
    }
  });

  globalLogs.sort((a, b) => (b._ts || 0) - (a._ts || 0));
  if (globalLogs.length > 0) {
    rekamanJejakAktivitasSiswaV63 = globalLogs.slice(0, 1500);
  }

  daftarSiswaOnline = mergedOnline;
  const totalOnline = Object.keys(mergedOnline).length;

  const countElAdmin = document.getElementById('admin-tot-mengerjakan');
  if (countElAdmin) countElAdmin.innerText = totalOnline;
  const countLbl = document.getElementById('monitorCountLabel');
  if (countLbl) countLbl.innerText = totalOnline;
  const badgeLog = document.getElementById('monitorTotalLogBadge');
  if (badgeLog) badgeLog.innerText = rekamanJejakAktivitasSiswaV63.length;

  const tabMon = document.getElementById('tab-monitor');
  if (tabMon && !tabMon.classList.contains('hidden')) {
    renderTabelMonitorAdmin();
  }
}

function pollAdminLiveMonitorDbV94(showFeedback = false) {
  if (!document.body.classList.contains('admin-mode')) return;
  if (v94ScaleEngine.heartbeatMode !== 'DB_RPC') {
    if (showFeedback && typeof showStudentToast === 'function') {
      showStudentToast('Menyegarkan Live Monitor (Mode Cadangan)...', 'info');
    }
    return;
  }
  const tok = window.currentAdminSessionTokenV91 || '';
  if (!tok || v94ScaleEngine.adminPollInFlight) return;

  v94ScaleEngine.adminPollInFlight = true;
  const btn = document.getElementById('btn-v93-ping-monitor');
  if (showFeedback && btn) {
    btn.innerHTML = '<i class="fa-solid fa-spinner fa-spin"></i> Menyegarkan...';
    btn.disabled = true;
  }

  google.script.run.withSuccessHandler(res => {
    v94ScaleEngine.adminPollInFlight = false;
    if (btn) {
      btn.innerHTML = '<i class="fa-solid fa-satellite-dish"></i> Segarkan Live';
      btn.disabled = false;
    }

    if (res && res.success) {
      updateV94MonitorEngineBadge(true, `DB Heartbeat • ${res.rows ? res.rows.length : 0} Tercatat`);
      hydrateAdminMonitorFromDbRowsV94(res.rows || [], res.serverNowMs);
      if (showFeedback && typeof showStudentToast === 'function') {
        const onCnt = Object.keys(daftarSiswaOnline || {}).length;
        showStudentToast(`Live Monitor tersinkron! ${onCnt} siswa sedang online saat ini.`, 'success');
      }
    } else if (res && (res.needsSqlSetup || res.needsServiceRoleKey)) {
      activateWebSocketFallbackV94(res.message);
      if (showFeedback && typeof showStudentToast === 'function') {
        showStudentToast(res.message, 'warning');
      }
    }
  }).withFailureHandler(() => {
    v94ScaleEngine.adminPollInFlight = false;
    if (btn) {
      btn.innerHTML = '<i class="fa-solid fa-satellite-dish"></i> Segarkan Live';
      btn.disabled = false;
    }
  }).adminFetchLiveMonitorV94(tok);
}

function startAdminLiveMonitorPollerV94() {
  if (v94ScaleEngine.adminPollTimer) clearInterval(v94ScaleEngine.adminPollTimer);
  pollAdminLiveMonitorDbV94(false);

  // Poll cerdas: tiap 8 detik saat tab Monitor terbuka, tiap 24 detik saat di tab Admin lain
  let tick = 0;
  v94ScaleEngine.adminPollTimer = setInterval(() => {
    const admSec = document.getElementById('admin-section');
    if (!admSec || admSec.classList.contains('hidden')) return;
    tick++;
    const tabMon = document.getElementById('tab-monitor');
    const isMonitorVisible = tabMon && !tabMon.classList.contains('hidden');
    if (isMonitorVisible || (tick % 3 === 0)) {
      pollAdminLiveMonitorDbV94(false);
    }
  }, 8000);
}

