initNewExam = function(selectedSubject) {
  Swal.fire({
    title: 'Masukkan Token Mulai',
    input: 'text',
    inputPlaceholder: 'Ketik Token Ujian...',
    showCancelButton: true,
    confirmButtonText: 'Mulai Ujian',
    cancelButtonText: 'Batal',
    customClass: { popup: 'swal-custom-popup', confirmButton: 'swal-custom-confirm', input: 'swal-custom-input' },
    preConfirm: (t) => {
      if (!t || !t.trim()) { Swal.showValidationMessage('Token wajib diisi!'); return false; }
      return t.trim();
    }
  }).then(async (result) => {
    if (!result.isConfirmed) return;

    enterFullScreen();
    document.getElementById('dashboard-section').classList.add('hidden');
    Swal.fire({
      title: 'Menyiapkan Soal...',
      html: '<div id="v95-load-exam-status" style="font-size:13px; color:#475569;">Mengambil paket soal terenkripsi &amp; menyinkronkan timer server...</div>',
      didOpen: () => Swal.showLoading(),
      allowOutsideClick: false,
      allowEscapeKey: false,
      customClass: { popup: 'swal-custom-popup' }
    });

    const sessMode = (typeof activeExamSessionModeV69 !== 'undefined' && activeExamSessionModeV69) ? activeExamSessionModeV69 : 'PTS';
    const subObj = (globalLMSDashboard && Array.isArray(globalLMSDashboard.subjects))
      ? globalLMSDashboard.subjects.find(x => x.name === selectedSubject)
      : null;
    const estDurMin = (subObj && Number(subObj.durasiUjian)) ? Number(subObj.durasiUjian) : 70;

    try {
      const res = await runGasWithAutoRetryJitterV95((resolve, reject) => {
        google.script.run.withSuccessHandler(resolve).withFailureHandler(reject).getQuestions(selectedSubject, result.value, {
          email: studentData.email || '',
          name: studentData.name || '',
          kelas: studentData.kelas || '',
          examMode: sessMode,
          sessionId: studentData.sessionId || '',
          skipGasTimer: true
        });
      }, {
        maxRetries: 3,
        minJitterMs: 1200,
        maxJitterMs: 3500,
        onRetry: (attempt, max) => {
          const stEl = document.getElementById('v95-load-exam-status');
          if (stEl) stEl.innerHTML = `Antrean server padat, mencoba ulang otomatis <b>(${attempt}/${max})</b>...`;
        }
      });

      if (!res || !res.success) {
        Swal.close();
        exitFullScreenOnly();
        Swal.fire({ icon: 'error', text: (res && res.message) || 'Gagal memuat soal.', customClass: { popup: 'swal-custom-popup', confirmButton: 'swal-custom-confirm' } }).then(() => {
          document.getElementById('dashboard-section').classList.remove('hidden');
        });
        return;
      }

      const serverDurMin = Number(res.durationMin) || estDurMin;
      const timerRes = await startOrResumeExamTimerHybridV95({
        email: studentData.email || '',
        name: studentData.name || '',
        kelas: studentData.kelas || '',
        examMode: sessMode,
        subject: selectedSubject,
        durationMin: serverDurMin,
        sessionId: studentData.sessionId || ''
      });

      Swal.close();

      if (timerRes && timerRes.duplicateLogin) {
        exitFullScreenOnly();
        if (typeof handleForcedDuplicateLoginLogoutV92 === 'function') handleForcedDuplicateLoginLogoutV92(timerRes.message);
        return;
      }
      if (timerRes && timerRes.isExpired) {
        exitFullScreenOnly();
        Swal.fire({
          icon: 'warning',
          title: 'Waktu Ujian Telah Habis',
          text: `Batas waktu server (${timerRes.durationMin} menit) untuk ujian ${selectedSubject} sudah habis. Hubungi Pengawas jika memerlukan reset sesi.`,
          customClass: { popup: 'swal-custom-popup', confirmButton: 'swal-custom-confirm' }
        }).then(() => {
          document.getElementById('dashboard-section').classList.remove('hidden');
        });
        return;
      }

      examData = shuffleArray(res.data);
      currentIdx = 0;
      userAnswers = {};
      doubtfulAnswers = {};
      activeEndToken = encryptData(res.endToken || '');

      if (timerRes && timerRes.success && typeof applyServerExamTimerV92 === 'function') {
        applyServerExamTimerV92(timerRes);
      } else {
        examEndTime = Date.now() + (serverDurMin * 60000);
        if (typeof setMonotonicExamTimerFallbackV92 === 'function') setMonotonicExamTimerFallbackV92(serverDurMin * 60000);
      }

      isExamActive = true;
      violationCount = 0;
      violationLogs = [];
      saveState();
      startStrictMode();
      document.getElementById('exam-section').classList.remove('hidden');
      document.getElementById('exam-title-badge').innerText = selectedSubject;
      buildNavGrid();
      renderSingleQuestion();
      startTimer();
      if (typeof broadcastStudentTelemetryNowV63 === 'function') {
        setTimeout(() => broadcastStudentTelemetryNowV63(true), 250);
      }
    } catch (err) {
      Swal.close();
      exitFullScreenOnly();
      document.getElementById('dashboard-section').classList.remove('hidden');
      Swal.fire({
        icon: 'warning',
        title: 'Antrean Soal Padat',
        text: 'Sistem telah mencoba ulang otomatis 3 kali. Tunggu 3 detik lalu klik Mulai Ujian kembali.',
        customClass: { popup: 'swal-custom-popup', confirmButton: 'swal-custom-confirm' }
      });
    }
  });
};

resumeExam = function(savedState, selectedSubject) {
  const localRem = savedState && savedState.endTime ? Math.max(0, savedState.endTime - Date.now()) : (70 * 60 * 1000);
  setMonotonicExamTimerFallbackV92(localRem);
  _v91OrigResumeExam(savedState, selectedSubject);

  if (studentData && studentData.email) {
    const sessMode = (typeof activeExamSessionModeV69 !== 'undefined' && activeExamSessionModeV69) ? activeExamSessionModeV69 : 'PTS';
    const subObj = (globalLMSDashboard && Array.isArray(globalLMSDashboard.subjects))
      ? globalLMSDashboard.subjects.find(x => x.name === selectedSubject)
      : null;
    const durMin = (subObj && Number(subObj.durasiUjian)) ? Number(subObj.durasiUjian) : 70;

    startOrResumeExamTimerHybridV95({
      email: studentData.email,
      name: studentData.name || '',
      kelas: studentData.kelas || '',
      examMode: sessMode,
      subject: selectedSubject,
      durationMin: durMin,
      sessionId: studentData.sessionId || ''
    }).then(tRes => {
      if (!tRes) return;
      if (tRes.duplicateLogin) {
        if (typeof handleForcedDuplicateLoginLogoutV92 === 'function') handleForcedDuplicateLoginLogoutV92(tRes.message);
        return;
      }
      if (tRes.success) {
        applyServerExamTimerV92(tRes);
        saveState();
        if (tRes.isExpired && isExamActive) {
          isExamActive = false;
          v92ExamTimerAnchor.active = false;
          if (timerInterval) clearInterval(timerInterval);
          if (typeof showStudentToast === 'function') {
            showStudentToast('Waktu server untuk sesi ujian ini telah habis. Jawaban otomatis dikumpulkan.', 'warning');
          }
          finishExam(true);
        }
      }
    });
  }
};

prosesKoreksiSiswa = async function(endToken, isForceSubmit) {
  const sessMode = (typeof activeExamSessionModeV69 !== 'undefined' && activeExamSessionModeV69) ? activeExamSessionModeV69 : 'PTS';
  if (studentData && studentData.email && studentData.subject) {
    try {
      const valRes = await validateExamSubmissionTimeHybridV95({
        email: studentData.email,
        subject: studentData.subject,
        examMode: sessMode
      });
      if (valRes && valRes.success && !valRes.withinGrace) {
        violationLogs.push(`[SERVER_TIME] Submit terlambat (${valRes.lateFlag}, durasi ${valRes.elapsedMin} mnt)`);
      }
    } catch (e) {}
  }
  if (typeof v92ExamTimerAnchor !== 'undefined') v92ExamTimerAnchor.active = false;
  return await _v91OrigProsesKoreksi(endToken, isForceSubmit);
};

applyRealtimeExamDurationUpdateV93 = function(payload) {
  if (!payload || !payload.durationMin) return;
  if (document.body.classList.contains('admin-mode')) return;

  const newDurMin = Number(payload.durationMin);
  if (isNaN(newDurMin) || newDurMin < 10) return;
  const isAll = payload.scope === 'ALL';
  const targetMapel = (payload.mapel || '').toString().trim();

  if (globalLMSDashboard && Array.isArray(globalLMSDashboard.subjects)) {
    globalLMSDashboard.subjects.forEach(s => {
      if (isAll || (s.name && s.name.toLowerCase() === targetMapel.toLowerCase())) {
        s.durasiUjian = newDurMin;
      }
    });
    if (typeof renderCBTBentoPortalV67 === 'function') {
      try { renderCBTBentoPortalV67(); } catch (e) {}
    }
  }

  if (isExamActive && studentData && studentData.subject && (isAll || studentData.subject.toLowerCase() === targetMapel.toLowerCase())) {
    const oldDurMin = (typeof v92ExamTimerAnchor !== 'undefined' && v92ExamTimerAnchor.durationMin) ? Number(v92ExamTimerAnchor.durationMin) : 70;
    if (oldDurMin !== newDurMin && typeof v92ExamTimerAnchor !== 'undefined' && v92ExamTimerAnchor.active) {
      const elapsedSoFarMs = performance.now() - v92ExamTimerAnchor.perfStartMs;
      const currentRemMs = Math.max(0, v92ExamTimerAnchor.remainingMs - elapsedSoFarMs);
      const deltaMs = (newDurMin - oldDurMin) * 60000;
      const adjustedRemMs = Math.max(60000, currentRemMs + deltaMs);

      v92ExamTimerAnchor.remainingMs = adjustedRemMs;
      v92ExamTimerAnchor.perfStartMs = performance.now();
      v92ExamTimerAnchor.durationMin = newDurMin;
      v92ExamTimerAnchor.deadlineMs = Date.now() + adjustedRemMs;
      examEndTime = Date.now() + adjustedRemMs;
      try { saveState(); } catch (e) {}
    }

    if (typeof showStudentToast === 'function') {
      showStudentToast(`⏱️ Pengawas memperbarui durasi ujian ${studentData.subject} menjadi ${newDurMin} menit. Sisa waktu otomatis disesuaikan!`, 'info');
    }

    if (studentData.email) {
      const sessMode = (typeof activeExamSessionModeV69 !== 'undefined' && activeExamSessionModeV69) ? activeExamSessionModeV69 : 'PTS';
      startOrResumeExamTimerHybridV95({
        email: studentData.email,
        name: studentData.name || '',
        kelas: studentData.kelas || '',
        examMode: sessMode,
        subject: studentData.subject,
        durationMin: newDurMin,
        sessionId: studentData.sessionId || ''
      }).then(tRes => {
        if (tRes && tRes.success && typeof applyServerExamTimerV92 === 'function') {
          applyServerExamTimerV92(tRes);
          try { saveState(); } catch (e) {}
        }
      });
    }
  } else if (!isExamActive && typeof showStudentToast === 'function') {
    const lbl = isAll ? 'seluruh mata pelajaran' : targetMapel;
    showStudentToast(`⏱️ Pengawas memperbarui durasi ujian ${lbl} menjadi ${newDurMin} menit.`, 'info');
  }
};

