function ujiKoneksi4GroqKeysAdminV96() {
  const btn = document.getElementById('btn-v96-test-groq-all');
  if (btn) {
    btn.disabled = true;
    btn.innerHTML = '<i class="fa-solid fa-spinner fa-spin"></i> Menguji ke api.groq.com...';
  }

  google.script.run.withSuccessHandler(res => {
    if (btn) {
      btn.disabled = false;
      btn.innerHTML = '<i class="fa-solid fa-bolt"></i> Uji Koneksi 5 API Key Groq';
    }
    if (!res || !res.success) {
      if (typeof showStudentToast === 'function') showStudentToast((res && res.message) || 'Gagal menguji Groq API.', 'error');
      return;
    }

    (res.results || []).forEach(r => {
      const bdg = document.getElementById('v96-groq-badge-' + r.key);
      if (bdg) {
        bdg.style.background = r.ok ? '#059669' : '#e11d48';
        bdg.innerText = (r.ok ? '✓ ' : '✕ ') + r.statusText;
      }
    });

    if (typeof showStudentToast === 'function') {
      showStudentToast(
        res.allValid
          ? `Semua ${res.validCount}/${res.total} API Key Groq AKTIF & VALID! Seluruh fitur AI siap digunakan.`
          : `${res.validCount}/${res.total} API Key Groq valid. Periksa kunci yang bertanda merah.`,
        res.allValid ? 'success' : 'warning'
      );
    }
  }).withFailureHandler(err => {
    if (btn) {
      btn.disabled = false;
      btn.innerHTML = '<i class="fa-solid fa-bolt"></i> Uji Koneksi 5 API Key Groq';
    }
    if (typeof showStudentToast === 'function') showStudentToast('Gagal menghubungi server: ' + err.toString(), 'error');
  }).testAllGroqApiKeysAdminV96(window.currentAdminSessionTokenV91 || '');
}

bukaModalStatusKeamananV90 = function() {
  Swal.fire({
    title: '<i class="fa-solid fa-shield-halved" style="color:#059669;"></i> Memeriksa Keamanan &amp; API Key V96...',
    html: 'Memverifikasi 5 API Key Groq (Auto-Bersih), Timer PostgreSQL, Live Monitor DB, 2FA, &amp; Hashing SHA-256...',
    allowOutsideClick: false,
    didOpen: () => Swal.showLoading(),
    customClass: { popup: 'swal-custom-popup' }
  });

  const tok = window.currentAdminSessionTokenV91 || '';
  google.script.run.withSuccessHandler(res => {
    if (!res || !res.success) {
      Swal.fire({ icon: 'error', title: 'Gagal Memeriksa', text: (res && res.message) || 'Terjadi kesalahan.', customClass: { popup: 'swal-custom-popup' } });
      return;
    }

    const isSuperAdmin = (window.currentStaffRole === 'ADMIN');
    const items = res.items || [];
    const groqItems = items.filter(it => it.isGroq);
    const otherItems = items.filter(it => !it.isGroq);

    // 1. Tampilkan 4 API Key Groq secara UTUH (tanpa tanda bintang / titik masking!)
    const groqRowsHtml = groqItems.map(it => {
      const fullVal = it.fullValue || '';
      const badgeBg = it.configured ? '#059669' : '#e11d48';
      const badgeTxt = it.configured
        ? (it.autoCleaned ? '✓ Auto-Dibetulkan (Tanda Kutip Dihapus)' : '✓ Format Valid (gsk_...)')
        : '⚠ Belum Diisi / Format Salah';
      return `
        <div class="v96-groq-key-card ${it.configured ? '' : 'is-missing'}">
          <div class="v96-groq-key-head">
            <div>
              <div class="v96-groq-key-name">${escapeHtml(it.key)}</div>
              <div class="v96-groq-key-desc">${escapeHtml(it.label)}</div>
            </div>
            <span id="v96-groq-badge-${escapeHtml(it.key)}" style="padding:3px 9px; border-radius:99px; font-size:10px; font-weight:900; white-space:nowrap; background:${badgeBg}; color:#ffffff;">
              ${badgeTxt}
            </span>
          </div>
          <div class="v96-groq-key-input-row">
            <input
              type="text"
              id="v96-groq-inp-${escapeHtml(it.key)}"
              class="v96-groq-full-input"
              value="${escapeHtml(fullVal)}"
              placeholder="Tempel API Key Groq (gsk_...) tanpa tanda kutip"
              autocomplete="off"
              spellcheck="false"
              ${isSuperAdmin ? '' : 'readonly'}
            >
            <button type="button" class="v96-groq-copy-btn" onclick="copyGroqKeyInputV96('${escapeHtml(it.key)}')" title="Salin API Key">
              <i class="fa-regular fa-copy"></i>
            </button>
          </div>
        </div>`;
    }).join('');

    // 2. Baris SUPABASE_SERVICE_ROLE_KEY (tetap terlindungi)
    const otherRowsHtml = otherItems.map(it => `
      <div style="display:flex; justify-content:space-between; align-items:center; gap:10px; padding:8px 11px; background:${it.configured ? '#f0fdf4' : '#fff1f2'}; border:1px solid ${it.configured ? '#86efac' : '#fecdd3'}; border-radius:10px; margin-bottom:6px;">
        <div style="min-width:0;">
          <div style="font-size:11.5px; font-weight:900; color:#0f172a; font-family:monospace;">${escapeHtml(it.key)}</div>
          <div style="font-size:10.5px; color:#64748b; font-weight:600;">${escapeHtml(it.label)}</div>
        </div>
        <span style="padding:3px 9px; border-radius:99px; font-size:10px; font-weight:900; white-space:nowrap; background:${it.configured ? '#059669' : '#e11d48'}; color:#ffffff;">
          ${it.configured ? '✓ ' + escapeHtml(it.masked) : '⚠ Belum Diisi'}
        </span>
      </div>`).join('');

    const autoCleanBanner = (Number(res.autoCleanedCount) > 0)
      ? `<div style="background:#dcfce7; border:1.5px solid #4ade80; color:#166534; padding:9px 12px; border-radius:11px; font-size:12px; font-weight:800; margin-bottom:10px;">
           <i class="fa-solid fa-wand-magic-sparkles"></i> Sistem V96 mendeteksi &amp; otomatis membersihkan tanda kutip/spasi berlebih pada <b>${res.autoCleanedCount} API Key Groq</b> di Script Properties! Error <i>Invalid API Key</i> telah diperbaiki otomatis.
         </div>`
      : '';

    const twoFA = res.twoFactor || { enabled: false, email: '' };
    const hs = res.hashingStats || { studentTotal: 0, studentHashed: 0, guruTotal: 0, guruHashed: 0, adminHashed: false };
    const totAcc = hs.studentTotal + hs.guruTotal + 1;
    const totHash = hs.studentHashed + hs.guruHashed + (hs.adminHashed ? 1 : 0);
    const hashPct = totAcc > 0 ? Math.round((totHash / totAcc) * 100) : 0;

    Swal.fire({
      title: '<i class="fa-solid fa-shield-halved" style="color:#059669;"></i> Pusat Keamanan &amp; Konkurensi (V96)',
      width: '740px',
      html: `
        <div style="text-align:left; font-size:12.5px; line-height:1.5; max-height:74vh; overflow-y:auto; padding-right:4px;">
          <div style="display:flex; flex-wrap:wrap; gap:6px; margin-bottom:11px;">
            <span class="v91-sec-pill ${res.examTimerSupabaseReady ? 'ok' : 'warn'}"><i class="fa-solid fa-stopwatch"></i> Timer PostgreSQL: ${res.examTimerSupabaseReady ? 'SIAP 255+' : 'Jalankan SQL V95'}</span>
            <span class="v91-sec-pill ${res.heartbeatMonitorReady ? 'ok' : 'warn'}"><i class="fa-solid fa-satellite-dish"></i> Monitor DB: ${res.heartbeatMonitorReady ? 'SIAP 500+' : 'Jalankan SQL V94'}</span>
            <span class="v91-sec-pill ok"><i class="fa-solid fa-bolt"></i> CacheService: Users 60s • Token 30s • Soal 60s</span>
            <span class="v91-sec-pill ok"><i class="fa-solid fa-rotate"></i> Auto-Retry Jitter: 3x</span>
            <span class="v91-sec-pill ${res.sessionActive ? 'ok' : 'warn'}"><i class="fa-solid fa-key"></i> Token: ${res.sessionActive ? res.sessionExpiresMin + ' mnt' : 'Re-login'}</span>
          </div>

          ${autoCleanBanner}

          <div style="font-size:11px; font-weight:900; color:#475569; text-transform:uppercase; margin-bottom:6px;">
            1. Script Properties &mdash; 5 API Key Groq (Tampil Utuh + Auto-Failover) &amp; Supabase
          </div>
          ${groqRowsHtml}

          <div class="v96-groq-actions-row">
            ${isSuperAdmin ? `
              <button type="button" class="v96-btn-save-groq" onclick="simpanSemuaGroqApiKeysAdminV96()">
                <i class="fa-solid fa-floppy-disk"></i> Simpan 5 API Key Groq (Auto-Bersih)
              </button>` : ''}
            <button type="button" id="btn-v96-test-groq-all" class="v96-btn-test-groq" onclick="ujiKoneksi4GroqKeysAdminV96()">
              <i class="fa-solid fa-bolt"></i> Uji Koneksi 5 API Key Groq
            </button>
          </div>

          ${otherRowsHtml}

          <div class="v91-sec-card">
            <div style="display:flex; justify-content:space-between; align-items:center; gap:8px; flex-wrap:wrap;">
              <div style="font-size:11.5px; font-weight:900; color:#0f172a; text-transform:uppercase;"><i class="fa-solid fa-fingerprint" style="color:#059669;"></i> 2. Kesiapan Login Read-Only (Batch Hash SHA-256)</div>
              <span class="v91-sec-pill ${hashPct === 100 ? 'ok' : 'warn'}">${hashPct === 100 ? '100% READ-ONLY SIAP UJIAN ✓' : hashPct + '% Terenkripsi (' + totHash + '/' + totAcc + ')'}</span>
            </div>
            <div class="v92-hash-bar-track"><div class="v92-hash-bar-fill" style="width:${hashPct}%;"></div></div>
            <div style="font-size:11.5px; color:#475569; margin-bottom:8px;">
              &bull; Siswa: <b>${hs.studentHashed}/${hs.studentTotal}</b> &bull; Guru: <b>${hs.guruHashed}/${hs.guruTotal}</b> &bull; Admin: <b>${hs.adminHashed ? 'SHA-256 ✓' : 'Belum di-hash'}</b>
            </div>
            ${isSuperAdmin && hashPct < 100 ? `
              <button type="button" onclick="konfirmasiBatchHashPasswordV92()" style="width:100%; background:#0f172a; color:#3ef08e; border:none; padding:9px 12px; border-radius:10px; font-size:12px; font-weight:800; cursor:pointer;">
                <i class="fa-solid fa-lock"></i> Hash Semua Password Tersisa Sekarang (Aktifkan Login Read-Only)
              </button>` : ''}
          </div>

          <div class="v91-sec-card">
            <div style="display:flex; justify-content:space-between; align-items:center; gap:8px; flex-wrap:wrap; margin-bottom:8px;">
              <div style="font-size:11.5px; font-weight:900; color:#065f46; text-transform:uppercase;"><i class="fa-solid fa-envelope-circle-check"></i> 3. Pengaturan 2FA OTP Admin (Email)</div>
              <span class="v91-sec-pill ${twoFA.enabled ? 'ok' : 'warn'}">${twoFA.enabled ? '2FA AKTIF' : '2FA NONAKTIF'}</span>
            </div>
            ${isSuperAdmin ? `
              <div style="display:flex; flex-direction:column; gap:8px;">
                <input type="email" id="v91-inp-2fa-email" class="swal-custom-input" value="${escapeHtml(twoFA.email || '')}" placeholder="Email Admin penerima OTP (mis: admin@gmail.com)" style="width:100%; padding:9px 12px !important; font-size:12.5px !important; background:#ffffff;">
                <div style="display:flex; gap:8px; flex-wrap:wrap;">
                  <button type="button" onclick="simpanPengaturan2FAAdminV91(true)" style="flex:1; background:#059669; color:#ffffff; border:none; padding:9px 12px; border-radius:10px; font-size:12px; font-weight:800; cursor:pointer;">
                    <i class="fa-solid fa-shield-halved"></i> Aktifkan 2FA &amp; Uji Email
                  </button>
                  <button type="button" onclick="simpanPengaturan2FAAdminV91(false)" style="background:#fff1f2; color:#be123c; border:1px solid #fecdd3; padding:9px 14px; border-radius:10px; font-size:12px; font-weight:800; cursor:pointer;">
                    Nonaktifkan
                  </button>
                </div>
              </div>` : `<div style="font-size:12px; color:#64748b;">Hanya Super Admin yang dapat mengubah konfigurasi 2FA OTP.</div>`}
          </div>
        </div>`,
      confirmButtonText: 'Tutup',
      customClass: { popup: 'swal-custom-popup', confirmButton: 'swal-custom-confirm' }
    });
  }).withFailureHandler(err => {
    Swal.fire({ icon: 'error', title: 'Gagal Memeriksa', text: err.toString(), customClass: { popup: 'swal-custom-popup' } });
  }).getSecurityDashboardStatusV92(tok);
};
